local function GetAppliedColor(colorIdx, brightness)
    local base = COLOR_MAP[colorIdx] or COLOR_MAP[4]
    local b = brightness or _G.ColorConfig.Brightness or 25
    return {
        R = math.min(255, (base.R or 0) * b / 25),
        G = math.min(255, (base.G or 0) * b / 25),
        B = math.min(255, (base.B or 0) * b / 25),
        A = 255
    }
end

-- AUTOMATIC VIP MENU STORAGE AND LOADING SYSTEM
local function GetConfigPaths(fileName)
    local paths = {}
    
    local android_packages = {
        "com.tencent.ig",
        "com.pubg.krmobile",
        "com.vng.pubgmobile",
        "com.rekoo.pubgm",
        "com.pubg.imobile",
        "com.pubg.tw",
        "com.tencent.pubgm",
    }
    
    for _, pkg in ipairs(android_packages) do
        table.insert(paths, "//storage/emulated/0/Android/data/" .. pkg .. "/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        table.insert(paths, "//storage/emulated/0/Android/data/" .. pkg .. "/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName)
    end
    
    if os and os.getenv then
        local home = os.getenv("HOME")
        if home and home ~= "" then
            table.insert(paths, home .. "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName)
            table.insert(paths, home .. "/Documents/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName)
        end
    end
    
    table.insert(paths, "Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
    table.insert(paths, "ShadowTrackerExtra/Saved/Paks/" .. fileName)
    table.insert(paths, "../../ShadowTrackerExtra/Saved/Paks/" .. fileName)
    
    return paths
end

local ConfigFileName = "TEST_JOIN.txt"
_G.LastConfigSaveStr = ""

_G.SaveModSettings = function()
    -- KEY_VALIDATED guard: SARE callers se protect karta hai.
    -- LizardVip timers, AutoSaveLoop, menu callbacks — koi bhi
    -- unlicensed state mein file nahi likhega.
    if not _G.KEY_VALIDATED then return end
    pcall(function()
        local function serializeTable(tbl, indent)
            indent = indent or ""
            local items = {}
            for k, v in pairs(tbl) do
                local keyStr
                if type(k) == "string" then
                    keyStr = string.format("[%q]", k)
                elseif type(k) == "number" then
                    keyStr = "[" .. tostring(k) .. "]"
                else
                    keyStr = "[" .. tostring(k) .. "]"
                end
                
                if type(v) == "table" then
                    table.insert(items, indent .. keyStr .. " = " .. serializeTable(v, indent .. "  "))
                elseif type(v) == "string" then
                    table.insert(items, indent .. keyStr .. " = " .. string.format("%q", v))
                elseif type(v) == "number" or type(v) == "boolean" then
                    table.insert(items, indent .. keyStr .. " = " .. tostring(v))
                else
                    table.insert(items, indent .. keyStr .. " = nil")
                end
            end
            return "{\n" .. table.concat(items, ",\n") .. "\n" .. indent:sub(1, #indent-2) .. "}"
        end
        
        -- [FIX-2] Also persist VIPConfig skin keys so they survive restart
        local vipSkinKeys = {
            ModSkin        = (_G.VIPConfig or {}).ModSkin        or false,
            SkinAttachment = (_G.VIPConfig or {}).SkinAttachment or false,
            SkinDeadBox    = (_G.VIPConfig or {}).SkinDeadBox    or false,
            KillCountUI    = (_G.VIPConfig or {}).KillCountUI    or false,
            ModEmote       = (_G.VIPConfig or {}).ModEmote       or false,
            KillMessage    = (_G.VIPConfig or {}).KillMessage    or false,
        }
        local data = "return {\npghacksConfig = " .. serializeTable(_G.pghacksConfig or {}, "  ") .. ",\n"
        data = data .. "CustomTextData = " .. serializeTable(_G.pghacksState.CustomTextData or {}, "  ") .. ",\n"
        data = data .. "ColorConfig = " .. serializeTable(_G.ColorConfig or {}, "  ") .. ",\n"
        data = data .. "VIPSkinConfig = " .. serializeTable(vipSkinKeys, "  ") .. "\n}"
        
        if data == _G.LastConfigSaveStr then return end
        _G.LastConfigSaveStr = data

        local paths = GetConfigPaths(ConfigFileName)
        for _, path in ipairs(paths) do
            local file = io.open(path, "w")
            if file then
                file:write(data)
                file:close()
                break
            end
        end
    end)
end

_G.LoadModSettings = function()
    pcall(function()
        local paths = GetConfigPaths(ConfigFileName)
        local content = nil
        for _, path in ipairs(paths) do
            local file = io.open(path, "r")
            if file then
                content = file:read("*a")
                file:close()
                break
            end
        end

        if content then
            local func = load(content)
            if func then
                local savedData = func()
                if savedData and type(savedData) == "table" then
                    if savedData.pghacksConfig then
                        for k, v in pairs(savedData.pghacksConfig) do
                            _G.pghacksConfig[k] = v
                        end
                    end
                    if savedData.CustomTextData then
                        _G.pghacksState.CustomTextData = _G.pghacksState.CustomTextData or {}
                        for k, v in pairs(savedData.CustomTextData) do
                            _G.pghacksState.CustomTextData[k] = v
                        end
                    end
                    if savedData.ColorConfig then
                        for k, v in pairs(savedData.ColorConfig) do
                            _G.ColorConfig[k] = v
                        end
                    end
                    -- [FIX-3] Restore VIPConfig skin keys
                    if savedData.VIPSkinConfig then
                        _G.VIPConfig = _G.VIPConfig or {}
                        local skinKeys = {"ModSkin","SkinAttachment","SkinDeadBox","KillCountUI","ModEmote","KillMessage"}
                        for _, k in ipairs(skinKeys) do
                            if savedData.VIPSkinConfig[k] ~= nil then
                                _G.VIPConfig[k] = savedData.VIPSkinConfig[k]
                            end
                        end
                    end
                end
            end
        end
    end)
end

local function AutoSaveLoop()
    -- Sirf tab save karo jab key verified ho — warna ForceDisableAllFeatures
    -- ka wiped state file mein likh jaata hai aur settings permanently reset ho jaati hain
    if _G.KEY_VALIDATED then
        pcall(function() if _G.SaveModSettings then _G.SaveModSettings() end end)
    end
    local okTicker = pcall(function()
        local okT, ticker = pcall(require, "common.time_ticker")
        if okT and ticker and ticker.AddTimerOnce then
            ticker.AddTimerOnce(3.0, AutoSaveLoop)
        else
            _G.AutoSaveRunning = false
        end
    end)
    if not okTicker then _G.AutoSaveRunning = false end
end

