    function F.hookCrewItemConfig()
        if _G.AddOutfitCrewItemConfigHooked then return true end
        if not CDataTable or type(CDataTable.GetTableData) ~= "function" then
            return false
        end
        local original = CDataTable.GetTableData
        _G.AddOutfitCrewItemConfigOriginal = original
        CDataTable.GetTableData = function(tableName, itemID, ...)
            if tableName == "Item" then
                local color = F.CREW_UNIFORM_COLORS[tonumber(itemID)]
                if color then
                    local nativeID = 140070800 + color
                    local nativeCfg = original(tableName, nativeID, ...)
                    if nativeCfg then return nativeCfg end
                    return original(tableName, F.CREW_UNIFORM_BASE_RES, ...)
                end
            end
            return original(tableName, itemID, ...)
        end
        _G.AddOutfitCrewItemConfigHooked = true
        return true
    end

    function F.getCrewUniformCustomization(resID, source)
        resID = tonumber(resID)
        local persist = _G.AddOutfitPersist or {}
        local selectorColor = F.CREW_UNIFORM_COLORS[resID]
        local selectorPattern = F.CREW_UNIFORM_PATTERNS[resID]
        if resID ~= F.CREW_UNIFORM_BASE_RES and not selectorColor then
            return nil
        end
        local color, pattern
        if source then
            pcall(function()
                color = tonumber(
                            source.color or source.Color or source.color_id or
                                source.colorID or source.ColorID)
                pattern = tonumber(source.pattern or source.Pattern or
                                       source.pattern_id or source.patternID or
                                       source.PatternID)
            end)
        end
        
        
        if color and color <= 0 then color = nil end
        if pattern and pattern <= 0 then pattern = nil end
        local savedPattern = tonumber(persist.crewPattern) or
                                 tonumber(_G.AddOutfitCrewPattern)
        if savedPattern and savedPattern <= 0 then savedPattern = nil end
        color = selectorColor or color or tonumber(persist.crewColor) or
                    tonumber(_G.AddOutfitCrewColor) or 1
        pattern = selectorPattern or pattern or savedPattern or
                      F.CREW_UNIFORM_PATTERN_ID
        color = math.max(1, math.min(6, color))
        pattern = math.max(0, math.min(14, pattern))
        return F.CREW_UNIFORM_BASE_RES, color, pattern
    end

    function F.rememberCrewUniformCustomization(resID, source)
        local base, color, pattern =
            F.getCrewUniformCustomization(resID, source)
        if not base then return nil end
        _G.AddOutfitCrewColor = color
        _G.AddOutfitCrewPattern = pattern
        local persist = _G.AddOutfitPersist or {}
        persist.crewColor = color
        persist.crewPattern = pattern
        if F.persistMarkDirty then F.persistMarkDirty() end
        return base, color, pattern
    end
