    function F.hookForcedEquipmentLevelMapping()
        if _G.AddOutfitForcedEquipmentLevelMappingHooked then return true end
        if not DataMgr or type(DataMgr.GetEquipmentItemIDByResID) ~= "function" then
            return false
        end
        local original = DataMgr.GetEquipmentItemIDByResID
        DataMgr.GetEquipmentItemIDByResID = function(level, resID, ...)
            local catalog = FORCED_EQUIPMENT_CATALOG[tonumber(resID)]
            local family = catalog and FORCED_EQUIPMENT_FAMILIES[catalog]
            level = math.max(1, math.min(3, math.floor(tonumber(level) or 1)))
            if family then return tonumber(family[level]) or 0 end
            return original(level, resID, ...)
        end
        _G.AddOutfitForcedEquipmentLevelMappingHooked = true
        return true
    end

