    function F.cfg(resID)
        if not resID or not CDataTable or not CDataTable.GetTableData then
            return nil
        end
        local cfg = CDataTable.GetTableData("Item", resID)
        if not cfg and F.CREW_UNIFORM_COLORS[tonumber(resID)] then
            cfg = CDataTable.GetTableData("Item", F.CREW_UNIFORM_BASE_RES)
        end
        return cfg
    end

    function F.subType(c)
        return c and (c.ItemSubType or c.itemSubType) or nil
    end

    local function hasResourcePrefix(resID, prefix)
        resID = tonumber(resID)
        if not resID then return false end
        return tostring(math.floor(resID)):sub(1, #prefix) == prefix
    end

    
    
    
    function F.isBackpackSkinRes(resID)
        local forced = FORCED_EQUIPMENT_CATALOG[tonumber(resID)]
        if forced and FORCED_EQUIPMENT_FAMILIES[forced] and
            tostring(forced):sub(1, 6) == "150100" then return true end
        local st = tonumber(F.subType(F.cfg(tonumber(resID))))
        return hasResourcePrefix(resID, "150100") and BAG_SUBS[st] == true
    end

    function F.isHelmetSkinRes(resID)
        local forced = FORCED_EQUIPMENT_CATALOG[tonumber(resID)]
        if forced and FORCED_EQUIPMENT_FAMILIES[forced] and
            tostring(forced):sub(1, 6) == "150200" then return true end
        local st = tonumber(F.subType(F.cfg(tonumber(resID))))
        return hasResourcePrefix(resID, "150200") and HELMET_SUBS[st] == true
    end

    function F.wardrobeTab(resID)
        resID = tonumber(resID)
        if F.FORCED_CLOTHES[resID] then return TAB_CLOTHES end
        if FORCED_SUITS[resID] then return TAB_SUIT end
        local c = F.cfg(resID)
        return c and tonumber(c.WardrobeTab) or 0
    end

