    end

    function F.resToCustSlot(resID, st)
        resID, st = tonumber(resID), tonumber(st)
        if not resID or resID <= 0 then return nil end
        st = st or F.subType(F.cfg(resID))
        if st == HAT_SUB or HAT_SUBS[st] then
            return F.CUST_SLOT.HatEquipemtSlot
        end
        if st == HAIR_SUB then return F.CUST_SLOT.HairEquipemtSlot end
        if st == OUTFIT_SUB then return F.CUST_SLOT.ClothesEquipemtSlot end
        if st == PANTS_SUB then return F.CUST_SLOT.PantsEquipemtSlot end
        if st == SHOES_SUB then return F.CUST_SLOT.ShoesEquipemtSlot end
        if st == GLASS_SUB then return F.CUST_SLOT.GlassEquipemtSlot end
        if FACE_SUBS[st] then return F.CUST_SLOT.FaceEquipemtSlot end
        if st == GLOVES_SUB then
            return F.CUST_SLOT.HandEffectEquipemtSlot
        end
        if BAG_SUBS[st] and F.isBackpackSkinRes(resID) then
            return F.CUST_SLOT.BackpackEquipemtSlot
        end
        if HELMET_SUBS[st] and F.isHelmetSkinRes(resID) then
            return F.CUST_SLOT.HelmetEquipemtSlot
        end
        if F.isParachuteRes(resID) or st == PARACHUTE_SUB then
            return F.CUST_SLOT.ParachuteEquipemtSlot
        end
        if F.isGlideRes(resID) or GLIDER_SUBS[st] then
            return F.CUST_SLOT.GlideEquipemtSlot
        end
        return nil
    end

    function F.isSuitRes(resID)
        if F.subType(F.cfg(resID)) ~= OUTFIT_SUB then return false end
        return F.wardrobeTab(resID) ~= TAB_CLOTHES
    end

    function F.isTshirtRes(resID)
        return F.subType(F.cfg(resID)) == OUTFIT_SUB and F.wardrobeTab(resID) ==
                   TAB_CLOTHES
    end

    function F.weaponIdFromSkin(resID)
        resID = tonumber(resID)
        if not resID then return nil end
        local meleeWeaponID = _G.VIP_MELEE_RESOURCE_TO_WEAPON[resID]
        if meleeWeaponID then return meleeWeaponID end
        local ok, m = pcall(function()
            return CDataTable and CDataTable.GetTableData and
                       CDataTable.GetTableData("WeaponSkinMapping", resID)
        end)
        if ok and m then
            local mapped = tonumber(m.WeaponID or m.WeaponId)
            if mapped and mapped > 0 then return mapped end
        end

        
        
        local s = tostring(math.floor(resID))
        if #s == 10 and s:sub(1, 2) == "11" then
            local fallback = tonumber("1" .. s:sub(3, 7))
            if fallback and fallback > 0 then return fallback end
        end
        return nil
    end

    function F.isValidWeaponId(weaponID)
        weaponID = F.normalizeMeleeWeaponID(weaponID)
        if not weaponID or weaponID <= 0 then return false end
        if weaponID == MELEE_ID or weaponID == 108001 or weaponID ==
            PAN_WEAPON_ID or weaponID == 108005 then return true end
        return weaponID >= 101000 and weaponID < 108000
    end

    function F.isValidWeaponPersistEntry(weaponID, resID)
        weaponID, resID = F.normalizeMeleeWeaponID(weaponID), tonumber(resID)
        if not F.isValidWeaponId(weaponID) or not resID or resID <= 0 then
            return false
        end
        if weaponID == resID then return false end
        if resID >= 1800000 and resID < 1810000 then return false end
        if resID >= 1900000 and resID < 2000000 then return false end
        local itemSubType = F.subType(F.cfg(resID))
        local mappedWeaponID = tonumber(F.weaponIdFromSkin(resID))
        if itemSubType == MELEE_ID and weaponID == MELEE_ID then return true end
        if F.isInjectedRes(resID) then
            return mappedWeaponID and mappedWeaponID == weaponID
        end
        return mappedWeaponID and mappedWeaponID == weaponID
    end

    function F.sanitizeConfigWeapons(wmap)
        if type(wmap) ~= "table" then return {} end
        local clean = {}
        for widKey, resKey in pairs(wmap) do
            local wid = F.normalizeMeleeWeaponID(widKey)
            local res = tonumber(resKey)
            if F.isValidWeaponPersistEntry(wid, res) then
                clean[wid] = res
            end
        end
        return clean
    end

    function F.indexWeaponSkin(resID, insID)
        resID, insID = tonumber(resID), tonumber(insID)
        if not resID or not insID then return end
        local c = F.cfg(resID)
        local st = F.subType(c)
        local wid = F.normalizeMeleeWeaponID(F.weaponIdFromSkin(resID))
        if not wid and st == MELEE_ID then wid = MELEE_ID end
        if not wid or wid <= 0 then return end
        R.byWeapon[wid] = R.byWeapon[wid] or {}
        R.byWeapon[wid][resID] = insID
    end

    function F.isInjectedIns(ins)
        return ins and R.insToRes[tonumber(ins)] ~= nil
    end

    function F.isInjectedRes(res)
        return res and R.resToIns[tonumber(res)] ~= nil
    end

    function F.isWeaponSkinRes(resID)
        resID = tonumber(resID)
        if not resID then return false end
        local st = F.subType(F.cfg(resID))
        return tonumber(F.weaponIdFromSkin(resID)) ~= nil or st == MELEE_ID
    end

    function F.isWeaponSkinIns(insID)
        insID = tonumber(insID)
        if not insID then return false end
        local res = R.insToRes[insID]
        return res and F.isWeaponSkinRes(res)
    end

    
    
    
