    function F.registerGrenadeSkinsWithController()
        local pc = F.getPC and F.getPC() or
                       (GameplayData and GameplayData.GetPlayerController and
                           GameplayData.GetPlayerController())
        if not pc or not slua.isValid(pc) then
            F.skinDiag("GRENADE_FAIL", "player controller unavailable", 1)
            return false
        end
        local registered, synced = 0, 0
        
        
        
        pcall(function()
            local avatar = pc.InitialConsumableAvatar
            if not avatar then return end
            for base, skin in pairs(_G.VIP_GRENADE_SKINS or {}) do
                local field = GRENADE_AVATAR_FIELD_BY_BASE[tonumber(base)]
                local skinID = tonumber(skin) or 0
                if field and skinID > 0 then
                    avatar[field] = skinID
                    synced = synced + 1
                end
            end
        end)
        pcall(function()
            if pc.InitGrenadeAvatarList then pc:InitGrenadeAvatarList(true) end
        end)
        pcall(function()
            local list = pc.GrenadeAvatarItemList
            if not list or not list.Add then return end
            for base, skin in pairs(_G.VIP_GRENADE_SKINS or {}) do
                local baseID, skinID = tonumber(base), tonumber(skin)
                if baseID and baseID > 0 and skinID and skinID > 0 then
                    list:Add(baseID, skinID)
                    registered = registered + 1
                end
            end
        end)
        F.skinDiag("GRENADE_LIST",
                   "synced=" .. tostring(synced) .. " registered=" ..
                       tostring(registered), 1)
        return synced > 0 or registered > 0
    end

    function F.hookGrenadeAvatarLookup()
        local installed = false
        pcall(function()
            local ADU = require(
                            "GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
            if not ADU or type(ADU.TryGetGrenadeAvatarID) ~= "function" then
                return
            end
            if ADU._4RGrenadeLookupHookedV1 then
                installed = true
                return
            end
            local original = ADU.TryGetGrenadeAvatarID
            ADU.TryGetGrenadeAvatarID = function(controller, itemID)
                local value = tonumber(itemID) or 0
                local base = _G.VIP_GRENADE_SKINS[value] and value or nil
                if not base and value > 0 then
                    local proto = math.floor(value / 100)
                    if _G.VIP_GRENADE_SKINS[proto] then
                        base = proto
                    end
                end
                local selected =
                    base and tonumber(_G.VIP_GRENADE_SKINS[base]) or 0
                if selected > 0 then return selected end
                return original(controller, itemID)
            end
            ADU._4RGrenadeLookupOriginal = original
            ADU._4RGrenadeLookupHookedV1 = true
            installed = true
        end)
        return installed
    end

    function F.hookGrenadeInventorySelection()
        local installed, editInstalled = false, false
        pcall(function()
            local fashion = require(
                                "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            if not fashion or type(fashion.PutOnThrowObjectSkin) ~= "function" then
                return
            end
            if fashion.__4RGrenadeInventoryHooked then
                installed = true
                return
            end
            local original = fashion.PutOnThrowObjectSkin
            fashion.__4RGrenadeInventoryOriginal = original
            fashion.PutOnThrowObjectSkin = function(self, insID, ...)
                insID = tonumber(insID)
                local resID = insID and tonumber(R.insToRes[insID]) or nil
                if resID and F.isFragGrenadeSkinRes(resID) then
                    F.putOnGrenadeSkin(insID, true)
                    return true
                end
                return original(self, insID, ...)
            end
            fashion.__4RGrenadeInventoryHooked = true
            installed = true
        end)
        
        
        
        pcall(function()
            local EditClass = require(
                                  "client.slua.logic.wardrobe.fashionbag.FashionBagEditUtils")
            local impl = EditClass and (EditClass.__inner_impl or EditClass)
            if not impl or type(impl.PutOnThrowObject) ~= "function" then
                return
            end
            if impl.__4RGrenadeEditHooked then
                editInstalled = true
                return
            end
            local original = impl.PutOnThrowObject
            impl.PutOnThrowObject = function(self, itemData, ...)
                local results = {pcall(original, self, itemData, ...)}
                if not results[1] then error(results[2]) end
                local insID = itemData and
                                  tonumber(itemData.ins_id or itemData.insID)
                local resID = itemData and
                                  tonumber(itemData.res_id or itemData.resID)
                if insID and resID and F.isFragGrenadeSkinRes(resID) then
                    R.insToRes[insID] = resID
                    R.resToIns[resID] = insID
                    F.putOnGrenadeSkin(insID, true)
                end
                local unpackResult = table.unpack or unpack
                return unpackResult(results, 2)
            end
            impl.__4RGrenadeEditHooked = true
            editInstalled = true
        end)
        F.skinDiag("GRENADE_SELECT_HOOK",
                   "data=" .. tostring(installed) .. " edit=" ..
                       tostring(editInstalled), 2)
        return installed or editInstalled
    end

    function F.applySelectedGrenadeSkin()
        local avatarHook = F.hookGrenadeAvatarLookup()
        local inventoryHook = F.hookGrenadeInventorySelection()
        local cache = F.cache()
        local selected = tonumber(cache.grenadeRes) or
                             tonumber(PERSIST.configSlots and
                                          PERSIST.configSlots.grenade)
        if selected and selected > 0 then
            local base = F.grenadeBaseFromSkin(selected)
            if base then _G.VIP_GRENADE_SKINS[base] = selected end
        end
        local listReady = F.registerGrenadeSkinsWithController()
        F.skinDiag("GRENADE_HOOK",
                   "avatar=" .. tostring(avatarHook) .. " inventory=" ..
                       tostring(inventoryHook) .. " selected=" ..
                       tostring(selected) .. " list=" ..
                       tostring(listReady), 1)
        return true
    end

    function F.putOnGrenadeSkin(insID, localOnly)
        insID = tonumber(insID)
        if not insID then
            F.skinDiag("GRENADE_FAIL", "invalid instance id", 0)
            return false
        end
        local resID = tonumber(R.insToRes[insID])
        if not resID then
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local data = wd:GetValidHallDepotItemDataByInsID(insID) or
                                 wd:GetHallDepotItemDataByInsID(insID)
                resID = data and tonumber(data.resID or data.res_id) or nil
            end)
        end
        if not resID or not F.isFragGrenadeSkinRes(resID) then
            F.skinDiag("GRENADE_FAIL",
                       "ins=" .. tostring(insID) .. " res=" ..
                           tostring(resID) .. " unsupported subtype", 0)
            return false
        end
        local base = F.grenadeBaseFromSkin(resID)
        if not base then
            F.skinDiag("GRENADE_FAIL",
                       "ins=" .. tostring(insID) .. " res=" ..
                           tostring(resID) .. " base unresolved", 0)
            return false
        end

        R.insToRes[insID] = resID
        R.resToIns[resID] = insID
        _G.VIP_GRENADE_SKINS[base] = resID
        local cache = F.cache()
        cache.grenadeRes = resID
        cache.grenadeIns = insID
        F.persistRememberSlot("grenade", resID)
        pcall(function() F.ensureDepotItemValid(insID, resID) end)
        pcall(function() F.ensureSkinDownload(resID) end)
        F.hookGrenadeAvatarLookup()
        F.registerGrenadeSkinsWithController()
        pcall(function()
            local fashion = require(
                                "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local bag = fashion and fashion.GetCurrentFashionBag and
                            fashion:GetCurrentFashionBag()
            if bag then
                bag.throw_object_skin_list = bag.throw_object_skin_list or {}
                bag.throw_object_skin_list[base] = {skin_id = insID}
                bag.grenade_skin_list = bag.grenade_skin_list or {}
                bag.grenade_skin_list[base] = {skin_id = insID}
            end
            if not localOnly and fashion and
                fashion.__4RGrenadeInventoryOriginal then
                fashion.__4RGrenadeInventoryOriginal(fashion, insID)
            end
        end)
        pcall(function()
            if EventSystem and EVENTTYPE_WARDROBE and
                EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                      EVENTID_WARDROBE_UPDATE_ITEM_LIST)
            end
        end)
        F.skinDiag("GRENADE_APPLY",
                   "ins=" .. tostring(insID) .. " res=" .. tostring(resID) ..
                       " base=" .. tostring(base) .. " local=" ..
                       tostring(localOnly == true), 0)
        return true
    end

    function F.cleanArmoryPollution()
        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            if not Arm.rsp_list then return end
            if Arm.rsp_list.install_list then
                for wid, entry in pairs(Arm.rsp_list.install_list) do
                    local ins = tonumber(entry and entry.skin_id)
                    if ins and not F.isWeaponSkinIns(ins) then
                        Arm.rsp_list.install_list[wid] = nil
                    end
                end
            end
            if Arm.rsp_list.skin_list then
                for wid, skins in pairs(Arm.rsp_list.skin_list) do
                    if type(skins) == "table" then
                        for resID in pairs(skins) do
                            if not F.isWeaponSkinRes(tonumber(resID)) then
                                skins[resID] = nil
                            end
                        end
                    end
                end
            end
        end)
    end

    function F.depotSubType(insID, resID)
        resID = tonumber(resID) or tonumber(R.insToRes[insID])
        local st = F.subType(F.cfg(resID))
        if st then return st end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetHallDepotItemDataByInsID(insID)
        return d and tonumber(d.itemSubType)
    end

    function F.tryLocalWearByIns(insID)
        insID = tonumber(insID)
        if not insID then return false end
        if _G.VIPConfig and _G.VIPConfig.ModSkin == false then
            return false
        end 
        local resID = R.insToRes[insID]
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetHallDepotItemDataByInsID(insID)
        if not resID and d then resID = tonumber(d.resID or d.res_id) end
        if not resID or resID <= 0 then return false end
        local st = F.depotSubType(insID, resID)

        local function mapLocal()
            if not R.insToRes[insID] then
                R.insToRes[insID] = resID
                R.resToIns[resID] = insID
            end
        end

        if st == GLOVES_SUB then
            mapLocal();
            F.putOnGloves(insID)
            return true
        end
        F.clearItemExpire(d, insID, resID)
        F.ensureDepotItemValid(insID, resID)
        if F.isParachuteRes(resID) then
            mapLocal();
            return F.putOnParachute(insID)
        end
        if F.isGlideRes(resID) or GLIDER_SUBS[st] then
            mapLocal();
            return F.putOnGlider(insID)
        end
        if F.isFragGrenadeSkinRes(resID) then
            mapLocal()
            return F.putOnGrenadeSkin(insID)
        end

        if st == OUTFIT_SUB then
            mapLocal()
            if F.isSuitRes(resID) or F.wardrobeTab(resID) == TAB_SUIT then
                F.putOnOutfit(insID)
            else
                F.putOnRoleWear(insID)
            end
            return true
        end
        if st == HAT_SUB or HEAD_SUBS[st] then
            mapLocal();
            F.putOnHat(insID)
            return true
        end
        if FACE_SUBS[st] then
            mapLocal();
            F.putOnFaceAccessory(insID)
            return true
        end
        if BODY_SUBS[st] or HELMET_SUBS[st] then
            mapLocal();
            F.putOnRoleWear(insID)
            return true
        end

        if not F.isInjectedIns(insID) then return false end
        local mappedWeaponID = F.weaponIdFromSkin(resID)
        if mappedWeaponID then
            F.equipWeaponSkin(mappedWeaponID, insID)
            return true
        end
        if st == MELEE_ID then
            F.equipWeaponSkin(MELEE_ID, insID)
            return true
        end
        if F.isHallThemeRes(resID) and
            (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
            mapLocal()
            return F.putOnHallTheme(insID)
        end
        if F.isVehicleRes(resID) and
            (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
            mapLocal()
            return F.putOnVehicle(insID)
        end
        return false
    end

    function F.isHallThemeRes(resID)
        local c = F.cfg(tonumber(resID))
        if not c then return false end
        local t = c.ItemType or c.itemType
        return t == HALL_THEME_TYPE
    end

    function F.isResourcesReady(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        local managedAttachment = _G.VIP_AttachmentResources and
                                      _G.VIP_AttachmentResources[resID]
        if not F.isInjectedRes(resID) and not managedAttachment then
            return true
        end
        local ready = false
        pcall(function()
            local PufferConst = require(
                                    "client.slua.logic.download.puffer_const")
            local mgr = ModuleManager.GetModule(
                            ModuleManager.CommonModuleConfig
                                .puffer_odpak_manager)
            if mgr and mgr.GetStateByItemID then
                local st = mgr:GetStateByItemID(resID)
                ready = st == PufferConst.ENUM_DownloadState.Done
            end
        end)
        return ready
    end

    function F.requestResourceDownload(resID)
        resID = tonumber(resID)
        local managedAttachment = resID and _G.VIP_AttachmentResources and
                                      _G.VIP_AttachmentResources[resID]
        if not resID or resID <= 0 or
            (not F.isInjectedRes(resID) and not managedAttachment) then
            return
        end
        if F.isResourcesReady(resID) then return end
        _G.AddOutfitDownloadQueued = _G.AddOutfitDownloadQueued or {}
        if _G.AddOutfitDownloadQueued[resID] then return end
        _G.AddOutfitDownloadQueued[resID] = true
        pcall(function()
            local PM = require(
                           "client.slua.logic.download.puffer.puffer_manager")
            local PufferConst = require(
                                    "client.slua.logic.download.puffer_const")
            PM.Download(PufferConst.ENUM_DownloadType.ODPAK, {resID},
                        "AddOutfit",
                        function()
                _G.AddOutfitDownloadQueued[resID] = nil
            end)
        end)
    end

    
    
    
    
    function F.resetTransientSkinSession()
        _G.AddOutfitDownloadQueued = {}
        _G.skinIdCache = {}
        _G.AddOutfitLobbyRestored = false
        _G.AddOutfitLobbyInitDone = false
        _G.__4REmoteInventoryEntity = nil
        _G.__4REmoteInventoryReady = false

        LOBBY.reapplyDone = false
        LOBBY.reapplyScheduled = false
        LOBBY.wardrobeRefreshed = false
        F.perfInvalidateLobby()
    end

    function F.ensureInjectedResources()
        for res in pairs(R.resToIns) do
            F.requestResourceDownload(tonumber(res))
        end
    end

    function F.restorePufferHooks()
        pcall(function()
            local mgr = ModuleManager.GetModule(
                            ModuleManager.CommonModuleConfig
                                .puffer_odpak_manager)
            if mgr and _G.AddOutfitPufferOrig then
                mgr.GetStateByItemID = _G.AddOutfitPufferOrig
            end
        end)
        pcall(function()
            local PM = require(
                           "client.slua.logic.download.puffer.puffer_manager")
            if PM and _G.AddOutfitPufferGetStateOrig then
                PM.GetState = _G.AddOutfitPufferGetStateOrig
            end
        end)
        pcall(function()
            local VAC = require(
                            "GameLua.GameCore.Module.Vehicle.Component.VehicleAvatarComponent")
            local vacImpl = VAC and VAC.__inner_impl
            if vacImpl and _G.AddOutfitVehOrigAssets then
                vacImpl.LuaIsAssetsAlreadyAvailable = _G.AddOutfitVehOrigAssets
            end
        end)
