        {"grenade", "grenadeRes", "grenadeIns", "AddOutfitLastLobbyGrenadeRes"}
    }

    
    
    
    function F.logSkinSlotDetails(reason)
        if not DEBUG then return end
        local cache = F.cache()
        for _, slot in ipairs(PERSIST_SLOTS) do
            local name, resKey, insKey, lastKey = slot[1], slot[2], slot[3],
                                                     slot[4]
            local persisted = PERSIST.configSlots and
                                  tonumber(PERSIST.configSlots[name]) or 0
            F.skinDiag("SLOT_" .. string.upper(name),
                       "phase=" .. tostring(reason) .. " cacheRes=" ..
                           tostring(cache[resKey]) .. " cacheIns=" ..
                           tostring(cache[insKey]) .. " persisted=" ..
                           tostring(persisted) .. " last=" ..
                           tostring(rawget(_G, lastKey)), 0)
        end
        local weaponCount = 0
        for _ in pairs(cache.weapons or {}) do weaponCount = weaponCount + 1 end
        F.skinDiag("SLOT_WEAPONS",
                   "phase=" .. tostring(reason) .. " count=" ..
                       tostring(weaponCount), 0)
    end

    function F.isPersistableWearRes(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        if F.isInjectedRes(resID) then return true end
        if F.isParachuteRes(resID) or F.isGlideRes(resID) then
            return true
        end
        if PERSIST.configSlots then
            for _, v in pairs(PERSIST.configSlots) do
                if tonumber(v) == resID then return true end
            end
        end
        return false
    end

    function F.persistRememberSlot(slotName, resID)
        slotName = slotName and tostring(slotName)
        resID = tonumber(resID)
        if not slotName or not resID or resID <= 0 then return end
        if slotName == "helmet" and not F.isHelmetSkinRes(resID) then
            return
        end
        if slotName == "bag" and not F.isBackpackSkinRes(resID) then
            return
        end
        PERSIST.configSlots = PERSIST.configSlots or {}
        PERSIST.configSlots[slotName] = resID
    end

    function F.persistForgetSlot(slotName)
        if PERSIST.configSlots and slotName then
            PERSIST.configSlots[tostring(slotName)] = nil
        end
    end

    function F.persistLoadSlotsFromSaved(saved)
        if type(saved) ~= "table" then return end
        PERSIST.configSlots = PERSIST.configSlots or {}
        for _, s in ipairs(PERSIST_SLOTS) do
            local res = tonumber(saved[s[1]])
            if res and res > 0 then PERSIST.configSlots[s[1]] = res end
        end
        local hc = tonumber(saved.hairColor)
        if hc and hc > 0 and hc <= 99 then
            PERSIST.configSlots.hairColor = hc
            _G.AddOutfitLastLobbyHairColor = hc
        end
        F.applyPersistSlotsToCache()
    end

    function F.resolveInsForRes(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return nil end
        if R.resToIns[resID] then return R.resToIns[resID] end
        local ins
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local list = wd.GetHallDepotItemListByResID and
                             wd:GetHallDepotItemListByResID(resID)
            if list then
                for _, v in pairs(list) do
                    local id = tonumber(v.insID or v.instid or v.ins_id)
                    if id and id > 0 then
                        ins = id
                        break
                    end
                end
            end
            if not ins then
                local d = wd.GetValidHallDepotItemDataByInsID and
                              wd:GetValidHallDepotItemDataByInsID(resID)
                if not d and wd.GetHallDepotItemDataByResID then
                    d = wd:GetHallDepotItemDataByResID(resID)
                end
                if d then
                    ins = tonumber(d.insID or d.instid or d.ins_id)
                end
            end
        end)
        return ins
    end

    function F.applyPersistSlotsToCache()
        if not PERSIST.configSlots then return end
        local cch = F.cache()
        local cleaned = false
        for _, s in ipairs(PERSIST_SLOTS) do
            local slotName, cacheResKey, cacheInsKey, globalKey = s[1], s[2],
                                                                  s[3], s[4]
            local res = tonumber(PERSIST.configSlots[slotName])
            local valid = res and res > 0
            if valid and slotName == "helmet" then
                valid = F.isHelmetSkinRes(res)
            elseif valid and slotName == "bag" then
                valid = F.isBackpackSkinRes(res)
            end
            if valid then
                cch[cacheResKey] = res
                _G[globalKey] = res
                local ins = F.resolveInsForRes(res)
                if ins and ins > 0 then cch[cacheInsKey] = ins end
                F.skinDiag("PERSIST",
                           "slot=" .. tostring(slotName) .. " res=" ..
                               tostring(res) .. " ins=" .. tostring(ins), 10)
            elseif res then
                F.skinDiag("PERSIST_DROP",
                           "slot=" .. tostring(slotName) .. " res=" ..
                               tostring(res) .. " failed validation", 0)
                PERSIST.configSlots[slotName] = nil
                cch[cacheResKey], cch[cacheInsKey] = nil, nil
                _G[globalKey] = nil
                cleaned = true
            end
        end
        if cleaned and F.persistMarkDirty then F.persistMarkDirty() end
    end

    function F.getDesiredGliderRes()
        F.applyPersistSlotsToCache()
        local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.glider)
        if r and r > 0 then return r end
        F.syncAirborneCacheFromLobby()
        return F.getDesiredWear("gliderRes", "gliderRes",
                                "AddOutfitLastLobbyGliderRes")
    end

    function F.getDesiredParachuteRes()
        F.applyPersistSlotsToCache()
        local r =
            tonumber(PERSIST.configSlots and PERSIST.configSlots.parachute)
        if r and r > 0 then return r end
        F.syncAirborneCacheFromLobby()
        return F.getDesiredWear("parachuteRes", "parachuteRes",
                                "AddOutfitLastLobbyParachuteRes")
    end

    function F.getAvatarComp2(char)
        if not char or not slua.isValid(char) then return nil end
        local comp
        pcall(function()
            if char.getAvatarComponent2 then
                comp = char:getAvatarComponent2()
            end
            if (not comp or not slua.isValid(comp)) and char.AvatarComponent2 then
                comp = char.AvatarComponent2
            end
            if (not comp or not slua.isValid(comp)) and
                char.CharacterAvatarComp2_BP then
                comp = char.CharacterAvatarComp2_BP
            end
        end)
        return comp
    end

    function F.isCharacterAirborne(char)
        if not char or not slua.isValid(char) then return false end
        local ok, r = pcall(function()
            local EParachuteState = import("EParachuteState")
            local st = char.ParachuteState
            return st and st ~= EParachuteState.PS_None
        end)
        return ok and r == true
    end

    function F.reapplyWeaponsFromConfig()
        local wmap = F.sanitizeConfigWeapons(PERSIST.configWeapons)
        local dropped = false
        for k in pairs(PERSIST.configWeapons or {}) do
            if not wmap[tonumber(k) or k] then
                dropped = true
                break
            end
        end
        PERSIST.configWeapons = wmap
        if dropped then F.persistMarkDirty() end
        if not next(wmap) then return false end
        local cch = F.cache()
        local any = false
        for widKey, resKey in pairs(wmap) do
            local wid = tonumber(widKey)
            local res = tonumber(resKey)
            local ins = res and R.resToIns[res]
            if wid and ins and F.isInjectedIns(ins) then
                cch.weapons[wid] = {resID = res, insID = ins}
                if F.equipWeaponSkin(wid, ins) then
                    any = true
                else
                    F.syncWeaponArmorySilent(wid, ins)
                end
            end
        end
        return any
    end

    function F.persistEncode()
        local cch = F.cache()
        local parts = {}
        for _, s in ipairs(PERSIST_SLOTS) do
            local res = tonumber(PERSIST.configSlots and
                                     PERSIST.configSlots[s[1]]) or
                            tonumber(cch[s[2]])
            if res and res > 0 and F.isPersistableWearRes(res) then
                parts[#parts + 1] = string.format("  \"%s\": %d", s[1], res)
            end
        end
        local savedHairColor = tonumber(PERSIST.configSlots and
                                              PERSIST.configSlots.hairColor) or
                                     tonumber(_G.AddOutfitLastLobbyHairColor)
        if savedHairColor and savedHairColor >= 1 and savedHairColor <= 99 then
            parts[#parts + 1] =
                string.format("  \"hairColor\": %d", savedHairColor)
        end
        local crewColor = tonumber(PERSIST.crewColor) or
                              tonumber(_G.AddOutfitCrewColor)
        local crewPattern = tonumber(PERSIST.crewPattern) or
                                tonumber(_G.AddOutfitCrewPattern) or
                                F.CREW_UNIFORM_PATTERN_ID
        if crewColor and crewColor >= 1 and crewColor <= 6 then
            parts[#parts + 1] = string.format("  \"crewColor\": %d", crewColor)
            parts[#parts + 1] = string.format("  \"crewPattern\": %d", math.max(0,
                                                                              math.min(
                                                                                  14,
                                                                                  crewPattern)))
        end
        local wparts = {}
        local wmap = {}
        for widKey, res in pairs(F.sanitizeConfigWeapons(PERSIST.configWeapons)) do
            wmap[widKey] = res
        end
        for widKey, w in pairs(cch.weapons or {}) do
            local res = w and tonumber(w.resID)
            local wid = tonumber(widKey)
            if F.isValidWeaponPersistEntry(wid, res) then
                wmap[wid] = res
            end
        end
        for widKey, res in pairs(wmap) do
            wparts[#wparts + 1] = string.format("    \"%d\": %d", widKey, res)
        end
        table.sort(wparts)
        parts[#parts + 1] = "  \"weapons\": {
" .. table.concat(wparts, ",
") ..
                                "
  }"
        local vparts = {}
        local function appendVehicleSlots(src)
            for subType, slots in pairs(src or {}) do
                local sparts = {}
                if type(slots) == "table" then
                    for idx, val in pairs(slots) do
                        local res =
                            type(val) == "table" and tonumber(val.resID) or
                                tonumber(val)
                        if res and res > 0 then
                            sparts[#sparts + 1] = string.format(
                                                      "      \"%d\": %d",
                                                      tonumber(idx), res)
                        end
                    end
                end
                table.sort(sparts)
                if #sparts > 0 then
                    vparts[#vparts + 1] = string.format(
                                              "    \"%d\": {
%s
    }",
                                              tonumber(subType),
                                              table.concat(sparts, ",
"))
                end
            end
        end
        local hasCacheSlots = false
        for _ in pairs(cch.vehicleSlots or {}) do
            hasCacheSlots = true;
            break
        end
        if hasCacheSlots then
            appendVehicleSlots(cch.vehicleSlots)
        elseif PERSIST.configVehicleSlots then
            appendVehicleSlots(PERSIST.configVehicleSlots)
        end
        table.sort(vparts)
        parts[#parts + 1] = "  \"vehicleSlots\": {
" ..
                                table.concat(vparts, ",
") .. "
  }"
        if PERSIST.lobbyVehicleSubType and PERSIST.lobbyVehicleSubType > 0 and
            PERSIST.lobbyVehicleSubType ~= CHASSIS_LIGHT_SUB and
            not F.isChassisLightId(PERSIST.lobbyVehicleResID) and
            F.isVehicleRes(PERSIST.lobbyVehicleResID) then
            parts[#parts + 1] = string.format("  \"lobbyVehicleSubType\": %d",
                                              PERSIST.lobbyVehicleSubType)
        end
        if PERSIST.lobbyVehicleResID and PERSIST.lobbyVehicleResID > 0 and
            F.isVehicleRes(PERSIST.lobbyVehicleResID) then
            parts[#parts + 1] = string.format("  \"lobbyVehicleResID\": %d",
                                              PERSIST.lobbyVehicleResID)
        end
        if PERSIST.lobbyVehicleIns and PERSIST.lobbyVehicleIns > 0 and
            F.isVehicleRes(
                PERSIST.lobbyVehicleResID or R.insToRes[PERSIST.lobbyVehicleIns]) then
            parts[#parts + 1] = string.format("  \"lobbyVehicleIns\": %d",
                                              PERSIST.lobbyVehicleIns)
        end
        local hres = tonumber(cch.hallThemeRes) or
                         tonumber(PERSIST.hallThemeResID)
        if hres and hres > 0 and F.isInjectedRes(hres) then
            parts[#parts + 1] = string.format("  \"hallTheme\": %d", hres)
        end
        local cl = tonumber(PERSIST.configChassisLight)
        if F.isChassisLightId(cl) then
            parts[#parts + 1] = string.format("  \"chassisLight\": %d", cl)
        end
        local cmap = PERSIST.configChassisLightMap
        if cmap and next(cmap) then
            local cparts = {}
            for vidKey, lidKey in pairs(cmap) do
                local vid = tonumber(vidKey)
                local lid = tonumber(lidKey)
                if vid and vid > 0 and F.isChassisLightId(lid) then
                    cparts[#cparts + 1] =
                        string.format("    \"%d\": %d", vid, lid)
                end
            end
            table.sort(cparts)
            if #cparts > 0 then
                parts[#parts + 1] = "  \"chassisLightMap\": {
" ..
                                        table.concat(cparts, ",
") .. "
  }"
            end
        end
        return ("{
") .. table.concat(parts, ",
") .. "
}
"
    end

    function F.persistWrite(txt)
        if not (io and io.open) then return false end
        local protectedText = EncodeProtectedConfig(txt)
        if PERSIST.path then
            local f
            pcall(function() f = io.open(PERSIST.path, "w") end)
            if f then
                f:write(protectedText)
                f:close()
                return true
            end
            PERSIST.path = nil
        end
        for _, p in ipairs(CONFIG_PATHS) do
            local f
            pcall(function() f = io.open(p, "w") end)
            if not f then
                pcall(function()
                    local dir = p:match("^(.*)/[^/]+$")
                    if dir and os and os.execute then
                        os.execute("mkdir -p \"" .. dir .. "\"")
                    end
                end)
                pcall(function() f = io.open(p, "w") end)
            end
            if f then
                f:write(protectedText)
                f:close()
                PERSIST.path = p
                return true
            end
        end
        return false
    end

    function F.persistFlush()
        if not PERSIST.dirty then return end
        PERSIST.dirty = false
        pcall(function()
            local txt = F.persistEncode()
            if txt == PERSIST.lastWritten then return end
            if F.persistWrite(txt) then PERSIST.lastWritten = txt end
        end)
    end

    F.persistMarkDirty = function()
        PERSIST.dirty = true
        if PERSIST.scheduled then return end
        PERSIST.scheduled = true
        F.later(2.0, function()
            PERSIST.scheduled = false
            F.persistFlush()
        end)
    end

    function F.persistParse(txt)
        if not txt or #txt == 0 then return nil end
        local out = {weapons = {}, vehicleSlots = {}}
        local parsed = false
        pcall(function()
            local t = json and json.decode and json.decode(txt)
            if type(t) == "table" then
                for k, v in pairs(t) do
                    if k == "weapons" and type(v) == "table" then
                        for wk, wv in pairs(v) do
                            local wid, res = tonumber(wk), tonumber(wv)
                            if F.isValidWeaponPersistEntry(wid, res) then
                                out.weapons[wid] = res
                            end
                        end
                    elseif k == "vehicleSlots" and type(v) == "table" then
                        for stk, slotMap in pairs(v) do
                            local st = tonumber(stk)
                            if st then
                                out.vehicleSlots[st] =
                                    out.vehicleSlots[st] or {}
                                for idxStr, res in pairs(slotMap) do
                                    local idx, r = tonumber(idxStr),
                                                   tonumber(res)
                                    if idx and r and r > 0 and F.isVehicleRes(r) and
                                        tonumber(F.subType(F.cfg(r))) == st then
                                        out.vehicleSlots[st][idx] = r
                                    end
                                end
                            end
                        end
                    elseif k == "chassisLightMap" and type(v) == "table" then
                        out.chassisLightMap = {}
                        for vk, lv in pairs(v) do
                            local vid, lid = tonumber(vk), tonumber(lv)
                            if vid and lid and F.isChassisLightId(lid) then
                                out.chassisLightMap[vid] = lid
                            end
                        end
                    else
                        local n = tonumber(v)
                        if n and n > 0 then out[k] = n end
                    end
                end
                parsed = true
            end
        end)
        if not parsed then
            for k, v in txt:gmatch("\"([%w_]+)\"%s*:%s*(%d+)") do
                local n = tonumber(v)
                if n and n > 0 then
                    local wid = tonumber(k)
                    if wid and F.isValidWeaponPersistEntry(wid, n) then
                        out.weapons[wid] = n
                    elseif not wid then
                        out[k] = n
                    end
                end
            end
        end
        return out
    end

    function F.persistLoadFromDisk()
        if not (io and io.open) then return end
        pcall(function()
            for _, p in ipairs(CONFIG_PATHS) do
                local f
                pcall(function() f = io.open(p, "r") end)
                if f then
                    local rawText = f:read("*a")
                    f:close()
                    local txt, wasEncrypted = DecodeProtectedConfig(rawText)
                    if not txt then return end
                    PERSIST.path = p
                    
                    
                    PERSIST.lastWritten = wasEncrypted and txt or nil
                    PERSIST.loaded = F.persistParse(txt)
                    if PERSIST.loaded then
                        PERSIST.crewColor = tonumber(PERSIST.loaded.crewColor)
                        PERSIST.crewPattern = tonumber(
                                                  PERSIST.loaded.crewPattern) or
                                                   F.CREW_UNIFORM_PATTERN_ID
                        _G.AddOutfitCrewColor = PERSIST.crewColor
                        _G.AddOutfitCrewPattern = PERSIST.crewPattern
                    end
                    F.persistLoadSlotsFromSaved(PERSIST.loaded)
                    if PERSIST.loaded and PERSIST.loaded.vehicleSlots then
                        PERSIST.configVehicleSlots = PERSIST.loaded.vehicleSlots
                    end
                    if PERSIST.loaded and PERSIST.loaded.weapons then
                        local raw = PERSIST.loaded.weapons
                        PERSIST.configWeapons = F.sanitizeConfigWeapons(raw)
                        if next(raw) and not next(PERSIST.configWeapons) then
                            F.persistMarkDirty()
                        elseif next(raw) then
                            for wid, res in pairs(raw) do
                                if not F.isValidWeaponPersistEntry(
                                    tonumber(wid), tonumber(res)) then
                                    F.persistMarkDirty()
                                    break
                                end
                            end
                        end
                    end
                    PERSIST.lobbyVehicleSubType =
                        tonumber(PERSIST.loaded and
                                     PERSIST.loaded.lobbyVehicleSubType)
                    PERSIST.lobbyVehicleResID =
                        tonumber(PERSIST.loaded and
                                     PERSIST.loaded.lobbyVehicleResID)
                    PERSIST.lobbyVehicleIns =
                        tonumber(PERSIST.loaded and
                                     PERSIST.loaded.lobbyVehicleIns)
                    if PERSIST.lobbyVehicleSubType or PERSIST.lobbyVehicleIns or
                        PERSIST.lobbyVehicleResID then
                        if F.isChassisLightId(PERSIST.lobbyVehicleResID) or
                            PERSIST.lobbyVehicleSubType == CHASSIS_LIGHT_SUB or
                            not F.isVehicleRes(PERSIST.lobbyVehicleResID) then
                            PERSIST.lobbyVehicleSubType = nil
                            PERSIST.lobbyVehicleResID = nil
                            PERSIST.lobbyVehicleIns = nil
                        else
                            _G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh or {}
                            _G.AddOutfitLobbyVeh.manual = true
                            _G.AddOutfitLobbyVeh.subType =
                                PERSIST.lobbyVehicleSubType
                            _G.AddOutfitLobbyVeh.resID =
                                PERSIST.lobbyVehicleResID
                            _G.AddOutfitLobbyVeh.insID = PERSIST.lobbyVehicleIns
                        end
                    end
                    PERSIST.hallThemeResID =
                        tonumber(PERSIST.loaded and PERSIST.loaded.hallTheme)
                    PERSIST.hallThemeIns = nil
                    if PERSIST.hallThemeResID then
                        _G.AddOutfitLobbyTheme = _G.AddOutfitLobbyTheme or {}
                        _G.AddOutfitLobbyTheme.manual = true
                        _G.AddOutfitLobbyTheme.resID = PERSIST.hallThemeResID
                    end
                    PERSIST.configChassisLight =
                        tonumber(PERSIST.loaded and PERSIST.loaded.chassisLight)
                    if PERSIST.loaded and PERSIST.loaded.chassisLightMap then
                        PERSIST.configChassisLightMap = PERSIST.loaded
                                                            .chassisLightMap
                    end
                    if not wasEncrypted then
                        F.persistMarkDirty()
                    end
                    return
                end
            end
        end)
    end

    function F.persistApplyLoaded()
        if not F.isEnabled() then return false end
        local saved = PERSIST.loaded
        if not saved then return end
        PERSIST.loaded = nil
        PERSIST.crewColor = tonumber(saved.crewColor) or PERSIST.crewColor
        PERSIST.crewPattern = tonumber(saved.crewPattern) or
                                 PERSIST.crewPattern or
                                 F.CREW_UNIFORM_PATTERN_ID
        _G.AddOutfitCrewColor = PERSIST.crewColor
        _G.AddOutfitCrewPattern = PERSIST.crewPattern
        local cch = F.cache()
        local any = false
        for _, s in ipairs(PERSIST_SLOTS) do
            local res = tonumber(saved[s[1]]) or
                            tonumber(
                                PERSIST.configSlots and
                                    PERSIST.configSlots[s[1]])
            if res and res > 0 and not cch[s[2]] then
                local ins = R.resToIns[res]
                if ins then
                    cch[s[2]], cch[s[3]] = res, ins
                    _G[s[4]] = res
                    any = true
                end
            end
        end
        PERSIST.configWeapons = F.sanitizeConfigWeapons(saved.weapons or
                                                            PERSIST.configWeapons)
        if saved.weapons and F.reapplyWeaponsFromConfig() then any = true end
        if saved.vehicleSlots then
            PERSIST.configVehicleSlots = saved.vehicleSlots
            if F.reapplyVehicleSlotsFromConfig(true) then any = true end
        end
        if saved.hallTheme then
            PERSIST.hallThemeResID = tonumber(saved.hallTheme)
            if PERSIST.hallThemeResID and F.reapplyHallThemeFromConfig(true) then
                any = true
            end
        end
        if saved.chassisLight then
            PERSIST.configChassisLight = tonumber(saved.chassisLight)
        end
        if saved.chassisLightMap then
            PERSIST.configChassisLightMap = saved.chassisLightMap
        end
        if any then
            _matchApplied = false
            F.perfInvalidateLobby()
        end
    end

    function F.getEntity()
        local ok, dc = pcall(require,
                             "client.slua.logic.wardrobe.logic_wardrobe_data_center")
        if not ok or not dc then return nil end
        local ok2, e = pcall(dc.GetWardrobeData)
        return ok2 and e or nil
    end

    
    
    
    function F.applyCrewUniformColorMetadata(entity, resID, insID)
        local colorIndex = F.CREW_UNIFORM_COLORS[tonumber(resID)]
        if not colorIndex or not entity then return nil end

        local data
        pcall(function()
            if entity.GetDataByInsID then
                data = entity:GetDataByInsID(insID)
            end
        end)
        if not data and entity.ResIDToIndexArrayMap and entity._data then
            local indices = entity.ResIDToIndexArrayMap[resID]
            if indices then
                for _, index in pairs(indices) do
                    local candidate = entity._data[index]
                    if candidate and
                        tonumber(candidate.insID or candidate.instid) ==
                        tonumber(insID) then
                        data = candidate
                        break
                    end
                end
            end
        end
        if data then
            pcall(function()
                
                
                
                data.color = colorIndex
                data.Color = colorIndex
                data.color_id = colorIndex
                data.colorID = colorIndex
                data.ColorID = colorIndex
                local pattern = F.getCrewSelectorPattern(resID)
                pattern = math.max(0, math.min(14, pattern))
                data.pattern = pattern
                data.Pattern = pattern
                data.pattern_id = pattern
                data.patternID = pattern
                data.PatternID = pattern
            end)
        end
        return colorIndex
    end

    function F.firstInsForRes(entity, resID)
        local arr = entity.ResIDToIndexArrayMap and
                        entity.ResIDToIndexArrayMap[resID]
        if not arr then return nil end
        for _, idx in pairs(arr) do
            local d = entity._data[idx]
            if d and d.count and d.count > 0 then return d.insID end
        end
        return nil
    end

    function F.injectOne(entity, resID, insID)
        
        
        local mappedIns = tonumber(R.resToIns[tonumber(resID)])
        if mappedIns and mappedIns >= INS_BASE and entity then
            local existing
            pcall(function()
                if entity.GetDataByInsID then
                    existing = entity:GetDataByInsID(mappedIns)
                end
            end)
            if existing then
                existing.count = 1
                existing.lock_cnt = 0
                existing.expire_ts = 0
                if existing.expireTS ~= nil then
                    existing.expireTS = 0
                end
                F.ensureInjectedItemAlive(entity, resID, mappedIns)
                F.applyCrewUniformColorMetadata(entity, resID, mappedIns)
                F.indexWeaponSkin(resID, mappedIns)
                return true
            end
        end
        local ownedIns = F.firstInsForRes(entity, resID)
        if ownedIns then
            F.ensureInjectedItemAlive(entity, resID, ownedIns)
            F.applyCrewUniformColorMetadata(entity, resID, ownedIns)
            R.resToIns[resID] = ownedIns
            R.insToRes[ownedIns] = resID
            F.indexWeaponSkin(resID, ownedIns)
            return true
        end
        local row = {
            instid = insID,
            res_id = resID,
            count = 1,
            lock_cnt = 0,
            isnew = 0,
            valid_hours = 0,
            expire_ts = 0
        }
        local crewColor = F.CREW_UNIFORM_COLORS[tonumber(resID)]
        if crewColor then
            row.color = crewColor
            row.Color = crewColor
            row.color_id = crewColor
            row.colorID = crewColor
            row.ColorID = crewColor
            local pattern = F.getCrewSelectorPattern(resID)
            row.pattern = pattern
            row.Pattern = pattern
            row.pattern_id = pattern
            row.patternID = pattern
            row.PatternID = pattern
        end
        local addedData = entity:AddData(row)
        pcall(function()
            if crewColor and addedData then
                local baseCfg = F.cfg(F.CREW_UNIFORM_BASE_RES)
                if baseCfg then
                    addedData.itemType = baseCfg.ItemType
                    addedData.itemSubType = baseCfg.ItemSubType
                    addedData.mainTabType = baseCfg.WardrobeMainTab
                    addedData.subTabType = baseCfg.WardrobeTab
                    addedData.itemQuality = baseCfg.ItemQuality
                    addedData.bConfigLoaded = true
                end
            elseif entity.LoadConfigForData and CDataTable and
                CDataTable.GetTableData then
                local idx = entity._DataCount
                if idx and entity._data[idx] then
                    entity:LoadConfigForData(entity._data[idx],
                                             CDataTable.GetTableData)
                end
            end
        end)
        F.applyCrewUniformColorMetadata(entity, resID, insID)
        R.insToRes[insID] = resID
        R.resToIns[resID] = insID
        F.indexWeaponSkin(resID, insID)
        return true
    end

    function F.reviveExpiredOwned(entity)
        entity = entity or F.getEntity()
        if not entity or not entity.bInit or not entity._data then return end
        local now = 0
        pcall(function()
            local TimeUtil = require("client.common.time_util")
            now = tonumber(TimeUtil.GetServerTimeInSec()) or 0
        end)
        if now <= 0 then return end
        _G.AddOutfitRevived = _G.AddOutfitRevived or {}
        local n = 0
        for i = 1, (entity._DataCount or #entity._data) do
            local d = entity._data[i]
            if d then
                local exp = tonumber(d.expire_ts or d.expireTS) or 0
                local res = tonumber(d.res_id or d.resID)
                local ins = tonumber(d.instid or d.insID)
                if exp > 0 and exp <= now and res and ins and
                    (tonumber(d.count) or 0) > 0 then
                    d.expire_ts = 0
                    if d.expireTS ~= nil then d.expireTS = 0 end
                    if d.valid_hours ~= nil then
                        d.valid_hours = 0
                    end
                    _G.AddOutfitRevived[res] = ins
                    n = n + 1
                end
            end
        end
    end

    function F.mergeRevivedIntoMaps()
        for res, ins in pairs(_G.AddOutfitRevived or {}) do
            if not R.resToIns[res] then
                R.resToIns[res] = ins
                R.insToRes[ins] = res
                F.indexWeaponSkin(res, ins)
            end
        end
    end

    function F.injectArmory(resID, insID)
        if not F.isEnabled() then return false end
        local wid = F.weaponIdFromSkin(resID)
        if not wid then return false end
        local Arm = require("client.logic.armory.logic_armory")
        Arm.rsp_list = Arm.rsp_list or {skin_list = {}, install_list = {}}
        Arm.rsp_list.skin_list = Arm.rsp_list.skin_list or {}
        Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
        if not Arm.rsp_list.skin_list[wid] then
            Arm.rsp_list.skin_list[wid] = {}
        end
        Arm.rsp_list.skin_list[wid][resID] = {is_open = 1}
        Arm.WardrobeInsList = Arm.WardrobeInsList or {}
        Arm.WardrobeInsList[resID] = insID
        return true
    end

    function F.mergeInjectedArmorySkins()
        if not F.isEnabled() then return false end
        for _, skins in pairs(R.byWeapon) do
            for resID, insID in pairs(skins) do
                F.injectArmory(resID, insID)
            end
        end
        return true
    end

    function F.injectAll(entity)
        if not F.isEnabled() then return false end
        entity = entity or F.getEntity()
        if not entity or not entity.bInit then return false end
        local n, nNew = 0, 0
        for i, resID in ipairs(ITEMS) do
            
            
            
            local itemCfg = F.cfg(resID)
            if itemCfg then
                local insID = INS_BASE + i
                local had = R.resToIns[resID] ~= nil
                if F.injectOne(entity, resID, insID) then
                    n = n + 1
                    if not had then nNew = nNew + 1 end
                    if GUN_SUB[F.subType(itemCfg)] or F.subType(itemCfg) ==
                        MELEE_ID then
                        F.injectArmory(resID, insID)
                    end
                end
            end
        end
        if not _G.AddOutfitUnexpireDone then
            _G.AddOutfitUnexpireDone = true
            pcall(F.reviveExpiredOwned, entity)
        end
        F.mergeRevivedIntoMaps()
        F.sanitizeAllInjectedExpire()
        F.ensureInjectedResources()
        return n > 0
    end

    function F.refreshWardrobe()
        pcall(function()
            if EventSystem and EVENTTYPE_WARDROBE then
                if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                          EVENTID_WARDROBE_UPDATE_ITEM_LIST)
                end
                if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                          EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
                end
                if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                          EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
                end
            end
        end)
    end

    function F.refreshWardrobeOnce()
        if LOBBY.wardrobeRefreshed then return end
        LOBBY.wardrobeRefreshed = true
        F.refreshWardrobe()
    end

    function F.scheduleInjectRefresh()
        LOBBY.injectRefreshGen = (LOBBY.injectRefreshGen or 0) + 1
        local gen = LOBBY.injectRefreshGen
        F.later(0.4, function()
            if gen ~= LOBBY.injectRefreshGen then return end
            F.refreshWardrobe()
        end)
    end

    function F.putOnOutfit(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or
                           wd:GetHallDepotItemDataByInsID(insID)
            resID = d0 and tonumber(d0.resID or d0.res_id)
        end
        if not resID or resID <= 0 then return end
        if not R.insToRes[insID] then
            R.insToRes[insID] = resID;
            R.resToIns[resID] = insID
        end
        F.ensureDepotItemValid(insID, resID)
        if not F.CREW_UNIFORM_COLORS[resID] and
            not F.isResourcesReady(resID) then
            F.requestResourceDownload(resID)
            return
        end
        if not F.isSuitRes(resID) then
            if F.isTshirtRes(resID) then
                return F.putOnRoleWear(insID)
            end
            return
        end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetHallDepotItemDataByInsID(insID)
        if not d then return end

        local suitFilter = function(r) return F.isSuitRes(r) end
        local oldIns, oldRes = F.findWornInsBySubType(OUTFIT_SUB, suitFilter)
        F.removeRoleWearBySubType(OUTFIT_SUB, suitFilter)
        F.saveEquip(resID, insID)

        local slot = F.getRoleWearSlotIndex(OUTFIT_SUB, PKG_SLOT)

        local olditem
        if oldIns and oldIns ~= insID then
            local previousRes = oldRes or R.insToRes[oldIns]
            if F.CREW_UNIFORM_COLORS[tonumber(previousRes)] then
                previousRes = F.CREW_UNIFORM_BASE_RES
            end
            olditem = {res_id = previousRes, count = 1, instid = oldIns}
        end

        local WRH = require("client.network.Protocol.WardRobeHandler")
        local item = {res_id = resID, count = 1, instid = insID}
        WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

        pcall(function()
            local av = require(
                           "client.slua.logic.wardrobe.logic_wardrobe_avatar")
            av:AddToWearInfo(OUTFIT_SUB, insID, resID, 0, 0)
            F.syncFashionBagRolewear()
        end)
    end

    function F.putOnHat(insID)
        insID = tonumber(insID)
