    function F.canRoleWear(resID, st)
        st = st or F.subType(F.cfg(resID))
        if FACE_SUBS[st] or BODY_SUBS[st] then return true end
        if st == GLOVES_SUB then return true end
        if st == OUTFIT_SUB and F.wardrobeTab(resID) == TAB_CLOTHES then
            return true
        end
        return false
    end

    F.putOnRoleWear = function(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or
                           wd:GetHallDepotItemDataByInsID(insID)
            resID = d0 and tonumber(d0.resID or d0.res_id)
        end
        if not resID or resID <= 0 then return end
        if not R.insToRes[insID] then
            R.insToRes[insID] = resID;
            R.resToIns[resID] = insID
        end
        F.ensureDepotItemValid(insID, resID)
        if not F.CREW_UNIFORM_COLORS[resID] and
            not F.isResourcesReady(resID) then
            F.requestResourceDownload(resID)
            return
        end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetHallDepotItemDataByInsID(insID)
        if not d then return end
        local st = F.subType(F.cfg(resID)) or tonumber(d.itemSubType)
        if not F.canRoleWear(resID, st) then return end

        local filterFn
        if st == OUTFIT_SUB then
            filterFn = function(r)
                return F.wardrobeTab(r) == TAB_CLOTHES
            end
        end
        local oldIns, oldRes = F.findWornInsBySubType(st, filterFn)
        F.removeRoleWearBySubType(st, filterFn)
        F.saveEquip(resID, insID)

        local slot = F.getRoleWearSlotIndex(st, PKG_SLOT)

        local olditem
        if oldIns and oldIns ~= insID then
            local previousRes = oldRes or R.insToRes[oldIns]
            if F.CREW_UNIFORM_COLORS[tonumber(previousRes)] then
                previousRes = F.CREW_UNIFORM_BASE_RES
            end
            olditem = {res_id = previousRes, count = 1, instid = oldIns}
        end

        local WRH = require("client.network.Protocol.WardRobeHandler")
        local crewColor = F.CREW_UNIFORM_COLORS[resID]
        
        
        
        local wearResID, wearColor, wearPattern = resID, d.color,
                                                  tonumber(
                                                      d.pattern or d.Pattern or
                                                          d.pattern_id or
                                                          d.patternID or
                                                          d.PatternID) or 0
        if crewColor or resID == F.CREW_UNIFORM_BASE_RES then
            wearResID, wearColor, wearPattern =
                F.rememberCrewUniformCustomization(resID, d)
        end
        local item = {
            res_id = wearResID,
            count = 1,
            instid = insID,
            color = wearColor,
            pattern = wearPattern,
            color_id = wearColor,
            colorID = wearColor,
            pattern_id = wearPattern,
            patternID = wearPattern
        }
        WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

        if crewColor then
            
            
            pcall(function()
                local avatar = require(
                                   "client.slua.logic.wardrobe.logic_wardrobe_avatar")
                avatar:AddToWearInfo(OUTFIT_SUB, insID, wearResID, wearColor,
                                     wearPattern)
                if DataMgr and DataMgr.UpdateRoleWearData then
                    DataMgr.UpdateRoleWearData(insID, oldIns or 0)
                end
                if avatar.AvatarChange then
                    avatar:AvatarChange(wearResID, true, wearColor, wearPattern)
                end
            end)
            pcall(function()
                local entity = F.getEntity()
                F.applyCrewUniformColorMetadata(entity, resID, insID)
            end)
        end

        if BAG_SUBS[st] or HELMET_SUBS[st] then
            pcall(function()
                DataMgr.equipmentSkinInsIDTable =
                    DataMgr.equipmentSkinInsIDTable or {}
                DataMgr.equipmentSkinInsIDTable[st] = insID
                local fbd = require(
                                "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local bag = fbd.GetCurrentFashionBag and
                                fbd:GetCurrentFashionBag()
                if bag then
                    if st == 504 or st == 501 then
                        DataMgr.equipmentSkinInsIDTable[504] = insID
                        bag.bag_skin = insID
                    elseif st == 505 or st == 502 then
                        DataMgr.equipmentSkinInsIDTable[505] = insID
                        bag.helmet_skin = insID
                    end
                end
            end)
            if F.applyLobbyEquipmentPreview then
                local cch = F.cache()
                F.applyLobbyEquipmentPreview(cch.bagRes, cch.helmetRes)
            end
        end

        pcall(function() F.syncFashionBagRolewear() end)
        F.invalidateSocialWearCache()
    end

    function F.putOnGloves(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or
