        end)
        pcall(function()
            if EventSystem and EVENTTYPE_WARDROBE then
                if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                          EVENTID_WARDROBE_UPDATE_ITEM_LIST)
                end
                if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                          EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
                end
            end
        end)
        F.invalidateSocialWearCache()
    end

    function F.ensureDepotItemValid(insID, resID)
        insID = tonumber(insID)
        if not insID then return end
        pcall(function()
            local entity = F.getEntity()
            if entity and entity.GetDataByInsID then
                local d = entity:GetDataByInsID(insID)
                if d then
                    d.expire_ts = 0
                    if d.expireTS ~= nil then d.expireTS = 0 end
                    if d.valid_hours ~= nil then
                        d.valid_hours = 0
                    end
                end
            end
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local hd = wd:GetHallDepotItemDataByInsID(insID)
            if hd then
                hd.expire_ts = 0
                if hd.expireTS ~= nil then hd.expireTS = 0 end
                if hd.valid_hours ~= nil then hd.valid_hours = 0 end
            end
        end)
    end

    function F.clearItemExpire(itemData, insID, resID)
        F.ensureDepotItemValid(insID, resID)
        if type(itemData) == "table" then
            itemData.expireTS = 0
            itemData.expire_ts = 0
            itemData.expireTs = 0
        end
    end

    function F.onGlideClick(self, itemData)
        if not itemData then return end
        local insID = tonumber(itemData.ins_id)
        local resID = tonumber(itemData.res_id)
        F.clearItemExpire(itemData, insID, resID)
        local isGlide = resID and F.isGlideRes(resID)
        if not isGlide and itemData.itemSubType then
            isGlide = GLIDER_SUBS[tonumber(itemData.itemSubType)] == true
        end
        if insID and resID and isGlide then
            F.saveEquip(resID, insID)
            if F.putOnGlider(insID) then
                pcall(function()
                    if self.ShowGlide then
                        self:ShowGlide(resID)
                    end
                    if self.ChangeItemStatus then
                        self:ChangeItemStatus(insID, true)
                    end
                end)
                return
            end
        end
        if _G.AddOutfitGlideClickOrig then
            F.clearItemExpire(itemData, insID, resID)
            return _G.AddOutfitGlideClickOrig(self, itemData)
        end
    end

    function F.onParachuteClick(self, itemData)
        if not itemData then return end
        local insID = tonumber(itemData.ins_id)
        local resID = tonumber(itemData.res_id)
        F.clearItemExpire(itemData, insID, resID)
        if insID and resID and F.isParachuteRes(resID) then
            F.saveEquip(resID, insID)
            if F.putOnParachute(insID) then
                pcall(function()
                    if self.ChangeItemStatus then
                        self:ChangeItemStatus(insID, true)
                    end
                end)
                return
            end
        end
        if _G.AddOutfitParaClickOrig then
            return _G.AddOutfitParaClickOrig(self, itemData)
        end
    end

    function F.hookAirborneClick()
        pcall(function()
            local WG = require("client.slua.umg.Wardrobe.subtab_gliding")
            if WG then
                if not WG._AddOutfitGlideWrapped then
                    WG._AddOutfitGlideWrapped = true
                    _G.AddOutfitGlideClickOrig = WG.ClickItem
                end
                WG.ClickItem = function(self, itemData)
                    return F.onGlideClick(self, itemData)
                end
            end
            local WP = require("client.slua.umg.Wardrobe.subtab_parachute")
            if WP then
                if not WP._AddOutfitParaWrapped then
                    WP._AddOutfitParaWrapped = true
                    _G.AddOutfitParaClickOrig = WP.ClickItem
                end
                WP.ClickItem = function(self, itemData)
                    return F.onParachuteClick(self, itemData)
                end
            end
        end)
        pcall(function()
            local fbd = require(
                            "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            if fbd and not fbd._AddOutfitAirborneFBHooked then
                fbd._AddOutfitAirborneFBHooked = true
                local oG = fbd.UpdateAircraftOrGliding
                fbd.UpdateAircraftOrGliding =
                    function(self, putOnID, bAircraft)
                        local r = oG(self, putOnID, bAircraft)
                        local ins = tonumber(putOnID)
                        if ins and ins > 0 then
                            local wd = require(
                                           "client.slua.logic.wardrobe.wardrobe_data")
                            local d =
                                wd:GetValidHallDepotItemDataByInsID(ins) or
                                    wd:GetHallDepotItemDataByInsID(ins)
                            local res = d and tonumber(d.resID)
                            if res and F.isGlideRes(res) then
                                F.saveEquip(res, ins)
                            end
                        end
                        return r
                    end
                local oP = fbd.UpdateParachute
                if oP then
                    fbd.UpdateParachute =
                        function(self, insID)
                            local r = oP(self, insID)
                            local ins = tonumber(insID)
                            if ins and ins > 0 then
                                local wd = require(
                                               "client.slua.logic.wardrobe.wardrobe_data")
                                local d =
                                    wd:GetValidHallDepotItemDataByInsID(ins) or
                                        wd:GetHallDepotItemDataByInsID(ins)
                                local res = d and tonumber(d.resID)
                                if res and F.isParachuteRes(res) then
                                    F.saveEquip(res, ins)
                                end
                            end
                            return r
                        end
                end
            end
        end)
        pcall(function()
            if not ModuleManager or not ModuleManager.GetModule then
                return
            end
            local FB = ModuleManager.GetModule(
                           ModuleManager.LobbyModuleConfig.FashionBagEditUtils)
            if FB and not FB._AddOutfitFBBagHooked then
                FB._AddOutfitFBBagHooked = true
                local o = FB.PutOnFashionBagItem
                FB.PutOnFashionBagItem =
                    function(self, itemData)
                        if itemData then
                            F.clearItemExpire(itemData, itemData.ins_id,
                                              itemData.res_id)
                        end
                        local r = o(self, itemData)
                        if itemData then
                            local res = tonumber(itemData.res_id)
                            local ins = tonumber(itemData.ins_id)
                            if res and ins and
                                (F.isGlideRes(res) or F.isParachuteRes(res)) then
                                F.saveEquip(res, ins)
                            end
                        end
                        return r
                    end
            end
        end)
    end

    function F.putOnParachute(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetValidHallDepotItemDataByInsID(insID) or
                          wd:GetHallDepotItemDataByInsID(insID)
            resID = d and tonumber(d.resID)
        end
        if not resID or not F.isParachuteRes(resID) then return false end
        if not R.insToRes[insID] then R.insToRes[insID] = resID end
        F.ensureDepotItemValid(insID, resID)
        F.saveEquip(resID, insID)
        F.ensureInjectedItemAlive(nil, resID, insID)
        local ready = F.isResourcesReady(resID)
        if not ready then F.requestResourceDownload(resID) end
        pcall(function()
            local fbd = require(
                            "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            if fbd.SetParachute then fbd:SetParachute(insID) end
            if fbd.UpdateParachute then fbd:UpdateParachute(insID) end
        end)
        if ready then
            local item = {
                res_id = resID,
                resID = resID,
                instid = insID,
                ins_id = insID,
                insID = insID,
                expire_ts = 0,
                expireTS = 0,
                count = 1
            }
            local WRH = require("client.network.Protocol.WardRobeHandler")
            WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
        end
        return true
    end

    function F.putOnGlider(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetValidHallDepotItemDataByInsID(insID) or
                          wd:GetHallDepotItemDataByInsID(insID)
            resID = d and tonumber(d.resID)
        end
        if not resID or resID <= 0 then return false end
        local st = F.depotSubType(insID, resID)
        if not F.isGlideRes(resID) and not GLIDER_SUBS[st] then
            return false
        end
        if not R.insToRes[insID] then R.insToRes[insID] = resID end
        F.ensureDepotItemValid(insID, resID)
        F.saveEquip(resID, insID)
        F.ensureInjectedItemAlive(nil, resID, insID)
        local ready = F.isResourcesReady(resID)
        if not ready then F.requestResourceDownload(resID) end
        local bAircraft = false
        pcall(function()
            local ModelDisplayTypeHelper = require(
                                               "client.logic.avatar.ModelDisplayTypeHelper")
            local st = F.subType(F.cfg(resID))
            bAircraft = ModelDisplayTypeHelper.IsGlideSmoke(st)
        end)
        pcall(function()
            local fbd = require(
                            "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            if fbd.UpdateAircraftOrGliding then
                fbd:UpdateAircraftOrGliding(insID, bAircraft)
            elseif fbd.SetGliding then
                fbd:SetGliding(insID)
                if DataMgr.UpdateEffect then
                    DataMgr.UpdateEffect(insID)
                end
            end
        end)
        if ready then
            local item = {
                res_id = resID,
                resID = resID,
                instid = insID,
                ins_id = insID,
                insID = insID,
                expire_ts = 0,
                expireTS = 0,
                count = 1
            }
            local WRH = require("client.network.Protocol.WardRobeHandler")
            WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
        end
        return true
    end

    function F.syncAirborneToDataMgr()
        F.applyPersistSlotsToCache()
        local cch = F.cache()
        local paraRes = F.getDesiredParachuteRes()
        local gliderRes = F.getDesiredGliderRes()
        if paraRes and paraRes > 0 and not cch.parachuteIns then
            cch.parachuteIns = F.resolveInsForRes(paraRes)
            cch.parachuteRes = paraRes
        end
        if gliderRes and gliderRes > 0 and not cch.gliderIns then
            cch.gliderIns = F.resolveInsForRes(gliderRes)
            cch.gliderRes = gliderRes
        end
        pcall(function()
            local fbd = require(
                            "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            if cch.parachuteIns and tonumber(cch.parachuteIns) > 0 then
                if fbd.SetParachute then
                    fbd:SetParachute(cch.parachuteIns)
                end
                if DataMgr.roleData then
                    DataMgr.roleData.parachute = tostring(cch.parachuteIns)
                end
            end
            if cch.gliderIns and tonumber(cch.gliderIns) > 0 then
                local bAircraft = false
                if cch.gliderRes then
                    pcall(function()
                        local MDH = require(
                                        "client.logic.avatar.ModelDisplayTypeHelper")
                        bAircraft = not MDH.IsGlideSmoke(F.subType(F.cfg(
                                                                       cch.gliderRes)))
                    end)
                end
                if fbd.UpdateAircraftOrGliding then
                    fbd:UpdateAircraftOrGliding(cch.gliderIns, bAircraft)
                elseif fbd.SetGliding then
                    fbd:SetGliding(cch.gliderIns)
                    if DataMgr.UpdateEffect then
                        DataMgr.UpdateEffect(cch.gliderIns)
                    end
                end
                if DataMgr.roleData then
                    if bAircraft then
                        DataMgr.roleData.aircraft_put_id = tostring(
                                                               cch.gliderIns)
                        DataMgr.gliding = cch.gliderIns
                    else
                        DataMgr.roleData.gliding = tostring(cch.gliderIns)
                    end
                end
            end
        end)
    end

    function F.putOnGenericInjected(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then return end
        if not F.isResourcesReady(resID) then
            F.requestResourceDownload(resID)
            return
        end
        F.saveEquip(resID, insID)
        local WRH = require("client.network.Protocol.WardRobeHandler")
        WRH.on_depot_put_on_rsp(NET_OK,
                                {res_id = resID, count = 1, instid = insID},
                                nil, 1, insID, 0)
    end

    function F.clearEquipCache(resID)
        local st = F.subType(F.cfg(resID))
        local cch = F.cache()
        if st == OUTFIT_SUB then
            if F.wardrobeTab(resID) == TAB_CLOTHES then
                cch.tshirtRes, cch.tshirtIns = nil, nil
                _G.AddOutfitLastLobbyTshirtRes = nil
                F.persistForgetSlot("tshirt")
            else
                cch.outfitRes, cch.outfitIns = nil, nil
                _G.AddOutfitLastLobbyOutfitRes = nil
                F.persistForgetSlot("outfit")
            end
        elseif st == HAT_SUB or HEAD_SUBS[st] then
            cch.hatRes, cch.hatIns = nil, nil
            _G.AddOutfitLastLobbyHatRes = nil
            F.persistForgetSlot("hat")
        elseif st == MASK_SUB then
            cch.maskRes, cch.maskIns = nil, nil
            _G.AddOutfitLastLobbyMaskRes = nil
            F.persistForgetSlot("mask")
        elseif st == GLASS_SUB then
            cch.glassRes, cch.glassIns = nil, nil
            _G.AddOutfitLastLobbyGlassRes = nil
            F.persistForgetSlot("glass")
        elseif st == PANTS_SUB then
            cch.pantsRes, cch.pantsIns = nil, nil
            _G.AddOutfitLastLobbyPantsRes = nil
            F.persistForgetSlot("pants")
        elseif st == SHOES_SUB then
            cch.shoesRes, cch.shoesIns = nil, nil
            _G.AddOutfitLastLobbyShoesRes = nil
            F.persistForgetSlot("shoes")
        elseif BAG_SUBS[st] then
            
            
            
            if tonumber(cch.bagRes) and tonumber(cch.bagRes) ~= tonumber(resID) then
                F.skinDiag("STALE_PUTDOWN",
                           "slot=bag removed=" .. tostring(resID) ..
                               " selected=" .. tostring(cch.bagRes), 0)
                return
            end
            cch.bagRes, cch.bagIns = nil, nil
            _G.AddOutfitLastLobbyBagRes = nil
            F.persistForgetSlot("bag")
        elseif HELMET_SUBS[st] then
            if tonumber(cch.helmetRes) and tonumber(cch.helmetRes) ~=
                tonumber(resID) then
                F.skinDiag("STALE_PUTDOWN",
                           "slot=helmet removed=" .. tostring(resID) ..
                               " selected=" .. tostring(cch.helmetRes), 0)
                return
            end
            cch.helmetRes, cch.helmetIns = nil, nil
            _G.AddOutfitLastLobbyHelmetRes = nil
            F.persistForgetSlot("helmet")
        elseif st == PARACHUTE_SUB then
            cch.parachuteRes, cch.parachuteIns = nil, nil
            _G.AddOutfitLastLobbyParachuteRes = nil
            F.persistForgetSlot("parachute")
        elseif F.isGlideRes(resID) then
            cch.gliderRes, cch.gliderIns = nil, nil
            _G.AddOutfitLastLobbyGliderRes = nil
            F.persistForgetSlot("glider")
        elseif st == GLOVES_SUB then
            cch.glovesRes, cch.glovesIns = nil, nil
            _G.AddOutfitLastLobbyGlovesRes = nil
            F.persistForgetSlot("gloves")
        end
        _matchApplied = false
        F.invalidateSocialWearCache()
        F.perfInvalidateLobby()
        F.persistMarkDirty()
    end

    function F.takeOffInjected(insID)
        insID = tonumber(insID)
        local resID = R.insToRes[insID]
        if not resID then return end
        local st = F.subType(F.cfg(resID))

        pcall(function()
            local WRH = require("client.network.Protocol.WardRobeHandler")
            WRH.on_depot_put_down_rsp(NET_OK, {res_id = resID, count = 1}, insID)
        end)

        pcall(function()
            local AvatarData = require("client.logic.data.AvatarData")
            AvatarData.RemoveRoleWearDataByValue(insID)
        end)
        if st == HAT_SUB or HEAD_SUBS[st] then
            pcall(function()
                local fbd = require(
                                "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local bag = fbd.GetCurrentFashionBag and
                                fbd:GetCurrentFashionBag()
                if bag and tonumber(bag.head_show) == insID then
                    fbd:SetHeadShow(0)
                end
            end)
        end
        if BAG_SUBS[st] or HELMET_SUBS[st] then
            pcall(function()
                local t = DataMgr.equipmentSkinInsIDTable
                if t then
                    for _, k in ipairs({st, 504, 505}) do
                        if tonumber(t[k]) == insID then
                            t[k] = 0
                        end
                    end
                end
                local fbd = require(
                                "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local bag = fbd.GetCurrentFashionBag and
                                fbd:GetCurrentFashionBag()
                if bag then
                    if tonumber(bag.bag_skin) == insID then
                        bag.bag_skin = 0
                    end
                    if tonumber(bag.helmet_skin) == insID then
                        bag.helmet_skin = 0
                    end
                end
            end)
        end

        F.clearEquipCache(resID)
        pcall(function() F.syncFashionBagRolewear() end)
    end

    function F.syncWeaponArmorySilent(weaponID, insID)
        weaponID, insID = tonumber(weaponID), tonumber(insID)
        if not weaponID or not insID or not F.isInjectedIns(insID) then
            return
        end
        local resID = R.insToRes[insID]
        if not resID then return end
        local Arm = require("client.logic.armory.logic_armory")
        Arm.rsp_list = Arm.rsp_list or {skin_list = {}, install_list = {}}
        Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
        F.injectArmory(resID, insID)
        local fbd = nil
        pcall(function()
            fbd = require(
                      "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        end)
        if F.subType(F.cfg(resID)) == MELEE_ID then
            weaponID = F.normalizeMeleeWeaponID(F.weaponIdFromSkin(resID)) or
                           F.normalizeMeleeWeaponID(weaponID) or weaponID
        end
        Arm.rsp_list.install_list[weaponID] = {skin_id = insID}
        pcall(function()
            if fbd and fbd.UpdateCurrentFashionBagWeaponSkin then
                fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
            end
        end)
    end

    function F.equipWeaponSkin(weaponID, insID, forceVisual)
        weaponID, insID = F.normalizeMeleeWeaponID(weaponID), tonumber(insID)
        if not weaponID or not insID or not F.isInjectedIns(insID) then
            return false
        end
        local resID = R.insToRes[insID]
        if not resID then return false end
        if F.subType(F.cfg(resID)) == MELEE_ID then
            weaponID = F.normalizeMeleeWeaponID(F.weaponIdFromSkin(resID)) or
                           weaponID
        end

        _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
        if not forceVisual and F.isWeaponVisuallyEquipped(weaponID, insID) then
            F.syncWeaponArmorySilent(weaponID, insID)
            return false
        end
        F.saveEquip(resID, insID)

        local Arm = require("client.logic.armory.logic_armory")
        local fbd = require(
                        "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local HT = require("client.logic.lobby.hall_theme_utils")
        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")

        F.injectArmory(resID, insID)
        if F.subType(F.cfg(resID)) == MELEE_ID then
            weaponID = F.normalizeMeleeWeaponID(F.weaponIdFromSkin(resID)) or
                           weaponID
        end
        Arm.rsp_list.install_list[weaponID] = {skin_id = insID}
        if fbd.UpdateCurrentFashionBagWeaponSkin then
            fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
        end

        local bagIdx = fbd:GetFashionBagUseIndex()
        HT.proc_skin_list_chg("weapon_skin", weaponID, insID, bagIdx, {})

        wgl:SetGunID(weaponID)
        wgl:UpdateCurrentGunAvatar(weaponID, insID)

        if EventSystem and EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
            EventSystem:postEvent(EVENTTYPE_ARMORY,
                                  EVENTID_ARMORY_EQUIP_STAT_CHANGE, resID)
        end
        if EventSystem and EVENTTYPE_WARDROBE and
            EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
            EventSystem:postEvent(EVENTTYPE_WARDROBE,
                                  EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN,
                                  resID)
        end
        _G.AddOutfitWeaponEquipped[weaponID] = insID
        return true
    end

    local SOCIAL = _G.AddOutfitSocialState or {}
    _G.AddOutfitSocialState = SOCIAL
    SOCIAL.debGen = SOCIAL.debGen or 0
    SOCIAL.wearPatchKey = SOCIAL.wearPatchKey or nil
    SOCIAL.snapshotKey = SOCIAL.snapshotKey or nil
    SOCIAL.fullSnapshot = SOCIAL.fullSnapshot or nil

    function F.socialDebounce(sec, fn)
        SOCIAL.debGen = (SOCIAL.debGen or 0) + 1
        local gen = SOCIAL.debGen
        F.later(sec, function()
            if gen ~= SOCIAL.debGen then return end
            pcall(fn)
        end)
    end

    function F.getLobbyCurPage()
        local p = nil
        pcall(function()
            local LMC = require(
                            "client.slua.logic.lobby.Main.Lobby_Main_Control")
            if LMC.GetCurPage then p = LMC.GetCurPage() end
        end)
        return p
    end

    function F.isLobbyLeftPage()
        return ENUM_LobbyPageType and F.getLobbyCurPage() ==
                   ENUM_LobbyPageType.Left
    end

    function F.getWeaponSkinResFast()
        local cch = F.cache()
        local wid = tonumber(DataMgr.Weapon_ID) or 0
        local w = wid > 0 and cch.weapons[wid] or nil
        if w and w.resID and w.resID > 0 then return w.resID end
        for _, ww in pairs(cch.weapons) do
            if ww.resID and ww.resID > 0 then return ww.resID end
        end
        return nil
    end

    function F.resolveLobbyWeaponSkinRes()
        if LOBBY.skinResolved then return LOBBY.cachedSkin end
        local wid = tonumber(DataMgr.Weapon_ID) or 0
        local skin = F.getWeaponSkinResFast()
        if skin and skin > 0 then return skin end

        if wid > 0 then
            local fromMatch = F.getMatchWeaponSkin(wid)
            if fromMatch and fromMatch > 0 then return fromMatch end
        end
        if MATCH_CONFIG.weaponSkins then
            for _, sValue in pairs(MATCH_CONFIG.weaponSkins) do
                local s = tonumber(sValue)
                if s and s > 0 then return s end
            end
        end

        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            local entry = Arm.rsp_list and Arm.rsp_list.install_list and
                              Arm.rsp_list.install_list[wid > 0 and wid or
                                  101004]
            local insID = tonumber(entry and entry.skin_id) or 0
            if insID > 0 and F.isInjectedIns(insID) then
                skin = tonumber(R.insToRes[insID])
            elseif insID > 0 then
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local d = wd:GetHallDepotItemDataByInsID(insID)
                if d and d.resID then skin = tonumber(d.resID) end
            end
        end)
        if skin and skin > 0 then return skin end

        pcall(function()
            local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
            if wgl.GetSkinIdByWeaponID and wid > 0 then
                local insID = tonumber(wgl:GetSkinIdByWeaponID(wid)) or 0
                if insID > 0 and F.isInjectedIns(insID) then
                    skin = tonumber(R.insToRes[insID])
                end
            end
        end)
        LOBBY.skinResolved = true
        LOBBY.cachedSkin = (skin and skin > 0) and skin or nil
        return LOBBY.cachedSkin
    end

    function F.resolveLobbyOutfitRes()
        if LOBBY.outfitResolved then return LOBBY.cachedOutfit end
        local cch = F.cache()
        local outfitRes = tonumber(cch.outfitRes) or 0
        if outfitRes > 0 then
            LOBBY.outfitResolved = true
            LOBBY.cachedOutfit = outfitRes
            return outfitRes
        end
        outfitRes = tonumber(_G.AddOutfitLastLobbyOutfitRes) or 0
        if outfitRes > 0 then
            LOBBY.outfitResolved = true
            LOBBY.cachedOutfit = outfitRes
            return outfitRes
        end
        if MATCH_CONFIG.outfitRes and tonumber(MATCH_CONFIG.outfitRes) > 0 then
            LOBBY.outfitResolved = true
            LOBBY.cachedOutfit = tonumber(MATCH_CONFIG.outfitRes)
            return LOBBY.cachedOutfit
        end

        local injectedRes, anyRes
        pcall(function()
            local AvatarData = require("client.logic.data.AvatarData")
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local function resFromIns(ins)
                ins = tonumber(ins)
                if not ins or ins <= 0 then return nil end
                if F.isInjectedIns(ins) then
                    return tonumber(R.insToRes[ins])
                end
                local d = wd:GetHallDepotItemDataByInsID(ins)
                return d and tonumber(d.resID) or nil
            end
            for _, ins in pairs(AvatarData.GetRoleWear()) do
                local res = resFromIns(ins)
                if res and F.isSuitRes(res) then
                    if F.isInjectedRes(res) then
                        injectedRes = res
                    end
                    anyRes = anyRes or res
                end
            end
            local fbd = require(
                            "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
            if bag and bag.rolewear_list then
                for _, ins in pairs(bag.rolewear_list) do
                    local res = resFromIns(ins)
                    if res and F.isSuitRes(res) then
                        if F.isInjectedRes(res) then
                            injectedRes = res
                        end
                        anyRes = anyRes or res
                    end
                end
            end
        end)
        if injectedRes and injectedRes > 0 then
            LOBBY.outfitResolved = true
            LOBBY.cachedOutfit = injectedRes
            return injectedRes
        end
        if anyRes and anyRes > 0 then
            LOBBY.outfitResolved = true
            LOBBY.cachedOutfit = anyRes
            return anyRes
        end
        LOBBY.outfitResolved = true
        LOBBY.cachedOutfit = nil
        return nil
    end

    function F.rememberLobbyOutfitRes(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 or not F.isSuitRes(resID) then return end
        _G.AddOutfitLastLobbyOutfitRes = resID
        F.invalidateLobbyResolved()
        local cch = F.cache()
        if not cch.outfitRes or cch.outfitRes <= 0 then
            cch.outfitRes = resID
            if F.isInjectedRes(resID) then
                cch.outfitIns = R.resToIns[resID]
            end
        end
    end

    function F.wearPatchKey()
        local outfit = F.resolveLobbyOutfitRes() or 0
        local skin = F.resolveLobbyWeaponSkinRes() or 0
        local openGun = 1
        pcall(function()
            local lds = require(
                            "client.slua.logic.wardrobe.logic_display_setting")
            if lds.data and lds.data.OpenGun ~= nil then
                openGun = lds.data.OpenGun and 1 or 0
            end
        end)
        local parts = {
            tostring(outfit), tostring(skin), tostring(openGun),
            tostring(
                tonumber(_G.AddOutfitCrewColor) or tonumber(PERSIST.crewColor) or
                    0),
            tostring(
                tonumber(_G.AddOutfitCrewPattern) or
                    tonumber(PERSIST.crewPattern) or F.CREW_UNIFORM_PATTERN_ID)
        }
        local cch = F.cache()
        for _, slot in ipairs(PERSIST_SLOTS) do
            local value = tonumber(PERSIST.configSlots and
                                       PERSIST.configSlots[slot[1]]) or
                              tonumber(cch[slot[2]]) or 0
            parts[#parts + 1] = tostring(value)
        end
        return table.concat(parts, "_")
    end

    function F.syncDepotShowWeaponFlags(depot)
        depot = depot or {}
        pcall(function()
            local lds = require(
                            "client.slua.logic.wardrobe.logic_display_setting")
            if lds.data then
                if lds.data.OpenGun ~= nil then
                    depot.weapon = lds.data.OpenGun
                end
                if lds.data.OpenSocialWeapon ~= nil then
                    depot.social_weapon = lds.data.OpenSocialWeapon
                end
            end
        end)
        return depot
    end

    function F.applyInjectedPspace(roleData)
        if not roleData then return end
        roleData.bshow = true
        roleData.pspace_wear_ext = roleData.pspace_wear_ext or {}
        local cch = F.cache()
        local outfitRes =
            F.resolveLobbyOutfitRes() or tonumber(cch.tshirtRes) or
                tonumber(PERSIST.configSlots and PERSIST.configSlots.tshirt)
        if outfitRes and outfitRes > 0 then
            local crewBase, crewColor, crewPattern =
                F.getCrewUniformCustomization(outfitRes)
            roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = {
                crewBase or outfitRes, crewColor or 0, crewPattern or 0
            }
        end
        local skinRes = F.resolveLobbyWeaponSkinRes()
        if skinRes and skinRes > 0 then
            roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = {
                0, 0, 0
            }
            roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] =
                {skinRes, 0, 0}
            roleData.depot_show_info = roleData.depot_show_info or {}
            if roleData.depot_show_info.weapon == nil then
                roleData.depot_show_info.weapon = true
            end
        end
        roleData.depot_show_info = F.syncDepotShowWeaponFlags(
                                       roleData.depot_show_info)
    end

    function F.patchSelfWearCache(force)
        local key = F.wearPatchKey()
        if not force and SOCIAL.wearPatchKey == key then return false end
        SOCIAL.wearPatchKey = key
        SOCIAL.snapshotKey = nil
        SOCIAL.fullSnapshot = nil

        local myUid = tonumber(DataMgr.roleData.uid)
        if not myUid then return false end

        local changed = false
        pcall(function()
            local BD = ModuleManager.GetModule(
                           ModuleManager.DataModuleConfig
                               .BasicDataAvatarWearInfo)
            local d = BD:GetCacheData(myUid)
            if not d then
                BD:OnHandleMsgDataAndCallback(myUid,
                                              F.buildLocalRoleDataForCoupleAvatar())
                return true
            end
            local oldCloth = d.pspace_wear_ext and
                                 d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
            local oldSkin = d.pspace_wear_ext and
                                d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
            F.applyInjectedPspace(d)
            if F.mergeInjectedWearSlotsIntoWearData then
                F.mergeInjectedWearSlotsIntoWearData(d)
            end
            local nc = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
            local ns =
                d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
            if oldCloth ~= nc or oldSkin ~= ns or not d.bshow then
                changed = true
            end
        end)
        return force or changed
    end

    function F.requestSocialAvatarRefresh()
        pcall(function()
            if EventSystem and EVENTTYPE_LOBBY_SOCIAL and
                EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR then
                EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL,
                                      EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR)
            end
        end)
    end

    function F.onSocialWearDirty(forceRefresh)
        SOCIAL.lastHandSkin = nil
        if F.patchSelfWearCache(forceRefresh) then
            F.requestSocialAvatarRefresh()
        end
    end

    function F.buildLocalRoleDataForCoupleAvatar()
        local key = F.wearPatchKey()
        if SOCIAL.fullSnapshot and SOCIAL.snapshotKey == key then
            return SOCIAL.fullSnapshot
        end
        F.syncWeaponCacheFromLobby()
        local cch = F.cache()
        local ad = DataMgr.avatarData or {}
        local gender = tonumber(ad.gamegender) or 2
        if gender < 1 then gender = 2 end

        local data = {
            uid = DataMgr.roleData.uid,
            gender = gender,
            bshow = true,
            pspace_wear_ext = {
                [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HEAD] = {
                    tonumber(ad.headid) or 401993, 0, 0
                },
                [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HAIR] = {
                    tonumber(ad.hairid) or 40601001, 0, 0
                },
                [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = {0, 0, 0},
                [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = {0, 0, 0}
            },
            depot_show_info = {
                weapon = true,
                social_weapon = true,
                idle = true,
                helmet = true,
                bag = true,
                vehicle = true,
                hand = true
            },
            WearInfoList = {}
        }

        local outfitRes =
            F.resolveLobbyOutfitRes() or tonumber(cch.tshirtRes) or
                tonumber(PERSIST.configSlots and PERSIST.configSlots.tshirt)
        if outfitRes and outfitRes > 0 then
            local crewBase, crewColor, crewPattern =
                F.getCrewUniformCustomization(outfitRes)
            data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = {
                crewBase or outfitRes, crewColor or 0, crewPattern or 0
            }
        end

        local skinRes = F.resolveLobbyWeaponSkinRes()
        if skinRes and skinRes > 0 then
            data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON][1] = 0
            data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN][1] =
                skinRes
        end
        if F.mergeInjectedWearSlotsIntoWearData then
            F.mergeInjectedWearSlotsIntoWearData(data)
        end
        data.depot_show_info = F.syncDepotShowWeaponFlags(data.depot_show_info)
        SOCIAL.fullSnapshot = data
        SOCIAL.snapshotKey = F.wearPatchKey()
        return data
    end

    function F.isMyWearData(wearData)
        if not wearData then return false end
        local currentUID
        pcall(function()
            currentUID = tonumber(DataMgr and DataMgr.roleData and
                                      DataMgr.roleData.uid)
        end)
        return currentUID and tonumber(wearData.uid) == currentUID
    end

    function F.mergeInjectedWeaponIntoWearData(wearData)
        if not F.isMyWearData(wearData) then return end
        local skinRes = F.resolveLobbyWeaponSkinRes()
        wearData.depot_show_info = F.syncDepotShowWeaponFlags(
                                       wearData.depot_show_info)
        if not skinRes or skinRes <= 0 then return end
        wearData.mainWeaponInfo = wearData.mainWeaponInfo or {
            weaponResId = 0,
            weaponSkinId = 0,
            diyInfo = {
                diyWeaponId = 0,
                diyDefaultScheme = false,
                diyScheme = nil
            }
        }
        if wearData.mainWeaponInfo.weaponSkinId == skinRes and
            (tonumber(wearData.mainWeaponInfo.weaponResId) or 0) == 0 then
            return
        end
        wearData.mainWeaponInfo.weaponSkinId = skinRes
        wearData.mainWeaponInfo.weaponResId = 0
    end

    function F.equipSocialHandWeapon(avatar, skinRes)
        if not avatar or not skinRes or skinRes <= 0 then return end
        if SOCIAL.lastHandSkin == skinRes then return end
        SOCIAL.lastHandSkin = skinRes
        pcall(function()
            avatar:PutonEquipment(skinRes, nil, {bIsUse = true})
        end)
    end

    function F.shouldShowHandWeapon()
        local show = true
        pcall(function()
            local lds = require(
                            "client.slua.logic.wardrobe.logic_display_setting")
            if lds.data and lds.data.OpenGun ~= nil then
                show = lds.data.OpenGun ~= false
            end
        end)
        return show
    end

    function F.mergeInjectedOutfitIntoWearData(wearData)
        if not F.isMyWearData(wearData) then return end
        local outfitRes = F.resolveLobbyOutfitRes()
        if not outfitRes or outfitRes <= 0 then return end
        F.rememberLobbyOutfitRes(outfitRes)
        local AvatarData = require("client.logic.data.AvatarData")
        local crewBase, crewColor, crewPattern =
            F.getCrewUniformCustomization(outfitRes)
        local converted = AvatarData.ConvertToAvatarCustom({
            crewBase or outfitRes, crewColor or 0, crewPattern or 0
        })
        if not converted then return end
        wearData.WearInfoList = wearData.WearInfoList or {}
        local replaced = false
        for i, e in ipairs(wearData.WearInfoList) do
            if e and e.ItemID and F.isSuitRes(e.ItemID) then
                wearData.WearInfoList[i] = converted
                replaced = true
                break
            end
        end
        if not replaced then
            table.insert(wearData.WearInfoList, converted)
        end
    end

    function F.mergeInjectedWearSlotsIntoWearData(wearData)
        if not F.isMyWearData(wearData) then return end

        F.applyPersistSlotsToCache()
        local cch = F.cache()
        local AvatarData = require("client.logic.data.AvatarData")
        wearData.WearInfoList = wearData.WearInfoList or {}

        local desired = {
            {cch.hatRes, F.CUST_SLOT.HatEquipemtSlot},
            {cch.maskRes, F.CUST_SLOT.FaceEquipemtSlot},
            {cch.glassRes, F.CUST_SLOT.GlassEquipemtSlot},
            {cch.pantsRes, F.CUST_SLOT.PantsEquipemtSlot},
            {cch.shoesRes, F.CUST_SLOT.ShoesEquipemtSlot},
            {cch.glovesRes, F.CUST_SLOT.HandEffectEquipemtSlot},
            {cch.bagRes, F.CUST_SLOT.BackpackEquipemtSlot},
            {cch.helmetRes, F.CUST_SLOT.HelmetEquipemtSlot},
            {cch.parachuteRes, F.CUST_SLOT.ParachuteEquipemtSlot},
            {cch.gliderRes, F.CUST_SLOT.GlideEquipemtSlot}
        }
        if not cch.outfitRes or tonumber(cch.outfitRes) <= 0 then
            desired[#desired + 1] = {
                cch.tshirtRes, F.CUST_SLOT.ClothesEquipemtSlot
            }
        end

        for _, wanted in ipairs(desired) do
            local resID, slotID = tonumber(wanted[1]), tonumber(wanted[2])
            if resID and resID > 0 and slotID then
                local crewBase, crewColor, crewPattern =
                    F.getCrewUniformCustomization(resID)
                local converted = AvatarData.ConvertToAvatarCustom({
                    crewBase or resID, crewColor or 0, crewPattern or 0
                })
                if converted then
                    local replaced = false
                    for index, current in ipairs(wearData.WearInfoList) do
                        local currentRes = current and
                                               tonumber(
                                                   current.ItemID or
                                                       current.ItemId or
                                                       current.item_id)
                        if currentRes and F.resToCustSlot(currentRes) == slotID then
                            wearData.WearInfoList[index] = converted
                            replaced = true
                            break
                        end
                    end
                    if not replaced then
                        table.insert(wearData.WearInfoList, converted)
                    end
                end
            end
        end
    end

    function F.applyLobbyEquipmentPreview(bagRes, helmetRes)
        local applied = false
        pcall(function()
            local uid = tostring(DataMgr.roleData.uid)
            local TAM = require("client.logic.avatar.logic_team_avatar_manager")
            local avatar = TAM.GetAvatarByUid and TAM.GetAvatarByUid(uid)
            if not avatar or not avatar.PutonEquipment then return end
            local function put(res)
                res = tonumber(res)
                if not res or res <= 0 then return end
                F.ensureSkinDownload(res)
                avatar:PutonEquipment(res, nil, {bIsUse = true})
                applied = true
            end
            if bagRes then put(bagRes) end
            if helmetRes then put(helmetRes) end
        end)
        return applied
    end

    function F.mergeInjectedIntoWearData(wearData)
        if not wearData then return end
        F.mergeInjectedWeaponIntoWearData(wearData)
        F.mergeInjectedOutfitIntoWearData(wearData)
        F.mergeInjectedWearSlotsIntoWearData(wearData)
    end

    function F.reapplyLobbyEquipped()
        if not GameStatus or not GameStatus.IsInLobbyOrMainCity or
            not GameStatus.IsInLobbyOrMainCity() then return end
        F.syncWeaponCacheFromLobby()
        F.applyPersistSlotsToCache()
        local curPage = F.getLobbyCurPage()

        if ENUM_LobbyPageType and curPage == ENUM_LobbyPageType.Left then
            F.onSocialWearDirty(true)
            return
        end

        local cch = F.cache()
        if cch.outfitIns and F.isInjectedIns(cch.outfitIns) then
            F.putOnOutfit(cch.outfitIns)
        end
        if cch.hatIns and F.isInjectedIns(cch.hatIns) then
            F.putOnHat(cch.hatIns)
        end
        if cch.maskIns and F.isInjectedIns(cch.maskIns) then
            F.putOnFaceAccessory(cch.maskIns)
        end
        if cch.glassIns and F.isInjectedIns(cch.glassIns) then
            F.putOnFaceAccessory(cch.glassIns)
        end
        if cch.tshirtIns and F.isInjectedIns(cch.tshirtIns) then
            F.putOnRoleWear(cch.tshirtIns)
        end
        if cch.pantsIns and F.isInjectedIns(cch.pantsIns) then
            F.putOnRoleWear(cch.pantsIns)
        end
        if cch.shoesIns and F.isInjectedIns(cch.shoesIns) then
            F.putOnRoleWear(cch.shoesIns)
        end
        if cch.bagIns and F.isInjectedIns(cch.bagIns) then
            F.putOnRoleWear(cch.bagIns)
        end
        if cch.helmetIns and F.isInjectedIns(cch.helmetIns) then
            F.putOnRoleWear(cch.helmetIns)
        end
        F.applyLobbyEquipmentPreview(cch.bagRes, cch.helmetRes)
        if cch.parachuteIns then F.putOnParachute(cch.parachuteIns) end
        if cch.gliderIns then F.putOnGlider(cch.gliderIns) end
        if cch.glovesIns and F.isInjectedIns(cch.glovesIns) then
            F.putOnGloves(cch.glovesIns)
        end

        local mainWid = tonumber(DataMgr.Weapon_ID) or 0
        local w = mainWid > 0 and cch.weapons[mainWid] or nil
        if w and w.resID and w.resID > 0 then
            if w.insID and F.isInjectedIns(w.insID) then
                F.equipWeaponSkin(mainWid, w.insID)
            else
                pcall(function()
                    DataMgr.InitWeaponData(mainWid, w.resID, w.insID or 0)
                end)
            end
        end

        pcall(function()
            local uid = tostring(DataMgr.roleData.uid)
            local LAM = require("client.logic.avatar.LobbyAvatarManager")
            local TAM = require("client.logic.avatar.logic_team_avatar_manager")
            if w and w.resID and w.resID > 0 and TAM.GetAvatarByUid(uid) then
                LAM.EquipWeapon(uid, {weaponId = mainWid, skinId = w.resID},
                                nil, true)
            end
        end)

        F.reapplyVehicleSlotsFromConfig(true)
        F.reapplyHallThemeFromConfig(true)
        F.reapplyWeaponsFromConfig()
        pcall(F.applyVehicleSkinsToPC)
        pcall(F.reapplyFaceAndHairLobby)
    end

    F.scheduleLobbyReapplyOnce = function()
        if LOBBY.reapplyDone or LOBBY.reapplyScheduled then return end
        LOBBY.reapplyScheduled = true
        F.later(2.0, function()
            LOBBY.reapplyScheduled = false
            if LOBBY.reapplyDone then return end
            LOBBY.reapplyDone = true
            F.reapplyLobbyEquipped()
        end)
    end

    function F.hookLobbySwipePersistence()
        if _G.AddOutfitLobbySwipeHooked then return end
        _G.AddOutfitLobbySwipeHooked = true
        pcall(function()
            local BD = ModuleManager.GetModule(
                           ModuleManager.DataModuleConfig
                               .BasicDataAvatarWearInfo)
            local oRsp = BD.on_get_avatar_show_rsp
            BD.on_get_avatar_show_rsp = function(self, res, target_uid, data)
                oRsp(self, res, target_uid, data)
                if tonumber(target_uid) == tonumber(DataMgr.roleData.uid) then
                    F.patchSelfWearCache(true)
                    SOCIAL.forceAvatarRedraw = true
                    SOCIAL.lastHandSkin = nil
                    if ENUM_LobbyPageType and F.getLobbyCurPage() ==
                        ENUM_LobbyPageType.Left then
                        F.requestSocialAvatarRefresh()
                    end
                end
            end
        end)

        pcall(function()
            local AC = require("client.slua.logic.avatar.avatar_common")
            local oGetWear = AC.GetWearDataFromRoleData
            AC.GetWearDataFromRoleData = function(roleData)
                local wearData = oGetWear(roleData)
                if wearData and roleData and tonumber(roleData.uid) ==
                    tonumber(DataMgr.roleData.uid) and F.isLobbyLeftPage() then
                    F.mergeInjectedIntoWearData(wearData)
                end
                return wearData
            end
            local oUp = AC.UpdateAvatar
            AC.UpdateAvatar = function(avatar, wearData, isShowWeapon,
                                       isShowHelmet, isShowBag)
                if F.isMyWearData(wearData) and F.isLobbyLeftPage() then
                    F.mergeInjectedIntoWearData(wearData)
                end
                local showGun = isShowWeapon and F.shouldShowHandWeapon()
                if wearData and wearData.depot_show_info then
                    showGun = showGun and wearData.depot_show_info.weapon ~=
                                  false
                end
                if F.isMyWearData(wearData) and F.isLobbyLeftPage() then
                    for _, e in ipairs(wearData.WearInfoList or {}) do
                        if e and e.ItemID and F.isInjectedRes(e.ItemID) and
                            F.isSuitRes(e.ItemID) then
                            F.rememberLobbyOutfitRes(e.ItemID)
                            break
                        end
                    end
                end
                local ret = oUp(avatar, wearData, showGun, isShowHelmet,
                                isShowBag)
                if showGun and F.isMyWearData(wearData) and avatar and
                    F.isLobbyLeftPage() then
                    local skin = tonumber(
                                     wearData.mainWeaponInfo and
                                         wearData.mainWeaponInfo.weaponSkinId) or
                                     0
                    if skin <= 0 then
                        skin = F.resolveLobbyWeaponSkinRes() or 0
                    end
                    if skin > 0 then
                        F.equipSocialHandWeapon(avatar, skin)
                    end
                end
                return ret
            end
        end)

        pcall(function()
            local CA = require("client.logic.avatar.CoupleAvatar")
            local Cfg = require(
                            "client.slua.logic.lobby.Left.CoupleAvatarConfig")
            local oMulti = CA._UpdateMultiAvatar
            if oMulti then
                CA._UpdateMultiAvatar = function(self, avatar, avatarType)
                    local isSelf = avatarType == Cfg.AvatarType.Self and
                                       self.SelfUID and tostring(self.SelfUID) ==
                                       tostring(DataMgr.roleData.uid)
                    if isSelf and F.isLobbyLeftPage() then
                        pcall(function()
                            local BD = ModuleManager.GetModule(
                                           ModuleManager.DataModuleConfig
                                               .BasicDataAvatarWearInfo)
                            local d = BD:GetCacheData(tonumber(self.SelfUID))
                            if d then
                                F.applyInjectedPspace(d)
                            end
                        end)
                        if SOCIAL.forceAvatarRedraw then
                            self.CompareDataCache[avatarType] = nil
                            SOCIAL.forceAvatarRedraw = nil
                        end
                    end
                    oMulti(self, avatar, avatarType)
                    if isSelf and F.isLobbyLeftPage() and self.isShowWeapon ~=
                        false and F.shouldShowHandWeapon() then
                        local skin = F.resolveLobbyWeaponSkinRes()
                        if skin and skin > 0 then
                            F.equipSocialHandWeapon(avatar, skin)
                        end
                    end
                end
            end
            local oHideCheck = CA.CheckSelfIsHideAvatar
            CA.CheckSelfIsHideAvatar = function(self, nSelfUId, tRoleData)
                if F.isLobbyLeftPage() and tostring(nSelfUId) ==
                    tostring(DataMgr.roleData.uid) then
                    return false
                end
                return oHideCheck(self, nSelfUId, tRoleData)
            end

            local oUpdate = CA.Update
            CA.Update = function(self)
                if not F.isLobbyLeftPage() then
                    return oUpdate(self)
                end
                local isSelf = self.SelfUID and tostring(self.SelfUID) ==
                                   tostring(DataMgr.roleData.uid)
                local oHide = CA.HideAvatars
                if isSelf then CA.HideAvatars = function() end end
                local ok, err = pcall(oUpdate, self)
                CA.HideAvatars = oHide
            end

            local oRecv = CA.OnReceiveData
            CA.OnReceiveData = function(self, uid, data)
                if F.isLobbyLeftPage() and uid == self.SelfUID and tostring(uid) ==
                    tostring(DataMgr.roleData.uid) then
                    if data then
                        F.applyInjectedPspace(data)
                    else
                        data = F.buildLocalRoleDataForCoupleAvatar()
                    end
                end
                return oRecv(self, uid, data)
            end
        end)

        pcall(function()
            if not EventSystem or not EventSystem.registEvent then
                return
            end
            if EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_START then
                EventSystem:registEvent(EVENTTYPE_LOBBY,
                                        EVENTID_SWITCHTO_PAGE_START,
                                        function(_, _, toPage)
                    if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Left then
                        F.syncWeaponCacheFromLobby()
                        SOCIAL.lastHandSkin = nil
                        local o = F.resolveLobbyOutfitRes()
                        if o then
                            F.rememberLobbyOutfitRes(o)
                        end
                        F.patchSelfWearCache(true)
                        SOCIAL.forceAvatarRedraw = true
                    end
                end)
            end
            if EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_END then
                EventSystem:registEvent(EVENTTYPE_LOBBY,
                                        EVENTID_SWITCHTO_PAGE_END,
                                        function(_, _, _, toPage)
                    if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Left then
                        F.syncWeaponCacheFromLobby()
                        SOCIAL.lastHandSkin = nil
                        F.socialDebounce(0.45, function()
                            F.onSocialWearDirty(true)
                        end)
                    elseif ENUM_LobbyPageType and toPage ==
                        ENUM_LobbyPageType.Mid then
                        SOCIAL.wearPatchKey = nil
                        F.invalidateLobbyResolved()
                        if not LOBBY.reapplyDone then
                            F.socialDebounce(0.5, F.scheduleLobbyReapplyOnce)
                        end
                    end
                end)
            end
            if EVENTTYPE_LOBBY_SOCIAL and EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA then
                EventSystem:registEvent(EVENTTYPE_LOBBY_SOCIAL,
                                        EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA,
                                        function(_, _, nUId)
                    if tonumber(nUId) == tonumber(DataMgr.roleData.uid) then
                        F.socialDebounce(0.2, function()
                            F.patchSelfWearCache(false)
                        end)
                    end
                end)
            end
            if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                EventSystem:registEvent(EVENTTYPE_WARDROBE,
                                        EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN,
                                        function()
                    SOCIAL.wearPatchKey = nil
                    SOCIAL.snapshotKey = nil
                    F.syncWeaponCacheFromLobby()

                    local curPage = ENUM_LobbyPageType and F.getLobbyCurPage()
                    if curPage == ENUM_LobbyPageType.Left then
                        F.socialDebounce(0.25, function()
                            F.onSocialWearDirty(true)
                        end)
                    end

                    
                    F.socialDebounce(0.3, function()
                        if F.reapplyLobbyEquipped then
                            F.reapplyLobbyEquipped()
                        end
                    end)
                end)
            end
        end)

        pcall(function()
            local lds = require(
                            "client.slua.logic.wardrobe.logic_display_setting")
            local oSwitch = lds.SwitchGun
            lds.SwitchGun = function(...)
                local r = oSwitch(...)
                SOCIAL.wearPatchKey = nil

                local curPage = ENUM_LobbyPageType and F.getLobbyCurPage()
                if curPage == ENUM_LobbyPageType.Left then
                    F.socialDebounce(0.2,
                                     function()
                        F.onSocialWearDirty(true)
                    end)
                end

                
                F.socialDebounce(0.3, function()
                    if F.reapplyLobbyEquipped then
                        F.reapplyLobbyEquipped()
                    end
                end)

                return r
            end
        end)
    end

    function F.hookDepotInit()
        pcall(function()
            local WDE = require("client.slua.logic.wardrobe.WardrobeDataEntity")
            if WDE._AddOutfitInitHooked then return end
            WDE._AddOutfitInitHooked = true
            local orig = WDE.InitData
            WDE.InitData = function(self, pkg)
                orig(self, pkg)
                
                
                F.resetTransientSkinSession()
                F.persistLoadFromDisk()
                F.applyPersistSlotsToCache()
                F.syncGlobalWearSkins()
                _G.AddOutfitUnexpireDone = false
                pcall(function()
                    if F.injectAll(self) then
                        F.persistApplyLoaded()
                        F.scheduleInjectRefresh()
                        LOBBY.reapplyDone = false
                        LOBBY.reapplyScheduled = false
                        F.scheduleLobbyReapplyOnce()
                    end
                end)
            end
        end)
    end

    function F.hookWardrobeData()
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            if wd._AddOutfitDataHooked then return end
            wd._AddOutfitDataHooked = true
            local function wrapGet(name)
                local o = wd[name]
                if not o then return end
                wd[name] = function(self, insID, ...)
                    insID = tonumber(insID)
                    local r
                    if F.isInjectedIns(insID) then
                        local e = F.getEntity()
                        if e then
                            r = e:GetDataByInsID(insID)
                        end
                    else
                        r = o(self, insID, ...)
                    end
                    if r and
                        (F.isInjectedIns(insID) or
                            F.isInjectedRes(r.resID or r.res_id)) then
                        r.expire_ts = 0
                        r.expireTS = 0
                        r.valid_hours = 0
                    end
                    return r
                end
            end
            wrapGet("GetHallDepotItemDataByInsID")
            wrapGet("GetValidHallDepotItemDataByInsID")
            local function wrapBool(name)
                local o = wd[name]
                if not o then return end
                wd[name] = function(self, id, ...)
                    if F.isInjectedRes(tonumber(id)) or
                        F.isInjectedIns(tonumber(id)) then
                        return true
                    end
                    return o(self, id, ...)
                end
            end
            wrapBool("HasItem")
            wrapBool("HasValidItem")
            wrapBool("CheckHasPermanentItem")
        end)
    end

    function F.hookPageFilter()
        pcall(function()
            local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
            if wl._AddOutfitPageFilterHooked then return end
            wl._AddOutfitPageFilterHooked = true
            local o1 = wl.IsValidCurrentPageItem
            wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, t)
                if v and F.isInjectedRes(v.resID) then
                    local itemTab = tonumber(v.subTabType) or
                                        F.wardrobeTab(v.resID)
                    if itemTab and itemTab == subTab then
                        if mainTab == PAGE_VEHICLE then
                            return F.isVehicleRes(v.resID)
                        end
                        if mainTab == PAGE_AVATAR then
                            if tonumber(subTab) == 15 then
                                return F.isBackpackSkinRes(v.resID)
                            end
                            if tonumber(subTab) == 16 then
                                return F.isHelmetSkinRes(v.resID)
                            end
                            return not F.isVehicleRes(v.resID) and
                                       not F.isHallThemeRes(v.resID) and
                                       not F.isWeaponSkinRes(v.resID)
                        end
                        if mainTab == PAGE_PARACHUTE then
                            return F.isHallThemeRes(v.resID) or
                                       F.isParachuteRes(v.resID) or
                                       F.isGlideRes(v.resID)
                        end
                    end
                end
                return o1(self, mainTab, subTab, v, t)
            end
            local o2 = wl.IsCanUse
            wl.IsCanUse = function(self, resId)
                if F.isInjectedRes(resId) then return true end
                return o2(self, resId)
            end
            local o3 = wl.IsCharacterUse
            wl.IsCharacterUse = function(self, resId)
                if F.isInjectedRes(resId) then return true end
                return o3(self, resId)
            end
            local o4 = wl.GetWardrobeInsIdByResId
            wl.GetWardrobeInsIdByResId =
                function(self, resid)
                    resid = tonumber(resid)
                    if F.isInjectedRes(resid) then
                        return R.resToIns[resid]
                    end
                    return o4(self, resid)
                end
        end)
    end

    function F.hookArmory()
        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            if Arm._AddOutfitArmoryHooked then return end
            Arm._AddOutfitArmoryHooked = true
            local oa = Arm.get_weapon_skin_list_rsp
            Arm.get_weapon_skin_list_rsp =
                function(a, b, c, d)
                    oa(a, b, c, d)
                    F.mergeInjectedArmorySkins()
                end
            local oi = Arm.install_weapon_skin
            Arm.install_weapon_skin = function(cd, wid, ins)
                ins = tonumber(ins)
                if F.isWeaponSkinIns(ins) then
                    wid = tonumber(F.weaponIdFromSkin(R.insToRes[ins]) or wid)
                    F.equipWeaponSkin(wid, ins)
                    return
                end
                return oi(cd, wid, ins)
            end

            
            
            
            local originalGetSkinList = Arm.GetSkinListByWeaponID
            if originalGetSkinList and not Arm._AddOutfitGetSkinListHooked then
                Arm._AddOutfitGetSkinListHooked = true
                Arm.GetSkinListByWeaponID =
                    function(self, weaponID)
                        weaponID = tonumber(weaponID) or weaponID
                        local skinList =
                            originalGetSkinList(self, weaponID) or {}
                        local injected = R.byWeapon[weaponID]
                        if injected then
                            for resID in pairs(injected) do
                                if skinList[resID] == nil then
                                    skinList[resID] = {is_open = 1}
                                end
                            end
                        end
                        return skinList
                    end
            end
        end)
        pcall(function()
            local AH = require("client.network.Protocol.ArmoryHandler")
            if AH._AddOutfitArmorySendHooked then return end
            AH._AddOutfitArmorySendHooked = true
            local o = AH.send_install_weapon_skin
            AH.send_install_weapon_skin =
                function(cd, wid, ins)
                    ins = tonumber(ins)
                    if F.isWeaponSkinIns(ins) then
                        wid =
                            tonumber(F.weaponIdFromSkin(R.insToRes[ins]) or wid)
                        F.equipWeaponSkin(wid, ins)
                        return
                    end
                    return o(cd, wid, ins)
                end
        end)
    end

    function F.hookGunSkinId()
        pcall(function()
            local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
            if wgl._AddOutfitGunSkinHooked then return end
            wgl._AddOutfitGunSkinHooked = true
            local o = wgl.GetSkinIdByWeaponID
            wgl.GetSkinIdByWeaponID = function(self, wid)
                local c = F.cache()
                local w = c.weapons[wid]
                if w and F.isWeaponSkinIns(w.insID) then
                    return w.insID
                end
                local Arm = require("client.logic.armory.logic_armory")
                if Arm.rsp_list and Arm.rsp_list.install_list and
                    Arm.rsp_list.install_list[wid] then
                    local sid = Arm.rsp_list.install_list[wid].skin_id
                    if sid and F.isWeaponSkinIns(sid) then
                        return sid
                    end
                end
                return o(self, wid)
            end
        end)
    end

    function F.hookPutOn()
        pcall(function()
            local WRH = require("client.network.Protocol.WardRobeHandler")
            if WRH._AddOutfitPutOnHooked then return end
            WRH._AddOutfitPutOnHooked = true
            local o = WRH.send_depot_put_on_req
            WRH.send_depot_put_on_req = function(insID, extra)
                insID = tonumber(insID)
                if F.tryLocalWearByIns(insID) then return end
                return o(insID, extra)
            end
        end)
    end

    function F.hookPutDown()
        pcall(function()
            local WRH = require("client.network.Protocol.WardRobeHandler")
            if WRH._AddOutfitPutDownHooked then return end
            WRH._AddOutfitPutDownHooked = true
            local o = WRH.send_depot_put_down_req
            WRH.send_depot_put_down_req = function(insID)
                if F.isInjectedIns(tonumber(insID)) then
                    F.takeOffInjected(insID)
                    return
                end
                return o(insID)
            end
            local ob = WRH.send_depot_batch_put_down_req
            WRH.send_depot_batch_put_down_req =
                function(instid_list)
                    local rest = {}
                    for _, id in ipairs(instid_list or {}) do
                        if F.isInjectedIns(tonumber(id)) then
                            F.takeOffInjected(id)
                        else
                            rest[#rest + 1] = id
                        end
                    end
                    if #rest > 0 then return ob(rest) end
                end
        end)
    end

    function F.hookVehicleSwitchEffect()
        if _G.AddOutfitVehSwitchHooked then return end
        pcall(function()
            local VAC = require(
                            "GameLua.GameCore.Module.Vehicle.Component.VehicleAvatarComponent")
            local impl = VAC and VAC.__inner_impl
            if not impl or impl._AddOutfitVehSwitchHooked then return end
            impl._AddOutfitVehSwitchHooked = true

            if not _G.AddOutfitVehOrigCanSwitch then
                _G.AddOutfitVehOrigCanSwitch = impl.CheckCanPlaySkinSwitchEffect
            end
            impl.CheckCanPlaySkinSwitchEffect =
                function(self, curVehicleId, lastVehicleId)
                    if self.IsLobbyActor and self:IsLobbyActor() then
                        return false
                    end
                    if not F.isInRealMatch() then
                        return false
                    end
                    return true
                end

            if not _G.AddOutfitVehOrigShowSwitch then
                _G.AddOutfitVehOrigShowSwitch = impl.ShowVehicleSwitchEffect
            end
            impl.ShowVehicleSwitchEffect = function(self)
                if self.IsLobbyActor and self:IsLobbyActor() then
                    return false
                end
                if not F.isInRealMatch() then return false end
                if not self.curSwitchEffectId or self.curSwitchEffectId <= 0 then
                    self.curSwitchEffectId = VEH_SWITCH_EFFECT_ID
                end
                local vehicleActor = self:GetOwner()
                if not slua.isValid(vehicleActor) then
                    return false
                end
                if self.uSwitchEffectActor then
                    self:StopSkinSwitchEffect()
                    pcall(function()
                        self.uSwitchEffectActor:K2_DestroyActor()
                    end)
                    self.uSwitchEffectActor = nil
                end
                if not self.lastEquipedAvatarId or self.lastEquipedAvatarId <= 0 then
                    local defId = 0
                    pcall(function()
                        defId = self:GetDefaultAvatarID() or 0
                    end)
                    self.lastEquipedAvatarId =
                        vehicleActor.ClientUsedAvatarID or defId or 0
                end
                local currentAvatarID = vehicleActor.ClientUsedAvatarID or
                                            self.lastEquipedAvatarId or 0
                local bIsLobbyActor = self:IsLobbyActor()
                local world = slua_GameFrontendHUD:GetWorld()
                local VehiclePlateLicenseUtil = require(
                                                    "GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                local SkinSwitchEffectActorPath =
                    VehiclePlateLicenseUtil.GetSwitchEffectActorPath()
                local BP_DissolveVehicleClass =
                    import(SkinSwitchEffectActorPath)
                self.uSwitchEffectActor = world:SpawnActor(
                                              BP_DissolveVehicleClass, nil, nil,
                                              nil)
                if not slua.isValid(self.uSwitchEffectActor) then
                    self.uSwitchEffectActor = nil
                    return false
                end
                self.uSwitchEffectActor:K2_AttachToActor(vehicleActor, "None",
                                                         1, 1, 1, false)
                self.uSwitchEffectActor:K2_SetActorRelativeLocation(FVector(0,
                                                                            0, 0),
                                                                    false, nil,
                                                                    false)
                self.uSwitchEffectActor:K2_SetActorRelativeRotation(FRotator(0,
                                                                             0,
                                                                             0),
                                                                    false, nil,
                                                                    false)
                pcall(function() self:HideParticles() end)
                self:ChangeFakeSwitchVehicleAvatar(self.uSwitchEffectActor.Mesh,
                                                   self.lastEquipedAvatarId)
                self.uSwitchEffectActor:SetAnimInsAndAnimState(
                    self.uOldVehicleMeshAnimClass, vehicleActor)
                self.uSwitchEffectActor:StartVehicleSwitchEffect(vehicleActor,
                                                                 self.curSwitchEffectId,
                                                                 self.lastEquipedAvatarId,
                                                                 currentAvatarID,
                                                                 bIsLobbyActor)
                self.uOldVehicleMeshAnimClass = nil
                return true
            end

            if not _G.AddOutfitVehOrigBeginPlay then
                _G.AddOutfitVehOrigBeginPlay = impl.ReceiveBeginPlay
            end
            local oBegin = _G.AddOutfitVehOrigBeginPlay
            impl.ReceiveBeginPlay = function(self)
                oBegin(self)
                pcall(function()
                    if self.uSwitchEffectActor then
                        self:StopSkinSwitchEffect()
                        pcall(function()
                            self.uSwitchEffectActor:K2_DestroyActor()
                        end)
                        self.uSwitchEffectActor = nil
                    end
                    self.lastEquipedAvatarId = 0
                    if self.IsLobbyActor and self:IsLobbyActor() then
                        self.curSwitchEffectId = 0
                    elseif F.isInRealMatch() then
                        self.curSwitchEffectId = VEH_SWITCH_EFFECT_ID
                    else
                        self.curSwitchEffectId = 0
                    end
                end)
            end

            if impl.LuaIsAssetsAlreadyAvailable and
                not _G.AddOutfitVehOrigAssets then
                _G.AddOutfitVehOrigAssets = impl.LuaIsAssetsAlreadyAvailable
                impl.LuaIsAssetsAlreadyAvailable =
                    function(self, avatarId)
                        if F.isVehicleSkinAllowed(tonumber(avatarId)) then
                            return true
                        end
                        return _G.AddOutfitVehOrigAssets(self, avatarId)
                    end
            end

            _G.AddOutfitVehSwitchHooked = true
        end)
    end

    function F.hookVehicleChassisLight()
        if _G.AddOutfitVehChassisHooked then return end
        pcall(function()
            local LIC = require(
                            "GameLua.Activity.Commercialize.Actor.ActorComponent.BP_VehicleLicenseComponentBase")
            if LIC and LIC.CheckHasVehicleDownloaded and
                not _G.AddOutfitVehOrigLicDownload then
                _G.AddOutfitVehOrigLicDownload = LIC.CheckHasVehicleDownloaded
                LIC.CheckHasVehicleDownloaded =
                    function(self, itemID)
                        local id = tonumber(itemID)
                        if F.isVehicleSkinAllowed(id) or F.isChassisLightId(id) then
                            return true
                        end
                        return _G.AddOutfitVehOrigLicDownload(self, itemID)
                    end
            end
        end)
        pcall(function()
            local LVF = ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig
                                .LogicVehicleExtendedFeature)
            if not LVF or LVF._AddOutfitChassisHooked then return end
            LVF._AddOutfitChassisHooked = true

            if not _G.AddOutfitVehOrigGetFeature then
                _G.AddOutfitVehOrigGetFeature = LVF.CheckHasGetFeatureItem
            end
            LVF.CheckHasGetFeatureItem =
                function(self, featureId)
                    if F.isChassisLightId(featureId) then
                        return true
                    end
                    return _G.AddOutfitVehOrigGetFeature(self, featureId)
                end

            if not _G.AddOutfitVehOrigEquippedFeature then
                _G.AddOutfitVehOrigEquippedFeature = LVF.CheckHasEquippedItem
            end
            LVF.CheckHasEquippedItem = function(self, featureId, vehicleId)
                
                if _G.VIPConfig and _G.VIPConfig.ModSkin ~= false then
                    if F.isChassisLightId(featureId) then
                        return F.getDesiredChassisLight(vehicleId) ==
                                   tonumber(featureId)
                    end
                end
                return _G.AddOutfitVehOrigEquippedFeature(self, featureId,
                                                          vehicleId)
            end

            if not _G.AddOutfitVehOrigEquipChassisData then
                _G.AddOutfitVehOrigEquipChassisData =
                    LVF.GetEquipedChassisLightData
            end
            LVF.GetEquipedChassisLightData =
                function(self, vehicleId, source)
                    
                    if _G.VIPConfig and _G.VIPConfig.ModSkin ~= false then
                        local our = F.getDesiredChassisLight(vehicleId)
                        if our then return our end
                    end
                    return _G.AddOutfitVehOrigEquipChassisData(self, vehicleId,
                                                               source)
                end

            if not _G.AddOutfitVehOrigChassisLightData then
                _G.AddOutfitVehOrigChassisLightData =
                    LVF.GetVehicleChassisLightData
            end
            LVF.GetVehicleChassisLightData =
                function(self, uid, vehicleId, position, source)
                    
                    if _G.VIPConfig and _G.VIPConfig.ModSkin ~= false then
                        if uid and DataMgr and DataMgr.roleData and
                            tonumber(uid) == tonumber(DataMgr.roleData.uid) then
                            local our = F.getDesiredChassisLight(vehicleId)
                            if our then return our end
                        end
                    end
                    return
                        _G.AddOutfitVehOrigChassisLightData(self, uid,
                                                            vehicleId, position,
                                                            source)
                end

            if not _G.AddOutfitVehOrigPutOnFeature then
                _G.AddOutfitVehOrigPutOnFeature = LVF.PutOnVehicleFeature
            end
            LVF.PutOnVehicleFeature = function(self, featureId, vehicleId)
                featureId = tonumber(featureId)
                vehicleId = tonumber(vehicleId)
                if F.isChassisLightId(featureId) then
                    F.saveChassisLight(vehicleId, featureId)
                    self.equip_chassis_light = self.equip_chassis_light or {}
                    if vehicleId and vehicleId > 0 then
                        self.equip_chassis_light[vehicleId] = featureId
                    end
                    return
                end
                return _G.AddOutfitVehOrigPutOnFeature(self, featureId,
                                                       vehicleId)
            end

            if not _G.AddOutfitVehOrigPutOffFeature then
                _G.AddOutfitVehOrigPutOffFeature = LVF.PutOffVehicleFeature
            end
            LVF.PutOffVehicleFeature = function(self, featureId, vehicleId)
                featureId = tonumber(featureId)
                vehicleId = tonumber(vehicleId)
                if F.isChassisLightId(featureId) then
                    PERSIST.configChassisLightMap =
                        PERSIST.configChassisLightMap or {}
                    if vehicleId and vehicleId > 0 then
                        PERSIST.configChassisLightMap[vehicleId] = nil
                    end
                    if self.equip_chassis_light and vehicleId then
                        self.equip_chassis_light[vehicleId] = nil
                    end
                    F.persistMarkDirty()
                    return
                end
                return _G.AddOutfitVehOrigPutOffFeature(self, featureId,
                                                        vehicleId)
            end
        end)
        _G.AddOutfitVehChassisHooked = true
    end

    function F.hookVehicles()
        F.hookVehicleSwitchEffect()
        F.hookVehicleChassisLight()
        pcall(function()
            local WV = require("client.slua.umg.Wardrobe.subtab_vehicles")
            if not WV or WV._AddOutfitVehClickHooked then return end
            WV._AddOutfitVehClickHooked = true
            local oClick = WV.ClickItem
            WV.ClickItem = function(self, vehicleSkin, bForceUsing)
                if vehicleSkin and F.isInjectedRes(vehicleSkin.res_id) then
                    vehicleSkin.expireTS = 0
                    vehicleSkin.expire_ts = 0
                end
                return oClick(self, vehicleSkin, bForceUsing)
            end
            local oDrop = WV.OnVehicleSlotDrop
            if oDrop then
                WV.OnVehicleSlotDrop = function(self, DragWidget, Index,
                                                DragDropData)
                    pcall(function()
                        local ins = DragDropData and DragDropData.ins_id
                        if F.isInjectedIns(tonumber(ins)) then
                            F.ensureInjectedItemAlive(nil, nil, ins)
                        end
                    end)
                    return oDrop(self, DragWidget, Index, DragDropData)
                end
            end
        end)
        pcall(function()
            local WNH = require("client.network.Protocol.WardrobeNewHandler")
            if WNH._AddOutfitVehicleHooked then return end
            WNH._AddOutfitVehicleHooked = true
            local oMod = WNH.send_depot_modify_combat_vehicle_req
            WNH.send_depot_modify_combat_vehicle_req = function(instid,
                                                                slot_index,
                                                                ope_type)
                if F.modifyInjectedVehicleSlot(instid, slot_index,
                                               ope_type == true) then
                    return
                end
                return oMod(instid, slot_index, ope_type)
            end
            local oRsp = WNH.on_depot_modify_combat_vehicle_rsp
            WNH.on_depot_modify_combat_vehicle_rsp = function(err_code,
                                                              knapsack_vst)
                if err_code == 0 or err_code == NET_OK then
                    knapsack_vst = F.mergeInjectedIntoVehicleSlotList(
                                       knapsack_vst)
                end
                oRsp(err_code, knapsack_vst)
                if err_code == 0 or err_code == NET_OK then
                    F.syncVehicleSlotsToDataMgr()
                    F.equipVehicleTypesFromConfig(PERSIST.configVehicleSlots)
                    if not (_G.AddOutfitLobbyVeh and _G.AddOutfitLobbyVeh.manual) then
                        pcall(F.applyVehicleSkinsToPC)
                    end
                    F.persistMarkDirty()
                end
            end
        end)
        pcall(function()
            local gsm = ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig.golden_suit_module)
            if gsm and gsm.VehicleNeedClothes and
                not gsm._AddOutfitVehClothesHooked then
                gsm._AddOutfitVehClothesHooked = true
                local o = gsm.VehicleNeedClothes
                gsm.VehicleNeedClothes =
                    function(self, vehicleId)
                        vehicleId = tonumber(vehicleId)
                        if vehicleId and F.isInjectedRes(vehicleId) then
                            return 0
                        end
                        return o(self, vehicleId)
                    end
            end
        end)
        pcall(function()
            local mod = require(
                            "GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
            if mod._FillVehicleSkinList then
                if not _G.AddOutfitVehFillOrig then
                    _G.AddOutfitVehFillOrig = mod._FillVehicleSkinList
                end
                local o = _G.AddOutfitVehFillOrig
                mod._FillVehicleSkinList =
                    function(self, playerInfo, uPlayerController)
                        F.mergeVstIntoPlayerInfo(playerInfo)
                        return o(self, playerInfo, uPlayerController)
                    end
                mod._AddOutfitFillVehHooked = true
            end
        end)
        pcall(function()
            local classMod = require(
                                 "GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinItem")
            if not classMod or not classMod.__inner_impl then return end
            local impl = classMod.__inner_impl
            if not _G.AddOutfitVehOrigClick then
                _G.AddOutfitVehOrigClick = impl.OnClickSkinButton
            end
            local oClick = _G.AddOutfitVehOrigClick
            impl.OnClickSkinButton = function(self)
                local resID = tonumber(self.resID)
                if resID and resID > 0 then
                    if F.matchApplyVehicleSkin(resID) then
                        pcall(function()
                            if EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL and
                                EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK then
                                EventSystem:postEvent(
                                    EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL,
                                    EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK)
                            end
                        end)
                    end
                    return
                end
                return oClick(self)
            end
            if not _G.AddOutfitVehOrigRefresh then
                _G.AddOutfitVehOrigRefresh = impl.OnRefresh
            end
            local oRefresh = _G.AddOutfitVehOrigRefresh
            impl.OnRefresh = function(self, resID, selectIndex)
                oRefresh(self, resID, selectIndex)
                if self.resID and tonumber(self.resID) and tonumber(self.resID) >
                    0 then
                    if F.isResourcesReady(self.resID) then
                        pcall(function()
                            local PufferConst = require(
                                                    "client.slua.logic.download.puffer_const")
                            self.dowloadState =
                                PufferConst.ENUM_DownloadState.Done
                            self.UIRoot.Image_Download:SetWidgetVisibility(
                                UEnums.ESlateVisibility.Collapsed)
                            self:SetWidgetVisible(self.UIRoot.Image_Mask, false)
                        end)
                    else
                        F.requestResourceDownload(self.resID)
                    end
                end
            end
            classMod._AddOutfitSkinClickHooked = true
        end)
        pcall(function()
            local utilMod = require(
                                "GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
            if utilMod.CheckHasUnLockFeature and
                not utilMod._AddOutfitVehPlateHooked then
                utilMod._AddOutfitVehPlateHooked = true
                local orig = utilMod.CheckHasUnLockFeature
                utilMod.CheckHasUnLockFeature =
                    function(ft, uid, itemId)
                        local id = tonumber(itemId)
                        if F.isVehicleSkinAllowed(id) or F.isChassisLightId(id) then
                            return true
                        end
                        return orig(ft, uid, itemId)
                    end
            end
        end)
        pcall(function()
            local panelMod = require(
                                 "GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinAndMusicPanel")
            if panelMod and panelMod.__inner_impl and
                not panelMod._AddOutfitInitSkinHooked then
                panelMod._AddOutfitInitSkinHooked = true
                local o = panelMod.__inner_impl.InitSkinList
                panelMod.__inner_impl.InitSkinList = function(self)
                    F.applyVehicleSkinsToPC(F.getPC())
                    return o(self)
                end
            end
        end)
        pcall(function()
            local VUC = require(
                            "GameLua.GameCore.Module.Vehicle.Component.VehicleUserComponent")
            if not VUC then return end
            if not _G.AddOutfitVehOrigEnter then
                _G.AddOutfitVehOrigEnter =
                    VUC.SendUIMsgWhenEnterVehicleCompleted
            end
            local oEnter = _G.AddOutfitVehOrigEnter
            VUC.SendUIMsgWhenEnterVehicleCompleted = function(self)
                oEnter(self)
                pcall(function()
                    if slua.isValid(self.Vehicle) then
                        F.autoApplyVehicleSkinOnEnter(self.Vehicle)
                    end
                end)
            end
            VUC._AddOutfitEnterVehHooked = true
        end)
    end

    function F.hookWeaponWear()
        pcall(function()
            local HT = require("client.logic.lobby.hall_theme_utils")
            local o = HT.IsWeaponWear
            HT.IsWeaponWear = function(insId)
                insId = tonumber(insId)
                if F.isInjectedIns(insId) then
                    local c = F.cache()
                    local Arm = require("client.logic.armory.logic_armory")
                    for wid, w in pairs(c.weapons) do
                        if tonumber(w.insID) == insId then
                            if Arm.rsp_list and Arm.rsp_list.install_list and
                                Arm.rsp_list.install_list[wid] then
                                return tonumber(
                                           Arm.rsp_list.install_list[wid]
                                               .skin_id) == insId
                            end
                            return true
                        end
                    end
                end
                return o(insId)
            end
        end)
    end

    function F.hookNotice()
        
        
        
        return true
    end

    function F.wrapWardrobeClick(classMod, key)
        if not classMod or not classMod[key] or
            classMod["_AddOutfitWrap_" .. key] then return end
        classMod["_AddOutfitWrap_" .. key] = true
        local orig = classMod[key]
        classMod[key] = function(self, widget, index)
            local itemData = self.LoopScrollGrid_Normal and
                                 self.LoopScrollGrid_Normal:GetItemData(index)
            if itemData then
                F.clearItemExpire(itemData, itemData.ins_id, itemData.res_id)
                F.ensureDepotItemValid(itemData.ins_id, itemData.res_id)
            end
            return orig(self, widget, index)
        end
    end

    function F.hookWardrobeWearClicks()
        if _G.AddOutfitWearClickHooked then return end
        _G.AddOutfitWearClickHooked = true
        F.hookNotice()
        pcall(function()
            local avatarClass =
                require("client.slua.umg.Wardrobe.subtab_avatar")
            F.wrapWardrobeClick(avatarClass, "OnClickItem")
            F.wrapWardrobeClick(avatarClass, "ClickAvatarItem")
        end)
        pcall(function()
            local suitClass = require("client.slua.umg.Wardrobe.subtab_suit")
            F.wrapWardrobeClick(suitClass, "OnClickItem")
        end)
        pcall(function()
            local bagClass = require("client.slua.umg.Wardrobe.subtab_bag")
            F.wrapWardrobeClick(bagClass, "OnClickItem")
        end)
    end

    function F.hookAvatarValid()
        pcall(function()
            local path =
                "GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent"
            local comp = require(path)
            if comp and comp.CheckItemValid then
                local o = comp.CheckItemValid
                comp.CheckItemValid = function(self, resID)
                    if F.isInjectedRes(resID) then
                        return true
                    end
                    return o(self, resID)
                end
            end
        end)
    end

    
    
    
    
    
    
    
    
    
    
    F.FACE_SUB = F.FACE_SUB or 407
    F.HAIR_SUB = F.HAIR_SUB or 406
    F.FACE_SLOT = F.CUST_SLOT.FaceEquipemtSlot 
    F.HAIR_SLOT = F.CUST_SLOT.HairEquipemtSlot 

    
    
    
    local LOCAL_APPEARANCE_FACE_IDS = {
        [1400563] = true,
        [1406003] = true,
        [402000] = true,
        [402372] = true
    }
    local LOCAL_APPEARANCE_HAIR_TYPES = {
        [10] = true,
        [11] = true,
        [12] = true,
        [14] = true,
        [15] = true,
        [16] = true,
        [17] = true,
        [18] = true
    }

    function F.isLocalCharacterAppearance(originData)
        if not originData then return false end
        
        
        
        
        
        local avatarType = tonumber(originData.AvatarType)
        if avatarType == 1 or avatarType == 2 or avatarType == 3 or
            avatarType == 5 or avatarType == 6 then return true end
        
        local avatarID = tonumber(originData.id or originData.AvatarId)
        local bodyID = tonumber(originData.BodyID or originData.ItemId)
        if LOCAL_APPEARANCE_FACE_IDS[avatarID] or
            LOCAL_APPEARANCE_FACE_IDS[bodyID] then return true end
        local hairType = tonumber(originData.Hair)
        return avatarType == 2 and LOCAL_APPEARANCE_HAIR_TYPES[hairType] == true
    end

    
    function F.isValidFaceRes(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        if LOCAL_APPEARANCE_FACE_IDS[resID] then return true end
        local row = F.cfg(resID)
        if not row then return false end
        local st = tonumber(F.subType(row))
        if st == F.FACE_SUB then return true end
        return resID >= 400000 and resID < 500000
    end

    function F.isValidHairRes(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        local hairType = resID >= 40605000 and (resID - 40605000) or resID
        if LOCAL_APPEARANCE_HAIR_TYPES[hairType] then return true end
        local row = F.cfg(resID)
        if not row then return false end
        local st = tonumber(F.subType(row))
        if st == F.HAIR_SUB then return true end
        return resID >= 40600000 and resID < 40700000
    end

    
    function F.rememberFaceRes(resID)
        resID = tonumber(resID)
        if not F.isValidFaceRes(resID) then return end
        PERSIST.configSlots = PERSIST.configSlots or {}
        PERSIST.configSlots.face = resID
        _G.AddOutfitLastLobbyFaceRes = resID
        F.persistMarkDirty()
    end

    function F.rememberHairRes(resID)
        resID = tonumber(resID)
        if not F.isValidHairRes(resID) then return end
        
        
        
        local desiredColor = F.getDesiredHairColor()
        if desiredColor then
            resID = F.composeHairRes(resID, desiredColor) or resID
        end
        PERSIST.configSlots = PERSIST.configSlots or {}
        PERSIST.configSlots.hair = resID
        _G.AddOutfitLastLobbyHairRes = resID
        F.persistMarkDirty()
    end

    
    
    
    
    
    
    function F.hairTypeFromRes(resID)
        resID = tonumber(resID)
        if not resID or resID < 40600000 or resID >= 40700000 then
            return nil
        end
        return (resID % 40600000) % 1000
    end

    function F.hairColorFromRes(resID)
        resID = tonumber(resID)
        if not resID or resID < 40600000 or resID >= 40700000 then
            return nil
        end
        return math.floor((resID % 40600000) / 1000)
    end

    function F.composeHairRes(hairType, hairColor)
        hairType = tonumber(hairType)
        if not hairType or hairType <= 0 then return nil end
        if hairType >= 40600000 then
            hairType = F.hairTypeFromRes(hairType)
        end
        if not hairType or hairType <= 0 then return nil end
        hairColor = tonumber(hairColor)
        if not hairColor or hairColor <= 0 or hairColor > 99 then
            hairColor = 5
        end
        return 40600000 + hairColor * 1000 + hairType
    end

    function F.rememberHairColor(color)
        color = tonumber(color)
        if not color or color <= 0 or color > 99 then return end
        PERSIST.configSlots = PERSIST.configSlots or {}
        PERSIST.configSlots.hairColor = color
        _G.AddOutfitLastLobbyHairColor = color
        F.persistMarkDirty()
    end

    function F.getDesiredHairColor()
        local c = tonumber(PERSIST.configSlots and
                               PERSIST.configSlots.hairColor)
        if c and c > 0 and c <= 99 then return c end
        c = tonumber(_G.AddOutfitLastLobbyHairColor)
        if c and c > 0 and c <= 99 then return c end
        return nil
    end

    function F.getDesiredFaceRes()
        local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.face)
        if r and F.isValidFaceRes(r) then return r end
        r = tonumber(_G.AddOutfitLastLobbyFaceRes)
        if r and F.isValidFaceRes(r) then return r end
        local cch = F.cache()
        if cch and cch.faceRes and F.isValidFaceRes(cch.faceRes) then
            return tonumber(cch.faceRes)
        end
        return nil
    end

    function F.getDesiredHairRes()
        local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.hair)
        if not (r and F.isValidHairRes(r)) then
            r = tonumber(_G.AddOutfitLastLobbyHairRes)
        end
        if not (r and F.isValidHairRes(r)) then
            local cch = F.cache()
            r = cch and tonumber(cch.hairRes) or nil
        end
        if not (r and F.isValidHairRes(r)) then return nil end
        
        
        local color = F.getDesiredHairColor() or F.hairColorFromRes(r) or 5
        return F.composeHairRes(r, color) or r
    end

    
    
    
    function F.hookAvatarInitAppearance()
        if _G.AddOutfitAvatarInitHooked then return true end
        local ok, AI = pcall(require, "client.logic.data.AvatarInit")
        if not ok or type(AI) ~= "table" then return false end

        if type(AI.UpdateAvatarIsCanUse) == "function" and
            not AI.__4RAvatarCanUseHooked then
            local original = AI.UpdateAvatarIsCanUse
            AI.__4RAvatarCanUseHooked = true
            AI.UpdateAvatarIsCanUse = function(self, avatarData)
                if F.isEnabled() and F.isLocalCharacterAppearance(avatarData) then
                    return true
                end
                return original(self, avatarData)
            end
        end

        _G.AddOutfitAvatarInitHooked = true
        return true
    end

    
    
    
    
    function F.hookCharacterAppearanceUnlock()
        local ok, Appearance = pcall(require,
                                     "client.slua.logic.wardrobe.logic_wardrobe_appearance")
        if not ok or not Appearance or Appearance._BunnyAppearanceUnlockHooked then
            return ok and Appearance ~= nil
        end

        if type(Appearance.GenerateAvatarData) ~= "function" or
            type(Appearance.PutAvatar) ~= "function" then return false end

        Appearance._BunnyAppearanceUnlockHooked = true
        Appearance._BunnyOriginalGenerateAvatarData =
            Appearance._BunnyOriginalGenerateAvatarData or
                (type(Appearance.GenerateAvatarData) == "function" and
                    Appearance.GenerateAvatarData or nil)
        Appearance._BunnyOriginalPutAvatar =
            Appearance._BunnyOriginalPutAvatar or
                (type(Appearance.PutAvatar) == "function" and
                    Appearance.PutAvatar or nil)

        local originalGenerate = Appearance._BunnyOriginalGenerateAvatarData
        local originalPut = Appearance._BunnyOriginalPutAvatar
        F.localAppearanceAvatarIDs = F.localAppearanceAvatarIDs or {}

        Appearance.GenerateAvatarData = function(self, originData)
            local result = originalGenerate(self, originData)
            if F.isEnabled() and result and
                F.isLocalCharacterAppearance(originData) then
                result.RemainTime = 0
                result.Owned = true
                local avatarID = tonumber(result.AvatarId or
                                              (originData and originData.id))
                if avatarID then
                    F.localAppearanceAvatarIDs[avatarID] = true
                end
            end
            return result
        end

        Appearance.PutAvatar = function(self, avatarID, appearanceType, bPutOn)
            avatarID = tonumber(avatarID)
            if F.isEnabled() and bPutOn ~= false and avatarID and
                F.localAppearanceAvatarIDs[avatarID] then
                local avatarData = self:GetAvatarDataById(avatarID)
                if avatarData and self.ModifyAvatar then
                    
                    F.localAppearanceOriginal = F.localAppearanceOriginal or {}
                    if F.localAppearanceOriginal[appearanceType] == nil and
                        self.GetAppearanceEquipAvatarId then
                        F.localAppearanceOriginal[appearanceType] =
                            self:GetAppearanceEquipAvatarId(appearanceType)
                    end
                    self:ModifyAvatar(appearanceType, avatarData, false)

                    local putType = tonumber(appearanceType)
                    if putType == 2 then
                        local hairType = tonumber(avatarData.Hair)
                        local hairRes = hairType and
                                            (hairType < 100 and
                                                (40605000 + hairType) or
                                                hairType) or avatarID
                        F.rememberHairRes(hairRes)
                    elseif putType == 1 then
                        local faceRes = tonumber(
                                            avatarData.BodyID or
                                                avatarData.ItemId or
                                                avatarData.id) or avatarID
                        F.rememberFaceRes(faceRes)
                    elseif putType == 3 then
                        
                        
                        
                        
                        
                        
                        
                        
                        local color = tonumber(avatarData.HairColor)
                        if color and color > 0 then
                            F.rememberHairColor(color)
                            local hairRes = F.getDesiredHairRes()
                            if hairRes then F.rememberHairRes(hairRes) end
                        end
                    end
                    
                    
                    return
                end
            end
            return originalPut(self, avatarID, appearanceType, bPutOn)
        end

        return true
    end

    function F.restoreLocalCharacterAppearance()
        if not F.localAppearanceOriginal then return true end
        local ok, Appearance = pcall(require,
                                     "client.slua.logic.wardrobe.logic_wardrobe_appearance")
        if ok and Appearance and Appearance.ModifyAvatar and
            Appearance.GetAvatarDataById then
            for appearanceType, avatarID in pairs(F.localAppearanceOriginal) do
                local avatarData = Appearance:GetAvatarDataById(avatarID)
                if avatarData then
                    pcall(Appearance.ModifyAvatar, Appearance, appearanceType,
                          avatarData, false)
                end
            end
        end
        F.localAppearanceOriginal = nil
        F.localAppearanceAvatarIDs = {}
        return true
    end

    
    
    
    
    function F.matchApplyFaceAndHair(char)
        char = char or F.getLocalChar()
        if not char or not slua.isValid(char) then return true end

        local faceRes = F.getDesiredFaceRes()
        local hairRes = F.getDesiredHairRes()
        if (not faceRes or faceRes <= 0) and (not hairRes or hairRes <= 0) then
            return true
        end

        local comp = F.getAvatarComp2(char)
        if not comp then return false end

        local ok = true
        if faceRes and faceRes > 0 then
            ok =
                F.setMakeSkin(comp, faceRes, F.FACE_SLOT, {allowPutOn = true}) and
                    ok
        end
        if hairRes and hairRes > 0 then
            ok =
                F.setMakeSkin(comp, hairRes, F.HAIR_SLOT, {allowPutOn = true}) and
                    ok
        end
        return ok
    end

    
    
    
    function F.reapplyFaceAndHairLobby()
        pcall(function()
            if not (GameStatus and GameStatus.IsInLobbyOrMainCity and
                GameStatus.IsInLobbyOrMainCity()) then return end
            if F.isInRealMatch and F.isInRealMatch() then return end

            local faceRes = F.getDesiredFaceRes()
            local hairRes = F.getDesiredHairRes()
            if (not faceRes or faceRes <= 0) and (not hairRes or hairRes <= 0) then
                return
            end

            local char = F.getLocalChar()
            if not char then return end
            local comp = F.getAvatarComp2(char)
            if not comp then return end

            if faceRes and faceRes > 0 then
                F.setMakeSkin(comp, faceRes, F.FACE_SLOT, {allowPutOn = true})
            end
            if hairRes and hairRes > 0 then
                F.setMakeSkin(comp, hairRes, F.HAIR_SLOT, {allowPutOn = true})
            end
        end)
    end

    function F.isInRealMatch()
        local ok, r = pcall(function()
            return GameStatus and GameStatus.IsInFightingStatus and
                       GameStatus.IsInFightingStatus()
        end)
        return ok and r == true
    end

