    function F.getDesiredOutfit()
        if MATCH_CONFIG.outfitRes and MATCH_CONFIG.outfitRes > 0 then
            return MATCH_CONFIG.outfitRes
        end
        local wornSuitRes
        pcall(function()
            local _, res = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                return F.isSuitRes(r)
            end)
            wornSuitRes = tonumber(res)
        end)
        if wornSuitRes and wornSuitRes > 0 then return wornSuitRes end
        local tshirtWorn = false
        pcall(function()
            local ins = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                return F.isTshirtRes(r)
            end)
            tshirtWorn = ins ~= nil
        end)
        if tshirtWorn then return nil end
        F.syncBodyCacheFromLobby()
        local c = F.cache()
        return c.outfitRes
    end

    function F.matchApplyOutfit(char)
        local outfitRes = F.getDesiredOutfit()
        if not outfitRes then return true end
        if not F.isResourcesReady(outfitRes) then
            F.requestResourceDownload(outfitRes)
            return false
        end
        local comp = F.getAvatarComp2(char)
        if not comp then return false end
        local ok = F.setMakeSkin(comp, outfitRes,
                                 F.CUST_SLOT.ClothesEquipemtSlot,
                                 {allowPutOn = true})
        return ok
    end

    function F.getDesiredHat()
        if MATCH_CONFIG.hatRes and tonumber(MATCH_CONFIG.hatRes) > 0 then
            return tonumber(MATCH_CONFIG.hatRes)
        end
        F.syncHatCacheFromLobby()
        local h = F.cache().hatRes
        if h and tonumber(h) > 0 then return tonumber(h) end
        return tonumber(_G.AddOutfitLastLobbyHatRes) or nil
    end

    function F.ensureSkinDownload(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return end
        _G.skinIdCache = _G.skinIdCache or {}
        if F.isResourcesReady(resID) then
            _G.skinIdCache[resID] = true
            if _G.AddOutfitDownloadQueued then
                _G.AddOutfitDownloadQueued[resID] = nil
            end
            return
        end

        
        _G.skinIdCache[resID] = nil
        F.requestResourceDownload(resID)
    end

    function F.syncGlobalWearSkins()
        if not F.isEnabled() then
            _G.HatSkin, _G.SuitSkin, _G.PantsSkin, _G.ShoesSkin = 0, 0, 0, 0
            _G.GlovesSkin, _G.MaskSkin, _G.GlassSkin = 0, 0, 0
            _G.GliderSkin, _G.ParachuteSkin = 0, 0
            return false
        end
        _G.CustSlotType = F.CUST_SLOT
        _G.skinIdCache = _G.skinIdCache or {}
        _G.HatSkin = tonumber(F.getDesiredHat()) or 0
        local outfit = F.getDesiredOutfit()
        _G.SuitSkin = tonumber(outfit) or
                          tonumber(F.getDesiredWear("tshirtRes", "tshirtRes",
                                                    "AddOutfitLastLobbyTshirtRes",
                                                    F.syncBodyCacheFromLobby)) or
                          0
        local crewBase, crewColor, crewPattern =
            F.getCrewUniformCustomization(_G.SuitSkin)
        if crewBase then
            _G.SuitSkin = crewBase
            _G.AddOutfitCrewColor = crewColor
            _G.AddOutfitCrewPattern = crewPattern
        end
        _G.PantsSkin = tonumber(F.getDesiredWear("pantsRes", "pantsRes",
                                                 "AddOutfitLastLobbyPantsRes",
                                                 F.syncBodyCacheFromLobby)) or 0
        _G.ShoesSkin = tonumber(F.getDesiredWear("shoesRes", "shoesRes",
                                                 "AddOutfitLastLobbyShoesRes",
                                                 F.syncBodyCacheFromLobby)) or 0
        _G.GlovesSkin = tonumber(F.getDesiredWear("glovesRes", "glovesRes",
                                                  "AddOutfitLastLobbyGlovesRes",
                                                  F.syncBodyCacheFromLobby)) or
                            0
        _G.MaskSkin = tonumber(F.getDesiredMask()) or 0
        _G.GlassSkin = tonumber(F.getDesiredGlass()) or 0
        _G.GliderSkin = tonumber(F.getDesiredGliderRes()) or 0
        _G.ParachuteSkin = tonumber(F.getDesiredParachuteRes()) or 0
    end

    function F.setMakeSkinAtIndex(comp, applyIdx, resID, slotID)
        resID = tonumber(resID)
        slotID = tonumber(slotID)
        applyIdx = tonumber(applyIdx)
        if not comp or not slua.isValid(comp) or not resID or resID <= 0 or
            not slotID or applyIdx == nil then return false end
        local changed = false
        pcall(function()
            local net = comp.NetAvatarData
            if not net then return end
            local applyData = net.SlotSyncData
            if not applyData or not slua.isValid(applyData) then
                return
            end
            local equipment = applyData:Get(applyIdx)
            if equipment and equipment.SlotID == slotID then
                local cur = tonumber(equipment.ItemId) or
                                tonumber(equipment.ItemID) or 0
                if cur ~= resID then
                    F.ensureSkinDownload(resID)
                    equipment.ItemId = resID
                    if equipment.ItemID ~= nil then
                        equipment.ItemID = resID
                    end
                    applyData:Set(applyIdx, equipment)
                    changed = true
                end
            end
        end)
        return changed
    end

    function F.applySlotSkinBatch(comp, entries, opts)
        opts = opts or {}
        if not comp or not slua.isValid(comp) or not entries then
            return false
        end
        local changed, appliedCount, requestedCount = false, 0, 0
        pcall(function()
            local ESyncOperation = import("ESyncOperation")
            local net = comp.NetAvatarData
            if not net then return end
            local applyData = net.SlotSyncData
            if not applyData or not slua.isValid(applyData) then
                return
            end

            local function applyCustomization(target, colorID, patternID)
                if not target or not colorID then return end
                for _, field in ipairs({
                    "ColorID", "ColorId", "colorID", "color_id", "Color",
                    "color"
                }) do
                    pcall(function() target[field] = colorID end)
                end
                for _, field in ipairs({
                    "PatternID", "PatternId", "patternID", "pattern_id",
                    "Pattern", "pattern"
                }) do
                    pcall(function()
                        target[field] = patternID or 0
                    end)
                end
                
                
                
                pcall(function()
                    local custom = target.CustomInfo
                    if slua and slua.IndexReference then
                        custom = slua.IndexReference(target, "CustomInfo") or
                                     custom
                    end
                    if custom then
                        custom.ColorID = colorID
                        custom.PatternID = patternID or 0
                    end
                end)
            end

            for _, e in ipairs(entries) do
                local itemId, slotId = tonumber(e[1]), tonumber(e[2])
                local colorID, patternID = tonumber(e[3]), tonumber(e[4]) or 0
                if itemId and itemId > 0 and slotId then
                    requestedCount = requestedCount + 1
                    F.ensureSkinDownload(itemId)
                    local found = false
                    for i = 0, applyData:Num() - 1 do
                        local equipment = applyData:Get(i)
                        if equipment and equipment.SlotID == slotId then
                            found = true
                            local cur = tonumber(equipment.ItemId) or
                                            tonumber(equipment.ItemID) or 0
                            if cur ~= itemId then
                                equipment.ItemId = itemId
                                if equipment.ItemID ~= nil then
                                    equipment.ItemID = itemId
                                end
                                if equipment.FakeItemID ~= nil then
                                    equipment.FakeItemID = itemId
                                end
                                if ESyncOperation then
                                    equipment.OperationType =
                                        ESyncOperation.PutOn
                                end
                                applyCustomization(equipment, colorID, patternID)
                                applyData:Set(i, equipment)
                                changed = true
                            elseif colorID then
                                applyCustomization(equipment, colorID, patternID)
                                applyData:Set(i, equipment)
                                changed = true
                            end
                            appliedCount = appliedCount + 1
                            break
                        end
                    end

                    
                    
                    if not found then
                        local okEntry, entry = pcall(function()
                            return import("AvatarSyncData")()
                        end)
                        if okEntry and entry then
                            entry.SlotID = slotId
                            entry.ItemId = itemId
                            if entry.ItemID ~= nil then
                                entry.ItemID = itemId
                            end
                            if entry.FakeItemID ~= nil then
                                entry.FakeItemID = itemId
                            end
                            if ESyncOperation then
                                entry.OperationType = ESyncOperation.PutOn
                            end
                            applyCustomization(entry, colorID, patternID)
                            applyData:Add(entry)
                            changed = true
                            appliedCount = appliedCount + 1
                        end
                    end
                end
            end
            if (changed or opts.forceRep) and comp.OnRep_BodySlotStateChanged then
                comp:OnRep_BodySlotStateChanged()
            end
        end)
        local complete = requestedCount > 0 and appliedCount == requestedCount
        F.skinDiag(complete and ("SLOT_BATCH") or ("SLOT_BATCH_FAIL"),
                   "requested=" .. tostring(requestedCount) .. " applied=" ..
                       tostring(appliedCount) .. " changed=" ..
                       tostring(changed), complete and 1 or 0)
        return complete
    end

    function F.setMakeSkin(comp, resID, slotID, opts)
        opts = opts or {}
        slotID, resID = tonumber(slotID), tonumber(resID)
        if not comp or not slua.isValid(comp) or not slotID or not resID or
            resID <= 0 then return false end
        local changed, already, found = false, false, false
        pcall(function()
            local ESyncOperation = import("ESyncOperation")
            local net = comp.NetAvatarData
            if not net then return end
            local applyData = net.SlotSyncData
            if not applyData or not slua.isValid(applyData) then
                return
            end
            local function applyCustomization(target)
                local colorID = tonumber(opts.color)
                local patternID = tonumber(opts.pattern) or 0
                if not target or not colorID then return end
                for _, field in ipairs({
                    "ColorID", "ColorId", "colorID", "color_id", "Color",
                    "color"
                }) do
                    pcall(function() target[field] = colorID end)
                end
                for _, field in ipairs({
                    "PatternID", "PatternId", "patternID", "pattern_id",
                    "Pattern", "pattern"
                }) do
                    pcall(function()
                        target[field] = patternID
                    end)
                end
                pcall(function()
                    local custom = target.CustomInfo
                    if slua and slua.IndexReference then
                        custom = slua.IndexReference(target, "CustomInfo") or
                                     custom
                    end
                    if custom then
                        custom.ColorID = colorID
                        custom.PatternID = patternID
                    end
                end)
            end
            local num = applyData:Num()
            for i = 0, num - 1 do
                local equipment = applyData:Get(i)
                if equipment and equipment.SlotID == slotID then
                    found = true
                    local cur = tonumber(equipment.ItemId) or
                                    tonumber(equipment.ItemID) or 0
                    if cur == resID then
                        already = true
                    elseif cur ~= resID then
                        F.ensureSkinDownload(resID)
                        equipment.ItemId = resID
                        if equipment.ItemID ~= nil then
                            equipment.ItemID = resID
                        end
                        if equipment.FakeItemID ~= nil then
                            equipment.FakeItemID = resID
                        end
                        if ESyncOperation then
                            equipment.OperationType = ESyncOperation.PutOn
                        end
                        applyData:Set(i, equipment)
                        changed = true
                    end
                    if opts.color then
                        applyCustomization(equipment)
                        applyData:Set(i, equipment)
                        changed = true
                    end
                    break
                end
            end

            if not found then
                F.ensureSkinDownload(resID)
                local entry = import("AvatarSyncData")()
                entry.SlotID = slotID
                entry.ItemId = resID
                if entry.ItemID ~= nil then entry.ItemID = resID end
                if entry.FakeItemID ~= nil then
                    entry.FakeItemID = resID
                end
                if ESyncOperation then
                    entry.OperationType = ESyncOperation.PutOn
                end
                applyCustomization(entry)
                applyData:Add(entry)
                changed = true
            end
            if changed and not opts.skipRep and comp.OnRep_BodySlotStateChanged then
                comp:OnRep_BodySlotStateChanged()
            end
            if opts.inAir and comp.PutOnCustomEquipmentByID then
                comp:PutOnCustomEquipmentByID(resID)
            end
        end)
        if already or changed then return true end
        if opts.allowPutOn and comp.PutOnCustomEquipmentByID then
            local ok = pcall(function()
                comp:PutOnCustomEquipmentByID(resID)
            end)
            return ok
        end
        return false
    end
    F.setSlotSkin = F.setMakeSkin

    _G.setMakeSkin = function(applyIdx, itemId, applyEquipSlot)
        local char = F.getLocalChar()
        if not char then return end
        local comp = F.getAvatarComp2(char)
        if not comp then return end
        if F.setMakeSkinAtIndex(comp, applyIdx, itemId, applyEquipSlot) then
            pcall(function()
                if comp.OnRep_BodySlotStateChanged then
                    comp:OnRep_BodySlotStateChanged()
                end
            end)
        end
    end

    function F.patchWearNetAvatar(comp, resID, slotName, noForceShow)
        if not comp or not slua.isValid(comp) or not resID or resID <= 0 or
            not slotName then return false end
        local ok = false
        pcall(function()
            local EAvatarSlotType = import("EAvatarSlotType")
            local ESyncOperation = import("ESyncOperation")
            local slot = EAvatarSlotType[slotName]
            if not slot then return end
            local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
            if sync then
                sync.ItemID = resID
                if sync.FakeItemID ~= nil then
                    sync.FakeItemID = resID
                end
                sync.OperationType = ESyncOperation.PutOn
                if comp.ChangeSlotSyncData then
                    comp:ChangeSlotSyncData(sync)
                    ok = true
                end
            end
            if not noForceShow and comp.SetAvatarVisibility then
                comp:SetAvatarVisibility(slot, true, true)
            end
        end)
        return ok
    end

