    local EQUIP_FAMILY_TABLES = {
        "BackpackMapping", "BackPackMapping", "BagMapping",
        "BackpackSkinMapping", "BagSkinMapping", "HelmetMapping",
        "HelmetSkinMapping", "HeadMapping"
    }

    
    
