    function F.getEquipmentSkinIcon(skinID)
        skinID = tonumber(skinID) or 0
        if skinID <= 0 then return nil end
        local row = F.cfg(skinID)
        if not row then return nil end
        return row.ItemSmallIcon or row.ItemBigIcon or row.Icon or nil
