    function F.getEquipmentSkinFamily(resID)
        resID = tonumber(resID) or 0
        if resID <= 0 then return {0, 0, 0}, 0 end

        local forcedCatalog = FORCED_EQUIPMENT_CATALOG[resID]
        if forcedCatalog then
            return FORCED_EQUIPMENT_FAMILIES[forcedCatalog], forcedCatalog
        end

        
        
        local family, catalogID = nil, nil
        pcall(function()
            local row = nil
            for _, tableName in ipairs(EQUIP_FAMILY_TABLES) do
                row = CDataTable.GetTableData(tableName, resID)
                if not row and CDataTable.GetTableDataByFilter then
                    row = CDataTable.GetTableDataByFilter(tableName, "SkinID",
                                                          resID)
                    if not row then
                        for level = 1, 3 do
                            row = CDataTable.GetTableDataByFilter(
                                      tableName, "SkinItemIDLv" .. level,
                                      resID)
                            if row then break end
                        end
                    end
                end
                if row then break end
            end
            if row then
                local values = {
                    tonumber(row.SkinItemIDLv1), tonumber(row.SkinItemIDLv2),
                    tonumber(row.SkinItemIDLv3)
                }
                if values[1] and values[1] > 0 and values[2] and values[2] > 0 and
                    values[3] and values[3] > 0 then
                    family = values
                    catalogID = tonumber(row.SkinID)
                end
            end
        end)
        return family or {resID, resID, resID}, catalogID or resID
    end

    
    
    
    function F.getEquipmentSkinFamilyCached(resID)
        resID = tonumber(resID) or 0
        local hit = F._equipFamilyCache[resID]
        if hit then return hit.family, hit.catalogID end
        local family, catalogID = F.getEquipmentSkinFamily(resID)
        F._equipFamilyCache[resID] = {family = family, catalogID = catalogID}
        return family, catalogID
    end

    
    
    
    
    
    
    
    
    
    
    

    
    
    
    
    
    
    
    
    

