    function F.equipmentLevelFromID(id)
        local n = tonumber(id)
        if not n then return nil end
        
        local sub = {[501001] = 1, [501004] = 1, [501002] = 2, [501005] = 2,
                     [501003] = 3, [502001] = 1, [502004] = 1, [502002] = 2,
                     [502005] = 2, [502003] = 3}
        if sub[n] then return sub[n] end
        
        
        local rangeBase = nil
        if n >= 1502000000 and n < 1502010000 then
            rangeBase = 1502000000
        elseif n >= 1501000000 and n < 1501010000 then
            rangeBase = 1501000000
        end
        if rangeBase then
            local lvl = math.floor((n - rangeBase) / 1000)
            if lvl >= 1 and lvl <= 3 then return lvl end
        end
        
        local rs = tostring(n)
        if #rs == 10 and (rs:sub(1, 6) == "150100" or rs:sub(1, 6) == "150200") then
            local d = tonumber(rs:sub(7, 7))
            if d ~= nil then
                if d <= 1 then return 1 end
                if d == 2 then return 2 end
                return 3
            end
        end
        
        local got = nil
        pcall(function()
            local BU = import("BackpackUtils")
            if BU then
                if type(BU.GetEquipmentHelmetLevel) == "function" then
                    got = tonumber(BU.GetEquipmentHelmetLevel(n))
                end
                if not got and type(BU.GetEquipmentBagLevel) == "function" then
                    got = tonumber(BU.GetEquipmentBagLevel(n))
                end
            end
        end)
        if got and got >= 1 and got <= 3 then return got end
        return nil
    end
    function F.levelSkinID(baseSkin, level)
        level = math.max(1, math.min(3, math.floor(tonumber(level) or 1)))
        local family = F.getEquipmentSkinFamily(baseSkin)
        return tonumber(family[level]) or tonumber(family[1]) or 0
    end

    
    
    
    
    
    function F.applyInitialEquipmentAvatar(char, bagRes, helmetRes)
        pcall(function()
            
            
            
            local pc = F.getPC and F.getPC() or nil
            if not pc then
                pc = Game and Game.GetPlayerController and
                         Game:GetPlayerController(0) or nil
            end
            if not pc then
                FourRDiag("EQUIP_AVATAR", "no pc", 10)
                return
            end
            local function physLevel(wantedSubType)
                local lvl = 1
                pcall(function()
                    local phys = F.getEquippedArmorItemID(wantedSubType)
                    if phys and phys > 0 then
                        local got = nil
                        pcall(function()
                            local BU = import("BackpackUtils")
                            local fn = BU and
                                           (wantedSubType == 501 and
                                                BU.GetEquipmentBagLevel or
                                                BU.GetEquipmentHelmetLevel)
                            if fn then got = tonumber(fn(phys)) end
                        end)
                        if not got and F.equipmentLevelFromID then
                            got = F.equipmentLevelFromID(phys)
                        end
                        if got then lvl = got end
                    end
                end)
                return math.max(1, math.min(3, lvl))
            end
            local eq = pc.InitialEquipmentAvatar or {}
            local wrote = false
            if tonumber(bagRes) and tonumber(bagRes) > 0 then
                local fam = F.getEquipmentSkinFamily(bagRes)
                local lvl = physLevel(501)
                local disp = tonumber(fam[lvl]) or tonumber(fam[1]) or 0
                if disp > 0 then
                    eq.BagAvatar = disp
                    eq.BagAvatarList = {
                        tonumber(fam[1]) or 0, tonumber(fam[2]) or 0,
                        tonumber(fam[3]) or 0
                    }
                    wrote = true
                end
            end
            if tonumber(helmetRes) and tonumber(helmetRes) > 0 then
                local fam = F.getEquipmentSkinFamily(helmetRes)
                local lvl = physLevel(502)
                local disp = tonumber(fam[lvl]) or tonumber(fam[1]) or 0
                if disp > 0 then
                    eq.HelmetAvatar = disp
                    eq.HelmetAvatarList = {
                        tonumber(fam[1]) or 0, tonumber(fam[2]) or 0,
                        tonumber(fam[3]) or 0
                    }
                    wrote = true
                end
            end
            if wrote then
                pc.InitialEquipmentAvatar = eq
                pcall(function()
                    if slua.isValid(pc.PlayerState) and
                        pc.PlayerState.MetroPlayerStateAvatarFeature then
                        pc.PlayerState.MetroPlayerStateAvatarFeature.InitialEquipmentAvatar =
                            eq
                    end
                end)
                FourRDiag("EQUIP_AVATAR",
                          "bag=" .. tostring(eq.BagAvatar) ..
                              " helmet=" .. tostring(eq.HelmetAvatar), 10)
            end
        end)
    end
    function F.getEquippedArmorItemID(wantedSubType)
        local found = 0
        pcall(function()
            local lib = import("STExtraBlueprintFunctionLibrary")
            local utils = import("BackpackUtils")
            local pc, char, comp

            
            
            
            pcall(function()
                local gd = require("GameLua.GameCore.Data.GameplayData")
                pc = gd and gd.GetPlayerController and gd.GetPlayerController()
            end)
            char = F.getLocalChar and F.getLocalChar() or nil
            if (not pc or not slua.isValid(pc)) and char then
                pc = char.Controller
            end
            if not pc or not slua.isValid(pc) then pc = F.getPC() end

            if char and slua.isValid(char) then
                comp = char.BackpackComponent or char.BackPackComponent
            end
            if not comp or not slua.isValid(comp) then
                comp = pc and lib.GetBackpackComponentFromController(pc)
            end
            if not comp or not slua.isValid(comp) then
                F.skinDiag("ARMOR_SCAN",
                           "wanted=" .. tostring(wantedSubType) ..
                               " no active backpack component", 3)
                return
            end
            local armors = utils.GetEuqippedArmorInBackpack(comp)
            local scanned = {}
            for _, armor in pairs(armors or {}) do
                local defineID = slua.IndexReference(armor, "DefineID")
                local itemID = defineID and tonumber(defineID.TypeSpecificID) or
                                   0
                local data = itemID > 0 and F.cfg(itemID)
                local subType = data and tonumber(data.ItemSubType) or 0
                scanned[#scanned + 1] = tostring(itemID) .. ":" ..
                                            tostring(subType)
                
                
                
                
                if subType == 504 then subType = 501 end
                if subType == 505 then subType = 502 end
                if subType == wantedSubType then
                    found = itemID
                    break
                end
            end
            F.skinDiag("ARMOR_SCAN",
                       "wanted=" .. tostring(wantedSubType) .. " entries=" ..
                           table.concat(scanned, ",") .. " found=" ..
                           tostring(found), 3)
        end)
        return found
    end

    function F.getEquipmentLevelFromItem(itemID, wantedSubType)
        itemID = tonumber(itemID) or 0
        local level = 1
        local detected = false
        pcall(function()
            local utils = import("BackpackUtils")
            if wantedSubType == 501 and utils.GetEquipmentBagLevel then
                local value = tonumber(utils.GetEquipmentBagLevel(itemID))
                if value and value >= 1 and value <= 3 then
                    level, detected = value, true
                end
            elseif wantedSubType == 502 and utils.GetEquipmentHelmetLevel then
                local value = tonumber(utils.GetEquipmentHelmetLevel(itemID))
                if value and value >= 1 and value <= 3 then
                    level, detected = value, true
                end
            end
        end)
        if not detected then
            if itemID >= 501001 and itemID <= 501003 then
                level = itemID - 501000
            elseif itemID >= 502001 and itemID <= 502003 then
                level = itemID - 502000
            else
                local major = math.floor(itemID / 10000)
                if major == 150100 or major == 150200 then
                    local marker = math.floor((itemID % 10000) / 1000)
                    if marker >= 1 and marker <= 3 then
                        level = marker
                    end
                end
            end
        end
        return math.max(1, math.min(3, level))
    end

    
    
    do
        local seen, normalized = {}, {}
        for index = 1, #ITEMS do
            local resID = tonumber(ITEMS[index])
            if resID and
                (F.isBackpackSkinRes(resID) or F.isHelmetSkinRes(resID)) then
                local _, catalogID = F.getEquipmentSkinFamily(resID)
                resID = tonumber(catalogID) or resID
            end
            if resID and resID > 0 and not seen[resID] then
                normalized[#normalized + 1] = resID
                seen[resID] = true
            end
        end
        ITEMS = normalized
    end

    function F.applyEquipSkinToComp(comp, bagRes, helmetRes)
        local applied, requested, completed = false, 0, 0
        pcall(function()
            local EAvatarSlotType = import("EAvatarSlotType")
            local ESyncOperation = import("ESyncOperation")
            local BackpackUtils = import("BackpackUtils")
            local function doSlot(slotEnum, res, levelFn, lastKey, wantedSubType)
                res = tonumber(res) or 0
                if res <= 0 or not slotEnum then return end
                requested = requested + 1
                local sync = comp.GetSlotSyncData and
                                 comp:GetSlotSyncData(slotEnum)
                local cur = sync and
                                (tonumber(sync.ItemID) or tonumber(sync.ItemId) or
                                    0) or 0
                local addID = sync and tonumber(sync.AdditionalItemID) or 0
                local physicalID = addID
                if physicalID <= 0 then
                    physicalID = F.getEquippedArmorItemID(wantedSubType)
                end
                local lvl = 1
                pcall(function()
                    
                    
                    
                    if physicalID > 0 then
                        local got = nil
                        if levelFn then got = tonumber(levelFn(physicalID)) end
                        if not got and F.equipmentLevelFromID then
                            got = F.equipmentLevelFromID(physicalID)
                        end
                        if got then lvl = got end
                    end
                end)
                if lvl < 1 then lvl = 1 end
                if lvl > 3 then lvl = 3 end
                local target = F.levelSkinID(res, lvl)
                if target <= 0 then
                    F.skinDiag("EQUIPMENT_FAIL",
                               "slot=" .. tostring(lastKey) .. " selected=" ..
                                   tostring(res) .. " level=" .. tostring(lvl) ..
                                   " target unresolved", 0)
                    return
                end
                F.skinDiag("EQUIPMENT_RESOLVE",
                           "slot=" .. tostring(lastKey) .. " selected=" ..
                               tostring(res) .. " physical=" ..
                               tostring(physicalID) .. " level=" ..
                               tostring(lvl) .. " target=" .. tostring(target) ..
                               " current=" .. tostring(cur), 3)
                F.ensureSkinDownload(target)

                if sync then
                    if cur ~= target then
                        sync.ItemID = target
                        if sync.ItemId ~= nil then
                            sync.ItemId = target
                        end
                        if sync.FakeItemID ~= nil then
                            sync.FakeItemID = target
                        end
                        if ESyncOperation then
                            sync.OperationType = ESyncOperation.PutOn
                        end
                        comp:ChangeSlotSyncData(sync)
                        applied = true
                    end
                    completed = completed + 1
                    EQUIP_APPLY[lastKey] = target
                    return
                end

                
                
                local net = comp.NetAvatarData
                local applyData = net and net.SlotSyncData
                if applyData and slua.isValid(applyData) then
                    local entry = import("AvatarSyncData")()
                    entry.SlotID = slotEnum
                    entry.ItemId = target
                    if entry.ItemID ~= nil then
                        entry.ItemID = target
                    end
                    if entry.FakeItemID ~= nil then
                        entry.FakeItemID = target
                    end
                    entry.AdditionalItemID = addID
                    if ESyncOperation then
                        entry.OperationType = ESyncOperation.PutOn
                    end
                    applyData:Add(entry)
                    applied = true
                    completed = completed + 1
                    EQUIP_APPLY[lastKey] = target
                end
            end
            doSlot(EAvatarSlotType.EAvatarSlotType_BackpackEquipemtSlot, bagRes,
                   BackpackUtils and BackpackUtils.GetEquipmentBagLevel,
                   "lastBagWrite", 501)
            doSlot(EAvatarSlotType.EAvatarSlotType_HelmetEquipemtSlot,
                   helmetRes,
                   BackpackUtils and BackpackUtils.GetEquipmentHelmetLevel,
                   "lastHelmetWrite", 502)
        end)
        local complete = requested == completed
        F.skinDiag(complete and ("EQUIPMENT") or ("EQUIPMENT_FAIL"),
                   "bag=" .. tostring(bagRes) .. " helmet=" ..
                       tostring(helmetRes) .. " requested=" ..
                       tostring(requested) .. " completed=" ..
                       tostring(completed) .. " changed=" .. tostring(applied),
                   complete and 3 or 0)
        return applied, complete
    end

    function F.matchApplyEquipmentSkin(char, bagRes, helmetRes)
        bagRes = tonumber(bagRes) or 0
        helmetRes = tonumber(helmetRes) or 0
        if bagRes <= 0 and helmetRes <= 0 then return true end
        local comp = char.CharacterAvatarComp2_BP
        if not slua.isValid(comp) then return false end

        F.applyInitialEquipmentAvatar(char, bagRes, helmetRes)

        local applied, complete =
            F.applyEquipSkinToComp(comp, bagRes, helmetRes)

        if applied then
            pcall(function()
                if comp.OnRep_BodySlotStateChanged then
                    comp:OnRep_BodySlotStateChanged()
                end
            end)
            return true
        end
        return complete
    end

    function F.startEquipmentSkinWatcher()
        if _G.AddOutfitEquipmentSkinWatcherActive then return true end
        local okTicker, ticker = pcall(require, "common.time_ticker")
        if not okTicker or not ticker or not ticker.AddTimerLoop then
            return false
        end

        _G.AddOutfitEquipmentSkinWatcherActive = true
        ticker.AddTimerLoop(0, function()
            local modSkin = _G.VIPConfig and _G.VIPConfig.ModSkin
            if not (modSkin == true or tonumber(modSkin) == 1) then
                return
            end
            if F.isInRealMatch and not F.isInRealMatch() then return end
            local char = F.getLocalChar()
            if not char or not slua.isValid(char) then return end

            local bagRes = F.getDesiredWear("bagRes", "bagRes",
                                            "AddOutfitLastLobbyBagRes",
                                            F.syncBodyCacheFromLobby)
            local helmetRes = F.getDesiredWear("helmetRes", "helmetRes",
                                               "AddOutfitLastLobbyHelmetRes",
                                               F.syncBodyCacheFromLobby)
            if (tonumber(bagRes) or 0) <= 0 and (tonumber(helmetRes) or 0) <= 0 then
                return
            end

            local comp = F.getAvatarComp2(char)
            if not comp or not slua.isValid(comp) then return end
            local applied = F.applyEquipSkinToComp(comp, bagRes, helmetRes)
            if applied and comp.OnRep_BodySlotStateChanged then
                pcall(function()
                    comp:OnRep_BodySlotStateChanged()
                end)
            end
        end, -1, 1.5)
        return true
    end

    function F.hookEquipmentRectify()
        _G.AddOutfitEquipRectifyFn = function(self)
            pcall(function()
                if self.IsLobbyActor and self:IsLobbyActor() then
                    return
                end
                if not (self.IsSelf and self:IsSelf()) then
                    return
                end
                local bagRes = F.getDesiredWear("bagRes", "bagRes",
                                                "AddOutfitLastLobbyBagRes",
                                                F.syncBodyCacheFromLobby)
                local helmetRes = F.getDesiredWear("helmetRes", "helmetRes",
                                                   "AddOutfitLastLobbyHelmetRes",
                                                   F.syncBodyCacheFromLobby)
                local applied = false
                if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
                    applied = F.applyEquipSkinToComp(self, bagRes, helmetRes)
                end
                local currentChar = F.getLocalChar()
                if not F.eventOwnsClothes(currentChar) then
                    local selected = tonumber(
                                         PERSIST.configSlots and
                                             PERSIST.configSlots.tshirt) or
                                         tonumber(F.cache().tshirtRes)
                    local crewBase, crewColor, crewPattern =
                        F.getCrewUniformCustomization(selected)
                    if crewBase then
                        applied = F.applySlotSkinBatch(self, {
                            {
                                crewBase, F.CUST_SLOT.ClothesEquipemtSlot,
                                crewColor, crewPattern
                            }
                        }, {forceRep = true}) or applied
                    end
                end
                if applied and self.OnRep_BodySlotStateChanged then
                    self:OnRep_BodySlotStateChanged()
                end
            end)
        end
        pcall(function()
            local MCAC = require(
                             "GameLua.Mod.TPlan.Component.MetroCharacterAvatarComponent")
            if MCAC._AddOutfitRectifyHooked then return end
            MCAC._AddOutfitRectifyHooked = true
            local o = MCAC.ProcessClientAvatarRectify
            MCAC.ProcessClientAvatarRectify = function(self)
                o(self)
                if _G.AddOutfitEquipRectifyFn then
                    _G.AddOutfitEquipRectifyFn(self)
                end
            end
        end)
    end

    function F.applyAirborneSlots(char, forceInAir)
        local comp = F.getAvatarComp2(char)
        if not comp or not slua.isValid(comp) then return false end
        pcall(function() F.syncAirborneToDataMgr() end)
        local inAir = forceInAir == true or F.isCharacterAirborne(char)
        local any = false
        local paraRes = F.getDesiredParachuteRes()
        if paraRes and paraRes > 0 then
            any = true
            if not F.isResourcesReady(paraRes) then
                F.requestResourceDownload(paraRes)
            end
            F.setMakeSkin(comp, paraRes, F.CUST_SLOT.ParachuteEquipemtSlot,
                          {inAir = inAir})
        end
        local gliderRes = F.getDesiredGliderRes()
        if gliderRes and gliderRes > 0 then
            any = true
            if not F.isResourcesReady(gliderRes) then
                F.requestResourceDownload(gliderRes)
            end
            F.setMakeSkin(comp, gliderRes, F.CUST_SLOT.GlideEquipemtSlot,
                          {inAir = inAir})
        end
        return any
    end

