        }
        pieces[#pieces + 1] = {
            F.getDesiredWear("glovesRes", "glovesRes",
                             "AddOutfitLastLobbyGlovesRes",
                             F.syncBodyCacheFromLobby),
            F.CUST_SLOT.HandEffectEquipemtSlot, "ÙÙØ§Ø²Ø§Øª"
        }
        local any, okAll = false, true
        for _, p in ipairs(pieces) do
            local res, slot, label = p[1], p[2], p[3]
            if res and res > 0 then
                any = true
                okAll = F.matchApplyWearItem(char, res, slot, label) and okAll
            end
        end
        local anyAir = F.applyAirborneSlots(char, false)
        if anyAir then any = true end
        local bagRes = F.getDesiredWear("bagRes", "bagRes",
                                        "AddOutfitLastLobbyBagRes",
                                        F.syncBodyCacheFromLobby)
        local helmetRes = F.getDesiredWear("helmetRes", "helmetRes",
                                           "AddOutfitLastLobbyHelmetRes",
                                           F.syncBodyCacheFromLobby)
        if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
            any = true
            okAll = F.matchApplyEquipmentSkin(char, bagRes, helmetRes) and okAll
        end
        return not any or okAll
    end

    function F.eventOwnsClothes(char)
        if not char or not slua.isValid(char) then return false end
        local owns = false
        pcall(function()
            owns = char:HasState(EPawnState.SpecialSuit) or
                       char:HasState(EPawnState.WebSwing)
        end)
        return owns
