    function F.matchApplyAllSlots(char)
        if not F.isEnabled() then return false end
        if not char then return false end
        F.logSkinSlotDetails("match_apply")
        F.syncGlobalWearSkins()
        local comp = F.getAvatarComp2(char)
        if not comp then return false end

        local entries = {}
        local function add(skin, slot, color, pattern)
            skin = tonumber(skin)
            if skin and skin > 0 and slot then
                entries[#entries + 1] = {skin, slot, color, pattern}
            end
        end
        add(_G.HatSkin, F.CUST_SLOT.HatEquipemtSlot)
        if not F.eventOwnsClothes(char) then
            local crewBase, crewColor, crewPattern =
                F.getCrewUniformCustomization(_G.SuitSkin)
            add(crewBase or _G.SuitSkin, F.CUST_SLOT.ClothesEquipemtSlot,
                crewColor, crewPattern)
        end
        add(_G.PantsSkin, F.CUST_SLOT.PantsEquipemtSlot)
        add(_G.ShoesSkin, F.CUST_SLOT.ShoesEquipemtSlot)
        add(_G.GlovesSkin, F.CUST_SLOT.HandEffectEquipemtSlot)
        add(_G.MaskSkin, F.CUST_SLOT.FaceEquipemtSlot)
        add(_G.GlassSkin, F.CUST_SLOT.GlassEquipemtSlot)

        local ok = (#entries == 0)
        if #entries > 0 then
            ok = F.applySlotSkinBatch(comp, entries, {forceRep = true})
            if not ok then
                local allOk = true
                for _, e in ipairs(entries) do
                    allOk = F.setMakeSkin(comp, e[1], e[2], {
                        allowPutOn = true,
                        color = e[3],
                        pattern = e[4]
                    }) and allOk
                end
                ok = allOk
            end
        end

        F.applyAirborneSlots(char, false)

        local bagRes = F.getDesiredWear("bagRes", "bagRes",
                                        "AddOutfitLastLobbyBagRes",
                                        F.syncBodyCacheFromLobby)
        local helmetRes = F.getDesiredWear("helmetRes", "helmetRes",
                                           "AddOutfitLastLobbyHelmetRes",
                                           F.syncBodyCacheFromLobby)
        if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
            ok = F.matchApplyEquipmentSkin(char, bagRes, helmetRes) and ok
        end

        
        ok = F.applySelectedGrenadeSkin() and ok

        F.skinDiag(ok and ("MATCH_SLOTS") or ("MATCH_SLOTS_FAIL"),
                   "wearEntries=" .. tostring(#entries) .. " bag=" ..
                       tostring(bagRes) .. " helmet=" ..
                       tostring(helmetRes) .. " grenade=" ..
                       tostring(F.cache().grenadeRes) .. " result=" ..
                       tostring(ok), ok and 3 or 0)

        return ok
    end

    function F.matchApplyHat(char)
        local hatRes = tonumber(F.getDesiredHat())
        if not hatRes or hatRes <= 0 then return true end
        char = char or F.getLocalChar()
        if not char then return false end
        local comp = F.getAvatarComp2(char)
        if not comp then return false end
        local slotID = F.CUST_SLOT.HatEquipemtSlot
        local ok = false
        pcall(function()
            local net = comp.NetAvatarData
            if not net then return end
            local applyData = net.SlotSyncData
            if not applyData or not slua.isValid(applyData) then
                return
            end
            local found = false
            for i = 0, applyData:Num() - 1 do
                local equipment = applyData:Get(i)
                if equipment and equipment.SlotID == slotID then
                    found = true
                    local cur = tonumber(equipment.ItemId) or
                                    tonumber(equipment.ItemID) or 0
                    if cur ~= hatRes then
                        F.ensureSkinDownload(hatRes)
                        equipment.ItemId = hatRes
                        if equipment.ItemID ~= nil then
                            equipment.ItemID = hatRes
                        end
                        if equipment.FakeItemID ~= nil then
                            equipment.FakeItemID = hatRes
                        end
                        applyData:Set(i, equipment)
                    end
                    ok = true
                    break
                end
            end
            if not found then
                F.ensureSkinDownload(hatRes)
                local ESyncOperation = import("ESyncOperation")
                local entry = import("AvatarSyncData")()
                entry.SlotID = slotID
                entry.ItemId = hatRes
                entry.ItemID = hatRes
                entry.FakeItemID = hatRes
                entry.OperationType = ESyncOperation.PutOn
                applyData:Add(entry)
                ok = true
            end

        end)
        return ok
    end

    local _avatarItemsRegistered = false

    function F.getDesiredWeaponSkins()
        if PERF.desiredSkins then return PERF.desiredSkins end
        F.syncWeaponCacheFromLobby()
        local out, seen = {}, {}
        local function add(res)
            res = tonumber(res)
            if res and res > 0 and not seen[res] then
                seen[res] = true;
                out[#out + 1] = res
            end
        end
        for _, w in pairs(F.cache().weapons) do
            
            
            if w.resID then add(w.resID) end
        end
        if MATCH_CONFIG.weaponSkins then
            for _, res in pairs(MATCH_CONFIG.weaponSkins) do add(res) end
        end
        PERF.desiredSkins = out
        return out
    end

    function F._cacheSkinTarget(weaponResID, skin)
        if skin and skin > 0 then
            PERF.skinTarget[weaponResID] = skin
        else
            PERF.skinTarget[weaponResID] = 0
        end
        return skin
    end

    local GUN_MASTER_SYN_SLOT = 7

    function F.findSkinSlotInSynData(weapon)
        if not slua.isValid(weapon) then return GUN_MASTER_SYN_SLOT, 0 end
        local arr = weapon.synData
        if not arr or not slua.isValid(arr) then
            return GUN_MASTER_SYN_SLOT, 0
        end
        local count = 0
        pcall(function() count = arr:Num() end)
        for i = 0, math.min(count - 1, 15) do
            local ok2, att = pcall(function() return arr:Get(i) end)
            if ok2 and att then
                local ok3, defRef = pcall(slua.IndexReference, att, "defineID")
                if ok3 and defRef then
                    local tid = 0
                    pcall(function()
                        tid = tonumber(defRef.TypeSpecificID) or 0
                    end)
                    if tid >= 1000000 then return i, tid end
                end
            end
        end
        return GUN_MASTER_SYN_SLOT, 0
    end

    function F.resolveWeaponTypeID(weaponResID)
        weaponResID = tonumber(weaponResID) or 0
        if weaponResID <= 0 then return 0 end
        local found = 0
        pcall(function()
            local wc = CDataTable.GetTableData("WeaponConfig", weaponResID)
            if wc then
                found = tonumber(wc.WeaponID or wc.WeaponId or wc.weaponID or 0)
            end
        end)
        if found > 0 then return found end
        pcall(function()
            local ic = CDataTable.GetTableData("Item", weaponResID)
            if ic then
                found = tonumber(ic.WeaponID or ic.weaponId or 0)
            end
        end)
        return found > 0 and found or weaponResID
    end

    function F.findTargetSkinForWeaponRes(weaponResID)
        weaponResID = tonumber(weaponResID) or 0
        if weaponResID <= 0 then return nil end
        local cached = PERF.skinTarget[weaponResID]
        if cached ~= nil then return cached == 0 and nil or cached end

        local memSkin = F.getMatchWeaponSkin(weaponResID)
        if memSkin then return F._cacheSkinTarget(weaponResID, memSkin) end
        local typeID = F.resolveWeaponTypeID(weaponResID)
        if typeID > 0 and typeID ~= weaponResID then
            memSkin = F.getMatchWeaponSkin(typeID)
            if memSkin then
                return F._cacheSkinTarget(weaponResID, memSkin)
            end
        end

        if MATCH_CONFIG.weaponSkins and MATCH_CONFIG.weaponSkins[weaponResID] then
            local fixed = tonumber(MATCH_CONFIG.weaponSkins[weaponResID])
            if fixed and fixed > 0 then
                return F._cacheSkinTarget(weaponResID, fixed)
            end
        end

        for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
            local wid = F.weaponIdFromSkin(skinRes)
            if wid and tonumber(wid) == weaponResID then
                return F._cacheSkinTarget(weaponResID, skinRes)
            end
        end

        local typeID = F.resolveWeaponTypeID(weaponResID)
        if typeID > 0 and typeID ~= weaponResID then
            if MATCH_CONFIG.weaponSkins and MATCH_CONFIG.weaponSkins[typeID] then
                local fixed = tonumber(MATCH_CONFIG.weaponSkins[typeID])
                if fixed and fixed > 0 then
                    return F._cacheSkinTarget(weaponResID, fixed)
                end
            end
            for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
                local wid = F.weaponIdFromSkin(skinRes)
                if wid and tonumber(wid) == typeID then
                    return F._cacheSkinTarget(weaponResID, skinRes)
                end
            end
        end

        local avatarMatch = nil
        pcall(function()
            local AU = import("AvatarUtils")
            local weaponBase = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(
                                                              weaponResID),
                                                          false)
            if not weaponBase or weaponBase <= 0 then return end
            for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
                local skinBase = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(
                                                                skinRes), false)
                if skinBase and skinBase > 0 and skinBase == weaponBase then
                    avatarMatch = skinRes
                    return
                end
            end
        end)
        if avatarMatch then
            return F._cacheSkinTarget(weaponResID, avatarMatch)
        end

        local c = F.cfg(weaponResID)
        local st = F.subType(c)
        if st and GUN_SUB[st] and MATCH_CONFIG.weaponSkins then
            for _, skinRes in pairs(MATCH_CONFIG.weaponSkins) do
                local skinWid = F.weaponIdFromSkin(skinRes)
                if skinWid then
                    local sc = F.cfg(tonumber(skinWid))
                    if sc and F.subType(sc) == st then
                        return F._cacheSkinTarget(weaponResID, skinRes)
                    end
                end
                local sc = F.cfg(skinRes)
                if sc and GUN_SUB[F.subType(sc)] and F.subType(sc) == st then
                    return F._cacheSkinTarget(weaponResID, skinRes)
                end
            end
        end

        PERF.skinTarget[weaponResID] = 0
        return nil
    end

    function F.getSynMasterSkinID(weapon)
        if not slua.isValid(weapon) then return 0 end
        local id = 0
        pcall(function()
            local slot, tid = F.findSkinSlotInSynData(weapon)
            id = tid
            if id == 0 then
                local arr = weapon.synData
                if not arr or not slua.isValid(arr) then return end
                local att = arr:Get(GUN_MASTER_SYN_SLOT)
                if not att then return end
                id = slua.IndexReference(att, "defineID").TypeSpecificID or 0
            end
        end)
        return id
    end

    _G.AddOutfitSkinIdMappings = _G.AddOutfitSkinIdMappings or {}
    _G.AddOutfitLastAppliedSkin = _G.AddOutfitLastAppliedSkin or {}

    function F.buildSkinMappings()
        if not PERF.mappingsDirty then return end
        F.syncWeaponCacheFromLobby()
        PERF.mappingsDirty = false
        local m = _G.AddOutfitSkinIdMappings
        for k in pairs(m) do m[k] = nil end
        for widKey, w in pairs(F.cache().weapons) do
            local wid = tonumber(widKey)
            if wid and w.resID and w.resID > 0 then
                m[wid] = {tonumber(w.resID)}
            end
        end
        if MATCH_CONFIG.weaponSkins then
            for weaponKeyValue, skinResValue in pairs(MATCH_CONFIG.weaponSkins) do
                local weaponKey = tonumber(weaponKeyValue)
                local skinRes = tonumber(skinResValue)
                if weaponKey and skinRes and skinRes > 0 and not m[weaponKey] then
                    m[weaponKey] = {skinRes}
                end
            end
        end
    end

    function F.get_skin_id(currentGunId, maxIt)
        if not F.isEnabled() then return 0 end
        currentGunId = tonumber(currentGunId) or 0
        maxIt = tonumber(maxIt) or 0
        if currentGunId <= 0 and maxIt <= 0 then return 0 end
        F.buildSkinMappings()
        if maxIt > 0 then
            local fromMem = F.getMatchWeaponSkin(maxIt)
            if fromMem then return fromMem end
        end
        local fromMem2 = F.getMatchWeaponSkin(
                             F.resolveWeaponTypeID(currentGunId))
        if fromMem2 then return fromMem2 end
        local m = _G.AddOutfitSkinIdMappings
        if maxIt > 0 and m[maxIt] and m[maxIt][1] then
            return tonumber(m[maxIt][1])
        end
        local list = m[currentGunId]
        if list and list[1] then return tonumber(list[1]) end
        local typeId = F.resolveWeaponTypeID(currentGunId)
        if typeId > 0 and m[typeId] and m[typeId][1] then
            return tonumber(m[typeId][1])
        end
        local target = F.findTargetSkinForWeaponRes(
                           maxIt > 0 and maxIt or currentGunId)
        if target then return target end
        return currentGunId
    end

    
    
    
    function F.hookBackpackWeaponSkinIcon()
        if _G.AddOutfitBackpackSkinHooked then return true end

        local ok, WIIB = pcall(require,
                               "GameLua.Mod.BaseMod.Client.Backpack.WeaponInfoItemBase")
        local impl = ok and WIIB and WIIB.__inner_impl
        local original = impl and impl.UpdateWeaponAppearanceInfo
        if type(original) ~= "function" then return false end

        impl.UpdateWeaponAppearanceInfo =
            function(self, typeSpecificID, battleData, dragOrigin)
                local baseID = tonumber(typeSpecificID) or 0
                local skinID = tonumber(F.get_skin_id(baseID, baseID)) or 0

                if baseID <= 0 or skinID <= 0 or skinID == baseID or
                    not F.isWeaponSkinRes(skinID) then
                    return
                        original(self, typeSpecificID, battleData, dragOrigin)
                end

                F.ensureSkinDownload(skinID)

                local callResult = {
                    pcall(original, self, skinID, battleData, dragOrigin)
                }
                if not callResult[1] then
                    
                    return
                        original(self, typeSpecificID, battleData, dragOrigin)
                end

                pcall(function()
                    local itemData = F.cfg(baseID)
                    self.TypeSpecificIDTemp = baseID
                    self.ItemID = baseID

                    if self.UIRoot then
                        self.UIRoot.ItemID = baseID
                        if self.UIRoot.TextBlock_WeaponName and itemData and
                            itemData.ItemName then
                            self.UIRoot.TextBlock_WeaponName:SetText(
                                itemData.ItemName)
                        end
                    end

                    
                    if self.UpdateBullet then
                        self:UpdateBullet()
                    end
                    if self.UpdateWeaponAttachment then
                        self:UpdateWeaponAttachment()
                    end
                    
                    
                    if _G.VIPConfig and _G.VIPConfig.KillCountUI and
                        self.UpdateKillCounter then
                        self:UpdateKillCounter(true)
                    end
                end)

                local unpackResult = table.unpack or unpack
                return unpackResult(callResult, 2)
            end

        _G.AddOutfitBackpackSkinHooked = true
        return true
    end

    function F.hookWeaponSlotKillCounterIcon()
        if _G.AddOutfitWeaponSlotCounterHooked then return true end
        local ok, SlotUI = pcall(require,
                                 "GameLua.Mod.BaseMod.Client.MainControlUI.SwitchWeaponSlotMode2")
        local impl = ok and SlotUI and SlotUI.__inner_impl
        local original = impl and impl.CheckShowKCIcon
        if type(original) ~= "function" then return false end

        impl.CheckShowKCIcon = function(self)
            local results = {pcall(original, self)}
            pcall(function()
                if not self.KillCounterImg then return end
                local visibility = import("ESlateVisibility")
                if not (_G.VIPConfig and _G.VIPConfig.KillCountUI) then
                    self.KillCounterImg:SetVisibility(visibility.Collapsed)
                    return
                end
                
                
                
                self.KillCounterImg:SetVisibility(
                    visibility.SelfHitTestInvisible)
            end)
            if not results[1] then error(results[2]) end
            local unpackResult = table.unpack or unpack
            return unpackResult(results, 2)
        end

        _G.AddOutfitWeaponSlotCounterHooked = true
        return true
    end

    
    
    function F.hookBackpackWeaponCounterBadge()
        if _G.AddOutfitBackpackWeaponCounterHooked then return true end
        local ok, WeaponUI = pcall(require,
                                   "GameLua.Mod.BaseMod.Client.Backpack.MainWeaponInfoItemUI")
        local impl = ok and WeaponUI and WeaponUI.__inner_impl
        local original = impl and impl.UpdateKillCounter
        if type(original) ~= "function" then return false end

        impl.UpdateKillCounter = function(self, show)
            local enabled = _G.VIPConfig and _G.VIPConfig.KillCountUI
            local panel = self.UIRoot and self.UIRoot.CanvasPanel_KillCounter
            local visibility = import("ESlateVisibility")

            if not enabled or not show then
                if panel then
                    panel:SetVisibility(visibility.Collapsed)
                end
                return original(self, false)
            end

            local baseID = tonumber(self.ItemID or self.TypeSpecificIDTemp) or 0
            local skinID = tonumber(self.WeaponIDOrAvatarID) or 0
            if skinID <= 0 or skinID == baseID then
                skinID = tonumber(F.get_skin_id(baseID, baseID)) or 0
            end
            if baseID <= 0 or skinID <= 1000000 or skinID == baseID then
                if panel then
                    panel:SetVisibility(visibility.Collapsed)
                end
                return original(self, false)
            end

            local okUI, UIManager = pcall(require,
                                          "client.slua_ui_framework.manager")
            if not okUI or not UIManager or not UIManager.UI_Config_InGame or
                not UIManager.UI_Config_InGame.MainWeaponKillCounter then
                return original(self, show)
            end

            local counterID = nil
            pcall(function()
                local ModuleManager = require(
                                          "client.module_framework.ModuleManager")
                local logic = ModuleManager.GetModule(
                                  ModuleManager.CommonModuleConfig
                                      .LogicKillCounter)
                if logic then
                    counterID = logic:GetBaseKillCounterIdByWeaponId(baseID)
                    if logic.GetMyEquipedKillCounterId then
                        counterID = logic:GetMyEquipedKillCounterId(skinID) or
                                        counterID
                    end
                end
            end)

            if panel then
                panel:SetVisibility(visibility.SelfHitTestInvisible)
                if panel.Slot and panel.Slot.SetLayer then
                    panel.Slot:SetLayer(1)
                end
            end

            if not self.KillCounterUI then
                self.KillCounterUI = UIManager.ShowUI(
                                         UIManager.UI_Config_InGame
                                             .MainWeaponKillCounter, baseID,
                                         skinID, self)
            elseif self.KillCounterUI.UpdateWeaponID then
                self.KillCounterUI:UpdateWeaponID(baseID, skinID)
            end

            if self.KillCounterUI and
                self.KillCounterUI.SetKillCounterItemShowWithNum then
                self.KillCounterUI:SetKillCounterItemShowWithNum(counterID,
                                                                 _G.getKills and
                                                                     _G.getKills(
                                                                         baseID) or
                                                                     0, skinID)
            end
            return true
        end

        _G.AddOutfitBackpackWeaponCounterHooked = true
        return true
    end

    function F.getAttachmentSkinForWeapon(baseAttachID, weaponSkinID)
        if not (_G.VIPConfig and _G.VIPConfig.ModSkin and
            _G.VIPConfig.SkinAttachment) then return nil end
        baseAttachID = tonumber(baseAttachID) or 0
        weaponSkinID = tonumber(weaponSkinID) or 0

        local originalBaseID = (_G.VipDirectAttachToBase and
                                   _G.VipDirectAttachToBase[baseAttachID]) or
                                   baseAttachID
        local directLinks = _G.VIP_DirectAttachmentLinks and
                                _G.VIP_DirectAttachmentLinks[weaponSkinID]
        local blockedBases = _G.VIP_AttachmentBlockedBaseBySkin and
                                 _G.VIP_AttachmentBlockedBaseBySkin[weaponSkinID]
        if blockedBases and blockedBases[originalBaseID] then return nil end

        
        
        _G.__4RAttachmentTableCache = _G.__4RAttachmentTableCache or {}
        local cached = _G.__4RAttachmentTableCache[weaponSkinID]
        if cached == nil then
            local dynamicMap = {}
            pcall(function()
                local rawList = nil
                local itemCfg = CDataTable and CDataTable.GetTableData and
                                    CDataTable.GetTableData("Item", weaponSkinID)
                if itemCfg and itemCfg.BPID then
                    local bpCfg = CDataTable.GetTableData("WeaponAttrBPTable",
                                                          itemCfg.BPID)
                    rawList = bpCfg and bpCfg.AttachmentSkinIDList or nil
                end
                if not rawList or rawList == "" then
                    local mapCfg = CDataTable.GetTableData("WeaponSkinMapping",
                                                           weaponSkinID)
                    rawList = mapCfg and mapCfg.AttachmentSkinIDList or nil
                end
                if type(rawList) == "string" then
                    for baseText, skinText in rawList:gmatch(
                                                  "(%d+)%s*[-:,]%s*(%d+)") do
                        local baseID, skinID = tonumber(baseText),
                                               tonumber(skinText)
                        if baseID and skinID and baseID > 0 and skinID > 0 then
                            dynamicMap[baseID] = skinID
                        end
                    end
                elseif type(rawList) == "table" then
                    for baseKey, skinValue in pairs(rawList) do
                        local baseID, skinID = tonumber(baseKey),
                                               tonumber(skinValue)
                        if baseID and skinID and baseID > 0 and skinID > 0 then
                            dynamicMap[baseID] = skinID
                        end
                    end
                end
            end)
            cached = next(dynamicMap) and dynamicMap or false
            _G.__4RAttachmentTableCache[weaponSkinID] = cached
        end
        if type(cached) == "table" then
            local dynamicTarget = tonumber(
                                      cached[originalBaseID] or
                                          cached[baseAttachID]) or 0
            if dynamicTarget > 0 then return dynamicTarget end
        end

        local directTarget = directLinks and
                                 tonumber(directLinks[originalBaseID]) or 0
        if directTarget > 0 then return directTarget end

        local index = (_G.BaseAttachToIndex and
                          _G.BaseAttachToIndex[baseAttachID]) or
                          (_G.VipAttachToIndex and
                              _G.VipAttachToIndex[baseAttachID])
        local list = index and _G.VIP_Attachments and
                         _G.VIP_Attachments[weaponSkinID]
        local target = list and tonumber(list[index]) or 0
        if target > 0 then return target end
        return nil
    end

    function F.restoreWeaponAttachments()
        local char = F.getLocalChar and F.getLocalChar() or nil
        if not char or not slua.isValid(char) then return false end
        local manager = nil
        pcall(function()
            manager = char.GetWeaponManager and char:GetWeaponManager() or
                          char.WeaponManagerComponent
        end)
        if not manager or not slua.isValid(manager) or
            type(manager.GetAllInventoryWeaponList) ~= "function" then
            return false
        end
        local weapons = manager:GetAllInventoryWeaponList(false)
        if not weapons or not slua.isValid(weapons) then return false end
        local changed = false
        local count = math.min(tonumber(weapons:Num()) or 0, 12)
        for index = 0, count - 1 do
            local weapon = weapons:Get(index)
            if weapon and slua.isValid(weapon) and weapon.synData then
                local data = weapon.synData
                local slotCount = 0
                pcall(function()
                    slotCount = math.min(data:Num(), 31)
                end)
                local weaponChanged = false
                for slot = 0, slotCount - 1 do
                    pcall(function()
                        local entry = data:Get(slot)
                        if not entry then return end
                        local define = slua.IndexReference(entry, "defineID")
                        local current = define and
                                            tonumber(define.TypeSpecificID)
                        local base = current and _G.VipDirectAttachToBase and
                                         tonumber(
                                             _G.VipDirectAttachToBase[current])
                        if base and base > 0 and base ~= current then
                            define.TypeSpecificID = base
                            entry.defineID = define
                            data:Set(slot, entry)
                            weaponChanged = true
                            changed = true
                        end
                    end)
                end
                if weaponChanged then
                    pcall(function()
                        local avatar = weapon.WeaponAvatarComponent
                        if avatar and slua.isValid(avatar) and
                            avatar.ReloadAllEquippedAvatar then
                            avatar:ReloadAllEquippedAvatar(1)
                        elseif weapon.DelayHandleAvatarMeshChanged then
                            weapon:DelayHandleAvatarMeshChanged()
                        end
                    end)
                end
            end
        end
        return changed
    end

    _G.RestoreLocalWeaponAttachmentSkins = F.restoreWeaponAttachments

    function F.getCurrentWeaponSkinForAttachmentIcon()
        local char = F.getLocalChar()
        if not char or not slua.isValid(char) then return 0 end
        local weapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
        if not weapon or not slua.isValid(weapon) then return 0 end

        local skinID = tonumber(F.getSynMasterSkinID(weapon)) or 0
        if skinID >= 10000000 and
            ((_G.VIP_Attachments and _G.VIP_Attachments[skinID]) or
                (_G.VIP_DirectAttachmentLinks and
                    _G.VIP_DirectAttachmentLinks[skinID])) then
            return skinID
        end

        local weaponID = 0
        pcall(function() weaponID = tonumber(weapon:GetWeaponID()) or 0 end)
        if weaponID <= 0 then
            pcall(function()
                weaponID = tonumber(weapon:GetItemDefineID().TypeSpecificID) or
                               0
            end)
        end
        skinID = tonumber(F.get_skin_id(weaponID, weaponID)) or 0
        return skinID
    end

    
    
    
    function F.hookBackpackAttachmentSkinIcons()
        if _G.AddOutfitAttachmentInventoryIconHooked then return true end
        local ok, ItemUI = pcall(require,
                                 "client.slua.component.item.ItemChildren.Common_Items_UIBP")
        local original = ok and ItemUI and ItemUI.InitView
        if type(original) ~= "function" then return false end

        ItemUI.InitView = function(self, nItemId, nCount, nValidTime, extraData)
            local baseID = tonumber(nItemId) or 0
            if _G.VIPConfig and _G.VIPConfig.ModSkin then
                local meleeID = F.normalizeMeleeWeaponID(baseID) or baseID
                local isMelee = meleeID == 108001 or meleeID == PAN_WEAPON_ID or
                                    meleeID == 108005 or meleeID == MELEE_ID
                if isMelee then
                    local displayID = tonumber(F.getMatchWeaponSkin(meleeID)) or
                                          0
                    local displayData = displayID > 0 and F.cfg(displayID) or
                                            nil
                    if displayID > 0 and F.subType(displayData) == MELEE_ID then
                        extraData = extraData or {}
                        extraData.displayResId = displayID
                        F.ensureSkinDownload(displayID)
                    end
                elseif _G.VIPConfig.SkinAttachment then
                    local skinID = F.getCurrentWeaponSkinForAttachmentIcon()
                    local displayID = F.getAttachmentSkinForWeapon(baseID,
                                                                   skinID)
                    if displayID then
                        extraData = extraData or {}
                        extraData.displayResId = displayID
                        F.ensureSkinDownload(displayID)
                    end
                end
            end
            return original(self, nItemId, nCount, nValidTime, extraData)
        end

        _G.AddOutfitAttachmentInventoryIconHooked = true
        return true
    end

    function F.hookBackpackArmorSkinIcons()
        if _G.AddOutfitBackpackArmorIconHooked then return true end
        local ok, ArmorUI = pcall(require,
                                  "GameLua.Mod.BaseMod.Client.Backpack.BackPackArmorSlotUI")
        local impl = ok and ArmorUI and (ArmorUI.__inner_impl or ArmorUI)
        local original = impl and impl.ShowItemIcon
        if type(original) ~= "function" then return false end

        impl.ShowItemIcon = function(self, itemData, avatarItemID)
            local results = {pcall(original, self, itemData, avatarItemID)}
            if not results[1] then error(results[2]) end

            pcall(function()
                
                
                
                local physicalID = itemData and itemData.DefineID and
                                       tonumber(itemData.DefineID.TypeSpecificID) or
                                       0
                if physicalID <= 0 then
                    local avatarID = tonumber(avatarItemID) or 0
                    if hasResourcePrefix(avatarID, "150100") then
                        physicalID = F.getEquippedArmorItemID(501)
                    elseif hasResourcePrefix(avatarID, "150200") then
                        physicalID = F.getEquippedArmorItemID(502)
                    end
                end
                if physicalID <= 0 then
                    physicalID = tonumber(avatarItemID) or 0
                end
                local physicalData = physicalID > 0 and F.cfg(physicalID) or nil
                local physicalSubType = physicalData and
                                            tonumber(physicalData.ItemSubType) or
                                            0
                if physicalSubType ~= 501 and physicalSubType ~= 502 and
                    physicalSubType ~= 504 and physicalSubType ~= 505 then
                    physicalID = 0
                end
                if physicalID <= 0 then return end

                local data = F.cfg(physicalID)
                local subType = data and tonumber(data.ItemSubType) or 0
                if subType == 504 then subType = 501 end
                if subType == 505 then subType = 502 end
                if subType ~= 501 and subType ~= 502 then
                    if hasResourcePrefix(physicalID, "150100") then
                        subType = 501
                    elseif hasResourcePrefix(physicalID, "150200") then
                        subType = 502
                    else
                        return
                    end
                end

                local selected
                if subType == 501 then
                    selected = F.getDesiredWear("bagRes", "bagRes",
                                                "AddOutfitLastLobbyBagRes",
                                                F.syncBodyCacheFromLobby)
                else
                    selected = F.getDesiredWear("helmetRes", "helmetRes",
                                                "AddOutfitLastLobbyHelmetRes",
                                                F.syncBodyCacheFromLobby)
                end
                selected = tonumber(selected) or 0
                if selected <= 0 then return end

                local level = F.getEquipmentLevelFromItem(physicalID, subType)
                local skinID = F.levelSkinID(selected, level)
                local icon = F.getEquipmentSkinIcon(skinID)
                if not icon or icon == "" then
                    
                    
                    
                    icon = F.getEquipmentSkinIcon(selected)
                end
                if not icon or icon == "" or not self.Image_EquipIcon then
                    return
                end
                F.ensureSkinDownload(skinID)
                local function paintSelectedSkinIcon()
                    pcall(function()
                        if not self or not self.Image_EquipIcon or
                            not slua.isValid(self.Image_EquipIcon) then return end

                        
                        
                        local current = self.ItemData
                        local currentID = current and current.DefineID and
                                              tonumber(current.DefineID.TypeSpecificID) or
                                              physicalID
                        if currentID ~= physicalID then return end

                        if not F.isResourcesReady(skinID) then
                            F.ensureSkinDownload(skinID)
                            return
                        end

                        local resolvedIcon = icon
                        pcall(function()
                            local fallback = ModuleManager.GetModule(
                                                 ModuleManager.CommonModuleConfig.item_display_fallback_logic)
                            if fallback and fallback.ResolveBattleIcon then
                                resolvedIcon = fallback:ResolveBattleIcon(
                                                   skinID, icon) or icon
                            end
                        end)
                        self.Image_EquipIcon:SetBrushFromPathAsync(resolvedIcon,
                                                                  true)
                    end)
                end

                
                
                
                paintSelectedSkinIcon()
                pcall(function()
                    local ticker = require("common.time_ticker")
                    if not ticker or not ticker.AddTimerOnce then return end
                    for _, delay in ipairs({0.08, 0.35, 1.0, 2.5}) do
                        ticker.AddTimerOnce(delay, paintSelectedSkinIcon)
                    end
                end)
                F.skinDiag("ARMOR_ICON",
                           "slot=" .. (subType == 501 and ("bag") or ("helmet")) ..
                               " physical=" .. tostring(physicalID) ..
                               " level=" .. tostring(level) .. " selected=" ..
                               tostring(selected) .. " skin=" ..
                               tostring(skinID) .. " ready=" ..
                               tostring(F.isResourcesReady(skinID)) ..
                               " icon=" .. tostring(icon), 1)
            end)

            local unpackResult = table.unpack or unpack
            return unpackResult(results, 2)
        end

        _G.AddOutfitBackpackArmorIconHooked = true
        return true
    end

    function F.hookWardrobeArmorIcon()
        if _G.AddOutfitWardrobeArmorIconHooked then return true end
        local okGrid, GridItem = pcall(require,
                                       "client.slua.umg.Wardrobe.Item.Common_Items_Goods_UIBP")
        local impl = okGrid and GridItem and (GridItem.__inner_impl or GridItem)
        if not impl or type(impl.RefreshItem) ~= "function" then
            return false
        end

        if not impl.__4RArmorIconOriginal then
            impl.__4RArmorIconOriginal = impl.RefreshItem
        end
        if impl.__4RArmorIconWrapped then return true end
        impl.__4RArmorIconWrapped = true

        local original = impl.__4RArmorIconOriginal
        impl.RefreshItem = function(self, itemData, ...)
            local res = original(self, itemData, ...)
            pcall(function()
                if not (_G.VIPConfig and _G.VIPConfig.ModSkin) then
                    return
                end
                local resID = tonumber(itemData and
                                           (itemData.res_id or itemData.resID or
                                               itemData.ResID))
                if not resID or resID <= 0 then return end
                local isBag = F.isBackpackSkinRes(resID)
                local isHelmet = F.isHelmetSkinRes(resID)
                if not isBag and not isHelmet then return end

                local equippedRes
                if isBag then
                    equippedRes = F.getDesiredWear("bagRes", "bagRes",
                                                   "AddOutfitLastLobbyBagRes",
                                                   F.syncBodyCacheFromLobby)
                else
                    equippedRes = F.getDesiredWear("helmetRes", "helmetRes",
                                                   "AddOutfitLastLobbyHelmetRes",
                                                   F.syncBodyCacheFromLobby)
                end
                equippedRes = tonumber(equippedRes) or 0
                if equippedRes <= 0 or equippedRes ~= resID then
                    return
                end

                local subType = isBag and 501 or 502
                local physicalID = F.getEquippedArmorItemID(subType)
                local level = F.getEquipmentLevelFromItem(physicalID, subType)
                local variantID = F.levelSkinID(resID, level)
                local variantIcon = F.getEquipmentSkinIcon(variantID)
                if not variantIcon or variantIcon == "" then
                    return
                end

                local iconWidget = self.Image_GoodsIcon or self.Image_Icon or
                                       (self.UIRoot and
                                           (self.UIRoot.Image_GoodsIcon or
                                               self.UIRoot.Image_Icon))
                if iconWidget and iconWidget.SetBrushFromPathAsync then
                    iconWidget:SetBrushFromPathAsync(variantIcon, true)
                end
            end)
            return res
        end
        _G.AddOutfitWardrobeArmorIconHooked = true
        return true
    end

    
    
    
    
    function F.hookCrewWardrobeBadge()
        local hooked = false

        pcall(function()
            local UIUtil = require("client.common.ui_util")
            if not UIUtil or type(UIUtil.IsCustomDIYTableCloth) ~= "function" then
                return
            end
            if not UIUtil.__4RCrewDIYOriginal then
                UIUtil.__4RCrewDIYOriginal = UIUtil.IsCustomDIYTableCloth
            end
            if not UIUtil.__4RCrewDIYWrapped then
                local original = UIUtil.__4RCrewDIYOriginal
                UIUtil.IsCustomDIYTableCloth = function(itemID, ...)
                    if F.CREW_UNIFORM_COLORS[tonumber(itemID)] then
                        return true
                    end
                    return original(itemID, ...)
                end
                UIUtil.__4RCrewDIYWrapped = true
            end
            hooked = true
        end)

        pcall(function()
            local List = require(
                             "client.slua.umg.Wardrobe.subtab_item_list_base")
            local impl = List and (List.__inner_impl or List)
            if not impl or type(impl.InitView) ~= "function" then return end
            if not impl.__4RCrewBadgeInitOriginal then
                impl.__4RCrewBadgeInitOriginal = impl.InitView
            end
            if not impl.__4RCrewBadgeInitWrapped then
                local original = impl.__4RCrewBadgeInitOriginal
                impl.InitView = function(self, nodeWidget, itemData, ...)
                    local selectorID
                    if itemData then
                        local resID = tonumber(itemData.res_id or itemData.resID or
                                                   itemData.ResID)
                        local color = F.CREW_UNIFORM_COLORS[resID]
                        if color then
                            selectorID = resID
                            local pattern = F.getCrewSelectorPattern(resID)
                            itemData.color = color
                            itemData.color_id = color
                            itemData.colorID = color
                            itemData.pattern = pattern
                            itemData.pattern_id = pattern
                            itemData.patternID = pattern
                            
                            
                            
                            itemData.res_id = 140070800 + color
                        end
                    end
                    local results = {original(self, nodeWidget, itemData, ...)}
                    if selectorID and itemData then
                        itemData.res_id = selectorID
                    end
                    return (table.unpack or unpack)(results)
                end
                impl.__4RCrewBadgeInitWrapped = true
            end
            hooked = true
        end)

        return hooked
    end

    function F.applySkinToWeaponRef(CurWeapon)
        if not slua.isValid(CurWeapon) then return false end

        
        
        
        local reportedWeaponID, defineWeaponID = 0, 0
        pcall(function()
            if CurWeapon.GetWeaponID then
                reportedWeaponID = tonumber(CurWeapon:GetWeaponID()) or 0
            end
            if CurWeapon.GetItemDefineID then
                local defineID = CurWeapon:GetItemDefineID()
                defineWeaponID =
                    tonumber(defineID and defineID.TypeSpecificID) or 0
            end
        end)
        reportedWeaponID = F.normalizeMeleeWeaponID(reportedWeaponID) or
                               reportedWeaponID
        defineWeaponID = F.normalizeMeleeWeaponID(defineWeaponID) or
                             defineWeaponID
        local liveMeleeWeaponID = nil
        local candidates = {
            F.normalizeMeleeWeaponID(F.resolveWeaponTypeID(defineWeaponID)),
            defineWeaponID,
            F.normalizeMeleeWeaponID(F.resolveWeaponTypeID(reportedWeaponID)),
            reportedWeaponID
        }
        for _, weaponID in ipairs(candidates) do
            if weaponID == 108001 or weaponID == PAN_WEAPON_ID or weaponID ==
                108005 or weaponID == MELEE_ID then
                liveMeleeWeaponID = weaponID
                break
            end
        end
        if liveMeleeWeaponID then
            local meleeSkin =
                tonumber(F.getMatchWeaponSkin(liveMeleeWeaponID)) or 0
            
            
            if meleeSkin <= 0 and
                (liveMeleeWeaponID == PAN_WEAPON_ID or liveMeleeWeaponID ==
                    MELEE_ID) then
                meleeSkin = tonumber(F.getMatchWeaponSkin(MELEE_ID)) or 0
            end
            local meleeConfig = meleeSkin > 0 and F.cfg(meleeSkin) or nil
            F.skinDiag("MELEE_RESOLVE",
                       "reported=" .. tostring(reportedWeaponID) ..
                           " define=" .. tostring(defineWeaponID) .. " base=" ..
                           tostring(liveMeleeWeaponID) .. " target=" ..
                           tostring(meleeSkin) .. " subtype=" ..
                           tostring(F.subType(meleeConfig)), 2)
            if meleeSkin > 0 and F.subType(meleeConfig) == MELEE_ID then
                F.ensureSkinDownload(meleeSkin)
                local wac = CurWeapon.WeaponAvatarComponent_BP or
                                CurWeapon.WeaponAvatarComponent or
                                CurWeapon.WeaponAvatar
                local currentVisualID = slua.isValid(wac) and
                                            tonumber(wac.CachedLoadedID) or 0
                if currentVisualID == meleeSkin then
                    F.skinDiag("MELEE_OK",
                               "base=" .. tostring(liveMeleeWeaponID) ..
                                   " target=" .. tostring(meleeSkin) ..
                                   " already loaded", 3)
                    return true
                end
                if currentVisualID ~= meleeSkin then
                    local applied = false
                    pcall(function()
                        if CurWeapon.SetWeaponAvatarID then
                            CurWeapon:SetWeaponAvatarID(meleeSkin)
                            applied = true
                        end
                        
                        
                        
                        local syn = CurWeapon.synData
                        if syn and slua.isValid(syn) and syn.Num and syn:Num() >
                            7 then
                            local attachment = syn:Get(7)
                            if attachment then
                                local defineRef =
                                    slua.IndexReference(attachment, "defineID")
                                if defineRef then
                                    defineRef.TypeSpecificID = meleeSkin
                                    syn:Set(7, attachment)
                                    if CurWeapon.OnRep_synData then
                                        CurWeapon:OnRep_synData()
                                    end
                                end
                            end
                        end
                        if slua.isValid(wac) then
                            if wac.ClearMeshPathCacheBySlot then
                                wac:ClearMeshPathCacheBySlot(0)
                            end
                            if wac.ClearMeshBySlot then
                                wac:ClearMeshBySlot(0, true, true)
                            end
                        end
                        if CurWeapon.DelayHandleAvatarMeshChanged then
                            CurWeapon:DelayHandleAvatarMeshChanged()
                        end
                        if slua.isValid(wac) and wac.ReloadAllEquippedAvatar then
                            wac:ReloadAllEquippedAvatar(1)
                        end
                        if slua.isValid(wac) and wac.OnRep_BodySlotStateChanged then
                            wac:OnRep_BodySlotStateChanged()
                        end
                    end)
                    if applied then
                        _G.AddOutfitLastAppliedSkin[liveMeleeWeaponID] =
                            meleeSkin
                        F.skinDiag("MELEE_APPLY",
                                   "base=" .. tostring(liveMeleeWeaponID) ..
                                       " target=" .. tostring(meleeSkin) ..
                                       " previous=" ..
                                       tostring(currentVisualID), 0)
                        return true
                    end
                end
            end
            F.skinDiag("MELEE_FAIL",
                       "base=" .. tostring(liveMeleeWeaponID) .. " target=" ..
                           tostring(meleeSkin) .. " current=" ..
                           tostring(currentVisualID), 0)
            return false
        end

        local AttachmentArray = CurWeapon.synData
        if not AttachmentArray or not slua.isValid(AttachmentArray) then
            return false
        end

        local masterSlot = GUN_MASTER_SYN_SLOT
        pcall(function()
            local detected = F.findSkinSlotInSynData(CurWeapon)
            if tonumber(detected) then
                masterSlot = tonumber(detected)
            end
        end)
        local AttachmentData = AttachmentArray:Get(masterSlot)
        if not AttachmentData then return false end

        local current_gunid = 0
        pcall(function()
            current_gunid = slua.IndexReference(AttachmentData, "defineID")
                                .TypeSpecificID or 0
        end)
        if not current_gunid or current_gunid <= 0 then return false end

        local MaxIt = 0
        pcall(function()
            if CurWeapon.GetWeaponID then
                MaxIt = CurWeapon:GetWeaponID()
            end
            if MaxIt <= 0 then
                MaxIt = CurWeapon:GetItemDefineID().TypeSpecificID
            end
        end)
        MaxIt = tonumber(MaxIt) or 0
        local tmp_id = F.get_skin_id(current_gunid, MaxIt)
        tmp_id = tonumber(tmp_id) or 0
        if tmp_id <= 0 or MaxIt <= 0 then return false end

        local changedAny = false

        
        local wac = CurWeapon.WeaponAvatarComponent
        local currentVisualID = 0
        if slua.isValid(wac) then
            currentVisualID = wac.CachedLoadedID or 0
        end

        
        if currentVisualID ~= tmp_id then
            changedAny = true
            pcall(function()
                local defRef = slua.IndexReference(AttachmentData, "defineID")
                defRef.TypeSpecificID = tmp_id
                local c0 = F.cfg(tmp_id)
                if c0 and c0.ItemType and defRef.Type ~= nil then
                    defRef.Type = c0.ItemType
                end
                AttachmentData.operationType = 0
                AttachmentArray:Set(masterSlot, AttachmentData)
                if CurWeapon.SetWeaponAvatarID then
                    CurWeapon:SetWeaponAvatarID(tmp_id)
                end
            end)
        end

        
        if _G.VIPConfig and _G.VIPConfig.SkinAttachment and tmp_id >= 1000000 then
            local attachSkinConfig = (_G.VIP_Attachments and
                                         _G.VIP_Attachments[tmp_id]) or {}
            local directAttachConfig = _G.VIP_DirectAttachmentLinks and
                                           _G.VIP_DirectAttachmentLinks[tmp_id]
            local baseAttachMap = _G.BaseAttachToIndex
            local vipAttachMap = _G.VipAttachToIndex

            if attachSkinConfig and baseAttachMap then
                local lastAttachIndex = 5
                pcall(function()
                    if AttachmentArray.Num then
                        lastAttachIndex = math.max(0, AttachmentArray:Num() - 1)
                    end
                end)
                
                
                lastAttachIndex = math.min(lastAttachIndex, 31)
                for AttachIdx = 0, lastAttachIndex do
                    if AttachIdx ~= masterSlot then
                        pcall(function()
                            local attachData = AttachmentArray:Get(AttachIdx)
                            if attachData then
                                local defineIDRef =
                                    slua.IndexReference(attachData, "defineID")
                                if defineIDRef then
                                    local attachmentId =
                                        defineIDRef.TypeSpecificID
                                    if attachmentId and attachmentId > 0 then
                                        local directBaseID =
                                            (_G.VipDirectAttachToBase and
                                                _G.VipDirectAttachToBase[attachmentId]) or
                                                attachmentId
                                        
                                        
                                        
                                        local targetAttachId =
                                            F.getAttachmentSkinForWeapon(
                                                attachmentId, tmp_id)
                                        if not targetAttachId then
                                            targetAttachId =
                                                directAttachConfig and
                                                    directAttachConfig[directBaseID]
                                        end
                                        
                                        
                                        local mapIndex =
                                            baseAttachMap[attachmentId] or
                                                (vipAttachMap and
                                                    vipAttachMap[attachmentId])
                                        if not targetAttachId and mapIndex then
                                            targetAttachId =
                                                attachSkinConfig[mapIndex]
                                        end
                                        local blockedBases =
                                            _G.VIP_AttachmentBlockedBaseBySkin and
                                                _G.VIP_AttachmentBlockedBaseBySkin[tmp_id]
                                        if not targetAttachId and blockedBases and
                                            blockedBases[directBaseID] and
                                            attachmentId ~= directBaseID then
                                            targetAttachId = directBaseID
                                        end
                                        if targetAttachId and targetAttachId > 0 then
                                            F.ensureSkinDownload(targetAttachId)
                                            if targetAttachId ~= attachmentId then
                                                defineIDRef.TypeSpecificID =
                                                    targetAttachId
                                                attachData.defineID =
                                                    defineIDRef
                                                AttachmentArray:Set(AttachIdx,
                                                                    attachData)
                                                changedAny = true

                                                
                                                if slua.isValid(wac) then
                                                    if wac.ClearMeshPathCacheBySlot then
                                                        wac:ClearMeshPathCacheBySlot(
                                                            AttachIdx)
                                                    end
                                                    if wac.ClearMeshBySlot then
                                                        wac:ClearMeshBySlot(
                                                            AttachIdx, true,
                                                            true)
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end)
                    end
                end
            end
        end

        
        if changedAny then
            pcall(function()
                if slua.isValid(wac) then
                    
                    if currentVisualID ~= tmp_id then
                        if wac.ClearMeshPathCacheBySlot then
                            wac:ClearMeshPathCacheBySlot(0)
                        end
                        if wac.ClearMeshBySlot then
                            wac:ClearMeshBySlot(0, true, true)
                        end
                    end

                    if CurWeapon.DelayHandleAvatarMeshChanged then
                        CurWeapon:DelayHandleAvatarMeshChanged()
                    end
                    if wac.ReloadAllEquippedAvatar then
                        wac:ReloadAllEquippedAvatar(1)
                    end
                end
            end)
            _G.AddOutfitLastAppliedSkin[MaxIt] = tmp_id
            return true
        end

        return false
    end

    function _G.equip_weapon_avatar(uCharacter)
        if not uCharacter or not slua.isValid(uCharacter) then
            return false
        end
        F.buildSkinMappings()
        local WeaponManager = uCharacter:GetWeaponManager()
        if not WeaponManager or not slua.isValid(WeaponManager) then
            return false
        end
        local uWeaponList = WeaponManager:GetAllInventoryWeaponList(false)
        if not uWeaponList or not slua.isValid(uWeaponList) then
            return false
        end

        local appliedAny = false
        for i = 0, uWeaponList:Num() - 1 do
            local CurWeapon = uWeaponList:Get(i)
            if slua.isValid(CurWeapon) and F.applySkinToWeaponRef(CurWeapon) then
                appliedAny = true
            end
        end
        return appliedAny
    end

    function F.equipWeaponAvatarSynData(char)
        return _G.equip_weapon_avatar(char)
    end

    F.applySkinToWeapon = F.applySkinToWeaponRef

    function F.registerWeaponAvatarItems(char)
        local pc = char.GetPlayerControllerSafety and
                       char:GetPlayerControllerSafety()
        if not slua.isValid(pc) then return false end
        local AU = import("AvatarUtils")
        local BU = import("BackpackUtils")
        local addedCount = 0

        for _, resID in ipairs(F.getDesiredWeaponSkins()) do
            local doneDirect = false
            pcall(function()
                if pc.AddWeaponAvatarItem then
                    pc:AddWeaponAvatarItem(tonumber(resID))
                    doneDirect = true
                    addedCount = addedCount + 1
                end
            end)
            if not doneDirect then
                pcall(function()
                    local skinBPID = BU.GetBPIDByResID(tonumber(resID))
                    local arr = slua.Array(UEnums.EPropertyClass.Int)
                    local parents = AU.GetWeaponAvatarParentIDList(skinBPID,
                                                                   arr, false)
                    if parents and parents.Num and parents:Num() > 0 and
                        pc.WeaponAvatarItemList then
                        for _, parentID in pairs(parents) do
                            pc.WeaponAvatarItemList:Add(parentID, skinBPID)
                        end
                        addedCount = addedCount + 1
                    end
                end)
            end
        end

        if addedCount == 0 then return false end

        pcall(function()
            if pc.InitWeaponAvatarItems then
                pc:InitWeaponAvatarItems()
            end
        end)
        pcall(function()
            if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end
        end)
        return true
    end

    function F.reloadCurrentWeaponAvatar(char)
        pcall(function()
            local weapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
            if not slua.isValid(weapon) then return end
            local wac = weapon.WeaponAvatarComponent
            if slua.isValid(wac) then
                local ES = import("EWeaponAttachmentSocketType")
                pcall(function()
                    wac:ClearMeshPathCacheBySlot(ES.MasterGun)
                end)
                pcall(function()
                    wac:ClearMeshBySlot(ES.MasterGun, true, true)
                end)
            end
            if weapon.DelayHandleAvatarMeshChanged then
                weapon:DelayHandleAvatarMeshChanged()
            elseif slua.isValid(wac) and wac.ReloadAllEquippedAvatar then
                local ESlotDescDiff = import("ESlotDescDiff")
                wac:ReloadAllEquippedAvatar(ESlotDescDiff.MeshDiff)
            end
        end)
    end

    local _weaponDiagDone = false
    local _weaponApplied = false
    local _lastWeaponResID = 0
    local _weaponSpawnHooked = false

    function F.onWeaponLuaInit(...)
        if not F.isEnabled() then return end
        local weapon = nil
        local args = {...}
        for i = #args, 1, -1 do
            local candidate = args[i]
            if candidate and slua.isValid(candidate) and
                (candidate.synData or candidate.GetWeaponID) then
                weapon = candidate
                break
            end
        end
        if not weapon or not slua.isValid(weapon) then return end
        local char = F.getLocalChar()
        if not char then return end
        local owner = nil
        pcall(function()
            if weapon.GetOwnerPawn then owner = weapon:GetOwnerPawn() end
        end)
        if not slua.isValid(owner) or owner ~= char then return end
        pcall(function()
            char:AddGameTimer(0.15, false, function()
                local c = F.getLocalChar()
                if c and slua.isValid(weapon) then
                    F.applySkinToWeapon(weapon)
                    _weaponApplied = false
                end
            end)
        end)
    end

    function F.hookWeaponSpawn()
        if _weaponSpawnHooked then return end
        pcall(function()
            if EventSystem and EventSystem.registEvent and
                EVENTTYPE_PLAYEREVENT_WEAPON and
                EVENTID_PLAYEREVENT_WEAPON_LUA_INIT then
                EventSystem:registEvent(EVENTTYPE_PLAYEREVENT_WEAPON,
                                        EVENTID_PLAYEREVENT_WEAPON_LUA_INIT,
                                        F.onWeaponLuaInit)
                _weaponSpawnHooked = true
            end
        end)
    end

    function F.matchApplyWeaponSkin(char)
        if not F.isEnabled() then return false end
        if not _avatarItemsRegistered then
            _avatarItemsRegistered = F.registerWeaponAvatarItems(char)
        end

        local curWeapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
        if not slua.isValid(curWeapon) then return false end

        local currentVisualID = 0
        pcall(function()
            local wac = curWeapon.WeaponAvatarComponent
            if slua.isValid(wac) then
                currentVisualID = wac.CachedLoadedID or 0
            end
        end)

        local curWeaponResID = 0
        pcall(function()
            curWeaponResID = curWeapon:GetItemDefineID().TypeSpecificID
        end)
        local targetSkin = F.findTargetSkinForWeaponRes(curWeaponResID) or
                               curWeaponResID

        local isVisualMatched = false
        if currentVisualID > 0 and currentVisualID == targetSkin then
            isVisualMatched = true
        end

        
        if not _G.SmartWeaponWatcherActive then
            _G.SmartWeaponWatcherActive = true
            pcall(function()
                local ticker = require("common.time_ticker")
                if ticker and ticker.AddTimerLoop then
                    ticker.AddTimerLoop(0, function()
                        if not _G.VIPConfig.ModSkin then
                            return
                        end

                        
                        if _G.AddOutfit and not _G.AddOutfit.isInRealMatch() then
                            return
                        end

                        local pController =
                            slua_GameFrontendHUD and
                                slua_GameFrontendHUD:GetPlayerController()
                        if not pController or not slua.isValid(pController) then
                            return
                        end
                        local pChar = pController:GetPlayerCharacterSafety()
                        if not pChar or not slua.isValid(pChar) then
                            return
                        end

                        
                        local WeaponManager = pChar:GetWeaponManager()
                        if not WeaponManager or not slua.isValid(WeaponManager) then
                            return
                        end
                        local uWeaponList =
                            WeaponManager:GetAllInventoryWeaponList(false)
                        if not uWeaponList or not slua.isValid(uWeaponList) then
                            return
                        end

                        local count = uWeaponList:Num()
                        
                        for i = 0, count - 1 do
                            local wep = uWeaponList:Get(i)
                            if slua.isValid(wep) then
                                
                                local synSkinID = F.getSynMasterSkinID(wep)
                                local baseID = 0
                                pcall(function()
                                    baseID =
                                        wep:GetItemDefineID().TypeSpecificID
                                end)
                                local tSkin =
                                    F.findTargetSkinForWeaponRes(baseID) or
                                        baseID

                                
                                
                                local hasAttachmentSkin =
                                    _G.VIP_Attachments and
                                        _G.VIP_Attachments[tSkin] ~= nil
                                if synSkinID ~= tSkin or hasAttachmentSkin then
                                    if _G.AddOutfit and
                                        _G.AddOutfit.applySkinToWeapon then
                                        _G.AddOutfit.applySkinToWeapon(wep)
                                    end
                                end
                            end
                        end
                    end, -1, 1.0)
                end
            end)
        end

        
        local hasAttachmentSkin = _G.VIP_Attachments and
                                      _G.VIP_Attachments[targetSkin] ~= nil
        if isVisualMatched and not hasAttachmentSkin then
            _weaponApplied = true
            F.skinDiag("WEAPON_OK",
                       "base=" .. tostring(curWeaponResID) .. " target=" ..
                           tostring(targetSkin) .. " visual=" ..
                           tostring(currentVisualID), 3)
            return true
        end

        F.buildSkinMappings()
        local okSyn = F.applySkinToWeapon(curWeapon)
        
        
        
        local weaponReady = okSyn or isVisualMatched
        if weaponReady then _weaponApplied = true end

        F.skinDiag(weaponReady and ("WEAPON_APPLY") or ("WEAPON_FAIL"),
                   "base=" .. tostring(curWeaponResID) .. " target=" ..
                       tostring(targetSkin) .. " visual=" ..
                       tostring(currentVisualID) .. " attachments=" ..
                       tostring(hasAttachmentSkin == true),
                   weaponReady and 3 or 0)

        return weaponReady
    end

    local _matchTimer = nil
    local _matchTimerOwner = nil
    local _matchWearDone = false

    function F.startMatchWatcher(char)
        if not F.isEnabled() then return false end
        F.startEquipmentSkinWatcher()
        if _matchTimer or PERF.matchActive then return end
        PERF.matchActive = true
        _matchTimerOwner = char
        local skipWear = PERF.wearDoneThisMatch
        _matchWearDone = skipWear
        _avatarItemsRegistered = false
        _weaponDiagDone = false
        _weaponApplied = false
        _lastWeaponResID = 0
        local elapsed = 0
        F.skinDiag("WATCHER_START",
                   "pawn=" .. tostring(char) .. " skipWear=" ..
                       tostring(skipWear), 0)

        _matchTimer = char:AddGameTimer(MATCH_TICK_SEC, true, function()
            elapsed = elapsed + MATCH_TICK_SEC
            local cur = F.getLocalChar()
            if not cur or not slua.isValid(cur) then return end

            if not _matchWearDone then
                _matchWearDone = F.matchApplyAllSlots(cur)
            end
            F.matchApplyHat(cur)
            F.matchApplyFaceWear(cur) 
            F.matchApplyFaceAndHair(cur) 
            if not _weaponApplied then F.matchApplyWeaponSkin(cur) end
            if F.isCharacterAirborne(cur) then
                F.applyAirborneSlots(cur, true)
            end

            if (_matchWearDone and _weaponApplied) or elapsed >= MATCH_MAX_SEC then
                if _matchWearDone then
                    PERF.wearDoneThisMatch = true
                end
                if _matchTimer and cur.RemoveGameTimer then
                    pcall(function()
                        cur:RemoveGameTimer(_matchTimer)
                    end)
                end
                _matchTimer = nil
                _matchTimerOwner = nil
                PERF.matchActive = false
                F.skinDiag("WATCHER_STOP",
                           "elapsed=" .. tostring(elapsed) .. " wear=" ..
                               tostring(_matchWearDone) .. " weapon=" ..
                               tostring(_weaponApplied), 0)
            end
        end)
    end

    function F.stopMatchWatcher()
        if _matchTimer then
            pcall(function()
                local char = _matchTimerOwner or F.getLocalChar()
                if char and char.RemoveGameTimer then
                    char:RemoveGameTimer(_matchTimer)
                end
            end)
            _matchTimer = nil
        end
        _matchTimerOwner = nil
        PERF.matchActive = false
        PERF.wearDoneThisMatch = false
        _matchWearDone = false
        _avatarItemsRegistered = false
        _weaponApplied = false
        _weaponDiagDone = false
        _lastWeaponResID = 0
        F.skinDiag("WATCHER_RESET", "match lifecycle reset", 0)
    end

    
    
    
    function F.disableSkinSystem()
        _G.AddOutfitActivationToken = (_G.AddOutfitActivationToken or 0) + 1
        F.stopMatchWatcher()
        _G.AddOutfitLifecyclePawnKey = nil
        PERF.lastBootstrapAt = 0
        PERF.wearDoneThisMatch = false
        _G.skinIdCache = {}

        pcall(function()
            if F.stopVehicleSkinTicker then F.stopVehicleSkinTicker() end
        end)

        
        
        pcall(function()
            local cache = F.cache()
            local seen = {}
            for key, value in pairs(cache) do
                if type(value) == "number" and key:match("Ins$") and value >=
                    INS_BASE and R.insToRes[value] then
                    seen[value] = true
                elseif key == "weapons" and type(value) == "table" then
                    for _, weaponData in pairs(value) do
                        local ins = tonumber(weaponData and weaponData.insID)
                        if ins and ins >= INS_BASE and R.insToRes[ins] then
                            seen[ins] = true
                        end
                    end
                end
            end
            for ins in pairs(seen) do F.takeOffInjected(ins) end
        end)

        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            if Arm and Arm.rsp_list then
                for wid, entry in pairs(Arm.rsp_list.install_list or {}) do
                    local ins = tonumber(entry and entry.skin_id)
                    if ins and ins >= INS_BASE and R.insToRes[ins] then
                        Arm.rsp_list.install_list[wid] = nil
                    end
                end
                for _, skins in pairs(Arm.rsp_list.skin_list or {}) do
                    if type(skins) == "table" then
                        for resID in pairs(skins) do
                            local ins = R.resToIns[tonumber(resID)]
                            if ins and tonumber(ins) >= INS_BASE then
                                skins[resID] = nil
                            end
                        end
                    end
                end
            end
            if Arm and Arm.WardrobeInsList then
                for resID, ins in pairs(Arm.WardrobeInsList) do
                    if tonumber(ins) and tonumber(ins) >= INS_BASE and
                        R.insToRes[tonumber(ins)] then
                        Arm.WardrobeInsList[resID] = nil
                    end
                end
            end
        end)

        
        
        pcall(function()
            local entity = F.getEntity()
            if entity and entity._data then
                for i = 1, (entity._DataCount or #entity._data) do
                    local row = entity._data[i]
                    local ins = row and tonumber(row.instid or row.insID)
                    if ins and ins >= INS_BASE and R.insToRes[ins] then
                        row.count = 0
                    end
                end
            end
        end)

        _G.HatSkin, _G.SuitSkin, _G.PantsSkin, _G.ShoesSkin = 0, 0, 0, 0
        _G.GlovesSkin, _G.MaskSkin, _G.GlassSkin = 0, 0, 0
        _G.GliderSkin, _G.ParachuteSkin = 0, 0
        F.perfInvalidateLobby()
        F.refreshWardrobe()
        return true
    end

    
    
    function F.startPawnLifecycleWatcher()
        _G.AddOutfitLifecycleTick = function()
            local system = _G.AddOutfit
            if not system then return end

            local sessionUID
            pcall(function()
                local role = DataMgr and DataMgr.roleData
                local uid = role and (role.uid or role.UID or role.roleID)
                if uid ~= nil and tostring(uid) ~= "" and tostring(uid) ~= "0" then
                    sessionUID = tostring(uid)
                end
            end)

            if not sessionUID then
                if _G.AddOutfitSessionUID then
                    _G.AddOutfitSessionDisconnected = true
                end
            elseif _G.AddOutfitSessionUID ~= sessionUID or
                _G.AddOutfitSessionDisconnected then
                _G.AddOutfitSessionUID = sessionUID
                _G.AddOutfitSessionDisconnected = false
                system.resetTransientSkinSession()
                pcall(function()
                    system.persistLoadFromDisk()
                    system.applyPersistSlotsToCache()
                    system.syncGlobalWearSkins()
                end)
                if _G.VIPConfig and _G.VIPConfig.ModSkin and
                    system.requestActivation then
                    system.requestActivation()
                end
            end

            local char = system.getLocalChar and system.getLocalChar()
            local realMatch = char and slua.isValid(char) and
                                  system.isInRealMatch and
                                  system.isInRealMatch()
            if realMatch then
                if not system.isEnabled() then
                    system.stopMatchWatcher()
                    _G.AddOutfitLifecyclePawnKey = nil
                    PERF.lastBootstrapAt = 0
                    return
                end
                local pawnKey = tostring(char)
                if _G.AddOutfitLifecyclePawnKey ~= pawnKey then
                    F.skinDiag("PAWN_CHANGE",
                               "old=" ..
                                   tostring(_G.AddOutfitLifecyclePawnKey) ..
                                   " new=" .. tostring(pawnKey), 0)
                    system.stopMatchWatcher()
                    _G.AddOutfitLifecyclePawnKey = pawnKey
                    PERF.lastBootstrapAt = 0
                    PERF.wearDoneThisMatch = false
                    pcall(function()
                        if system.injectAll() then
                            system.afterInjectApply(false)
                        else
                            system.mergeInjectedArmorySkins()
                        end
                    end)
                    system.later(0.35, function()
                        local current = system.getLocalChar()
                        if current and slua.isValid(current) and
                            tostring(current) == pawnKey then
                            system.bootstrapMatch(current)
                        end
                    end)
                elseif not PERF.matchActive and not PERF.wearDoneThisMatch then
                    system.bootstrapMatch(char)
                end
            elseif _G.AddOutfitLifecyclePawnKey ~= nil then
                F.skinDiag("LOBBY_RETURN",
                           "oldPawn=" ..
                               tostring(_G.AddOutfitLifecyclePawnKey), 0)
                system.stopMatchWatcher()
                _G.AddOutfitLifecyclePawnKey = nil
                PERF.lastBootstrapAt = 0
                
                
                
                LOBBY.reapplyDone = false
                LOBBY.reapplyScheduled = false
                system.later(0.75, function()
                    pcall(function()
                        system.persistLoadFromDisk()
                        system.applyPersistSlotsToCache()
                        system.reapplyLobbyEquipped()
                    end)
                end)
                system.later(2.0, function()
                    pcall(system.reapplyLobbyEquipped)
                end)
            end
        end

        if _G.AddOutfitLifecycleLoopStarted then return true end
        local okTicker, ticker = pcall(require, "common.time_ticker")
        if not okTicker or not ticker or not ticker.AddTimerLoop then
            return false
        end
        _G.AddOutfitLifecycleLoopStarted = true
        ticker.AddTimerLoop(0, function()
            if _G.AddOutfitLifecycleTick then
                pcall(_G.AddOutfitLifecycleTick)
            end
        end, -1, 1.0)
        return true
    end

    function F.hookAirborneCache()
        if _G.AddOutfitAirborneHooked then return end
        _G.AddOutfitAirborneHooked = true
        pcall(function()
            if not EventSystem or not EventSystem.registEvent then
                return
            end
            if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:registEvent(EVENTTYPE_WARDROBE,
                                        EVENTID_WARDROBE_UPDATE_ITEM_LIST,
                                        function()
                    F.syncAirborneCacheFromLobby()
                end)
            end
        end)
    end

    
    
    
    function F.hookCrewUniformCustomizationData()
        pcall(function()
            local avatar = require(
                               "client.slua.logic.wardrobe.logic_wardrobe_avatar")
            if avatar._4RCrewCustomizationHooked then return end
            avatar._4RCrewCustomizationHooked = true
            local original = avatar.InitCurrentWearPreviewMap
            if type(original) == "function" then
                avatar.InitCurrentWearPreviewMap =
                    function(self, force, ...)
                        local results = {original(self, force, ...)}
                        pcall(function()
                            local selected = tonumber(
                                                 PERSIST.configSlots and
                                                     PERSIST.configSlots.tshirt) or
                                                 tonumber(F.cache().tshirtRes)
                            local base, color, pattern =
                                F.getCrewUniformCustomization(selected)
                            if base and self.AddToWearInfo then
                                local ins =
                                    tonumber(F.cache().tshirtIns) or
                                        tonumber(F.resolveInsForRes(selected)) or
                                        0
                                self:AddToWearInfo(OUTFIT_SUB, ins, base, color,
                                                   pattern)
                            end
                        end)
                        return (table.unpack or unpack)(results)
                    end
            end
        end)

        for _, moduleName in ipairs({
            "GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil",
            "client.logic.avatar.AvatarDataUtil"
        }) do
            pcall(function()
                local util = require(moduleName)
                if util._4RCrewCustomizationHooked or
                    type(util.GetAvatarStandaloneData) ~= "function" then
                    return
                end
                util._4RCrewCustomizationHooked = true
                local original = util.GetAvatarStandaloneData
                util.GetAvatarStandaloneData = function(...)
                    local info, hasData = original(...)
                    pcall(function()
                        local currentChar = F.getLocalChar()
                        if F.isInRealMatch() and F.eventOwnsClothes(currentChar) then
                            return
                        end
                        local selected = tonumber(
                                             PERSIST.configSlots and
                                                 PERSIST.configSlots.tshirt) or
                                             tonumber(F.cache().tshirtRes)
                        local base, color, pattern =
                            F.getCrewUniformCustomization(selected)
                        if not base or type(info) ~= "table" then
                            return
                        end
                        info.wear_ext = info.wear_ext or {}
                        local replaced = false
                        for index, value in ipairs(info.wear_ext) do
                            local current =
                                type(value) == "table" and tonumber(value[1])
                            if current == base or F.CREW_UNIFORM_COLORS[current] then
                                info.wear_ext[index] = {base, color, pattern}
                                replaced = true
                                break
                            end
                        end
                        if not replaced then
                            table.insert(info.wear_ext, {base, color, pattern})
                        end
                        hasData = true
                    end)
                    return info, hasData
                end
            end)
        end
    end

    function F.hookPutOnRsp()
        pcall(function()
            local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
            local o = wl.on_puton_rsp
            wl.on_puton_rsp = function(self, res, item, olditem, index, extra)
                o(self, res, item, olditem, index, extra)
                if not item or not item.instid then return end
                local resID = tonumber(item.res_id)
                local insID = tonumber(item.instid)
                if not resID or not insID then return end
                if resID == F.CREW_UNIFORM_BASE_RES or
                    F.CREW_UNIFORM_COLORS[resID] then
                    F.rememberCrewUniformCustomization(resID, item)
                end
                local c = F.cfg(resID)
                local st = F.subType(c)
                if st == OUTFIT_SUB then
                    F.saveEquip(resID, insID)
                elseif st == HAT_SUB or FACE_SUBS[st] or BODY_SUBS[st] or
                    HELMET_SUBS[st] or st == PARACHUTE_SUB or
                    F.isGlideRes(resID) or st == GLOVES_SUB then
                    F.saveEquip(resID, insID)
                elseif F.isParachuteRes(resID) or F.isGlideRes(resID) then
                    F.saveEquip(resID, insID)
                elseif HEAD_SUBS[st] then
                    F.saveEquip(resID, insID)
                elseif F.weaponIdFromSkin(resID) then
                    F.cacheWeaponSkinFromIns(F.weaponIdFromSkin(resID), insID)
                elseif st == MELEE_ID then
                    F.cacheWeaponSkinFromIns(
                        F.weaponIdFromSkin(resID) or MELEE_ID, insID)
                elseif F.isInjectedIns(insID) then
                    F.saveEquip(resID, insID)
                end
            end
        end)
    end

    function F.hookLobbyWeaponCache()
        if _G.AddOutfitLobbyWeaponCacheHooked then return end
        _G.AddOutfitLobbyWeaponCacheHooked = true
        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            local oRsp = Arm.install_weapon_skin_rsp
            Arm.install_weapon_skin_rsp =
                function(client_data, errorCode, weapon_id, instanceID)
                    oRsp(client_data, errorCode, weapon_id, instanceID)
                    if (errorCode == 0 or errorCode == NET_OK) and
                        F.isWeaponSkinIns(instanceID) then
                        F.cacheWeaponSkinFromIns(weapon_id, instanceID)
                    end
                end
            local oH = Arm.HandleWeaponSkinChange
            Arm.HandleWeaponSkinChange =
                function(client_data, weapon_id, instanceID)
                    oH(client_data, weapon_id, instanceID)
                    if F.isWeaponSkinIns(instanceID) then
                        F.cacheWeaponSkinFromIns(weapon_id, instanceID)
                    end
                end
        end)
        pcall(function()
            local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
            local o = wgl.on_put_on_weapon_wear_rsp
            wgl.on_put_on_weapon_wear_rsp =
                function(self, client_data, res, weapon_id, new_skin_id,
                         extra_weapon_list)
                    o(self, client_data, res, weapon_id, new_skin_id,
                      extra_weapon_list)
                    if res == 0 or res == NET_OK then
                        F.cacheWeaponSkinFromIns(weapon_id, new_skin_id)
                    end
                end
        end)
        pcall(function()
            if not EventSystem or not EventSystem.registEvent then
                return
            end
            if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                EventSystem:registEvent(EVENTTYPE_WARDROBE,
                                        EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN,
                                        function(_, _, resOrFlag, weapon_id)
                    weapon_id = tonumber(weapon_id)
                    if weapon_id and weapon_id > 0 then
                        pcall(function()
                            local wgl = require(
                                            "client.slua.logic.wardrobe.logic_wardrobe_gun")
                            local insID = tonumber(
                                              wgl:GetSkinIdByWeaponID(weapon_id)) or
                                              0
                            if insID > 0 then
                                F.cacheWeaponSkinFromIns(weapon_id, insID)
                            end
                        end)
                    elseif tonumber(resOrFlag) and tonumber(resOrFlag) > 100000 then
                        pcall(function()
                            local wid = F.weaponIdFromSkin(resOrFlag)
                            if wid then
                                local wd = require(
                                               "client.slua.logic.wardrobe.wardrobe_data")
                                local ins =
                                    wd.GetWardrobeInsIdByResId and
                                        wd:GetWardrobeInsIdByResId(resOrFlag)
                                if ins and ins > 0 then
                                    F.cacheWeaponSkinFromIns(wid, ins)
                                end
                            end
                        end)
                    end
                end)
            end
        end)
        pcall(function()
            local WRH = require("client.network.Protocol.WardRobeHandler")
            local oHeadReq = WRH.send_depot_set_head_show_req
            WRH.send_depot_set_head_show_req = function(insID)
                insID = tonumber(insID) or 0
                if insID > 0 and F.isInjectedIns(insID) then
                    local wd = require(
                                   "client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if d and d.resID then
                        F.saveEquip(tonumber(d.resID), insID)
                    end
                    local fbd = require(
                                    "client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    fbd:SetHeadShow(insID)
                    WRH.on_depot_set_head_show_rsp(NET_OK, insID)
                    return
                end
                return oHeadReq(insID)
            end
            local oHead = WRH.on_depot_set_head_show_rsp
            WRH.on_depot_set_head_show_rsp =
                function(err_code, id)
                    oHead(err_code, id)
                    if err_code ~= 0 and err_code ~= NET_OK then
                        return
                    end
                    id = tonumber(id) or 0
                    if id <= 0 then return end
                    local wd =
                        require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(id)
                    if d and d.resID then
                        local st = tonumber(d.itemSubType or
                                                F.subType(F.cfg(d.resID)))
                        if st == HAT_SUB or HELMET_SUBS[st] then
                            F.saveEquip(tonumber(d.resID), id)
                        end
                    end
                end
        end)
    end

    function F.hookWardrobePutOnReq()
        pcall(function()
            local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
            if wl._AddOutfitPutOnReqHooked then return end
            wl._AddOutfitPutOnReqHooked = true
            local oReq = wl.wardrobe_puton_req
            wl.wardrobe_puton_req = function(self, insID, extra)
                insID = tonumber(insID)
                F.ensureDepotItemValid(insID)
                if F.tryLocalWearByIns(insID) then return end
                return oReq(self, insID, extra)
            end
            if not wl._AddOutfitPutOnDataHooked then
                wl._AddOutfitPutOnDataHooked = true
                local oData = wl.wardrobe_puton_data_req
                wl.wardrobe_puton_data_req =
                    function(self, itemData)
                        if itemData then
                            local insID =
                                tonumber(itemData.ins_id or itemData.insID)
                            local resID =
                                tonumber(itemData.res_id or itemData.resID)
                            F.clearItemExpire(itemData, insID, resID)
                            F.ensureDepotItemValid(insID, resID)
                            if resID == F.CREW_UNIFORM_BASE_RES or
                                F.CREW_UNIFORM_COLORS[resID] then
                                F.rememberCrewUniformCustomization(resID,
                                                                   itemData)
                            end
                        end
                        return oData(self, itemData)
                    end
            end
        end)
    end

    local _bootstrapNotified = false

    function F.bootstrapMatch(char)
        if not F.isEnabled() then return false end
        char = char or F.getLocalChar()
        if not char or not slua.isValid(char) then return false end
        if F.isInRealMatch and not F.isInRealMatch() then return false end
        if PERF.matchActive then return true end
        local now = os.clock()
        if (now - PERF.lastBootstrapAt) < BOOTSTRAP_COOLDOWN then
            return false
        end
        PERF.lastBootstrapAt = now
        F.skinDiag("BOOTSTRAP",
                   "pawn=" .. tostring(char) .. " persistedBag=" ..
                       tostring(PERSIST.configSlots and PERSIST.configSlots.bag) ..
                       " persistedHelmet=" ..
                       tostring(PERSIST.configSlots and
                                    PERSIST.configSlots.helmet) ..
                       " grenade=" .. tostring(F.cache().grenadeRes), 0)
        F.syncWeaponCacheFromLobby(true)
        F.applyPersistSlotsToCache()
        F.cleanArmoryPollution()
        F.syncGlobalWearSkins()
        F.syncAirborneToDataMgr()
        pcall(function()
            F.applyAirborneSlots(char, F.isCharacterAirborne(char))
        end)
        pcall(function() F.matchApplyFaceAndHair(char) end)
        F.syncVehicleCacheFromDataMgr()
        F.syncVehicleSlotsToDataMgr()
        pcall(function() F.applyVehicleSkinsToPC(F.getPC()) end)
        F.startVehicleSkinTicker()
        pcall(function()
            local v = F.getMatchVehicle()
            if slua.isValid(v) then F.autoApplyVehicleSkinOnEnter(v) end
        end)
        _weaponApplied = false
        _weaponDiagDone = false
        _matchApplied = false
        if not _bootstrapNotified then _bootstrapNotified = true end
        F.startMatchWatcher(char)
        return true
    end

    
    
    
    function F.ensureMatchBootstrap(char)
        if PERF.matchActive or PERF.wearDoneThisMatch then return true end
        return F.bootstrapMatch(char)
    end

    function F.hookMatchAvatar()
        pcall(function()
            local CAC = require(
                            "GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
            local o = CAC.OnAvatarAllMeshLoadedLua
            CAC.OnAvatarAllMeshLoadedLua = function(self)
                o(self)
                pcall(function()
                    if self.IsLobbyActor and self:IsLobbyActor() then
                        return
                    end
                    local isSelf = self.IsSelf and self:IsSelf()
                    if not isSelf then return end
                    if PERF.wearDoneThisMatch or PERF.matchActive then
                        return
                    end
                    local char = F.getLocalChar()
                    if char and char.AddGameTimer then
                        char:AddGameTimer(0.5, false,
                                          function()
                            F.bootstrapMatch(char)
                        end)
                    end
                end)
            end
        end)
        pcall(function()
            local WAC = require(
                            "GameLua.Mod.Library.GamePlay.Avatar.Component.WeaponAvatarComponent")
            local oLoad = WAC.OnWeaponAvatarLoadedLua
            WAC.OnWeaponAvatarLoadedLua =
                function(self, slotID, definedID)
                    oLoad(self, slotID, definedID)
                    pcall(function()
                        if self.IsLobbyActor and self:IsLobbyActor() then
                            return
                        end
                        local isSelf = self.IsSelf and self:IsSelf()
                        if not isSelf then return end
                        local char = F.getLocalChar()
                        if not char then return end
                        _weaponApplied = false
                        if not PERF.matchActive then
                            F.bootstrapMatch(char)
                        elseif char.AddGameTimer then
                            char:AddGameTimer(0.25, false, function()
                                local c = F.getLocalChar()
                                if c then
                                    F.matchApplyWeaponSkin(c)
                                end
                            end)
                        end
                    end)
                end
        end)
    end

    function F.hookVehicleInfoInit()
        pcall(function()
            if DataMgr._AddOutfitVehInfoHooked then return end
            DataMgr._AddOutfitVehInfoHooked = true
            local orig = DataMgr.InitVehicleInfo
            DataMgr.InitVehicleInfo = function(vehicle_info, vst_skin)
                vehicle_info = F.mergeInjectedIntoVehicleSlotList(vehicle_info)
                orig(vehicle_info, vst_skin)
                F.later(0.15, function()
                    F.reapplyVehicleSlotsFromConfig()
                    F.reapplyHallThemeFromConfig()
                    LOBBY.reapplyDone = false
                    LOBBY.reapplyScheduled = false
                    F.scheduleLobbyReapplyOnce()
                end)
            end
        end)
    end

    function F.hookVehicleSkinDataInit()
        pcall(function()
            if DataMgr._AddOutfitVehSkinDataHooked then return end
            DataMgr._AddOutfitVehSkinDataHooked = true
            local origInit = DataMgr.InitVehicleSkinData
            DataMgr.InitVehicleSkinData = function(data)
                data = F.mergeInjectedVehicleSkinTable(data)
                origInit(data)
                F.later(0.1, function()
                    F.equipVehicleTypesFromConfig(PERSIST.configVehicleSlots)
                end)
            end
            local origUpd = DataMgr.UpdateVehicleSkin
            DataMgr.UpdateVehicleSkin = function(itemSubType, putOnId)
                origUpd(itemSubType, putOnId)
                if not _G.AddOutfitApplyingConfig and F.isInjectedIns(putOnId) then
                    F.setLobbyVehicleManual(itemSubType, R.insToRes[putOnId],
                                            putOnId)
                end
            end
        end)
        pcall(function()
            local HallThemeUtils =
                require("client.logic.lobby.hall_theme_utils")
            if HallThemeUtils._AddOutfitLobbyVehHooked then return end
            HallThemeUtils._AddOutfitLobbyVehHooked = true
            local orig = HallThemeUtils.ProcPutOnVehicle
            HallThemeUtils.ProcPutOnVehicle =
                function(putOnItem, bShowVehicle)
                    orig(putOnItem, bShowVehicle)
                    if not _G.AddOutfitApplyingConfig and putOnItem then
                        local ins = tonumber(putOnItem.instid)
                        local res = tonumber(putOnItem.res_id)
                        local actualRes = res or (ins and R.insToRes[ins])
                        if ins and F.isInjectedIns(ins) then
                            F.setLobbyVehicleManual(F.vehicleSubType(actualRes),
                                                    actualRes, ins)
                        end
                    end
                end
        end)
    end

    function F.hookHallTheme()
        pcall(function()
            local HT = require("client.logic.lobby.hall_theme_utils")
            if HT._AddOutfitHallThemeHooked then return end
            local orig = HT.ProcPutOnHallTheme
            if type(orig) ~= "function" then return end
            HT._AddOutfitHallThemeHooked = true
            HT.ProcPutOnHallTheme = function(putOnItem, putOffItem)
                orig(putOnItem, putOffItem)
                if not _G.AddOutfitApplyingTheme and putOnItem then
                    local ins = tonumber(putOnItem.instid)
                    local res = tonumber(putOnItem.res_id)
                    if ins and F.isInjectedIns(ins) then
                        F.setHallThemeManual(res or R.insToRes[ins], ins)
                    end
                end
            end
        end)
    end

    
    
    
    function F.hookGarageTheme()
        pcall(function()
            local TeamupHandler = require(
                                      "client.network.Protocol.TeamupHandler")
            local ModuleManager = require(
                                      "client.module_framework.ModuleManager")
            if not TeamupHandler or not ModuleManager then return end

            local function getGarageSystem()
                local config = ModuleManager.LobbyModuleConfig
                if not config or not config.GarageThemeSystem then
                    return nil
                end
                return ModuleManager.GetModule(config.GarageThemeSystem)
            end

            local function refreshGarage(system)
                pcall(function()
                    if system and system.ReportSpecialEffectTlog then
                        system:ReportSpecialEffectTlog()
                    end
                end)
                pcall(function()
                    if EventSystem and EVENTTYPE_LOBBY_THEME and
                        EVENTID_GARAGE_VEHICLE_DATA_CHANGE then
                        EventSystem:postEvent(EVENTTYPE_LOBBY_THEME,
                                              EVENTID_GARAGE_VEHICLE_DATA_CHANGE)
                    end
                end)
                pcall(function()
                    local utils = require("client.logic.lobby.hall_theme_utils")
                    if utils and utils.UpdateThemeVehicleShow then
                        utils.UpdateThemeVehicleShow()
                    end
                    if utils and utils.ShowThemeVehicle then
                        utils.ShowThemeVehicle()
                    end
                end)
            end

            local function applyInjectedGarageSlot(system, slotID, insID)
                slotID = math.floor(tonumber(slotID) or 0)
                insID = tonumber(insID) or 0
                local resID = R.insToRes[insID]
                if slotID < 1 or not resID or not F.isVehicleRes(resID) then
                    return false
                end

                system.GarageVehicleInfo = system.GarageVehicleInfo or {}
                system.GarageVehicleInfo[slotID] = {
                    inst_id = insID,
                    res_id = resID
                }
                for otherSlot, info in pairs(system.GarageVehicleInfo) do
                    if otherSlot ~= slotID and info and tonumber(info.inst_id) ==
                        insID then
                        system.GarageVehicleInfo[otherSlot] = nil
                    end
                end

                pcall(function()
                    local subType = F.vehicleSubType(resID)
                    if subType and DataMgr and DataMgr.UpdateVehicleSkin then
                        DataMgr.UpdateVehicleSkin(subType, insID)
                    end
                    if DataMgr then DataMgr.vst_skin = insID end
                end)
                return true
            end

            local originalUpdate =
                TeamupHandler.send_update_car_main_page_slot_req
            if originalUpdate and not TeamupHandler._AddOutfitGarageUpdateHooked then
                TeamupHandler._AddOutfitGarageUpdateHooked = true
                TeamupHandler.send_update_car_main_page_slot_req = function(
                    slotID, itemInstID)
                    local insID = tonumber(itemInstID)
                    if F.isInRealMatch() or not F.isInjectedIns(insID) then
                        return originalUpdate(slotID, itemInstID)
                    end
                    local system = getGarageSystem()
                    if not system or
                        not applyInjectedGarageSlot(system, slotID, insID) then
                        return originalUpdate(slotID, itemInstID)
                    end
                    refreshGarage(system)
                end
            end

            local originalBatch = TeamupHandler.send_batch_put_on_sportscar_req
            if originalBatch and not TeamupHandler._AddOutfitGarageBatchHooked then
                TeamupHandler._AddOutfitGarageBatchHooked = true
                TeamupHandler.send_batch_put_on_sportscar_req =
                    function(slotMap)
                        if F.isInRealMatch() or type(slotMap) ~= "table" then
                            return originalBatch(slotMap)
                        end

                        local system = getGarageSystem()
                        if not system then
                            return originalBatch(slotMap)
                        end

                        local changed = false
                        local genuineSlots = {}
                        for slotID, itemInstID in pairs(slotMap) do
                            local insID = tonumber(itemInstID)
                            if F.isInjectedIns(insID) and
                                applyInjectedGarageSlot(system, slotID, insID) then
                                changed = true
                            else
                                genuineSlots[slotID] = itemInstID
                            end
                        end

                        if changed then
                            refreshGarage(system)
                        end
                        if next(genuineSlots) then
                            return originalBatch(genuineSlots)
                        end
                        if not changed then
                            return originalBatch(slotMap)
                        end
                    end
            end
        end)
    end

    
    
    
    
    
    function F.hookProfileShowcaseLocal()
        if F._profileShowcaseLocalHooked then return true end

        local function enabled()
            local value = _G.VIPConfig and _G.VIPConfig.CollectionHallLocal
            return value == true or tonumber(value) == 1
        end

        
        
        local function enabledForSelfCard(self)
            if not enabled() or not self then return false end
            if self._isSelfRole == true then return true end
            local localUID = DataMgr and DataMgr.roleData and
                                 tonumber(DataMgr.roleData.uid)
            local cardUID = tonumber(self._uid)
            return localUID ~= nil and cardUID ~= nil and localUID == cardUID
        end

        local okMM, moduleManager = pcall(require,
                                          "client.module_framework.ModuleManager")
        if not okMM or not moduleManager or not moduleManager.LobbyModuleConfig then
            return false
        end

        
        
        local cpKey = moduleManager.LobbyModuleConfig.logic_custom_presentation
        local cp = cpKey and moduleManager.GetModule(cpKey)
        if not cp or type(cp.GetData) ~= "function" then return false end

        if not cp.__4RProfileShowcaseOriginal_GetData then
            cp.__4RProfileShowcaseOriginal_GetData = cp.GetData
            cp.GetData = function(self, ...)
                if enabled() then
                    
                    
                    
                    return {
                        {mId = 1, mData = {rank_segment_id = 801}},
                        {mId = 4, mData = {collect_level = 70}},
                        {mId = 11, mData = {rank_segment_id = 801}},
                        {mId = 12, mData = {peak_segment_id = 1501}}
                    }
                end
                return self.__4RProfileShowcaseOriginal_GetData(self, ...)
            end
        end

        
        
        pcall(function()
            local item = require(
                             "client.slua.umg.PersonSpace.Popup.Item.Common_InformationCustom_Item")
            if type(item) ~= "table" or item.__4RProfileShowcaseCardHooked then
                return
            end

            if type(item.GetCommonRankIntegralLevelShow) == "function" then
                local original = item.GetCommonRankIntegralLevelShow
                item.GetCommonRankIntegralLevelShow =
                    function(self, profile, segmentID, ...)
                        if enabledForSelfCard(self) then
                            local copy = {}
                            for key, value in pairs(profile or {}) do
                                copy[key] = value
                            end
                            copy.segment_info = nil
                            return original(self, copy, 801, ...)
                        end
                        return original(self, profile, segmentID, ...)
                    end
            end

            if type(item.GetCommonRankIntegralLevelShowMax) == "function" then
                local original = item.GetCommonRankIntegralLevelShowMax
                item.GetCommonRankIntegralLevelShowMax =
                    function(self, profile, ...)
                        if enabledForSelfCard(self) then
                            local copy = {}
                            for key, value in pairs(profile or {}) do
                                copy[key] = value
                            end
                            copy.history_max_segment_level = {801}
                            copy.history_max_segment_season_id = {
                                tonumber(DataMgr and DataMgr.season_id) or 0
                            }
                            return original(self, copy, ...)
                        end
                        return original(self, profile, ...)
                    end
            end

            if type(item.GetPeakGameRankIntegralShow) == "function" then
                local original = item.GetPeakGameRankIntegralShow
                item.GetPeakGameRankIntegralShow =
                    function(self, profile, ...)
                        if enabledForSelfCard(self) then
                            local okUtil, peakUtil = pcall(require,
                                                           "client.logic.PeakGame.LogicPeakGameUtil")
                            local cfg = okUtil and peakUtil and
                                            peakUtil.GetPeakRankTableData(1501)
                            if cfg then
                                pcall(function()
                                    if self.UIRoot and
                                        self.UIRoot.WidgetSwitcher_BG_Text then
                                        self.UIRoot.WidgetSwitcher_BG_Text:SetActiveWidgetIndex(
                                            0)
                                    end
                                end)
                                return {icon = cfg.BigIcon, title = cfg.Name}
                            end
                        end
                        return original(self, profile, ...)
                    end
            end

            if type(item.GetCollectInfo) == "function" then
                local original = item.GetCollectInfo
                item.GetCollectInfo = function(self, profile, ...)
                    if not enabledForSelfCard(self) then
                        return original(self, profile, ...)
                    end
                    local collectKey = moduleManager.LobbyModuleConfig
                                           .collect_module
                    local collect = collectKey and
                                        moduleManager.GetModule(collectKey)
                    local oldData = collect and collect.collect_data
                    if collect then
                        local season = collect.GetSeasonId and
                                           collect:GetSeasonId() or 0
                        local seasonScore = {}
                        if type(oldData) == "table" and
                            type(oldData.season_score) == "table" then
                            for key, value in pairs(oldData.season_score) do
                                seasonScore[key] = value
                            end
                        end
                        seasonScore[season] = 700000
                        collect.collect_data = {
                            total_score = 700000,
                            season_score = seasonScore
                        }
                    end
                    local result = {pcall(original, self, profile, ...)}
                    if collect then
                        collect.collect_data = oldData
                    end
                    if result[1] then
                        table.remove(result, 1)
                        return (table.unpack or unpack)(result)
                    end
                    return nil
                end
            end

            item.__4RProfileShowcaseCardHooked = true
        end)

        F._profileShowcaseLocalHooked = true
        return true
    end

    function F.hookCollectionHallLocal()
        local ok, ModuleManager = pcall(require,
                                        "client.module_framework.ModuleManager")
        if not ok or not ModuleManager or not ModuleManager.LobbyModuleConfig then
            return false
        end
        local config = ModuleManager.LobbyModuleConfig
        local moduleKey = config.Logic_SocialLobbyModule
        local social = moduleKey and ModuleManager.GetModule(moduleKey)
        if not social then return false end

        local SLOT_AVATAR, SLOT_VEHICLE, SLOT_WEAPON, SLOT_PET = 1, 2, 3, 4
        local SLOT_BGWALL = 100
        local maxSlots = {
            [SLOT_AVATAR] = 6,
            [SLOT_VEHICLE] = 6,
            [SLOT_WEAPON] = 8,
            [SLOT_PET] = 4
        }

        local function enabled()
            local value = _G.VIPConfig and _G.VIPConfig.CollectionHallLocal
            return value == true or tonumber(value) == 1
        end

        local function isSelf(uid)
            return DataMgr and DataMgr.roleData and tonumber(uid) ==
                       tonumber(DataMgr.roleData.uid)
        end

        local function wrap(name, localResult)
            local originalKey = "__4RCollectionOriginal_" .. name
            if social[originalKey] or type(social[name]) ~= "function" then
                return
            end
            social[originalKey] = social[name]
            social[name] = function(self, ...)
                if enabled() then
                    local values = {localResult(self, ...)}
                    if values[1] ~= nil then
                        return (table.unpack or unpack)(values)
                    end
                end
                return self[originalKey](self, ...)
            end
        end

        wrap("GetSlotIsUnlockBySlotTypeAndIndex", function(_, uid, slotType)
            if slotType ~= SLOT_BGWALL and isSelf(uid) then
                return true
            end
            return nil
        end)
        wrap("GetSlotIsUnlockedByCollectHallLevel", function(_, uid, slotType)
            if slotType ~= SLOT_BGWALL and isSelf(uid) then
                return true
            end
            return nil
        end)
        wrap("CheckSlotTypeIsUCUnlock", function(self, slotType)
            if self.GetCurShowIsSelf and self:GetCurShowIsSelf() then
                return false
            end
            return nil
        end)
        wrap("GetSlotTypeMaxCount", function(_, uid, slotType)
            if isSelf(uid) and maxSlots[slotType] then
                return maxSlots[slotType]
            end
            return nil
        end)
        wrap("GetSlotTypeUCUnlockMaxCount", function(self, slotType)
            if self.GetCurShowIsSelf and self:GetCurShowIsSelf() then
                return maxSlots[slotType] or 0
            end
            return nil
        end)
        wrap("GetSlotUnlockCountByCollectHallLevel", function(_, uid, slotType)
            if isSelf(uid) then return maxSlots[slotType] or 0 end
            return nil
        end)
        wrap("GetSlotTypeAllUnlockData", function(_, uid, slotType)
            if not isSelf(uid) or slotType == SLOT_BGWALL then
                return nil
            end
            local data = social:GetSocialData(uid)
            return data and data.mixed_hall_slot_unlock_info and
                       data.mixed_hall_slot_unlock_info[slotType] or {}
        end)
        wrap("GetWeaponSlotIsShowBySlotIndex", function(self)
            if self.GetCurShowIsSelf and self:GetCurShowIsSelf() then
                return true
            end
            return nil
        end)

        
        
        

        pcall(F.hookProfileShowcaseLocal)

        F._collectionHallSocial = social
        _G.AddOutfitCollectionHallHooked = true
        return true
    end

    function F.copyCollectionHallLocalValue(value, seen)
        if type(value) ~= "table" then return value end
        seen = seen or {}
        if seen[value] then return seen[value] end
        local copy = {}
        seen[value] = copy
        for key, entry in pairs(value) do
            copy[F.copyCollectionHallLocalValue(key, seen)] =
                F.copyCollectionHallLocalValue(entry, seen)
        end
        return copy
    end

    function F.snapshotCollectionHallLocal(data, uid)
        if not data then return false end
        
        
        local previous = _G.__4RCollectionHallLocalBackup
        if previous and previous.data == data and previous.uid == uid then
            return true
        end

        local backup = {data = data, uid = uid, mixed = {}, unlock = {}}
        for slotType = 1, 4 do
            local mixed = data.mixed_data and data.mixed_data[slotType]
            local unlock = data.mixed_hall_slot_unlock_info and
                               data.mixed_hall_slot_unlock_info[slotType]
            backup.mixed[slotType] = {
                existed = mixed ~= nil,
                value = F.copyCollectionHallLocalValue(mixed)
            }
            backup.unlock[slotType] = {
                existed = unlock ~= nil,
                value = F.copyCollectionHallLocalValue(unlock)
            }
        end
        _G.__4RCollectionHallLocalBackup = backup
        return true
    end

    function F.restoreCollectionHallLocal()
        local backup = _G.__4RCollectionHallLocalBackup
        if not backup or not backup.data then return false end
        local data = backup.data
        data.mixed_data = data.mixed_data or {}
        data.mixed_hall_slot_unlock_info =
            data.mixed_hall_slot_unlock_info or {}
        for slotType = 1, 4 do
            local mixed = backup.mixed[slotType]
            local unlock = backup.unlock[slotType]
            data.mixed_data[slotType] = mixed and mixed.existed and
                                            F.copyCollectionHallLocalValue(
                                                mixed.value) or nil
            data.mixed_hall_slot_unlock_info[slotType] = unlock and
                                                             unlock.existed and
                                                             F.copyCollectionHallLocalValue(
                                                                 unlock.value) or
                                                             nil
        end
        _G.__4RCollectionHallLocalBackup = nil
        return true
    end

    function F.populateCollectionHallLocal()
        local social = F._collectionHallSocial
        local uid = DataMgr and DataMgr.roleData and
                        tonumber(DataMgr.roleData.uid)
        if not social or not uid or not social.GetSocialData then
            return false
        end
        local data = social:GetSocialData(uid)
        if not data then return false end

        
        
        F.snapshotCollectionHallLocal(data, uid)

        local SLOT_AVATAR, SLOT_VEHICLE, SLOT_WEAPON, SLOT_PET = 1, 2, 3, 4
        local maxSlots = {
            [SLOT_AVATAR] = 6,
            [SLOT_VEHICLE] = 6,
            [SLOT_WEAPON] = 8,
            [SLOT_PET] = 4
        }
        data.mixed_hall_slot_unlock_info =
            data.mixed_hall_slot_unlock_info or {}
        data.mixed_data = data.mixed_data or {}
        local now = os and os.time and os.time() or 9999999999
        for slotType, count in pairs(maxSlots) do
            data.mixed_hall_slot_unlock_info[slotType] =
                data.mixed_hall_slot_unlock_info[slotType] or {}
            data.mixed_data[slotType] = data.mixed_data[slotType] or {}
            for index = 1, count do
                data.mixed_hall_slot_unlock_info[slotType][index] = now
            end
        end

        
        
        local vehicleSkins = {
            1961153, 
            1908117, 
            1961145, 
            1915021, 
            1961147, 
            1915008 
        }
        for index, resID in ipairs(vehicleSkins) do
            F.ensureSkinDownload(resID)
            data.mixed_data[SLOT_VEHICLE][index] = {
                resid = resID,
                instid = resID * 1000 + index
            }
        end

        
        local weaponSkins = {
            1101101007, 1101004246, 1101004218, 1101004226, 1101003227,
            1101005098, 1101006085, 1101008146
        }
        for index, resID in ipairs(weaponSkins) do
            F.ensureSkinDownload(resID)
            data.mixed_data[SLOT_WEAPON][index] = {
                resid = resID,
                instid = resID * 1000 + index,
                weapon_id = 0
            }
        end

        
        
        
        local avatarXSuits = {
            1407895, 
            1407856, 
            1406469, 
            1407140, 
            1407142, 
            1407141 
        }

        
        
        F.syncBodyCacheFromLobby()
        local cache = F.cache()
        local wear = {
            {cache.outfitRes, cache.outfitIns}, {cache.hatRes, cache.hatIns},
            {cache.maskRes, cache.maskIns}, {cache.glassRes, cache.glassIns},
            {cache.pantsRes, cache.pantsIns}, {cache.shoesRes, cache.shoesIns},
            {cache.glovesRes, cache.glovesIns}, {cache.bagRes, cache.bagIns},
            {cache.helmetRes, cache.helmetIns}
        }
        if not cache.outfitRes or tonumber(cache.outfitRes) <= 0 then
            wear[#wear + 1] = {cache.tshirtRes, cache.tshirtIns}
        end
        local avatarTools = nil
        pcall(function()
            avatarTools = require(
                              "client.slua.logic.lobby.Left.SocialLobby.Logic_AvatarWardrobeDataTools")
        end)
        for index = 1, maxSlots[SLOT_AVATAR] do
            local slotData = {
                gender = tonumber(DataMgr.roleData.sex or
                                      DataMgr.roleData.gender) or 1,
                pose_type = 0,
                item_info = {},
                bIsEditData = true
            }
            for _, entry in ipairs(wear) do
                local resID, insID = tonumber(entry[1]), tonumber(entry[2])
                if resID and resID > 0 then
                    local avatarSlot = nil
                    pcall(function()
                        local row = F.cfg(resID)
                        if row and avatarTools and avatarTools.GetAvatarSlotType then
                            avatarSlot =
                                avatarTools.GetAvatarSlotType(row.ItemSubType)
                        end
                    end)
                    avatarSlot = tonumber(avatarSlot) or F.resToCustSlot(resID)
                    if avatarSlot then
                        slotData.item_info[avatarSlot] = {
                            resid = resID,
                            instid = insID or (resID * 1000 + index),
                            origin_resid = 0
                        }
                        F.ensureSkinDownload(resID)
                    end
                end
            end
            local xSuitRes = avatarXSuits[index]
            if xSuitRes then
                local xSuitSlot = nil
                pcall(function()
                    local row = F.cfg(xSuitRes)
                    if row and avatarTools and avatarTools.GetAvatarSlotType then
                        xSuitSlot = avatarTools.GetAvatarSlotType(
                                        row.ItemSubType)
                    end
                end)
                xSuitSlot = tonumber(xSuitSlot) or
                                F.CUST_SLOT.ClothesEquipemtSlot
                slotData.item_info[xSuitSlot] = {
                    resid = xSuitRes,
                    instid = xSuitRes * 1000 + index,
                    origin_resid = 0
                }
                F.ensureSkinDownload(xSuitRes)
            end
            data.mixed_data[SLOT_AVATAR][index] = slotData
        end
        return true
    end

    function _G.ApplyCollectionHallLocalState(enabled)
        enabled = enabled == true or tonumber(enabled) == 1
        _G.VIPConfig.CollectionHallLocal = enabled
        if enabled then
            F.hookCollectionHallLocal()
            F.hookProfileShowcaseLocal()
            F.populateCollectionHallLocal()
        else
            F.restoreCollectionHallLocal()
        end

        pcall(function()
            if EventSystem and EVENTTYPE_LOBBY_SOCIAL and
                EVENTID_SOCIAL_LOBBY_SLOT_DATA_UPDATE then
                EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL,
                                      EVENTID_SOCIAL_LOBBY_SLOT_DATA_UPDATE)
            end
        end)
        pcall(function()
            if EventSystem and EVENTTYPE_ROLEINFO and
                EVENTID_ROLEINFO_CUSTOM_PRESENTATION_CHANGE then
                EventSystem:postEvent(EVENTTYPE_ROLEINFO,
                                      EVENTID_ROLEINFO_CUSTOM_PRESENTATION_CHANGE)
            end
        end)
        
        
        
        return true
    end

    function F.hookEnterGame()
        if _G.AddOutfitEnterGameHooked then return end
        _G.AddOutfitEnterGameHooked = true
        pcall(function()
            if EventSystem and EventSystem.registEvent and EVENTTYPE_LOBBY and
                EVENTID_ENTER_GAME_BEGIN then
                EventSystem:registEvent(EVENTTYPE_LOBBY,
                                        EVENTID_ENTER_GAME_BEGIN, function()
                    F.perfInvalidateLobby()
                    F.syncWeaponCacheFromLobby(true)
                    F.reapplyVehicleSlotsFromConfig(true)
                    F.reapplyHallThemeFromConfig(true)
                    pcall(F.applyVehicleSkinsToPC)
                    F.stopMatchWatcher()
                    _bootstrapNotified = false
                end)
            end
        end)
    end

    function F.afterInjectApply(firstTime)
        F.mergeInjectedArmorySkins()
        F.cleanArmoryPollution()
        if firstTime then
            F.refreshWardrobeOnce()
            F.persistApplyLoaded()
            F.syncLobbyVehicleResFromIns()
            F.reapplyVehicleSlotsFromConfig(true)
            F.reapplyHallThemeFromConfig(true)
            F.reapplyWeaponsFromConfig()
            F.scheduleLobbyReapplyOnce()
        else
            F.reapplyWeaponsFromConfig()
        end
    end

    
    
    
    function F.requestActivation()
        if not (_G.VIPConfig and _G.VIPConfig.ModSkin) then return false end

        _G.AddOutfitActivationToken = (_G.AddOutfitActivationToken or 0) + 1
        local activationToken = _G.AddOutfitActivationToken
        local tries = 0

        pcall(function()
            F.persistLoadFromDisk()
            F.applyPersistSlotsToCache()
            F.syncGlobalWearSkins()
        end)

        local function attempt()
            if activationToken ~= _G.AddOutfitActivationToken or
                not (_G.VIPConfig and _G.VIPConfig.ModSkin) then
                return
            end

            tries = tries + 1
            if F.injectAll() then
                local firstLobby = not _G.AddOutfitLobbyInitDone
                if firstLobby then
                    _G.AddOutfitLobbyInitDone = true
                end
                F.afterInjectApply(firstLobby)
                if _G.AddOutfitLifecycleTick then
                    pcall(_G.AddOutfitLifecycleTick)
                end
                local char = F.getLocalChar()
                if char and slua.isValid(char) and F.isInRealMatch() then
                    PERF.lastBootstrapAt = 0
                    PERF.matchActive = false
                    pcall(function() F.bootstrapMatch(char) end)
                end
                return
            end

            if tries < INJECT_RETRY_MAX then
                F.later(INJECT_RETRY_SEC, attempt)
            end
        end

        attempt()
        return true
    end

