        _G.AddOutfitCountedKillRecords =
            _G.AddOutfitCountedKillRecords or setmetatable({}, {__mode = "k"})

        function _G.addKill(weaponID, count, killRecord)
            if not weaponID or not count then return end
            local record = killRecord or _G.AddOutfitActiveKillRecord
            if record and _G.AddOutfitCountedKillRecords[record] then
                return false
            end
            if record then
                _G.AddOutfitCountedKillRecords[record] = true
            end
            _G.killCountInfo[weaponID] =
                (_G.killCountInfo[weaponID] or 0) + count
            _G.saveKillCountToFile()
            return true
        end

        function _G.getKills(weaponID)
            weaponID = tonumber(weaponID)
            if not weaponID then return 0 end
            if _G.killCountInfo[weaponID] == nil then
                _G.killCountInfo[weaponID] =
                    520 + ((weaponID * 37) % 180)
            end
            return _G.killCountInfo[weaponID]
        end

        
        pcall(function()
            local SKillInfo = require(
                                  "GameLua.Mod.BaseMod.Client.KillInfoTips.KillInfo")
            local SKillInfoModuleManager = require(
                                               "client.module_framework.ModuleManager")
            local UEnums = _ENV.UEnums
            local ECharacterHealthStatus = import("ECharacterHealthStatus")

            local KillInfoImpl = SKillInfo and SKillInfo.__inner_impl
            if KillInfoImpl and KillInfoImpl.FileItem and
                not KillInfoImpl._AddOutfitKillCounterHooked then
                
                
                KillInfoImpl._AddOutfitKillCounterHooked = true
                local O_FileItem = KillInfoImpl.FileItem

                
                
                KillInfoImpl.FileItem = function(self, DamageRecordData)
                    if not self or not DamageRecordData then
                        return
                    end

                    
                    
                    _G.AddOutfitActiveKillRecord = DamageRecordData

                    
                    if not _G.VIPConfig.SkinDeadBox and
                        not _G.VIPConfig.KillCountUI and
                        not _G.VIPConfig.KillMessage then
                        return O_FileItem(self, DamageRecordData)
                    end

                    local LogicKillCounter =
                        SKillInfoModuleManager.GetModule(
                            SKillInfoModuleManager.CommonModuleConfig
                                .LogicKillCounter)
                    if not LogicKillCounter then
                        return O_FileItem(self, DamageRecordData)
                    end

                    local uCharacter = slua_GameFrontendHUD and
                                           slua_GameFrontendHUD:GetPlayerController() and
                                           slua_GameFrontendHUD:GetPlayerController()
                                               :GetPlayerCharacterSafety()
                    if not uCharacter or not slua.isValid(uCharacter) then
                        return O_FileItem(self, DamageRecordData)
                    end

                    local SelfName = uCharacter:GetPlayerNameSafety()
                    local bIsCauser = DamageRecordData.Causer == SelfName

                    if bIsCauser then
                        if DamageRecordData.DamageType ==
                            UEnums.DamageType.VehicleDamage then
                            if _G.VIPConfig.SkinDeadBox or
                                _G.VIPConfig.KillMessage then
                                local carSkinID = _G.CurrentEquipVehicleID or 0
                                if carSkinID ~= 0 then
                                    local ExpandData =
                                        slua.LuaArchiverDecode(LuaStateWrapper,
                                                               DamageRecordData.ExpandDataContent) or
                                            {}
                                    ExpandData.CauserVehicleSkinID = carSkinID
                                    if _G.VIPConfig.KillMessage then 
                                        self:ChangeInfoBgByWeaponAvatarIDLua(
                                            carSkinID)
                                        DamageRecordData.CauserWeaponAvatarID =
                                            carSkinID
                                        DamageRecordData.CauserClothAvatarID =
                                            _G.SuitSkin or 0
                                    end
                                    DamageRecordData.ExpandDataContent =
                                        slua.LuaArchiverEncode(LuaStateWrapper,
                                                               ExpandData)
                                end
                            end
                        elseif DamageRecordData.CauserWeaponAvatarID ~= 69 and
                            DamageRecordData.CauserClothAvatarID ~= 69 then
                            local currWeapon = uCharacter:GetCurrentWeapon()
                            if currWeapon and slua.isValid(currWeapon) then
                                local defineID = currWeapon:GetItemDefineID()
                                local DefineID = defineID and
                                                     slua.isValid(defineID) and
                                                     defineID.TypeSpecificID or
                                                     0
                                if DefineID ~= 0 then
                                    local ExpandData =
                                        slua.LuaArchiverDecode(LuaStateWrapper,
                                                               DamageRecordData.ExpandDataContent) or
                                            {}
                                    local hasChanged = false

                                    local SupportKillCounter =
                                        LogicKillCounter:GetBaseKillCounterIdByWeaponId(
                                            DefineID)
                                    if SupportKillCounter and
                                        DamageRecordData.ResultHealthStatus ==
                                        ECharacterHealthStatus.FinishedLastBreath then
                                        local SkinID = getCurrentWeaponSkinID()

                                        
                                        if SkinID > 1000000 then
                                            if _G.VIPConfig.KillCountUI then
                                                
                                                
                                                
                                                if _G.addKill(DefineID, 1,
                                                              DamageRecordData) then
                                                    ExpandData.KillCounterItemId =
                                                        DefineID
                                                    ExpandData.KillCounterNum =
                                                        (ExpandData.KillCounterNum or
                                                            0) + 1
                                                    hasChanged = true
                                                end
                                            end
                                            if _G.VIPConfig.SkinDeadBox then
                                                _G.NeedCheckDeadBoxTimer = 5
                                                hasChanged = true
                                            end
                                        end
                                    end

                                    if hasChanged or _G.VIPConfig.KillMessage then
                                        _G.UpdateMyKillCounter = true
                                        if _G.VIPConfig.KillMessage then 
                                            local synData = currWeapon.synData
                                            if synData and slua.isValid(synData) then
                                                local weaponDefineID =
                                                    slua.IndexReference(
                                                        synData:Get(7),
                                                        "defineID")
                                                if weaponDefineID and
                                                    slua.isValid(weaponDefineID) then
                                                    DamageRecordData.CauserWeaponAvatarID =
                                                        weaponDefineID.TypeSpecificID
                                                end
                                            end
                                            DamageRecordData.CauserClothAvatarID =
                                                _G.SuitSkin or 0
                                        end
                                        DamageRecordData.ExpandDataContent =
                                            slua.LuaArchiverEncode(
                                                LuaStateWrapper, ExpandData)
                                    end
                                end
                            end
                        end
                    end
                    if bIsCauser then self.bSelfKill = true end
                    return O_FileItem(self, DamageRecordData)
                end
            end
        end)

        
        pcall(function()
            local MyMainKillCounter = require(
                                          "GameLua.Mod.BaseMod.Client.KillCounter.MainKillCounter")
            local MyKillCountSubSystem = require(
                                             "GameLua.Mod.BaseMod.Client.KillCounter.KillCounterUISubsystem")
