                    if currweapon ~= nil then
                        local defineID = currweapon:GetItemDefineID()
                        local DefineID =
                            defineID and slua.isValid(defineID) and
                                defineID.TypeSpecificID or 0
                        local synDataRef =
                            slua.IndexReference(
                                currweapon.synData:Get(7), "defineID")
                        local SkinID =
                            synDataRef and slua.isValid(synDataRef) and
                                synDataRef.TypeSpecificID or 0
                        self.KillCounterItem:SetKillCounterItemShowWithNum(
                            curEquipedKillCounter, _G.getKills(DefineID), SkinID)
                    end
                end

                MyKillCountSubSystem.__inner_impl.CheckSupportKCUI = function(
                    self) return _G.VIPConfig.KillCountUI end

                local o_UpdateMainKillCounterUI =
                    MyKillCountSubSystem.__inner_impl.UpdateMainKillCounterUI
                MyKillCountSubSystem.__inner_impl.UpdateMainKillCounterUI =
                    function(self, bShow, WeaponID, AvatarID)
                        
                        if not _G.VIPConfig.KillCountUI then
                            o_UpdateMainKillCounterUI(self, false, WeaponID,
