        local function AppendUniqueEmoteIDs(list)
            if type(list) ~= "table" or not IsEmoteFeatureEnabled() then
                return list
            end

            
            
            pcall(EnsureVIPEmoteInventoryInstances)

            local seenRes, seenIns = {}, {}
            local sample = nil
            for _, value in pairs(list) do
                if sample == nil then sample = value end
                local insID = type(value) == "table" and
                                  tonumber(
                                      value.instid or value.insID or
                                          value.ins_id) or nil
                local resID = type(value) == "table" and tonumber(
                                  (value.DefineID and
                                      value.DefineID.TypeSpecificID) or
                                      value.ItemTableID or value.itemId or
                                      value.ItemID or value.resID or
                                      value.res_id or value.ResID) or
                                  tonumber(value)
                if insID then
                    seenIns[insID] = true
                    resID = tonumber(R.insToRes[insID]) or resID
                elseif resID and R.insToRes[resID] then
                    seenIns[resID] = true
                    resID = tonumber(R.insToRes[resID])
                end
                if resID then seenRes[math.abs(resID)] = true end
            end

            local shape = "resource"
            if type(sample) == "table" then
                if sample.instid ~= nil or sample.insID ~= nil or sample.ins_id ~=
                    nil then
                    shape = "depot"
                elseif sample.ItemTableID ~= nil then
                    shape = "item_table"
                elseif sample.DefineID ~= nil then
                    shape = "define"
                elseif sample.itemId ~= nil then
                    shape = "item_id"
                end
            elseif tonumber(sample) and
                (R.insToRes[tonumber(sample)] or tonumber(sample) >= INS_BASE) then
                shape = "instance"
            end

            local entity = F.getEntity and F.getEntity() or nil
            for _, id in ipairs(_G.VIPEmoteIDs or {}) do
                id = tonumber(id)
                local insID = id and tonumber(R.resToIns[id]) or nil
                if id and id > 0 and insID and not seenRes[id] and
                    not seenIns[insID] then
                    local entry
                    if shape == "instance" then
                        entry = insID
                    elseif shape == "depot" then
                        pcall(function()
                            if entity and entity.GetDataByInsID then
                                entry = entity:GetDataByInsID(insID)
                            end
                        end)
                        entry = entry or {
                            instid = insID,
                            insID = insID,
                            res_id = id,
                            resID = id,
                            count = 1,
                            expire_ts = 0
                        }
                    elseif shape == "item_table" then
                        entry = {ItemTableID = id, Count = 1, instid = insID}
                    elseif shape == "define" then
                        entry = {
                            DefineID = {TypeSpecificID = id},
                            Name = tostring(id),
                            instid = insID
                        }
                    elseif shape == "item_id" then
                        entry = {itemId = id, instid = insID}
                    else
                        entry = id
                    end
                    list[#list + 1] = entry
                    seenRes[id] = true
                    seenIns[insID] = true
                end
            end
            return list
        end

        local function GetOptimizedLobbyEmoteList(baseList)
            local result, seen = {}, {}

            for _, data in ipairs(baseList or {}) do
                if data then
                    result[#result + 1] = data
                    local emoteID = tonumber(data.itemId)
                    if emoteID and emoteID > 0 then
                        seen[emoteID] = true
                    end
                end
            end

            if not (_G.VIPConfig and _G.VIPConfig.ModEmote == true) then
                return result
            end

            local function AddLobbyEmote(emoteID)
                
                
                for i, data in ipairs(result) do
                    if not data or tonumber(data.itemId) == 0 then
                        result[i] = {itemId = emoteID}
                        return
                    end
                end
                result[#result + 1] = {itemId = emoteID}
            end

            for _, emoteID in ipairs(EXTRA_EMOTES) do
                if not seen[emoteID] then
                    AddLobbyEmote(emoteID)
                    seen[emoteID] = true
                end
            end
            return result
        end

