        local function RefreshLobbyMotionSlots()
            local dataMgr = rawget(_G, "DataMgr")
            local slots = dataMgr and dataMgr.MotionSlotList
            if type(slots) ~= "table" then return false end

            
            
            
            
            local originals = _G.__4RInjectedMotionSlotOriginals or {}
            local sameSlotTable = _G.__4RInjectedMotionSlotList == slots
            if not sameSlotTable then originals = {} end
            _G.__4RInjectedMotionSlotList = slots
            _G.__4RInjectedMotionSlotOriginals = originals

            if not IsEmoteFeatureEnabled() then
                local restored = false
                if sameSlotTable then
                    for index, saved in pairs(originals) do
                        if saved.hadValue then
                            slots[index] = saved.value
                        else
                            slots[index] = nil
                        end
                        restored = true
                    end
                end
                _G.__4RInjectedMotionSlotOriginals = {}
                if restored then
                    pcall(function()
                        if EventSystem and EVENTTYPE_MOTION and
                            EVENTID_MOTION_UPDATE_SLOT_LIST then
                            EventSystem:postEvent(EVENTTYPE_MOTION,
                                                  EVENTID_MOTION_UPDATE_SLOT_LIST)
                        end
                    end)
                end
                return true
            end

            
            if sameSlotTable and next(originals) ~= nil then
                return true
            end

            local desired = {}
            for _, emoteID in ipairs(_G.VIPEmoteIDs or {}) do
                local insID = tonumber(R.resToIns[tonumber(emoteID)])
                if insID then
                    desired[#desired + 1] = insID
                    if #desired == 9 then break end
                end
            end
            if #desired < 9 then return false end

            for index = 1, 9 do
                originals[index] = {
                    hadValue = slots[index] ~= nil,
                    value = slots[index]
                }
                slots[index] = desired[index]
            end
            _G.__4RInjectedMotionSlotOriginals = originals
            pcall(function()
                if EventSystem and EVENTTYPE_MOTION and
                    EVENTID_MOTION_UPDATE_SLOT_LIST then
                    EventSystem:postEvent(EVENTTYPE_MOTION,
                                          EVENTID_MOTION_UPDATE_SLOT_LIST)
                end
            end)
            return true
        end

        local function HookEmoteListGetter(module, method, marker)
            if type(module) ~= "table" or type(module[method]) ~= "function" then
                return false
            end
            local wrapperKey = marker .. "Wrapper"
            local originalKey = marker .. "Original"
            if module[wrapperKey] and module[method] == module[wrapperKey] then
                return true
            end
            local original = module[originalKey] or module[method]
            local wrapper = function(...)
                local results = {original(...)}
                results[1] = AppendUniqueEmoteIDs(results[1])
                return (table.unpack or unpack)(results)
            end
            module[originalKey] = original
            module[wrapperKey] = wrapper
            module[method] = wrapper
            return true
        end

        
        
        
        
        local function HookWardrobeEmoteListGetter(module, marker, oldMarker)
            local method = "GetEmoteListByUnLockProp"
            if type(module) ~= "table" or type(module[method]) ~= "function" then
                return false
            end
            local wrapperKey = marker .. "Wrapper"
            local originalKey = marker .. "Original"
            if module[wrapperKey] and module[method] == module[wrapperKey] then
                return true
            end
            local original = module[originalKey] or
                                 (oldMarker and module[oldMarker .. "Original"]) or
                                 module[method]
            local wrapper = function(...)
                local results = {original(...)}
                local list = results[1]
                if type(list) == "table" and IsEmoteFeatureEnabled() then
                    pcall(EnsureVIPEmoteInventoryInstances)
                    local seen = {}
                    for _, value in pairs(list) do
                        local valueID = tonumber(value)
                        if not valueID and type(value) == "table" then
                            valueID = tonumber(
                                          value.itemId or value.ItemID or
                                              value.ItemTableID or value.resID or
                                              value.res_id or
                                              (value.DefineID and
                                                  value.DefineID.TypeSpecificID))
                        end
                        if valueID then
                            local mapped = tonumber(R.insToRes[valueID])
                            seen[math.abs(mapped or valueID)] = true
                        end
                    end
                    for _, emoteID in ipairs(_G.VIPEmoteIDs or {}) do
                        emoteID = tonumber(emoteID)
                        if emoteID and emoteID > 0 and not seen[emoteID] then
                            list[#list + 1] = emoteID
                            seen[emoteID] = true
                        end
                    end
                end
                results[1] = list
                return (table.unpack or unpack)(results)
            end
            module[originalKey] = original
            module[wrapperKey] = wrapper
            module[method] = wrapper
            return true
        end

        local function HookEmoteUnlockChecks(module)
            if type(module) ~= "table" then return false end
            local installed = false
            for _, method in ipairs({
                "IsWeaponEmoteUnlocked",
                "IsWeaponEmoteUnlockedWithOutCheckWeapon", "IsWeaponEmoteOwned",
                "HasWeaponEmote", "CanUseWeaponEmote", "IsEmoteUnlocked",
                "HasEmote", "IsEmoteUnlock"
            }) do
                local originalKey = "__4REmoteOriginal_" .. method
                local wrapperKey = "__4REmoteWrapper_" .. method
                if module[wrapperKey] and module[method] == module[wrapperKey] then
                    installed = true
                elseif type(module[method]) == "function" then
                    local original = module[originalKey] or module[method]
                    local wrapper = function(...)
                        if IsEmoteFeatureEnabled() then
                            return true
                        end
                        return original(...)
                    end
                    module[originalKey] = original
                    module[wrapperKey] = wrapper
                    module[method] = wrapper
                    installed = true
                end
            end
            return installed
        end

        local function HookEmoteImageMap(module)
            if type(module) ~= "table" or type(module.GetEmoteImagePalthMap) ~=
                "function" then return false end
            if module.__4REmoteImageWrapper and module.GetEmoteImagePalthMap ==
                module.__4REmoteImageWrapper then return true end
            local original = module.__4REmoteImageOriginal or
                                 module.GetEmoteImagePalthMap
            local wrapper = function(self, ...)
                local result = original(self, ...)
                if IsEmoteFeatureEnabled() and self and
                    type(self.ItemIDToImagePathMap) == "table" then
                    pcall(function()
                        local UIUtil = require("client.common.ui_util")
                        for _, id in ipairs(_G.VIPEmoteIDs or {}) do
                            if self.ItemIDToImagePathMap[id] == nil then
                                self.ItemIDToImagePathMap[id] =
                                    UIUtil.GetItemSmallIcon(id) or ""
                            end
                        end
                    end)
                end
                return result
            end
            module.__4REmoteImageOriginal = original
            module.__4REmoteImageWrapper = wrapper
            module.GetEmoteImagePalthMap = wrapper
            return true
        end

        local function HookBattleExpressionList(module)
            if type(module) ~= "table" or type(module.SyncNewBattlePlayer) ~=
                "function" then return false end
            if module.__4RExpressionListV2Wrapper and module.SyncNewBattlePlayer ==
                module.__4RExpressionListV2Wrapper then return true end
            local original = module.__4RExpressionListV2Original or
                                 module.SyncNewBattlePlayer
            local wrapper = function(...)
                if IsEmoteFeatureEnabled() then
                    local args = {...}
                    local params = nil
                    for i = #args, 1, -1 do
                        if type(args[i]) == "table" then
                            params = args[i]
                            break
                        end
                    end
                    if params then
                        params.ExpressionItemList =
                            params.ExpressionItemList or {}
                        local seen = {}
                        for _, entry in pairs(params.ExpressionItemList) do
                            local id = type(entry) == "table" and
                                           tonumber(
                                               entry.ItemTableID or entry.resID or
                                                   entry.ResID) or
                                           tonumber(entry)
                            if id then
                                seen[id] = true
                            end
                        end
                        for _, id in ipairs(_G.VIPEmoteIDs or {}) do
                            id = tonumber(id)
                            if id and id > 0 and not seen[id] then
                                params.ExpressionItemList[#params.ExpressionItemList +
                                    1] = {ItemTableID = id, Count = 1}
                                seen[id] = true
                            end
                        end
                    end
                end
                return original(...)
            end
            module.__4RExpressionListV2Original = original
            module.__4RExpressionListV2Wrapper = wrapper
            module.SyncNewBattlePlayer = wrapper
            return true
        end

        
        
        
        local function HookInventoryMotionRequests()
            local okWRH, WRH = pcall(require,
                                     "client.network.Protocol.WardRobeHandler")
            if not okWRH or type(WRH) ~= "table" then return false end

            local emoteSet = {}
            for _, id in ipairs(_G.VIPEmoteIDs or {}) do
                id = tonumber(id)
                if id and id > 0 then emoteSet[id] = true end
            end

            local function GetMotionData()
                local dataMgr = rawget(_G, "DataMgr")
                if type(dataMgr) ~= "table" then return nil end
                dataMgr.MotionSlotList = dataMgr.MotionSlotList or {}
                return dataMgr
            end

            local function IsVIPEmoteInstance(value)
                local insID = tonumber(value)
                local resID = insID and tonumber(R.insToRes[insID])
                return resID ~= nil and emoteSet[resID] == true
            end

            local function IsVIPEmoteSlotValue(value)
                local number = tonumber(value)
                if not number then return false end
                local resID = tonumber(R.insToRes[number])
                if not resID and number < 0 then resID = -number end
                return resID ~= nil and emoteSet[resID] == true
            end

            local function NotifyMotionSlotsChanged()
                local eventSystem = rawget(_G, "EventSystem")
                if not eventSystem then
                    local okEvent, module = pcall(require,
                                                  "client.slua.event.EventSystem")
                    if okEvent then eventSystem = module end
                end
                local eventType = rawget(_G, "EVENTTYPE_MOTION")
                local eventID = rawget(_G, "EVENTID_MOTION_UPDATE_SLOT_LIST")
                if eventSystem and eventSystem.postEvent and eventType and
                    eventID then
                    pcall(function()
                        eventSystem:postEvent(eventType, eventID)
                    end)
                end
            end

            local installed = false

            if type(WRH.send_equip_motion_req) == "function" then
                local marker = "__4REquipMotionV2"
                if WRH[marker .. "Wrapper"] and WRH.send_equip_motion_req ==
                    WRH[marker .. "Wrapper"] then
                    installed = true
                else
                    local original = WRH[marker .. "Original"] or
                                         WRH.send_equip_motion_req
                    local wrapper = function(instid, dstSlot, ...)
                        local dataMgr = GetMotionData()
                        dstSlot = tonumber(dstSlot)
                        if IsEmoteFeatureEnabled() and dataMgr and dstSlot and
                            IsVIPEmoteInstance(instid) then
                            dataMgr.MotionSlotList[dstSlot] = tonumber(instid)
                            NotifyMotionSlotsChanged()
                            return true
                        end
                        return original(instid, dstSlot, ...)
                    end
                    WRH[marker .. "Original"] = original
                    WRH[marker .. "Wrapper"] = wrapper
                    WRH.send_equip_motion_req = wrapper
                    installed = true
                end
            end

            if type(WRH.send_exchange_motion_req) == "function" then
                local marker = "__4RExchangeMotionV2"
                if WRH[marker .. "Wrapper"] and WRH.send_exchange_motion_req ==
                    WRH[marker .. "Wrapper"] then
                    installed = true
                else
                    local original = WRH[marker .. "Original"] or
                                         WRH.send_exchange_motion_req
                    local wrapper = function(srcSlot, dstSlot, ...)
                        local dataMgr = GetMotionData()
                        srcSlot, dstSlot = tonumber(srcSlot), tonumber(dstSlot)
                        if IsEmoteFeatureEnabled() and dataMgr and srcSlot and
                            dstSlot then
                            local srcValue = dataMgr.MotionSlotList[srcSlot]
                            local dstValue = dataMgr.MotionSlotList[dstSlot]
                            if IsVIPEmoteSlotValue(srcValue) or
                                IsVIPEmoteSlotValue(dstValue) then
                                dataMgr.MotionSlotList[srcSlot] = dstValue or 0
                                dataMgr.MotionSlotList[dstSlot] = srcValue or 0
                                NotifyMotionSlotsChanged()
                                return true
                            end
                        end
                        return original(srcSlot, dstSlot, ...)
                    end
                    WRH[marker .. "Original"] = original
                    WRH[marker .. "Wrapper"] = wrapper
                    WRH.send_exchange_motion_req = wrapper
                    installed = true
                end
            end

            if type(WRH.send_unequip_motion_req) == "function" then
                local marker = "__4RUnequipMotionV2"
                if WRH[marker .. "Wrapper"] and WRH.send_unequip_motion_req ==
                    WRH[marker .. "Wrapper"] then
                    installed = true
                else
                    local original = WRH[marker .. "Original"] or
                                         WRH.send_unequip_motion_req
                    local wrapper = function(instid, slot, ...)
                        local dataMgr = GetMotionData()
                        slot = tonumber(slot)
                        if IsEmoteFeatureEnabled() and dataMgr and slot and
                            (IsVIPEmoteInstance(instid) or
                                IsVIPEmoteSlotValue(dataMgr.MotionSlotList[slot])) then
                            dataMgr.MotionSlotList[slot] = 0
                            NotifyMotionSlotsChanged()
                            return true
                        end
                        return original(instid, slot, ...)
                    end
                    WRH[marker .. "Original"] = original
                    WRH[marker .. "Wrapper"] = wrapper
                    WRH.send_unequip_motion_req = wrapper
                    installed = true
                end
            end

            return installed
        end

        _G.SetupLobbyInventoryEmoteHooks = function()
            local installed = false
            pcall(function()
                installed = RefreshLobbyMotionSlots() or installed
                installed = HookInventoryMotionRequests() or installed

                local okLPE, LPE = pcall(require,
                                         "client.slua.logic.wardrobe.LogicParticleEmote")
                if okLPE then
                    installed = HookWardrobeEmoteListGetter(LPE,
                                                            "__4RWardrobeEmoteV3",
                                                            "__4RWardrobeEmoteV2") or
                                    installed
                    installed = HookWardrobeEmoteListGetter(
                                    type(LPE) == "table" and LPE.__inner_impl or
                                        nil, "__4RWardrobeEmoteInnerV3",
                                    "__4RWardrobeEmoteInnerV2") or installed
                end

                local okEAS, EAS = pcall(require,
                                         "GameLua.Mod.SocialIsland.Client.Emote.EmoteActionSys")
                if okEAS then
                    installed = HookEmoteListGetter(EAS, "GetEmoteList",
                                                    "__4RLobbyEmoteV2") or
                                    installed
                    installed = HookEmoteListGetter(
                                    type(EAS) == "table" and EAS.__inner_impl or
                                        nil, "GetEmoteList",
                                    "__4RLobbyEmoteInnerV2") or installed
                end

                local okBattle, BattleHandler = pcall(require,
                                                      "GameLua.Mod.BaseMod.Client.BattleHandler")
                if okBattle then
                    installed = HookBattleExpressionList(BattleHandler) or
                                    installed
                    installed = HookBattleExpressionList(
                                    type(BattleHandler) == "table" and
                                        BattleHandler.__inner_impl or nil) or
                                    installed
                end

                local okUpgrade, upgrade = pcall(require,
                                                 "client.logic.ItemUpgrade.ItemUpgradeModule")
                if okUpgrade then
                    installed = HookEmoteUnlockChecks(upgrade) or installed
                    installed = HookEmoteUnlockChecks(
                                    type(upgrade) == "table" and
                                        upgrade.__inner_impl or nil) or
                                    installed
                end

                local okAction, action = pcall(require,
                                               "client.slua.umg.Wardrobe.subtab_action")
                if okAction then
                    installed = HookEmoteUnlockChecks(action) or installed
                    installed = HookEmoteUnlockChecks(
                                    type(action) == "table" and
                                        action.__inner_impl or nil) or installed
                end

                
                
                
                for name, module in pairs(package.loaded) do
                    if type(name) == "string" and
                        name:find("QuickExpression", 1, true) and
                        not name:find("Utils", 1, true) then
                        installed = HookEmoteImageMap(module) or installed
                        if type(module) == "table" then
                            installed =
                                HookEmoteImageMap(module.__inner_impl) or
                                    installed
                        end
                    end
                end
            end)
            return installed
        end

        _G.RefreshLobbyInventoryEmotes = function()
            return _G.SetupLobbyInventoryEmoteHooks()
        end

        _G.SetupLobbyInventoryEmoteHooks()

        
        if ExpressionUtil and type(ExpressionUtil.GetMotionDataList) ==
            "function" then
            if not _G.__EMOTE_ORIG_GET_MOTION then
                _G.__EMOTE_ORIG_GET_MOTION = ExpressionUtil.GetMotionDataList
            end
            ExpressionUtil.GetMotionDataList = function(...)
                local baseList = _G.__EMOTE_ORIG_GET_MOTION(...)
                return GetOptimizedLobbyEmoteList(baseList)
            end
            _G.__EMOTE_LOBBY_HOOKED = true

            if type(ExpressionUtil.OpenExpressionPopUI) == "function" then
                if not _G.__EMOTE_ORIG_OPEN_LOBBY then
                    _G.__EMOTE_ORIG_OPEN_LOBBY =
                        ExpressionUtil.OpenExpressionPopUI
                end
                ExpressionUtil.OpenExpressionPopUI =
                    function(actionID, ...)
                        local result = _G.__EMOTE_ORIG_OPEN_LOBBY(actionID, ...)
                        local refreshedLater = false
                        pcall(function()
                            if slua and slua.Timer and slua.Timer.Add then
                                slua.Timer.Add(0.15, function()
                                    RefreshLobbyEmotePanel()
                                end)
                                refreshedLater = true
                            end
                        end)
                        if not refreshedLater then
                            RefreshLobbyEmotePanel()
                        end
                        return result
                    end
                _G.__EMOTE_LOBBY_OPEN_HOOKED = true
            end
        end

        
        local CachedInGameEmotes = nil
        local LastBaseCount = -1
        local LastEmoteSwitchState = nil

        
        local function GetOptimizedEmoteList(baseList)
            local baseCount = baseList and #baseList or 0
            local isEmoteModEnabled = _G.VIPConfig.ModEmote == true

            
            if CachedInGameEmotes and LastBaseCount == baseCount and
                LastEmoteSwitchState == isEmoteModEnabled then
                return CachedInGameEmotes
            end

            local compact = {}
            local seen = {}

            
            if baseList then
                for _, data in pairs(baseList) do
                    if data and data.DefineID and data.DefineID.TypeSpecificID then
                        table.insert(compact, data)
                        seen[data.DefineID.TypeSpecificID] = true
                    end
                end
            end

            
            if isEmoteModEnabled then
                for _, nEmoteID in ipairs(EXTRA_EMOTES) do
                    if not seen[nEmoteID] then
                        table.insert(compact, {
                            DefineID = {TypeSpecificID = nEmoteID},
                            Name = tostring(nEmoteID)
                        })
                        seen[nEmoteID] = true
                    end
                end
            end

            CachedInGameEmotes = compact
            LastBaseCount = baseCount
            LastEmoteSwitchState = isEmoteModEnabled
            return CachedInGameEmotes
        end

        
        if QuickExpressionUtils and not _G.__EMOTE_INGAME_HOOKED then
            _G.__EMOTE_INGAME_HOOKED = true
            _G.__EMOTE_ORIG_GET_LIST =
                QuickExpressionUtils.GetShowExpressionList

            QuickExpressionUtils.GetShowExpressionList = function()
                local baseList, nWeaponShowEmoteID = _G.__EMOTE_ORIG_GET_LIST()
                return GetOptimizedEmoteList(baseList), nWeaponShowEmoteID
            end
        end

        
        if not _G.__EMOTE_MENU_EVENT_HOOKED and EventSystem and
            EventSystem.registEvent then
            _G.__EMOTE_MENU_EVENT_HOOKED = true
            EventSystem:registEvent(EVENTTYPE_INGAME,
                                    EVENTID_INGAME_QUICK_EXPRESSION_DECAL_CLICK,
                                    function()
                pcall(function()
                    
                    if not _G.VIPConfig.ModEmote then return end

                    local UIManager =
                        require("client.slua_ui_framework.manager")
                    if not UIManager or not UIManager.UI_Config_InGame then
                        return
                    end
                    local subPanel = UIManager.GetUI(
                                         UIManager.UI_Config_InGame
                                             .QuickExpressionDecalSubPanel)

                    
                    
                    
                    
                    local currentList = nil
                    pcall(function()
                        currentList = select(1,
                                             QuickExpressionUtils
                                                 .GetShowExpressionList())
                    end)
                    if currentList then CachedInGameEmotes = currentList end

                    if subPanel and subPanel.GetQuickExpressionDecalItemByIndex and
                        CachedInGameEmotes then
                        local showCount = 0
                        for _, data in ipairs(CachedInGameEmotes) do
                            local nEmoteID = data.DefineID and
                                                 data.DefineID.TypeSpecificID
                            if nEmoteID and nEmoteID > 0 then
                                showCount = showCount + 1
                                local item =
                                    subPanel:GetQuickExpressionDecalItemByIndex(
                                        showCount)
                                if item then
                                    
                                    if item.UIRoot.WidgetSwitcher_Effect then
                                        item.UIRoot.WidgetSwitcher_Effect:SetWidgetVisibility(
                                            UEnums.ESlateVisibility.Collapsed)
                                    end
                                    if item.UIRoot.Image_Weapon then
                                        item.UIRoot.Image_Weapon:SetWidgetVisibility(
                                            UEnums.ESlateVisibility.Collapsed)
                                    end

                                    item:Show()
                                    item:RefreshData(nEmoteID, -1)
                                end
                            end
                        end
                        if subPanel.HideRestBlocks then
                            subPanel:HideRestBlocks(showCount)
                        end
                        if subPanel.UIRoot then
                            subPanel.UIRoot.WrapBox_List:SetWidgetVisibility(
                                UEnums.ESlateVisibility.Visible)
                            subPanel.UIRoot.VerticalBox_Empty:SetWidgetVisibility(
                                UEnums.ESlateVisibility.Collapsed)
                        end
                    end
                end)
            end)
        end
    end)
    
    
    

    
    
    
    
    
    if false then

        
        local HALL_THEME_ID = 202408061 

        if not _G.LobbyThemeSystem then _G.LobbyThemeSystem = {} end

        
        local MY_VEHICLES = {
            1915021, 
            1915022, 
            1915026, 
            1908117, 
            1908118, 
            1908119 
        }

        local GARAGE_THEME_IDS = {[202408061] = true, [202408087] = true}

        
        
        if type(_G.LobbyThemeSystem.MY_VEHICLES) == "table" and
            #_G.LobbyThemeSystem.MY_VEHICLES > 0 then
            MY_VEHICLES = _G.LobbyThemeSystem.MY_VEHICLES
        end

        _G.HallThemeApplicationValue = HALL_THEME_ID
        _G.LobbyThemeSystem.MY_VEHICLES = MY_VEHICLES
        _G.ShowroomVehicleSlot = math.max(1, math.min(6, math.floor(
                                                          tonumber(
                                                              _G.VIPConfig
                                                                  .ShowroomVehicleSlot or
                                                                  _G.ShowroomVehicleSlot) or
                                                              1)))
        _G.VIPConfig.ShowroomVehicleSlot = _G.ShowroomVehicleSlot

        function _G.LobbyThemeSystem.SetVehicleSkin(position, skinID)
            position = math.floor(tonumber(position) or 0)
            skinID = math.floor(tonumber(skinID) or 0)
            if position < 1 or position > 6 or skinID <= 0 or
                not F.isVehicleRes(skinID) then return false end
            MY_VEHICLES[position] = skinID
            _G.LobbyThemeSystem.MY_VEHICLES = MY_VEHICLES
            if F.ensureSkinDownload then
                pcall(F.ensureSkinDownload, skinID)
            end
            if _G.LobbyThemeSystem.UpdateTheme then
                pcall(_G.LobbyThemeSystem.UpdateTheme)
            end
            return true
        end

        function _G.LobbyThemeSystem.GetVehicleSkin(position)
            position = math.floor(tonumber(position) or 0)
            return MY_VEHICLES[position]
        end

        local function isSuperCarEnabled()
            local value = _G.VIPConfig and _G.VIPConfig.SanhSieuXeVip
            return value == true or tonumber(value) == 1
        end

        function _G.LobbyThemeSystem.SetEnabled(enabled)
            enabled = enabled == true or tonumber(enabled) == 1
            _G.VIPConfig.SanhSieuXeVip = enabled
            
            
            if not enabled then
                _G.LobbyThemeSystem.IsRestoredToOriginal = false
            end
            if _G.LobbyThemeSystem.UpdateTheme then
                pcall(_G.LobbyThemeSystem.UpdateTheme)
            end
            return enabled
        end

        local function isCustomGarageTheme()
            
            if not isSuperCarEnabled() then return false end
            return GARAGE_THEME_IDS[_G.HallThemeApplicationValue] == true
        end

        local function buildVehicleList()
            local Result = {}
            for i = 1, #MY_VEHICLES do
                local id = MY_VEHICLES[i]
                if id and id > 0 and F.isVehicleRes(id) then
                    Result[i] = id
                end
            end
            return Result
        end

        function _G.LobbyThemeSystem.BuildVehicleInfoList()
            local Result = {}
            for i = 1, #MY_VEHICLES do
                local id = MY_VEHICLES[i]
                if id and id > 0 and F.isVehicleRes(id) then
                    Result[i] = {
                        ItemID = id,
                        Source = EWardrobeDataSource and
                            EWardrobeDataSource.Wardrobe or 0
                    }
                end
            end
            return Result
        end

        function _G.LobbyThemeSystem.TryInitHooks()
            local ok, ModuleManager = pcall(require,
                                            "client.module_framework.ModuleManager")
            if not ok or not ModuleManager or not ModuleManager.GetModule then
                return false
            end
            if not ModuleManager.LobbyModuleConfig then return false end

            local MyThemeVehicleManager =
                ModuleManager.GetModule(ModuleManager.LobbyModuleConfig
                                            .ThemeVehicleManager)
            local MyGarageThemeSystem = ModuleManager.GetModule(
                                            ModuleManager.LobbyModuleConfig
                                                .GarageThemeSystem)

            if not MyThemeVehicleManager or not MyGarageThemeSystem then
                return false
            end

            _G.LobbyThemeSystem.ModuleManager = ModuleManager
            _G.LobbyThemeSystem.MyThemeVehicleManager = MyThemeVehicleManager
            _G.LobbyThemeSystem.MyGarageThemeSystem = MyGarageThemeSystem

            
            if MyGarageThemeSystem.GetSelfGarageVehicleIDs and
                not _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs then
                _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs =
                    MyGarageThemeSystem.GetSelfGarageVehicleIDs
            end
            if MyGarageThemeSystem.GetSelfGarageVehicleIDs then
                MyGarageThemeSystem.GetSelfGarageVehicleIDs = function(self)
                    if isCustomGarageTheme() then
                        return buildVehicleList()
                    end
                    if _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs then
                        return _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs(
                                   self)
                    end
                    return {}
                end
            end

            
            if MyGarageThemeSystem.GetSelfGarageVehicleAndSource and
                not _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource then
                _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource =
                    MyGarageThemeSystem.GetSelfGarageVehicleAndSource
            end
            if MyGarageThemeSystem.GetSelfGarageVehicleAndSource then
                MyGarageThemeSystem.GetSelfGarageVehicleAndSource = function(
                    self)
                    if isCustomGarageTheme() then
                        return _G.LobbyThemeSystem.BuildVehicleInfoList()
                    end
                    if _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource then
                        return _G.LobbyThemeSystem
                                   .OriginalGetSelfVehicleAndSource(self)
                    end
                    return {}
                end
            end

            
            if MyThemeVehicleManager.ShowThemeVehicle and
                not _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                _G.LobbyThemeSystem.OriginalShowThemeVehicle =
                    MyThemeVehicleManager.ShowThemeVehicle
            end
            if MyThemeVehicleManager.ShowThemeVehicle then
                MyThemeVehicleManager.ShowThemeVehicle = function(self)
                    if not self then return end
                    if isCustomGarageTheme() then
                        self:_ShowSelfVehicle()
                    elseif _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                        _G.LobbyThemeSystem.OriginalShowThemeVehicle(self)
                    end
                end
            end

            
            if MyThemeVehicleManager._ShowSelfVehicle and
                not _G.LobbyThemeSystem.Original_ShowSelfVehicle then
                _G.LobbyThemeSystem.Original_ShowSelfVehicle =
                    MyThemeVehicleManager._ShowSelfVehicle
            end
            if MyThemeVehicleManager._ShowSelfVehicle then
                MyThemeVehicleManager._ShowSelfVehicle = function(self)
                    if not self then return end

                    if not isCustomGarageTheme() then
                        if _G.LobbyThemeSystem.Original_ShowSelfVehicle then
                            return _G.LobbyThemeSystem.Original_ShowSelfVehicle(
                                       self)
                        end
                        return
                    end

                    local VehicleRefitHandler = require(
                                                    "client.network.Protocol.VehicleRefitHandler")
                    if not VehicleRefitHandler then return end

                    local uid = _ENV.DataMgr and _ENV.DataMgr.roleData and
                                    _ENV.DataMgr.roleData.uid or 0
                    local LogicVehicleAccessory =
                        ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig
                                .LogicVehicleAccessory)
                    local LogicVehicleExtendedFeature =
                        ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig
                                .LogicVehicleExtendedFeature)

                    for Position = 1, #MY_VEHICLES do
                        local ItemID = MY_VEHICLES[Position]
                        if ItemID and ItemID > 0 and F.isVehicleRes(ItemID) then
                            local StyleList =
                                VehicleRefitHandler.GetCarStyleList(ItemID, nil,
                                                                    nil) or {}
                            local accessoryList =
                                LogicVehicleAccessory and
                                    LogicVehicleAccessory:GetEquipedAccessoryList(
                                        ItemID) or {}
                            local ChassisLight =
                                LogicVehicleExtendedFeature and
                                    LogicVehicleExtendedFeature:GetEquipedChassisLightData(
                                        ItemID) or nil
                            local MultiSlotParts =
                                LogicVehicleExtendedFeature and
                                    LogicVehicleExtendedFeature:GetEquipedMultiSlotParts(
                                        ItemID) or nil

                            self:_TryCreateVehicleModel(ItemID, StyleList, true,
                                                        Position, accessoryList,
                                                        ChassisLight, uid,
                                                        MultiSlotParts)
                        end
                    end

                    if self.OnVehicleChange then
                        self:OnVehicleChange()
                    end
                end
            end

            
            _G.LobbyThemeSystem.UpdateTheme = function()
                local lobbyThemeManager = nil
                pcall(function()
                    lobbyThemeManager = ModuleManager.GetModule(
                                            ModuleManager.LobbyModuleConfig
                                                .LobbyThemeManager)
                end)

                
                if not isSuperCarEnabled() then
                    
                    if not _G.LobbyThemeSystem.IsRestoredToOriginal then

                        
                        local mgr = _G.LobbyThemeSystem.MyThemeVehicleManager
                        if mgr and _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                            _G.LobbyThemeSystem.OriginalShowThemeVehicle(mgr)
                        end

                        
                        if lobbyThemeManager then
                            pcall(function()
                                local realResID = 0
                                local HT = require(
                                               "client.logic.lobby.hall_theme_utils")
                                local insID =
                                    HT.GetThemeInstId and HT.GetThemeInstId()
                                if insID and tonumber(insID) > 0 then
                                    local wd = require(
                                                   "client.slua.logic.wardrobe.wardrobe_data")
                                    local d =
                                        wd.GetHallDepotItemDataByInsID and
                                            wd:GetHallDepotItemDataByInsID(insID)
                                    if d and d.resID then
                                        realResID = tonumber(d.resID)
                                    end
                                end
                                
                                lobbyThemeManager:ShowThemeByItemID(realResID or
                                                                        0)
                            end)
                        end

                        
                        _G.LobbyThemeSystem.IsRestoredToOriginal = true
                    end
                    return
                end

                
                _G.LobbyThemeSystem.IsRestoredToOriginal = false

                if not _G.HallThemeApplicationValue or
                    _G.HallThemeApplicationValue == 0 then return end

                if not lobbyThemeManager then return end

                
                local currentThemeID = lobbyThemeManager:GetDisplayItemID()
                if currentThemeID ~= _G.HallThemeApplicationValue then
                    lobbyThemeManager:ShowThemeByItemID(
                        _G.HallThemeApplicationValue)
                end

                
                local mgr = _G.LobbyThemeSystem.MyThemeVehicleManager
                if not mgr then return end

                if isCustomGarageTheme() then
                    mgr:ShowThemeVehicle()
                elseif _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                    _G.LobbyThemeSystem.OriginalShowThemeVehicle(mgr)
                end
            end

            _G.LobbyThemeSystem.__inited = true
            return true
        end

        local function startTimers()
            if _G.LobbyThemeSystem.TimersStarted then return end

            local ok, TXtime_ticker = pcall(require, "common.time_ticker")
            if not ok or not TXtime_ticker then return end

            local delays = {0.5, 1, 2, 5, 10}
            for i = 1, #delays do
                TXtime_ticker.AddTimerOnce(delays[i], function()
                    if not _G.LobbyThemeSystem.__inited then
                        if _G.LobbyThemeSystem.TryInitHooks() and
                            _G.LobbyThemeSystem.UpdateTheme then
                            _G.LobbyThemeSystem.UpdateTheme()
                        end
                    elseif _G.LobbyThemeSystem.UpdateTheme then
                        _G.LobbyThemeSystem.UpdateTheme()
                    end
                end)
            end

            TXtime_ticker.AddTimerLoop(0, function()
                
                if not isSuperCarEnabled() then return end

                if not _G.LobbyThemeSystem.__inited then
                    _G.LobbyThemeSystem.TryInitHooks()
                end

                local GameStatus = _ENV.GameStatus
                if not GameStatus or not GameStatus.GetGameStatus then
                    return
                end

                local status = GameStatus.GetGameStatus()
                if status == GameStatus.Lobby then
                    if _G.LobbyThemeSystem and _G.LobbyThemeSystem.UpdateTheme then
                        _G.LobbyThemeSystem.UpdateTheme()
                    end
                end
            end, -1, 0.5)

            _G.LobbyThemeSystem.TimersStarted = true
        end

        
        
        
    end

    
    
    
