        local function isValid(object)
            if not object then return false end
            local ok, value = pcall(slua.isValid, object)
            return ok and value == true
        end

        local visibilityCache = setmetatable({}, {__mode = "k"})
        local function setVisible(object, visible)
            if not isValid(object) then return end
            if visibilityCache[object] == visible then return end
            pcall(function()
                object:SetWidgetVisibility(visible and
                                               UEnums.ESlateVisibility
                                                   .SelfHitTestInvisible or
                                               UEnums.ESlateVisibility.Collapsed)
                visibilityCache[object] = visible
            end)
        end

        local function removeObject(object)
            if not isValid(object) then return end
            pcall(function() object:RemoveFromParent() end)
            pcall(function() object:ConditionalBeginDestroy() end)
        end

        local destroyEntry
        local function getCanvas()
            
            
            if isValid(V2.canvas) then return V2.canvas end
            local live = LootEspState.ResolveGameplayCanvas and
                             LootEspState.ResolveGameplayCanvas(false) or nil
            if V2.canvas ~= nil then
                
                
                V2.widgets = {}
                V2.players = {}
                V2.vis = {}
                V2.boneSockets = {}
                V2.playerCount = 0
            end
            local canvas = live
            V2.canvas = canvas
            V2.canvasSignature = canvas and tostring(canvas) or nil
            return canvas
        end

        local function newBorder(color, z)
            local canvas = getCanvas()
            if not canvas then return nil end
            local widget = NewRuntimeWidget("/Script/UMG.Border", canvas)
            if not isValid(widget) then return nil end
            pcall(function()
                widget:SetBrushColor(color)
                widget:SetRenderTransformPivot(FVector2D(0, 0.5))
                setVisible(widget, false)
            end)
            local slot = nil
            pcall(function() slot = canvas:AddChildToCanvas(widget) end)
            if not slot then
                removeObject(widget)
                return nil
            end
            pcall(function()
                slot:SetAutoSize(false)
                slot:SetZOrder(z or 990)
            end)
            return {widget = widget, slot = slot}
        end

        local function newImage(z)
            local canvas = getCanvas()
            if not canvas then return nil end
            local widget = NewRuntimeWidget("/Script/UMG.Image", canvas)
            if not isValid(widget) then return nil end
            pcall(function()
                if widget.SetRenderOpacity then
                    widget:SetRenderOpacity(0.82)
                end
                setVisible(widget, false)
            end)
            local slot = nil
            pcall(function() slot = canvas:AddChildToCanvas(widget) end)
            if not slot then
                removeObject(widget)
                return nil
            end
            pcall(function()
                slot:SetAutoSize(false)
                slot:SetZOrder(z or 998)
            end)
            return {
                widget = widget,
                slot = slot,
                weaponID = nil,
                loaded = false
            }
        end

        local function applyFont(textWidget, size)
            if not isValid(textWidget) then return end
            pcall(function()
                local font = textWidget.Font
                if font then
                    font.Size = math.floor(size)
                    if font.OutlineSettings then
                        font.OutlineSettings.OutlineSize = 1
                        font.OutlineSettings.OutlineColor = FLinearColor(0, 0,
                                                                         0, 1)
                    end
                    if textWidget.SetFont then
                        textWidget:SetFont(font)
                    else
                        textWidget.Font = font
                    end
                end
                if textWidget.SetFontSize then
                    textWidget:SetFontSize(math.floor(size))
                end
            end)
        end

        local function newText(color)
            local canvas = getCanvas()
            if not canvas then return nil end
            local widget = NewRuntimeWidget("/Script/UMG.TextBlock", canvas)
            if not isValid(widget) then return nil end
            pcall(function()
                widget:SetText("")
                widget:SetJustification(1)
                if widget.SetHorizontalAlignment then
                    widget:SetHorizontalAlignment(1)
                end
                if widget.SetVerticalAlignment then
                    widget:SetVerticalAlignment(1)
                end
                if widget.SetAutoWrapText then
                    widget:SetAutoWrapText(false)
                end
                widget:SetColorAndOpacity(
                    FSlateColor and FSlateColor(color) or color)
                applyFont(widget, V2.fontSize)
                setVisible(widget, false)
            end)
            local slot = nil
            pcall(function() slot = canvas:AddChildToCanvas(widget) end)
            if not slot then
                removeObject(widget)
                return nil
            end
            pcall(function()
                slot:SetAutoSize(true)
                slot:SetZOrder(1000)
                slot:SetAlignment(FVector2D(0.5, 0.5))
            end)
            return {widget = widget, slot = slot, value = nil}
        end

        destroyEntry = function(entry)
            if not entry then return end
            if entry.line then removeObject(entry.line.widget) end
            for _, part in pairs(entry.box or {}) do
                removeObject(part.widget)
            end
            for _, part in ipairs(entry.skeleton or {}) do
                removeObject(part.widget)
            end
            if entry.hpBg then removeObject(entry.hpBg.widget) end
            if entry.hpFill then removeObject(entry.hpFill.widget) end
            if entry.nameBg then removeObject(entry.nameBg.widget) end
            if entry.weaponIcon then
                removeObject(entry.weaponIcon.widget)
            end
            for _, part in pairs(entry.text or {}) do
                removeObject(part.widget)
            end
        end

        local function cleanup()
            for key, entry in pairs(V2.widgets) do
                destroyEntry(entry)
                V2.widgets[key] = nil
            end
            V2.players = {}
            V2.vis = {}
            V2.boneSockets = {}
            V2.canvas = nil
            V2.canvasSignature = nil
            V2.playerCount = 0
        end

        local function hideEntry(entry)
