            if entry.line then setVisible(entry.line.widget, false) end
            for _, part in pairs(entry.box or {}) do
                setVisible(part.widget, false)
            end
            for _, part in ipairs(entry.skeleton or {}) do
                setVisible(part.widget, false)
            end
            if entry.hpBg then setVisible(entry.hpBg.widget, false) end
            if entry.hpFill then
                setVisible(entry.hpFill.widget, false)
            end
            if entry.nameBg then
                setVisible(entry.nameBg.widget, false)
            end
            if entry.weaponIcon then
                setVisible(entry.weaponIcon.widget, false)
            end
            for _, part in pairs(entry.text or {}) do
                setVisible(part.widget, false)
            end
        end

        local function getKey(player)
            if player.PlayerKey ~= nil then
