        local function getEntry(key)
            local entry = V2.widgets[key]
            if entry then return entry end
            entry = {box = {}, skeleton = {}, text = {}}
            entry.line = newBorder(C_GREEN, 990)
            local names = {
                "tlh", "tlv", "trh", "trv", "blh", "blv", "brh", "brv"
            }
            for _, name in ipairs(names) do
                entry.box[name] = newBorder(C_GREEN, 992)
            end
            
            entry.hpBg = nil
            entry.hpFill = nil
            
            
            entry.nameBg = nil
            entry.weaponIcon = newImage(998)
            entry.text.weapon = newText(C_WHITE)
            entry.text.name = newText(C_YELLOW)
            entry.text.distance = newText(C_WHITE)
            entry.text.status = newText(C_RED)
            V2.widgets[key] = entry
            return entry
        end

        local function setColor(part, color)
            if part and isValid(part.widget) then
                if part.color == color then return end
                pcall(function()
                    part.widget:SetBrushColor(color)
                    part.color = color
                end)
            end
        end

        local function changed(a, b)
            return a == nil or math.abs(a - b) >= 0.25
        end

        local function drawLine(part, x1, y1, x2, y2, thickness, color)
            if not part or not part.slot or not isValid(part.widget) then
                return
            end
            local dx, dy = x2 - x1, y2 - y1
            local length = math.sqrt(dx * dx + dy * dy)
            if length < 1 then
                setVisible(part.widget, false)
                return
            end
            setColor(part, color)
            pcall(function()
                local y = y1 - thickness * 0.5
                local angle = math.deg(math.atan(dy, dx))
                if changed(part.x, x1) or changed(part.y, y) then
                    part.slot:SetPosition(FVector2D(x1, y))
                    part.x, part.y = x1, y
                end
                if changed(part.w, length) or changed(part.h, thickness) then
                    part.slot:SetSize(FVector2D(length, thickness))
                    part.w, part.h = length, thickness
                end
                if changed(part.angle, angle) then
                    part.widget:SetRenderAngle(angle)
                    part.angle = angle
                end
                setVisible(part.widget, true)
            end)
        end

        local function drawRect(part, x, y, width, height, color)
            if not part or not part.slot or not isValid(part.widget) then
                return
            end
            if width < 1 or height < 1 then
                setVisible(part.widget, false)
                return
            end
            setColor(part, color)
            pcall(function()
                if changed(part.x, x) or changed(part.y, y) then
                    part.slot:SetPosition(FVector2D(x, y))
                    part.x, part.y = x, y
                end
                if changed(part.w, width) or changed(part.h, height) then
                    part.slot:SetSize(FVector2D(width, height))
                    part.w, part.h = width, height
                end
                if part.angle ~= 0 then
                    part.widget:SetRenderAngle(0)
                    part.angle = 0
                end
                setVisible(part.widget, true)
            end)
        end

        local function drawCornerBox(parts, left, top, width, height, color)
            local thickness = 1.5
            local corner = math.max(7, math.min(width, height) * 0.25)
            drawRect(parts.tlh, left, top, corner, thickness, color)
            drawRect(parts.tlv, left, top, thickness, corner, color)
            drawRect(parts.trh, left + width - corner, top, corner, thickness,
                     color)
            drawRect(parts.trv, left + width - thickness, top, thickness,
                     corner, color)
            drawRect(parts.blh, left, top + height - thickness, corner,
                     thickness, color)
            drawRect(parts.blv, left, top + height - corner, thickness, corner,
                     color)
            drawRect(parts.brh, left + width - corner, top + height - thickness,
                     corner, thickness, color)
            drawRect(parts.brv, left + width - thickness, top + height - corner,
                     thickness, corner, color)
        end

        local function hideBox(parts)
            for _, part in pairs(parts or {}) do
                setVisible(part.widget, false)
            end
        end

        local function setText(part, value, x, y, color, updateValue)
            if not part or not part.slot or not isValid(part.widget) then
                return
            end
            pcall(function()
                if updateValue and part.value ~= value then
                    part.widget:SetText(value)
                    part.value = value
                end
                if color then
                    part.widget:SetColorAndOpacity(FSlateColor and
                                                       FSlateColor(color) or
                                                       color)
                end
                part.slot:SetPosition(FVector2D(x, y))
                part.slot:SetAlignment(FVector2D(0.5, 0.5))
                setVisible(part.widget, value ~= nil and value ~= "")
            end)
        end

        local function setTextSize(part, size)
            if not part or not isValid(part.widget) then return end
            size = math.max(8, math.floor((tonumber(size) or V2.fontSize) +
                                              0.5))
            if part.fontSize == size then return end
            applyFont(part.widget, size)
            part.fontSize = size
        end

        local function updateTransform(controller, now)
            if now - V2.lastTransform < 0.50 and isValid(V2.canvas) then
                return
            end
            local canvas = getCanvas()
            if not canvas then return end
            V2.lastTransform = now
            pcall(function()
                local size = FVector2D(0, 0)
                controller:GetViewportSize(size)
                if size.X > 200 then V2.viewportW = size.X end
                if size.Y > 100 then V2.viewportH = size.Y end
            end)
            pcall(function()
                local size = UIUtil and UIUtil.GetViewportSize and
                                 UIUtil.GetViewportSize() or nil
                if not size or not size.X or size.X <= 200 then
                    size = FVector2D(0, 0)
                    controller:GetViewportSize(size)
                end
                if size and size.X and size.X > 200 then
                    V2.snapViewportW = size.X
                end
            end)
            pcall(function()
                local geometry = canvas:GetCachedGeometry()
                local p0, p1 = nil, nil
                if UIUtil and
                    type(UIUtil.ViewportPixelToWidgetLocal) == "function" then
                    p0 = UIUtil.ViewportPixelToWidgetLocal(FVector2D(0, 0),
                                                           canvas)
                    p1 = UIUtil.ViewportPixelToWidgetLocal(
                             FVector2D(100, 100), canvas)
                end
                if not (p0 and p1) then
                    p0 = SlateBP.AbsoluteToLocal(geometry, FVector2D(0, 0))
                    p1 = SlateBP.AbsoluteToLocal(geometry,
                                                  FVector2D(100, 100))
                end
                if p0 and p1 then
                    V2.scaleX = (p1.X - p0.X) / 100
                    V2.scaleY = (p1.Y - p0.Y) / 100
                    V2.offX = p0.X
                    V2.offY = p0.Y
                end
            end)
            V2.canvasW = V2.viewportW * V2.scaleX
            V2.canvasH = V2.viewportH * V2.scaleY
            local minSide = math.min(V2.viewportW, V2.viewportH)
            local maxSide = math.max(V2.viewportW, V2.viewportH)
            local tablet = minSide >= 1000 and maxSide / minSide < 2.0
            local nextSize = tablet and 16 or 13
            if nextSize ~= V2.fontSize then
                V2.fontSize = nextSize
                for _, entry in pairs(V2.widgets) do
                    for _, part in pairs(entry.text or {}) do
                        applyFont(part.widget, nextSize)
                    end
                end
            end
        end

        local function screenToCanvas(point)
            if not point then return nil end
            
            
            
            return {
                X = point.X * V2.scaleX + V2.offX,
                Y = point.Y * V2.scaleY + V2.offY
            }
        end

        local function project(controller, worldLocation)
            if not worldLocation then return nil, nil end
            local point = FVector2D(0, 0)
            local success = false
            pcall(function()
                local result = controller:ProjectWorldLocationToScreen(
                                   worldLocation, point, true)
                success = result == true or result == 1 or point.X ~= 0 or
                              point.Y ~= 0
            end)
            if not success then return nil, nil end
            return screenToCanvas(point), point
        end

        local function getBone(player, name, key)
            local result = nil
            pcall(function()
                local mesh = player.Mesh
                if not isValid(mesh) and player.getAvatarComponent2 then
                    mesh = player:getAvatarComponent2()
                end
                if not isValid(mesh) or not mesh.GetSocketLocation then
                    return
                end
                key = key or tostring(player)
                local cache = V2.boneSockets[key]
                if not cache then
                    cache = {}
                    V2.boneSockets[key] = cache
                end
                local cachedSocket = cache[name]
                if cachedSocket then
                    local point = mesh:GetSocketLocation(cachedSocket)
                    if point and
                        (point.X ~= 0 or point.Y ~= 0 or point.Z ~= 0) then
                        result = point
                        return
                    end
                    cache[name] = nil
                end
                for _, socket in ipairs(BONE_NAMES[name] or {name}) do
                    local point = mesh:GetSocketLocation(socket)
                    if point and (point.X ~= 0 or point.Y ~= 0 or point.Z ~= 0) then
                        result = point
                        cache[name] = socket
                        break
                    end
                end
            end)
            return result
        end

        local function getVisible(controller, player, key, now)
            local cached = V2.vis[key]
            if cached and now - cached.time < 0.25 then
                return cached.value
            end
            local visible = false
            pcall(function()
                if controller.LineOfSightTo then
                    visible = controller:LineOfSightTo(player) == true
                    if not visible then
                        local manager = controller.PlayerCameraManager
                        if isValid(manager) and manager.GetCameraLocation then
                            local cameraLocation = manager:GetCameraLocation()
                            if cameraLocation then
                                visible = controller:LineOfSightTo(
                                              player, cameraLocation, false) ==
                                              true or
                                              controller:LineOfSightTo(
                                                  player, cameraLocation, true) ==
                                                  true
                            end
                        end
                    end
                end
            end)
            
            
            
            V2.vis[key] = {time = now, value = visible}
            return visible
        end

        local function teamColor(team)
            local teamNumber = math.floor(tonumber(team) or 1)
            if V2.teamColors[teamNumber] then
                return V2.teamColors[teamNumber]
            end
            local colors = {
                {1, 0.20, 0.20}, {0.25, 0.65, 1}, {1, 0.65, 0.15},
                {0.85, 0.25, 1}, {0.15, 0.85, 1}, {1, 0.35, 0.65}
            }
            local index = (teamNumber - 1) % #colors + 1
            local value = colors[index]
            local color = FLinearColor(value[1] * 0.72, value[2] * 0.72,
                                       value[3] * 0.72, 0.46)
            V2.teamColors[teamNumber] = color
            return color
        end

        local function isBot(player)
            if _G.BunnyIsBot(player) then return true end
            local bot = player.bIsAI == true or player.IsAI == true or
                            player.bEnsure == true
            pcall(function()
                if player.IsBot and player:IsBot() then
                    bot = true
                end
                local ps = player.PlayerState
                if isValid(ps) and
                    (ps.bIsABot == true or ps.bIsBot == true or
                        (ps.IsBot and ps:IsBot())) then
                    bot = true
                end
            end)
            return bot
        end

        local function playerName(player)
            if isBot(player) then return ("Bot") end
            local name = nil
            pcall(function()
                if player.GetPlayerNameSafety then
                    name = player:GetPlayerNameSafety()
                end
                local ps = player.PlayerState
                if (not name or tostring(name) == "") and isValid(ps) and
                    ps.GetPlayerName then
                    name = ps:GetPlayerName()
                end
                if not name or tostring(name) == "" then
                    name = player.PlayerName
                end
                if (not name or tostring(name) == "") and player.GetPlayerName then
                    name = player:GetPlayerName()
                end
            end)
            name = tostring(name or ("Player"))
            if name == "" or name == "ModelTarget" then return ("Bot") end
            return name
        end

        local function weaponInfo(player)
            local info = {
                weapon = nil,
                id = 0,
                name = "Fist",
                iconPath = nil,
                iconTexture = nil
            }
            pcall(function()
                local weapon = player.CurrentWeapon
                if not isValid(weapon) and player.GetCurrentWeapon then
                    weapon = player:GetCurrentWeapon()
                end
                if not isValid(weapon) and player.GetCurrentShootWeapon then
                    weapon = player:GetCurrentShootWeapon()
                end
                if not isValid(weapon) and player.WeaponManagerComponent then
                    weapon = player.WeaponManagerComponent
                                 .CurrentWeaponReplicated
                end
                if not isValid(weapon) and player.GetWeaponManager then
                    local manager = player:GetWeaponManager()
                    if isValid(manager) and manager.GetCurrentWeapon then
                        weapon = manager:GetCurrentWeapon()
                    end
                end
                if not isValid(weapon) then return end
                info.weapon = weapon
                if weapon.GetWeaponID then
                    info.id = tonumber(weapon:GetWeaponID()) or 0
                end
                if info.id <= 0 and weapon.WeaponID then
                    info.id = tonumber(weapon.WeaponID) or 0
                end
                if info.id <= 0 and weapon.GetItemDefineID then
                    local define = weapon:GetItemDefineID()
                    if define then
                        info.id = tonumber(define.TypeSpecificID) or 0
                    end
                end
                if weapon.GetWeaponName then
                    local value = weapon:GetWeaponName()
                    if value and tostring(value) ~= "" then
                        info.name = tostring(value)
                    end
                end
                if weapon.GetWeaponIconPath then
                    info.iconPath = weapon:GetWeaponIconPath()
                end
                if weapon.GetWeaponIcon then
                    info.iconTexture = weapon:GetWeaponIcon()
                end
            end)
            if info.id > 0 and (not info.iconPath or info.iconPath == "") then
                pcall(function()
                    if CDataTable and CDataTable.GetTableData then
                        local row = CDataTable.GetTableData("Item", info.id)
                        if row then
                            info.iconPath =
                                row.KillWhiteIcon or row.SmallIcon or
                                    row.BigIcon
                        end
                    end
                end)
            end
            return info
        end

        local function applyWeaponIcon(part, info)
            if not part or not isValid(part.widget) or not info or info.id <= 0 then
                return false
            end
            if part.weaponID == info.id then
                return part.loaded == true
            end
            part.weaponID = info.id
            part.loaded = false
            pcall(function()
                if isValid(info.iconTexture) and part.widget.SetBrushFromTexture then
                    part.widget:SetBrushFromTexture(info.iconTexture, true)
                    part.loaded = true
                    return
                end
                if info.iconPath and tostring(info.iconPath) ~= "" then
                    if part.widget.SetBrushResourceFromPathSync then
                        part.widget:SetBrushResourceFromPathSync(tostring(
                                                                     info.iconPath),
                                                                 true)
                        part.loaded = true
                        return
                    end
                    local texture = import(tostring(info.iconPath))
                    if isValid(texture) and part.widget.SetBrushFromTexture then
                        part.widget:SetBrushFromTexture(texture, true)
                        part.loaded = true
                    end
                end
            end)
            return part.loaded == true
        end

        local function playerStatus(player)
            if tonumber(player.HealthStatus) == 1 then
                return ("Knock"), C_WHITE
            end
            local function activeFlag(value)
                if value == true then return true end
                local valueType = type(value)
                if valueType == "number" then return value == 1 end
                if valueType == "string" then
                    return value == "1" or string.lower(value) == "true"
                end
                return false
            end
            local aiming = activeFlag(player.bIsGunADS) or
                               activeFlag(player.bIsWeaponAiming) or
                               activeFlag(player.bIsAiming)
            if not aiming then
                pcall(function()
                    for _, methodName in ipairs({
                        "IsGunADS", "IsAiming", "IsWeaponAiming",
                        "GetIsWeaponAiming"
                    }) do
                        local method = player[methodName]
                        if type(method) == "function" and
                            activeFlag(method(player)) then
                            aiming = true
                            break
                        end
                    end
                end)
            end
            if not aiming then
                pcall(function()
                    local weapon = player.CurrentWeapon
                    if not isValid(weapon) and player.GetCurrentWeapon then
                        weapon = player:GetCurrentWeapon()
                    end
                    if not isValid(weapon) and player.GetCurrentShootWeapon then
                        weapon = player:GetCurrentShootWeapon()
                    end
                    if isValid(weapon) then
                        aiming = activeFlag(weapon.bIsGunADS) or
                                     activeFlag(weapon.bIsADS) or
                                     activeFlag(weapon.bIsAiming) or
                                     activeFlag(weapon.bIsWeaponAiming)
                    end
                end)
            end
            if aiming then
                return ("Aiming"), C_RED
            end
            return "", C_WHITE
        end

        local function worldOffset(actorLocation, worldLocation, extraZ)
            if not actorLocation or not worldLocation then
                return {X = 0, Y = 0, Z = extraZ or 0}
            end
            return {
                X = worldLocation.X - actorLocation.X,
                Y = worldLocation.Y - actorLocation.Y,
                Z = worldLocation.Z - actorLocation.Z + (extraZ or 0)
            }
        end

        local function debugText(controller, player, text, offset, color, scale)
            if not text or text == "" then return end
            local hud = controller and controller.MyHUD
            if not isValid(hud) or type(hud.AddDebugText) ~= "function" then
                return
            end
            pcall(function()
                hud:AddDebugText(text, player, 0.20, offset, offset, color,
                                 true, false, true, nil, scale, true)
            end)
        end

        local function resolveTeamID(player)
            if not isValid(player) then return nil end
            local team = nil
            pcall(function() team = tonumber(player.TeamID) end)
            if team == nil then
                pcall(function()
                    if type(player.GetTeamID) == "function" then
                        team = tonumber(player:GetTeamID())
                    end
                end)
            end
            if team == nil then
                pcall(function()
                    local state = type(player.GetPlayerStateSafety) ==
                                      "function" and
                                      player:GetPlayerStateSafety() or
                                      player.PlayerState
                    if isValid(state) then team = tonumber(state.TeamID) end
                end)
            end
            if team == nil then
                pcall(function()
                    if Game and type(Game.GetTeamID) == "function" then
                        team = tonumber(Game:GetTeamID(player))
                    end
                end)
            end
            return team
        end

        local function updatePlayerList(localPlayer, now)
            if now - V2.lastScan < 0.20 then return end
            V2.lastScan = now
            local all = {}
            pcall(function()
                if GameplayData.GetAllPlayerCharacters then
                    all = GameplayData.GetAllPlayerCharacters() or {}
                elseif GameplayData.GameCharacters then
                    for _, player in pairs(GameplayData.GameCharacters) do
                        all[#all + 1] = player
                    end
                end
            end)
            local team = resolveTeamID(localPlayer)
            local nextPlayers = {}
            for _, player in pairs(all) do
                if isValid(player) and player ~= localPlayer then
                    local enemyTeam = resolveTeamID(player)
                    local alive = tonumber(player.HealthStatus) ~= 2
                    local ignoredBot = _G.VIPConfig.IgnoreBots == true and
                                           _G.BunnyIsBot(player)
                    local sameTeam = team ~= nil and enemyTeam ~= nil and
                                         enemyTeam == team
                    if alive and not sameTeam and not ignoredBot then
                        local distance = math.huge
                        pcall(function()
                            distance = localPlayer:GetDistanceTo(player) / 100
                        end)
                        if distance <= MAX_DISTANCE then
                            nextPlayers[#nextPlayers + 1] = {
                                actor = player,
                                key = getKey(player),
                                team = enemyTeam,
                                distance = distance
                            }
                        end
                    end
                end
            end
            V2.players = nextPlayers
            V2.playerCount = #nextPlayers
        end

        local function drawSkeleton(entry, controller, player, color, distance,
                                    key, frameProjected, now)
            if not _G.VIPConfig.EspV2Skeleton or distance > SKELETON_DISTANCE then
                for _, part in ipairs(entry.skeleton) do
                    setVisible(part.widget, false)
                end
                entry.lastSkeleton = nil
                return
            end
            local interval = distance > 100 and 0.05 or 0.033
            if entry.lastSkeleton and now - entry.lastSkeleton < interval then
                return
            end
            entry.lastSkeleton = now
            local projected = frameProjected or {}
            local function bonePoint(name)
                if projected[name] == nil then
                    projected[name] =
                        project(controller, getBone(player, name, key)) or false
                end
                return projected[name] ~= false and projected[name] or nil
            end
            local index = 0
            local function segment(a, b)
                if not a or not b then return end
                index = index + 1
                if not entry.skeleton[index] then
                    entry.skeleton[index] = newBorder(color, 991)
                end
                drawLine(entry.skeleton[index], a.X, a.Y, b.X, b.Y, 1.25, color)
            end
            for _, pair in ipairs(SIMPLE_BONES) do
                segment(bonePoint(pair[1]), bonePoint(pair[2]))
            end
            for n = index + 1, #entry.skeleton do
                setVisible(entry.skeleton[n].widget, false)
            end
        end

        local function updateOne(controller, localPlayer, data, now, textUpdate)
            local player = data.actor
            local entry = getEntry(data.key)
            if not isValid(player) or not entry then
                hideEntry(entry)
                return false
            end
            local headWorld = getBone(player, "head", data.key)
            local pelvisWorld = getBone(player, "pelvis", data.key)
            local footLeftWorld = getBone(player, "foot_l", data.key)
            local footRightWorld = getBone(player, "foot_r", data.key)
            local head, headPixel = project(controller, headWorld)
            local pelvis = project(controller, pelvisWorld)
            local footLeft = project(controller, footLeftWorld)
            local footRight = project(controller, footRightWorld)
            if not head or not pelvis or not headPixel or headPixel.X < 0 or
                headPixel.X > V2.viewportW or headPixel.Y < 0 or headPixel.Y >
                V2.viewportH then
                hideEntry(entry)
                return false
            end
            local bottom = math.max((footLeft and footLeft.Y or pelvis.Y),
                                    (footRight and footRight.Y or pelvis.Y))
            if bottom <= head.Y then
                bottom = pelvis.Y + math.max(18, pelvis.Y - head.Y)
            end
            local height = math.max(24, bottom - head.Y)
            local centerX = pelvis.X
            if footLeft and footRight then
                centerX = (footLeft.X + footRight.X + pelvis.X * 2) / 4
            end
            local width = math.max(16, math.min(height * 0.52, 120))
            local left = centerX - width * 0.5
            local top = head.Y - 5
            height = bottom - top + 3
            local visible = getVisible(controller, player, data.key, now)
            
            
            local trackColor = visible and C_GREEN or C_RED
            local plateColor = teamColor(data.team)
            local lineColor = visible and C_GREEN or plateColor

            if _G.VIPConfig.EspV2Line then
                local origin = screenToCanvas(FVector2D(
                                                  V2.snapViewportW *
                                                      ORIGIN_X_FRAC,
                                                  ORIGIN_Y_PIX))
                local originX = (origin and origin.X or 0) + ORIGIN_X_PIX
                local originY = origin and origin.Y or 0
                drawLine(entry.line, originX, originY, head.X, head.Y, 1.5,
                         lineColor)
            else
                setVisible(entry.line.widget, false)
            end
            if _G.VIPConfig.EspV2Box then
                drawCornerBox(entry.box, left, top, width, height, trackColor)
            else
                hideBox(entry.box)
            end
            drawSkeleton(entry, controller, player, trackColor, data.distance,
                         data.key, {
                    head = head,
                    pelvis = pelvis,
                    foot_l = footLeft or false,
                    foot_r = footRight or false
                }, now)

            
            
            
            local distanceScale = math.max(0.48, math.min(1.0, 1.08 -
                                                              data.distance *
                                                              0.0045))
            local tabletBoost = V2.fontSize >= 16 and 1.15 or 1.0
            local uiScale = distanceScale * tabletBoost
            local plateWidth = 142 * uiScale
            local plateHeight = (V2.fontSize + 7) * uiScale
            local plateLeft = head.X - plateWidth * 0.5
            local plateTop = head.Y - plateHeight - 7 * uiScale
            
            
            
            
            
            
            
            local showPlate = false
            if showPlate then
                if not entry.nameBg then
                    entry.nameBg = newBorder(C_PLATE, 995)
                end
                if entry.nameBg then
                    drawRect(entry.nameBg, plateLeft, plateTop, plateWidth,
                             plateHeight, plateColor)
                end
            elseif entry.nameBg then
                setVisible(entry.nameBg.widget, false)
            end

            if _G.VIPConfig.EspV2HP then
                if not entry.hpBg then entry.hpBg = newBorder(C_BLACK, 996) end
                if not entry.hpFill then
                    entry.hpFill = newBorder(C_GREEN, 997)
                end
                if not entry.healthTime or now - entry.healthTime >= 0.10 then
                    local hp, maxHp
                    local ok = pcall(function()
                        hp = tonumber(player.Health)
                        maxHp = tonumber(player.HealthMax) or
                                    tonumber(player.MaxHealth) or 100
                    end)
                    if ok and hp and hp == hp and math.abs(hp) < 100000 and
                        maxHp and maxHp == maxHp and maxHp > 0 and maxHp <
                        100000 then
                        entry.healthPercent = math.max(0,
                                                       math.min(1, hp / maxHp))
                    else
                        entry.healthPercent = nil
                    end
                    entry.healthTime = now
                end
                local percent = entry.healthPercent
                if percent then
                    local barWidth = math.max(2, 4 * uiScale)
                    local barGap = math.max(2, 3 * uiScale)
                    local barX = left - barGap - barWidth
                    local barY = top
                    local barHeight = height
                    drawRect(entry.hpBg, barX, barY, barWidth, barHeight,
                             C_BLACK)
                    local fillColor = percent > 0.6 and C_GREEN or
                                          (percent > 0.3 and C_YELLOW or C_RED)
                    local fillHeight = barHeight * percent
                    drawRect(entry.hpFill,
                             barX, barY + barHeight - fillHeight,
                             barWidth, fillHeight, fillColor)
                else
                    if entry.hpBg then setVisible(entry.hpBg.widget, false) end
                    if entry.hpFill then
                        setVisible(entry.hpFill.widget, false)
                    end
                end
            else
                if entry.hpBg then setVisible(entry.hpBg.widget, false) end
                if entry.hpFill then setVisible(entry.hpFill.widget, false) end
            end

            
            
            local footCenterX = centerX
            if footLeft and footRight then
                footCenterX = (footLeft.X + footRight.X) * 0.5
            end
            local bottomRow = bottom + V2.fontSize * 0.75 * uiScale
            local weapon = nil
            local showDetailedText = data.distance <= 100
            local showNameText = data.distance <= 200
            local showWeapon = _G.VIPConfig.EspV2Weapon and showDetailedText
            if showWeapon then
                if not entry.weaponInfo or
                    now >= (entry.nextWeaponCheck or 0) then
                    entry.weaponInfo = weaponInfo(player)
                    entry.nextWeaponCheck = now + 0.50
                end
                weapon = entry.weaponInfo
            else
                entry.weaponInfo = nil
                entry.nextWeaponCheck = 0
            end
            local weaponIconVisible = false
            if weapon then
                weaponIconVisible = applyWeaponIcon(entry.weaponIcon, weapon)
            end
            if weaponIconVisible and entry.weaponIcon and entry.weaponIcon.slot then
                local iconW = 36 * uiScale
                local iconH = 18 * uiScale
                pcall(function()
                    entry.weaponIcon.slot:SetPosition(FVector2D(
                                                          head.X - iconW * 0.5,
                                                          head.Y - iconH - 3 *
                                                              uiScale))
                    entry.weaponIcon.slot:SetSize(FVector2D(iconW, iconH))
                end)
                setVisible(entry.weaponIcon.widget, true)
            elseif entry.weaponIcon then
                setVisible(entry.weaponIcon.widget, false)
            end
            if textUpdate or entry.nameValue == nil then
                local playerLabel = playerName(player)
                local bot = playerLabel == "Bot" or isBot(player)
                if #playerLabel > 20 then
                    playerLabel = playerLabel:sub(1, 20)
                end
                if bot then
                    entry.nameValue = "Bot"
                else
                    local number = math.floor(tonumber(data.team) or 0)
                    entry.nameValue = string.format("%d | %s", number,
                                                    playerLabel)
                end
                entry.distanceValue = string.format(
                                          "%dm",
                                          math.floor(data.distance + 0.5))
                entry.statusValue, entry.statusColor = playerStatus(player)
                entry.weaponValue = weapon and weapon.name or ""
            end

            local tabletText = V2.fontSize >= 16
            local nearFont = tabletText and 14 or 12
            local textFontSize
            if data.distance <= 30 then
                textFontSize = nearFont
            elseif data.distance <= 100 then
                local farFont = tabletText and 11 or 9
                local t = (data.distance - 30) / 70
                textFontSize = math.floor(nearFont +
                                              (farFont - nearFont) * t + 0.5)
            elseif data.distance <= 200 then
                textFontSize = tabletText and 10 or 8
            else
                textFontSize = tabletText and 9 or 8
            end
            local rowGap = textFontSize + 3
            local firstRowY = bottom + math.max(8, textFontSize * 0.65)
            local textCenterX = centerX

            local weaponPart = entry.text.weapon
            if showWeapon and weapon and
                not weaponIconVisible then
                setTextSize(weaponPart, textFontSize)
                setText(weaponPart, entry.weaponValue, head.X,
                        head.Y - textFontSize - 8 * uiScale, C_WHITE,
                        textUpdate or not weaponPart or weaponPart.value == nil)
            elseif weaponPart then
                setVisible(weaponPart.widget, false)
            end

            local namePart = entry.text.name
            if _G.VIPConfig.EspV2Name and showNameText then
                setTextSize(namePart, textFontSize)
                setText(namePart, entry.nameValue, textCenterX, firstRowY,
                        C_YELLOW,
                        textUpdate or not namePart or namePart.value == nil)
            elseif namePart then
                setVisible(namePart.widget, false)
            end

            local distancePart = entry.text.distance
            if _G.VIPConfig.EspV2Distance then
                setTextSize(distancePart, textFontSize)
                setText(distancePart, entry.distanceValue, textCenterX,
                        firstRowY + rowGap, C_WHITE,
                        textUpdate or not distancePart or
                            distancePart.value == nil)
            elseif distancePart then
                setVisible(distancePart.widget, false)
            end

            local statusPart = entry.text.status
            if _G.VIPConfig.EspV2Status and showDetailedText then
                setTextSize(statusPart, textFontSize)
                setText(statusPart, entry.statusValue, textCenterX,
                        firstRowY + rowGap * 2,
                        entry.statusColor or C_WHITE,
                        textUpdate or not statusPart or statusPart.value == nil)
            elseif statusPart then
                setVisible(statusPart.widget, false)
            end
            return true
        end

        local function nextInterval()
            local configured = tonumber(_G.VIPConfig.EspV2FPS) or 0
            local count = V2.playerCount
            local fps
            if configured == 30 then
                fps = count > 16 and 20 or 30
            elseif configured == 60 then
                
                
                fps = count > 16 and 20 or (count > 8 and 30 or 60)
            else
                fps = count > 16 and 20 or (count > 8 and 30 or 45)
            end
            return 1 / fps
        end

        local function schedule(generation, delay)
            if not V2.running or V2.generation ~= generation then
                return
            end
            
            
            
            local gameOK = pcall(function()
                local liveGame = rawget(_G, "Game")
                if not liveGame or type(liveGame.SetTimer) ~= "function" then
                    error("live Game timer unavailable")
                end
                liveGame:SetTimer(delay, false, function()
                    if _G.BunnyEspV2Tick then
                        _G.BunnyEspV2Tick(generation)
                    end
                end)
            end)
            if gameOK then return end
            local ticker = V2.ticker or TimeTicker
            if ticker and type(ticker.AddTimerOnce) == "function" then
                local ok = pcall(ticker.AddTimerOnce, delay, function()
                    if _G.BunnyEspV2Tick then
                        _G.BunnyEspV2Tick(generation)
                    end
                end)
                if ok then return end
            end
            FourRDiag("ESPV2_FAIL", "unable to schedule render tick", 3)
        end

        function _G.BunnyEspV2Tick(generation)
            generation = generation or V2.generation
            if not V2.running or generation ~= V2.generation or
                not (_G.VIPConfig and _G.VIPConfig.EspV2Enable) then
                return
            end
            V2.lastTick = os.clock()
            if not IsAuthorized() then
                for _, entry in pairs(V2.widgets) do hideEntry(entry) end
                schedule(generation, 0.5)
                return
            end
            local reschedule = 0.10
            local tickOK, tickError = pcall(function()
                local controller = GameplayData.GetPlayerController()
                if not isValid(controller) then
                    for _, entry in pairs(V2.widgets) do hideEntry(entry) end
                    FourRDiag("ESPV2_FAIL", "player controller unavailable", 3)
                    return
                end
                local localPlayer = controller:GetPlayerCharacterSafety()
                if not isValid(localPlayer) then
                    for _, entry in pairs(V2.widgets) do hideEntry(entry) end
                    FourRDiag("ESPV2_FAIL", "local pawn unavailable", 3)
                    return
                end
                local now = os.clock()
                updateTransform(controller, now)
                if not getCanvas() then
                    FourRDiag("ESPV2_FAIL", "gameplay canvas unavailable", 3)
                    return
                end
                V2.lastCanvasAt = now
                updatePlayerList(localPlayer, now)
                local textUpdate = now - V2.lastText >= 0.15
                if textUpdate then V2.lastText = now end
                local seen = {}
                for _, data in ipairs(V2.players) do
                    seen[data.key] = true
                    local entry = V2.widgets[data.key]
                    if entry then entry.lastSeen = now end
                    updateOne(controller, localPlayer, data, now, textUpdate)
                    entry = V2.widgets[data.key]
                    if entry then entry.lastSeen = now end
                end
                for key, entry in pairs(V2.widgets) do
                    if not seen[key] then
                        hideEntry(entry)
                        if now - (entry.lastSeen or 0) > 1.5 then
                            destroyEntry(entry)
                            V2.widgets[key] = nil
                            V2.vis[key] = nil
                            V2.boneSockets[key] = nil
                        end
                    end
                end
                
                
                V2.lastRenderAt = now
                reschedule = nextInterval()
            end)
            if not tickOK then
                FourRDiag("ESPV2_FAIL",
                          "tick error=" .. tostring(tickError):sub(1, 180), 3)
            end
            schedule(generation, reschedule)
        end

        function _G.StartBunnyEspV2()
            if V2.running then return end
            V2.running = true
            V2.generation = V2.generation + 1
            V2.lastScan = 0
            V2.lastTransform = 0
            V2.lastText = 0
            V2.lastCanvasAt = 0
            V2.lastRenderAt = 0
            V2.lastTick = 0
            V2.startedAt = os.clock()
            local tickerOK, ticker = pcall(require, "common.time_ticker")
            V2.ticker = tickerOK and ticker or nil
            schedule(V2.generation, 0)
        end

        function _G.StopBunnyEspV2()
            V2.running = false
            V2.generation = V2.generation + 1
            cleanup()
        end

        
        
        
        
        
        
        function _G.EnsureBunnyEspV2()
            if not (_G.VIPConfig and _G.VIPConfig.EspV2Enable) then return end
            local now = os.clock()
            local live = LootEspState.ResolveGameplayCanvas and
                             LootEspState.ResolveGameplayCanvas(true) or nil
            local liveSignature = live and tostring(live) or nil
            local canvasChanged = isValid(live) and
                                      (not isValid(V2.canvas) or
                                          live ~= V2.canvas or
                                          liveSignature ~= V2.canvasSignature)
            local startupGrace = V2.running and V2.lastCanvasAt == 0 and
                                     now - (V2.startedAt or 0) < 2.5
            local chainHealthy = V2.running and
                                     (now - (V2.lastTick or 0) < 2.5 or
                                         startupGrace)
            local canvasHealthy = isValid(V2.canvas) and
                                      now - (V2.lastCanvasAt or 0) < 2.5
            local renderHealthy = V2.running and
                                      (now - (V2.lastRenderAt or 0) < 2.5 or
                                          startupGrace)
            if chainHealthy and renderHealthy and
                (canvasHealthy or startupGrace) and
                not canvasChanged then
                return
            end
            FourRDiag("ESPV2_RESTART",
                      string.format(
                          "chain=%s render=%s canvas=%s changed=%s live=%s cached=%s players=%d",
                          tostring(chainHealthy), tostring(renderHealthy),
                          tostring(canvasHealthy), tostring(canvasChanged), tostring(live),
                          tostring(V2.canvas), tonumber(V2.playerCount) or 0),
                      1.0)
            
            
            V2.running = false
            V2.generation = V2.generation + 1
            cleanup()
            V2.lastScan = 0
            V2.lastTransform = 0
            V2.lastText = 0
            V2.lastCanvasAt = 0
            V2.lastRenderAt = 0
            V2.ticker = nil
            _G.StartBunnyEspV2()
        end

        function _G.RefreshBunnyEspV2ForWorld(worldKey, force)
            if not force and V2.worldKey == worldKey then return end
            V2.worldKey = worldKey
            V2.running = false
            V2.generation = V2.generation + 1
            cleanup()
            V2.lastScan = 0
            V2.lastTransform = 0
            V2.lastText = 0
            V2.lastCanvasAt = 0
            V2.lastRenderAt = 0
            V2.lastTick = 0
            V2.canvasSignature = nil
            V2.ticker = nil
            if worldKey and _G.VIPConfig and
                _G.VIPConfig.EspV2Enable then
                _G.StartBunnyEspV2()
            end
        end

        if _G.VIPConfig and _G.VIPConfig.EspV2Enable then
            _G.StartBunnyEspV2()
        end
    end

    
    
    
    
    pcall(function()
        if EventSystem and type(EventSystem.registEvent) == "function" and
            EVENTID_TDM_ONPLAYER_RESPAWN then
            EventSystem:registEvent(EVENTTYPE_INGAME_NORMAL,
                                    EVENTID_TDM_ONPLAYER_RESPAWN,
                                    function()
                if myToken ~= _G.VIPState.LoopToken then return end
                _G.BunnyVisualWorldKey = nil
                
                
                _G.BTSteerHooked = false
