    function _G.FourRPayloadStart()
        if myToken ~= _G.VIPState.LoopToken then return false end

        
        
        
        
        local tickStale = os.clock() - (_G.BunnyFastTickAt or 0) > 2.5
        local actionStale = os.clock() - (_G.BunnyFastActionTickAt or 0) > 2.5
        if _G.FourRPayloadLoopToken ~= myToken or tickStale then
            _G.FourRPayloadLoopToken = myToken
            FastTick()
        end
        if actionStale then FastActionTick() end

