    local BF = _G.FourRFake
    BF.GetProfile = function() return AVATAR_ID, AVATAR_BOX_ID end

    local function saveProfile()
        
        local a, b = BF.GetProfile()
        _G.FourRProfile.avatar = tonumber(a) or 0
        _G.FourRProfile.frame = tonumber(b) or 0
        if F.persistMarkDirty then pcall(F.persistMarkDirty) end
    end
    local rawSetAvatar, rawSetBox = BF.SetAvatar, BF.SetAvatarBox
    BF.SetAvatar = function(id) rawSetAvatar(id); saveProfile() end
    BF.SetAvatarBox = function(id) rawSetBox(id); saveProfile() end

    pcall(function()
        local p = _G.FourRProfile or {}
        local a = tonumber(p.avatar)
        local b = tonumber(p.frame)
        if a and a > 0 then rawSetAvatar(a) end
        if b and b > 0 then rawSetBox(b) end
    end)

    local function post(evType, evId, arg1)
        pcall(function()
            if EventSystem and _G[evType] and _G[evId] then
                EventSystem:postEvent(_G[evType], _G[evId], arg1)
            end
        end)
    end

    local INJ_A, INJ_F = {}, {}

    local function mergeAvatars(sys)
        sys.HeadportraitList = sys.HeadportraitList or {}
        for _, id in ipairs(AVATAR_IDS) do
            local k = tostring(id)
            if sys.HeadportraitList[k] == nil then
                sys.HeadportraitList[k] = 1
                INJ_A[k] = true
            end
        end
    end

    local function mergeFrames(sys)
        sys.AvatarFrameList = sys.AvatarFrameList or {}
        for _, id in ipairs(FRAME_IDS) do
            if sys.AvatarFrameList[id] == nil then
                sys.AvatarFrameList[id] = { expire_time = 1 }
                INJ_F[id] = true
            end
        end
    end

    local function hookAvatar()
        local ok, sys = pcall(require, "client.slua.logic.roleInfo.logic_roleInfo_Avatar")
        if not ok or type(sys) ~= "table" then return false end
        if sys._FourRPickerHooked then return true end
        sys._FourRPickerHooked = true

        local origRsp = sys.get_user_avatar_list_rsp
        sys.get_user_avatar_list_rsp = function(err, list, url)
            INJ_A = {}
            origRsp(err, list, url)
            if err == 0 then
                mergeAvatars(sys)
                post("EVENTTYPE_ROLEINFO", "EVENTID_ROLEINFO_UPDATE_HEAD_INFO", DataMgr.roleData.headIconUrl)
            end
        end

        local origSend = sys.send_change_user_avatar
        sys.send_change_user_avatar = function(item_url)
            local id = tonumber(item_url)
            if id and INJ_A[tostring(id)] then
                BF.SetAvatar(id)
                pcall(function() DataMgr.UpdateHeadIconUrl(tostring(id)) end)
                post("EVENTTYPE_ROLEINFO", "EVENTID_ROLEINFO_UPDATE_USE_AVATAR")
                post("EVENTTYPE_LOBBY", "EVENTID_UPDATE_LOBBY_AVATAR")
                return
            end
            return origSend(item_url)
        end

        mergeAvatars(sys)
        return true
    end

    local function hookFrame()
        local ok, sys = pcall(require, "client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
        if not ok or type(sys) ~= "table" then return false end
        if sys._FourRPickerHooked then return true end
        sys._FourRPickerHooked = true

        local origRsp = sys.get_avatar_box_list_rsp
        sys.get_avatar_box_list_rsp = function(err, list, cur)
            INJ_F = {}
            origRsp(err, list, cur)
            if err == 0 then
                mergeFrames(sys)
                post("EVENTTYPE_ROLEINFO", "EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO")
            end
        end

        local origChange = sys.change_avatar_box
        sys.change_avatar_box = function(item_id)
            local id = tonumber(item_id)
            if id and INJ_F[id] then
                BF.SetAvatarBox(id)
                pcall(function() sys.UpdateCurAvatarBoxID(id) end)
                post("EVENTTYPE_ROLEINFO", "EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO")
                post("EVENTTYPE_LOBBY", "EVENTID_UPDATE_LOBBY_AVATAR")
                return
            end
            return origChange(item_id)
        end

        mergeFrames(sys)
        return true
    end

    local function hookAll()
        local a = hookAvatar()
        local b = hookFrame()
        return a and b
    end


    local okAF, resAF = pcall(hookAll)
    if not okAF then FourRDiag("AvatarFrame", tostring(resAF), 10) end
    if not okAF or not resAF then
        for _, sec in ipairs({ 3.0, 8.0, 20.0 }) do
            pcall(function()
                F.later(sec, function()
                    local ok2, res2 = pcall(hookAll)
                    if not ok2 then
                        FourRDiag("AvatarFrame", tostring(res2), 10)
                    end
                end)
            end)
        end
    end
end











do
    local T = { use = 0, showSet = false, show = {} }
    _G.FourRTitle = T

    local function saveT()
        
        _G.FourRProfile.title = tonumber(T.use) or 0
        if F.persistMarkDirty then pcall(F.persistMarkDirty) end
    end

    pcall(function()
        local p = _G.FourRProfile or {}
        T.use = tonumber(p.title) or 0
    end)

    local function isComplex(cfgRow)
        local ty = type(cfgRow) == "table" and tonumber(cfgRow.AliasType) or 0
        return ty == 5 or ty == 6 or ty == 7 or ty == 8
    end


    local function injectAll(list)
        local injected = {}
        local okc, cfg = pcall(function() return CDataTable.GetTable("AliasCfg") end)
        if okc and type(cfg) == "table" then
            for k, row in pairs(cfg) do
                if list[k] == nil then
                    list[k] = { state = 1, rank = 0, rank_id = 0, nation = "", expire_ts = 0,
                                receive_time = os.time(), have_used = 1 }
                    injected[k] = isComplex(row)
                end
            end
        end
        for _, v in pairs(list) do
            if type(v) == "table" then
                if (tonumber(v.state) or 0) == 0 then
                    v.state = 1
                    v.rank = v.rank or 0
                    v.rank_id = v.rank_id or 0
                    v.nation = v.nation or ""
                    v.expire_ts = v.expire_ts or 0
                    v.receive_time = v.receive_time or os.time()
                    v.have_used = v.have_used or 1
                end
            end
        end
        if T.use ~= 0 then
            for k, v in pairs(list) do
                if type(v) == "table" and v.state == 2 and tonumber(k) ~= T.use then v.state = 1 end
            end
            local e = list[T.use] or list[tostring(T.use)]
            if e then e.state = 2 end
        end
        return injected
    end

    local function post(evType, evId, a1)
        pcall(function()
            if EventSystem and _G[evType] and _G[evId] then
                EventSystem:postEvent(_G[evType], _G[evId], a1)
            end
        end)
    end

    local function hookTitle()
        local ok, S = pcall(require, "client.slua.logic.roleInfo.logic_roleinfo_title")
        if not ok or type(S) ~= "table" then return false end
        if S._FourRTitleHooked then return true end
        local orig = S.alias_list_res
        if type(orig) ~= "function" then return false end
        S._FourRTitleHooked = true

        S.alias_list_res = function(res, list, red_point, alias)
            if type(list) ~= "table" then return orig(res, list, red_point, alias) end
            local inj = injectAll(list)
            if pcall(orig, res, list, red_point, alias) then return end
            for k, complex in pairs(inj) do if complex then list[k] = nil end end
            if pcall(orig, res, list, red_point, alias) then return end
            for k in pairs(inj) do list[k] = nil end
            return orig(res, list, red_point, alias)
        end

        local origReq = S.change_alias_req
        S.change_alias_req = function(id, state)
            local nid = tonumber(id)
            local list = S.alias_list_info
            local cur = type(list) == "table" and nid and (list[id] or list[nid])
            if cur then
                if cur.state == 2 then
                    T.use = 0
                    cur.state = 1
                else
                    T.use = nid
                end
                saveT()
                pcall(injectAll, list)
                S.newCheckId = nid
                pcall(S.initAliasInfo)
                post("EVENTTYPE_LOBBY_SOCIAL", "EVENTID_LOBBY_SOCIAL_ALIAS_LIST")
                post("EVENTTYPE_LOBBY_SOCIAL", "EVENTID_LOBBY_SOCIAL_GOT_ALIAS_DATA")
                pcall(function() if ShowNotice then ShowNotice(49951) end end)
                return
            end
            return origReq(id, state)
        end

        pcall(S.get_alias_list)
        return true
    end

    local function hookShow()
        local ok, CH = pcall(require, "client.network.Protocol.CharacterHandler")
        if not ok or type(CH) ~= "table" then return false end
        if CH._FourRShowHooked then return true end
        if type(CH.send_get_show_alias_req) ~= "function" or type(CH.send_set_show_alias_req) ~= "function" then
            return false
        end
        CH._FourRShowHooked = true
        local origGet, origSet = CH.send_get_show_alias_req, CH.send_set_show_alias_req

        local function localShowInfo()
            local info = {}
            for id, order in pairs(T.show) do
                info[id] = { order_id = order, rank = 0, rank_id = 0, nation = "", expire_ts = 0 }
            end
            return info
        end

        CH.send_get_show_alias_req = function(...)
            if T.showSet then
                pcall(CH.on_get_show_alias_rsp, 0, localShowInfo())
                return
            end
            return origGet(...)
        end

        CH.send_set_show_alias_req = function(tbl, ...)
            if type(tbl) ~= "table" then return origSet(tbl, ...) end
            T.show = {}
            for order, id in pairs(tbl) do
                local nid, no = tonumber(id), tonumber(order)
                if nid and no then T.show[nid] = no end
            end
            T.showSet = true
            saveT()
            pcall(CH.on_set_show_alias_rsp, 0, tbl)
        end
        return true
    end

    local function hookAllTitle()
        local a = hookTitle()
        local b = hookShow()
        return a and b
    end

    local okTi, resTi = pcall(hookAllTitle)
    if not okTi then FourRDiag("Titles", tostring(resTi), 10) end
    if not okTi or not resTi then
        for _, sec in ipairs({ 3.0, 8.0, 20.0, 40.0 }) do
            pcall(function()
                F.later(sec, function()
                    local ok2, res2 = pcall(hookAllTitle)
                    if not ok2 then
                        FourRDiag("Titles", tostring(res2), 10)
                    end
                end)
            end)
        end
    end
end


    
    return true
end)()

