-- MAIN LOOP: EXTREMELY POWERFUL OPTIMIZED
local function MainLoop()
    if isExpired then return end
    -- KEY GATE: Jab tak key verify na ho, koi feature kaam nahi karega
    if not BRLicenseActive() then
        ForceDisableAllFeatures()
        return
    end

    -- ★★★ ပြင်ဆင်ချက်: ESP V2 Classic Rank / TDM အတွက် ပြန်စမ်းသပ် Watchdog ★★★
    -- ယခင်က ClearVisionV2.Start() ကို menu toggle ဖွင့်ချိန် တစ်ကြိမ်သာ ခေါ်ခဲ့ပါတယ်။
    -- Classic rank မှာ local pawn/HUD က အဲဒီအချိန်မှာ အဆင်သင့်မဖြစ်သေးတာကြောင့်
    -- Start() fail ဖြစ်ပြီး ပြန်မစမ်းတော့ပါဘူး (Training Ground မှာ pawn ရှိပြီးသားမို့ အလုပ်လုပ်သလို ဖြစ်နေတာပါ)။
    -- SyncEnabled() မှာ session watchdog အားလုံးပါပြီးသားဖြစ်လို့ world/controller/pawn/canvas
    -- ပြောင်းသွားရင် widget ဟောင်းတွေကို ဖျက်ပြီး match အသစ်ပေါ်မှာ ပြန်ချိတ်ပေးပါတယ်။
    -- ဒီ 0.2s MainLoop ထဲကနေ ခေါ်လိုက်ရင် automatic retry နဲ့ respawn/match transition rebind ရပါပြီ။

    if _G.pghacksState.CustomTextData == nil then 
        _G.pghacksState.CustomTextData = {OuterSpeed = 10, InnerSpeed = 10, HRecoil = 0.3, VRecoil = 0.3, MagicHead = 1.0, MagicBody = 1.0, MagicLegs = 1.0, IpadViewFOV = 120, AimTouchHipPrio = 1, AimTouchHipBone = 1, AimTouchHipCond = 1, AimTouchHipSpeed = 58, AimTouchHipFOV = 20, AimTouchHipDist = 50, AimTouchSGPrio = 1, AimTouchSGBone = 2, AimTouchSGCond = 1, AimTouchSGSpeed = 80, AimTouchSGFOV = 40, AimTouchSGDist = 30, AimTouchScopePrio = 1, AimTouchScopeRecoil = 4, AimTouchScopeBone = 1, AimTouchScopeCond = 1, AimTouchScopeSpeed = 65, AimTouchScopeFOV = 20, AimTouchScopeDist = 180, AimTouchSniperPrio = 1, AimTouchSniperBone = 1, AimTouchSniperCond = 1, AimTouchSniperSpeed = 30, AimTouchSniperFOV = 20, AimTouchSniperDist = 400, FastCarSpeed = 6000}
    end

    local okData, GameplayData = pcall(require, "GameLua.GameCore.Data.GameplayData") 
    if not okData or not GameplayData then return end 
    local pc = GameplayData.GetPlayerController() 
    local localPlayer = nil
    if Valid(pc) then localPlayer = pc:GetPlayerCharacterSafety() end 

    if not Valid(localPlayer) then 
        if _G.pghacksState.TrackedMarks then
            for markId, _ in pairs(_G.pghacksState.TrackedMarks) do
                SafeRemoveMark(markId)
            end
        end
        _G.pghacksState.TrackedMarks = {} 
        
        for key, data in pairs(_G.pghacksState.EnemyMarks) do
            if data and data.MIDs then
                for meshStr, midTable in pairs(data.MIDs) do
                    for k, _ in pairs(midTable) do midTable[k] = nil end
                end
                data.MIDs = nil
            end
        end
        
        _G.pghacksState.EnemyMarks = {}
        _G.AK_OrigHitboxes = {}
        _G.AK_ModdedPhysAssets = {}
        -- Match transition: LastMagicConfigHash reset karo taaki match 2 mein
        -- PhysicsAsset fresh originals ke saath dobara scale ho (not from match-1 modified values)
        _G.pghacksState.LastMagicConfigHash = ""
        _G.pghacksState.MagicUpdateVersion = (_G.pghacksState.MagicUpdateVersion or 0) + 1
        _G.pghacksState.PrevGraphicsState = {}
        -- _LicenseWasActive ab wrapper khud reset karta hai (inactive tick par)
        -- match-end block mein alag se reset ki zaroorat nahi
        return
    end

--    INIT 'AddOutfit' =====
    if not _G.AddOutfitStarted then
        _G.AddOutfitStarted = true
        pcall(function()
            if _G.AddOutfit and _G.AddOutfit.start then
                _G.AddOutfit.start()
            end
        end)
    end

    local Cached_PPM = nil
    pcall(function() Cached_PPM = import("PostProcessManager").GetInstance() end)
    local Cached_SecurityCommonUtils = nil
    pcall(function() Cached_SecurityCommonUtils = require("GameLua.Mod.BaseMod.Common.Security.SecurityCommonUtils") end)
    local Cached_MyHUD = pc and pc.MyHUD or nil

    if _G.pghacksConfig.UnlockFPS then InitializeGraphicsUnlock() end
    InitializeNativeESP()
    ShowpghacksVIPMenu()
    
    if _G.pghacksConfig.IpadView and _G.pghacksState.CustomTextData then
        pcall(function()
            local targetTPP = _G.pghacksState.CustomTextData.IpadViewFOV or 120
            local uTPPCam = localPlayer.ThirdPersonCameraComponent
            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
                if uTPPCam.FieldOfView ~= targetTPP then uTPPCam.FieldOfView = targetTPP end
            end
        end)
    else
        pcall(function()
            local uTPPCam = localPlayer.ThirdPersonCameraComponent
            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
                if uTPPCam.FieldOfView ~= 80 then uTPPCam.FieldOfView = 80 end
            end
        end)
    end

    -- Aimbot Force dipindahkan ke loop terpisah
    pcall(function()
        if _G.pghacksConfig.CustomAimbot and localPlayer.bIsWeaponFiring and localPlayer.bIsGunADS then
            local outerRecoilVal = _G.pghacksState.CustomTextData.OuterRecoil or 0
            if outerRecoilVal > 0 then
                local curTime = os.clock()
                
                if not _G.RecoilTargetCacheTime or (curTime - _G.RecoilTargetCacheTime) > 0.2 then
                    _G.RecoilTargetCacheTime = curTime
                    _G.HasRecoilTargetCached = false
                    
                    local ui_util = require("client.common.ui_util")
                    if ui_util then
                        local viewportSize = ui_util.GetViewportSize()
                        if viewportSize then
                            local centerX = viewportSize.X * 0.5
                            local centerY = viewportSize.Y * 0.5
                            local FOV_RADIUS = (6 / 100.0) * (viewportSize.X / 2.0) 
                            
                            local enemies = _G.GetEnemyTargetsFromActors(40000) 
                            if enemies and #enemies > 0 then
                                local FVector2D = import("Vector2D")
                                for _, target in ipairs(enemies) do
                                    if slua.isValid(target) and target.HealthStatus ~= 1 then 
                                        local tPos = type(target.K2_GetActorLocation) == "function" and target:K2_GetActorLocation() or nil
                                        if tPos then
                                            local screen = FVector2D()
                                            if pc:ProjectWorldLocationToScreen(tPos, screen, false) and screen.X > 0 and screen.Y > 0 then
                                                local dx = screen.X - centerX
                                                local dy = screen.Y - centerY
                                                if math.sqrt(dx*dx + dy*dy) <= FOV_RADIUS then
                                                    _G.HasRecoilTargetCached = true
                                                    break 
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                if _G.HasRecoilTargetCached then
                    local currentRot = pc:GetControlRotation()
                    if currentRot then
                        local pullDownForce = (outerRecoilVal / 50.0) * 1.5
                        currentRot.Pitch = currentRot.Pitch - pullDownForce
                        pc:SetControlRotation(currentRot, "CustomAimbotRecoil")
                    end
                end
            end
        else
            _G.HasRecoilTargetCached = false
        end
    end)

    pcall(function()
