-- MAIN LOOP (ESP & OTHER FEATURES) EVERY 0.2 SECONDS
local function FastTick() 
    if isExpired then 
        if not _G.pghacksNotifiedExpire then
            Notify("MOD HAS EXPIRED! PLEASE CONTACT ADMIN TO RENEW!\nTelegram @PGHACKS1")
            _G.pghacksNotifiedExpire = true
        end
        return 
    end

    if myToken ~= _G.pghacksState.LoopToken then return end
    pcall(MainLoop) 
    local okTicker, ticker = pcall(require, "common.time_ticker") 
    if okTicker and ticker and ticker.AddTimerOnce then 
        ticker.AddTimerOnce(0.2, FastTick) 
    end 
end

