-- SKIN LOOP UNTUK MENERAPKAN SKIN KARAKTER (HACK)
local function SkinHackLoop()
    if isExpired then return end
    if not (_G.VIPConfig and _G.VIPConfig.ModSkin) then return end -- [FIX-5a] was pghacksConfig

    local okData, GameplayData = pcall(require, "GameLua.GameCore.Data.GameplayData")
    if not okData or not GameplayData then return end

    local pc = GameplayData.GetPlayerController()
    if not Valid(pc) then return end

    local localPlayer = pc:GetPlayerCharacterSafety()
    if not Valid(localPlayer) then return end

    local isAlive = type(localPlayer.IsAlive) == "function" and localPlayer:IsAlive() or true
    if not isAlive then return end

    if _G.AddOutfit and _G.AddOutfit.isInRealMatch() then
        if not _G.AddOutfitLobbyRestored then
            _G.AddOutfitLobbyRestored = true
        end

        -- Terapkan semua skin (outfit, hat, pants, shoes, gloves, mask, glass, dll)
        _G.AddOutfit.matchApplyAllSlots(localPlayer)

        -- Terapkan skin senjata (dipanggil ulang untuk jaga-jaga)
        _G.AddOutfit.matchApplyWeaponSkin(localPlayer)

        -- Jika sedang di udara, terapkan skin parasut/glider
        if _G.AddOutfit.isCharacterAirborne(localPlayer) then
            _G.AddOutfit.applyAirborneSlots(localPlayer, true)
        end

        -- Terapkan skin kendaraan ke PlayerController
        if _G.AddOutfit.applyVehicleSkinsToPC then
            _G.AddOutfit.applyVehicleSkinsToPC(pc)
        end
    end
end

