function _G.FeatureSwitch(key, defaultOn)
    local ok, v = pcall(function()
        if _G.PGHACKS1_Config and _G.PGHACKS1_Config.Get then
            return _G.PGHACKS1_Config.Get(key, defaultOn and 1 or 0)
        end
        return nil
    end)
    if ok and v ~= nil then return v == 1 end
    return defaultOn ~= false
end

