                if DataMgr.ticket ~= FAKE_UC_AMOUNT() then DataMgr.ticket = FAKE_UC_AMOUNT() dirty = true end
                if DataMgr.diamond ~= FAKE_SILVER_AMOUNT() then DataMgr.diamond = FAKE_SILVER_AMOUNT() dirty = true end
            end
            if dirty and EventSystem and EVENTTYPE_DATA_MGR then
                if _G.EVENTID_DATAMGR_ETERNAL_DIAMOND_CHANGE then
                    EventSystem:postEvent(EVENTTYPE_DATA_MGR, _G.EVENTID_DATAMGR_ETERNAL_DIAMOND_CHANGE, FAKE_G_AMOUNT())
