function BuildEmoteItem_Extra(nEmoteID)
  local uItemCfg = CDataTable.GetTableData("Item", nEmoteID)
  return {
    DefineID = {TypeSpecificID = nEmoteID},
    Name = uItemCfg and uItemCfg.ItemName or tostring(nEmoteID)
