_G.LobbySkinInjector = _G.LobbySkinInjector or {
    applied = false,
    customSet = nil,
    fakeByRes = {},
    customWorn = {},
    BASE_ID = 900000000,
    MAX_CUSTOM_IN_LIST = 20000
}

LSI = _G.LobbySkinInjector

function fakeInstanceId(resId)
    resId = tonumber(resId)
    if not resId or resId == 0 then return LSI.BASE_ID end
    if LSI.fakeByRes[resId] then return LSI.fakeByRes[resId] end
    local fakeId = LSI.BASE_ID + resId
    LSI.fakeByRes[resId] = fakeId
    return fakeId
end

function isCustomItem(resId)
    if not resId or resId == 0 then return false end
    resId = tonumber(resId)

    if LSI.customSet == nil then
        LSI.customSet = {}
        for _, id in ipairs(CUSTOM_ITEM_IDS) do
            if type(id) == "number" and id ~= 0 then LSI.customSet[id] = true end
        end
    end
    return LSI.customSet[resId] == true
end

function isFakeInstance(insId)
    insId = tonumber(insId)
    if not insId or insId < LSI.BASE_ID then return false end
    local realId = insId - LSI.BASE_ID
    return isCustomItem(realId) and realId or false
end

__itemCfgCache = {}
function getItemConfig(resId)
    if not CDataTable or not resId then return nil end
    local cached = __itemCfgCache[resId]
    if cached ~= nil then return cached or nil end
    local ok, cfg = pcall(CDataTable.GetTableData, "item", resId)
    if ok and cfg then __itemCfgCache[resId] = cfg; return cfg end
    ok, cfg = pcall(CDataTable.GetTableData, "Item", resId)
    __itemCfgCache[resId] = (ok and cfg) or false
    return (ok and cfg) or nil
end

function getItemTabs(resId)
    local cfg = getItemConfig(resId)
    if cfg and cfg.WardrobeMainTab ~= nil and cfg.WardrobeTab ~= nil then
        return cfg.WardrobeMainTab, cfg.WardrobeTab
    end
    return 1, 10
end

function getItemTypes(resId)
    local cfg = getItemConfig(resId)
    return (cfg and cfg.ItemType) or 5, (cfg and cfg.ItemSubType) or 0
end

function getLobbyItemCategory(resId)
    local cfg = getItemConfig(resId)
    local mt = cfg and tonumber(cfg.WardrobeMainTab) or nil
    if mt then
        if mt == 4 then return "weapon" end
        if mt == 6 then return "vehicle" end
        return "suit"
    end
    local id = tonumber(resId) or 0
    if (id >= 1900000 and id < 2000000) or (id >= 19100000 and id < 19102000) or (id >= 181000000 and id < 182000000) then return "vehicle" end
    if (id >= 1010000 and id < 1100000) or (id >= 1101000000 and id < 1102000000) then return "weapon" end
    return "suit"
end

function lobbyCatAllowed(resId)
    return true
end
_G.LobbyItemCategory = getLobbyItemCategory
_G.LobbyCatAllowed = lobbyCatAllowed

__fakeItemDataCache = {}
function buildFakeItemData(resId)
    resId = tonumber(resId)
    if not resId or resId == 0 then return nil end
    local cachedData = __fakeItemDataCache[resId]
    if cachedData ~= nil then return cachedData or nil end

    local ok, result = pcall(function()
        local cfg = getItemConfig(resId)
        local itemType, itemSubType = (cfg and cfg.ItemType) or 5, (cfg and cfg.ItemSubType) or 0
        local mainTab, subTab = getItemTabs(resId)
        local fakeId = fakeInstanceId(resId)

        return {
            insID = tostring(fakeId),
            ins_id = fakeId,
            resID = resId,
            res_id = resId,
            item_res_id = resId,
            itemType = itemType,
            itemSubType = itemSubType,
            mainTabType = mainTab,
            subTabType = subTab,
            count = 1,
            expireTS = 0,
            validHours = 999999,
            valid_hours = 999999,
            expire_ts = 0,
            isNew = false,
            itemQuality = (cfg and cfg.ItemQuality) or 0,
            colorID = 0,
            patternID = 0,
            expire_time = 0,
            obtain_time = os.time(),
            obtainTime = os.time()
        }
    end)
    local finalData = ok and result or nil
    __fakeItemDataCache[resId] = finalData or false
    return finalData
end

function isWorn(insId)
    if not DataMgr or type(DataMgr.rolewear) ~= "table" then return false end
    local strId = tostring(insId)
    for _, v in pairs(DataMgr.rolewear) do
        if tostring(v) == strId then return true end
    end
    return false
end

function mergeCustomWornToRolewear()
    if not DataMgr or type(DataMgr.rolewear) ~= "table" then return end

    local wornSet = {}
    for _, v in pairs(DataMgr.rolewear) do
        wornSet[tostring(v)] = true
    end
    for resId, _ in pairs(LSI.customWorn) do
        if isCustomItem(resId) and lobbyCatAllowed(resId) then
            local fakeId = tostring(fakeInstanceId(resId))
            if not wornSet[fakeId] then
                table.insert(DataMgr.rolewear, fakeId)
                wornSet[fakeId] = true
            end
        end
    end
end
_G.LobbyMergeCustomWorn = mergeCustomWornToRolewear

function setWornState(resId, worn)
    resId = tonumber(resId)
    if not resId then return end

    if worn then
        if not lobbyCatAllowed(resId) then
            LSI.customWorn[resId] = nil
            if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
                pcall(DataMgr.UpdateRoleWearData, "", tostring(fakeInstanceId(resId)))
            end
            return
        end
        local fakeData = buildFakeItemData(resId)
        if fakeData and fakeData.itemSubType then
            local subType = fakeData.itemSubType
            for rid, _ in pairs(LSI.customWorn) do
                local fr = buildFakeItemData(rid)
                if fr and fr.itemSubType == subType then
                    LSI.customWorn[rid] = nil
                end
            end
            LSI.customWorn[resId] = true

            if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
                pcall(DataMgr.UpdateRoleWearData, tostring(fakeInstanceId(resId)), "")
            else
                mergeCustomWornToRolewear()
            end
        end
    else
        LSI.customWorn[resId] = nil
        if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
            pcall(DataMgr.UpdateRoleWearData, "", tostring(fakeInstanceId(resId)))
        end
    end
end

function _G.LobbyUnwearCategory(cat)
    if not LSI or not LSI.customWorn then return end
    local H, OK = _G.LSI_WardRobeHandler, _G.LSI_OK_CODE
    for resId, _ in pairs(LSI.customWorn) do
        if isCustomItem(resId) then
            local c = getLobbyItemCategory(resId)
            local hit = (cat == "weapon" and c == "weapon") or (cat == "vehicle" and c == "vehicle") or (cat == "suit" and c == "suit")
            if hit then
                local fakeId = fakeInstanceId(resId)
                if H and type(H.on_depot_put_down_rsp) == "function" then
                    pcall(H.on_depot_put_down_rsp, OK, { res_id = resId, instid = fakeId }, fakeId)
                end
                if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
                    pcall(DataMgr.UpdateRoleWearData, "", tostring(fakeId))
                end
            end
        end
    end

    local AL = _G.LSI_AvatarLogic
    if AL and type(AL.InitCurrentWearPreviewMap) == "function" then
        pcall(AL.InitCurrentWearPreviewMap, AL, true)
    end
end

function _G.LobbyPurgeFakeByCategory(cat)
    if not DataMgr or type(DataMgr.rolewear) ~= "table" then return end
    local removed = {}
    for i = #DataMgr.rolewear, 1, -1 do
        local v = tonumber(DataMgr.rolewear[i])
        if v and v >= LSI.BASE_ID then
            local rid = v - LSI.BASE_ID
            if isCustomItem(rid) then
                local c = getLobbyItemCategory(rid)
                local hit = (cat == "weapon" and c == "weapon") or (cat == "vehicle" and c == "vehicle") or (cat == "suit" and c == "suit")
                if hit then
                    table.insert(removed, tostring(v))
                    table.remove(DataMgr.rolewear, i)
                end
            end
        end
    end
    if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
        for _, fid in ipairs(removed) do pcall(DataMgr.UpdateRoleWearData, "", fid) end
    end
end

function _G.AddCustomSkinItem(resId)
    resId = tonumber(resId)
    if not resId or resId == 0 then return false end
    if LSI.customSet and LSI.customSet[resId] then return true end

    for _, id in ipairs(CUSTOM_ITEM_IDS) do
        if id == resId then return true end
    end
    CUSTOM_ITEM_IDS[#CUSTOM_ITEM_IDS + 1] = resId
    if LSI.customSet then LSI.customSet[resId] = true end
    return true
end

function _G.RemoveCustomSkinItem(resId)
    resId = tonumber(resId)
    for i = #CUSTOM_ITEM_IDS, 1, -1 do
        if CUSTOM_ITEM_IDS[i] == resId then
            table.remove(CUSTOM_ITEM_IDS, i)
            LSI.fakeByRes[resId] = nil
            if LSI.customSet then LSI.customSet[resId] = nil end
            return true
        end
    end
    return false
end

function safeRequire(paths)
    for _, p in ipairs(paths) do
        local ok, mod = pcall(require, p)
        if ok and mod and type(mod) == "table" then
            return mod
        end
    end
    return nil
end

function hookValidTime()
    if LSI.validTimeHooked then return true end
    if not DataMgr or not DataMgr.IsValidTime then return false end
    if DataMgr.__expireTimeHooked then LSI.validTimeHooked = true return true end

    local original = DataMgr.IsValidTime
    DataMgr.IsValidTime = function(ts)
        if ts == nil or tonumber(ts) == 0 then
            return true
        end
        return original(ts)
    end
    DataMgr.__expireTimeHooked = true

    LSI.validTimeHooked = true
    return true
end

function _G.InjectLobbySkins()
    if LSI.applied then return true end

    hookValidTime()

    if not LSI.validTimeHooked and not LSI.validTimeTimer then
        LSI.validTimeTimer = true
        local ticker = _G.Mytimer_ticker or (_G.timer_ticker)
        if ticker and ticker.AddTimerLoop then
            ticker.AddTimerLoop(1, function()
                if not LSI.validTimeHooked then hookValidTime() end
            end, 5, 1)
        end
    end

    local ArmoryHandler = safeRequire({ "client.network.Protocol.ArmoryHandler", "Client.network.Protocol.ArmoryHandler" })
    if ArmoryHandler then
        local ArmorySystem = safeRequire({ "client.logic.armory.logic_armory", "Client.logic.armory.logic_armory" })
        if ArmorySystem then

            if ArmoryHandler.send_install_weapon_skin then
                local original = ArmoryHandler.send_install_weapon_skin
                ArmoryHandler.send_install_weapon_skin = function(client_data, weapon_id, instanceID)
                    if isFakeInstance(instanceID) then
                        ArmorySystem.install_weapon_skin_rsp(client_data, 0, weapon_id, tonumber(instanceID))
                        return
                    end
                    return original(client_data, weapon_id, instanceID)
                end
            end

            if ArmoryHandler.send_uninstall_weapon_skin then
                local original = ArmoryHandler.send_uninstall_weapon_skin
                ArmoryHandler.send_uninstall_weapon_skin = function(client_data, weapon_id)
                    local cur = ArmorySystem.rsp_list and ArmorySystem.rsp_list.install_list and ArmorySystem.rsp_list.install_list[weapon_id]
                    local skinId = cur and cur.skin_id
                    if skinId and isFakeInstance(skinId) then
                        ArmorySystem.uninstall_weapon_skin_rsp(client_data, 0, weapon_id)
                        return
                    end
                    return original(client_data, weapon_id)
                end
            end
        end
    end

    local WardrobeDataList = {}
    for _, path in ipairs({
        "client.slua.logic.wardrobe.wardrobe_data",
        "client.slua.logic.wardrobe.WardrobeData",
        "Client.slua.logic.wardrobe.wardrobe_data",
        "client.logic.wardrobe.wardrobe_data",
        "client.logic.wardrobe.WardrobeData",
        "Client.logic.wardrobe.wardrobe_data",
    }) do
        local m = safeRequire({ path })
        if type(m) == "table" then
            local dup = false
            for _, x in ipairs(WardrobeDataList) do if x == m then dup = true break end end
            if not dup then WardrobeDataList[#WardrobeDataList + 1] = m end
        end
    end

    for _, WardrobeData in ipairs(WardrobeDataList) do

        local function hookByResId(original, self, id)
            if isCustomItem(id) and lobbyCatAllowed(id) then
                local fakeData = buildFakeItemData(id)
                if fakeData then return fakeData end
            end
            return original(self, id)
        end

        local function hookByInsId(original, self, id)
            local realId = isFakeInstance(id)
            if realId and lobbyCatAllowed(realId) then
                local fakeData = buildFakeItemData(realId)
                if fakeData then return fakeData end
            end
            return original(self, id)
        end

        for _, name in ipairs({ "GetHallDepotItemDataByResIDAndValidExpireTime", "GetHallDepotItemDataByResID" }) do
            if WardrobeData[name] then
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, id) return hookByResId(original, self, id) end
            end
        end

        for _, name in ipairs({ "GetHallDepotItemDataByInsID", "GetValidHallDepotItemDataByInsID" }) do
            if WardrobeData[name] then
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, id) return hookByInsId(original, self, id) end
            end
        end

        if WardrobeData.GetArrayHallDepotItemInfo then
            local original = WardrobeData.GetArrayHallDepotItemInfo
            local maxAdd = LSI.MAX_CUSTOM_IN_LIST
            WardrobeData.GetArrayHallDepotItemInfo = function(self)
                local list = original(self) or {}
                if maxAdd == 0 then return list end

                local seenRes, seenIns = {}, {}
                for _, v in pairs(list) do
                    if v and type(v) == "table" then
                        local resId = v.resID or v.res_id or v.item_res_id
                        local insId = v.insID or v.ins_id
                        if resId then seenRes[tonumber(resId)] = true end
                        if insId then seenIns[tostring(insId)] = true end
                    end
                end

                local added = 0
                for i = 1, #CUSTOM_ITEM_IDS do
                    if added >= maxAdd then break end
                    local resId = CUSTOM_ITEM_IDS[i]
                    if type(resId) ~= "number" then resId = tonumber(resId) end
                    if resId and resId ~= 0 and lobbyCatAllowed(resId) then
                        local fakeId = fakeInstanceId(resId)
                        if not seenRes[resId] and not seenIns[tostring(fakeId)] then
                            local fakeData = buildFakeItemData(resId)
                            if fakeData and type(fakeData) == "table" then
                                table.insert(list, fakeData)
                                seenRes[resId] = true
                                seenIns[tostring(fakeId)] = true
                                added = added + 1
                            end
                        end
                    end
                end
                return list
            end
        end

        for _, name in ipairs({ "GetHallDepotItemCountByResIDAndValidInfo", "GetHallDepotItemCountByResID" }) do
            if WardrobeData[name] then
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, resId, ...)
                    return (isCustomItem(resId) and lobbyCatAllowed(resId)) and 1 or original(self, resId, ...)
                end
            end
        end

        for _, name in ipairs({ "HasItem", "HasValidItem" }) do
            if WardrobeData[name] then
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, id, ...)
                    local rid = isCustomItem(id) and tonumber(id) or isFakeInstance(id)
                    if rid then
                        if lobbyCatAllowed(rid) then return true end
                        return original(self, id, ...)
                    end
                    return original(self, id, ...)
                end
            end
        end
    end

    local WardRobeHandler = safeRequire({ "client.network.Protocol.WardRobeHandler", "Client.network.Protocol.WardRobeHandler" })
    if WardRobeHandler then
        local OK_CODE = (type(NetErrorCode_NONE) == "string" and NetErrorCode_NONE) or "ok"
        _G.LSI_WardRobeHandler = WardRobeHandler
        _G.LSI_OK_CODE = OK_CODE

        if WardRobeHandler.send_depot_put_on_req then
            local original = WardRobeHandler.send_depot_put_on_req
            WardRobeHandler.send_depot_put_on_req = function(insId)
                local realId = isFakeInstance(insId)
                if realId then
                    if not lobbyCatAllowed(realId) then return end
                    insId = tonumber(insId)
                    if isWorn(insId) then
                        if WardRobeHandler.on_depot_put_down_rsp then
                            WardRobeHandler.on_depot_put_down_rsp(OK_CODE, { res_id = realId, instid = insId }, insId)
                            setWornState(realId, false)

                            pcall(function()
                                local rid = tonumber(realId)
                                if rid and ((rid >= 4531000 and rid < 4532000) or (rid >= 4541000 and rid < 4542000)) then
                                    local T = _G.GoldenLeavesTrail
                                    if T then
                                        T.Enabled = false
                                        if T.Stop then pcall(T.Stop) end
                                    end
                                    if _G.PGHACKS1_Config and _G.PGHACKS1_Config.Set then
                                        pcall(_G.PGHACKS1_Config.Set, "TRAIL_ENABLE", 0)
                                    end
                                end
                            end)
                        end
                        return
                    end
                    local fakeData = buildFakeItemData(realId)
                    if fakeData then
                        local item = {
                            res_id = realId,
                            instid = insId,
                            color = fakeData.colorID or 0,
                            pattern = fakeData.patternID or 0,
                            color_id = fakeData.colorID or 0,
                            pattern_id = fakeData.patternID or 0
                        }
                        if WardRobeHandler.on_depot_put_on_rsp then
                            WardRobeHandler.on_depot_put_on_rsp(OK_CODE, item, nil, nil, insId, nil)
                            setWornState(realId, true)

                            pcall(function()
                                local rid = tonumber(realId)
                                if rid and ((rid >= 4531000 and rid < 4532000) or (rid >= 4541000 and rid < 4542000)) then
                                    local T = _G.GoldenLeavesTrail
                                    if T then
                                        T.TRAIL_ITEM_ID = rid
                                        T.Enabled = true
                                        if T.Apply then pcall(T.Apply) end
                                    end
                                    if _G.PGHACKS1_Config and _G.PGHACKS1_Config.Set then
                                        pcall(_G.PGHACKS1_Config.Set, "TRAIL_TYPE", rid)
                                        pcall(_G.PGHACKS1_Config.Set, "TRAIL_ENABLE", 1)
                                    end
                                end
                            end)
                        end
                    end
                    return
                end
                return original(insId)
            end
        end

        if WardRobeHandler.send_depot_put_down_req then
            local original = WardRobeHandler.send_depot_put_down_req
            WardRobeHandler.send_depot_put_down_req = function(insId)
                local realId = isFakeInstance(insId)
                if realId then
                    if WardRobeHandler.on_depot_put_down_rsp then
                        WardRobeHandler.on_depot_put_down_rsp(OK_CODE, { res_id = realId, instid = tonumber(insId) }, insId)
                        setWornState(realId, false)

                        pcall(function()
                            local rid = tonumber(realId)
                            if rid and ((rid >= 4531000 and rid < 4532000) or (rid >= 4541000 and rid < 4542000)) then
                                local T = _G.GoldenLeavesTrail
                                if T then
                                    T.Enabled = false
                                    if T.Stop then pcall(T.Stop) end
                                end
                                if _G.PGHACKS1_Config and _G.PGHACKS1_Config.Set then
                                    pcall(_G.PGHACKS1_Config.Set, "TRAIL_ENABLE", 0)
                                end
                            end
                        end)
                    end
                    return
                end
                return original(insId)
            end
        end
    end

    local AvatarLogic = safeRequire({ "client.slua.logic.wardrobe.logic_wardrobe_avatar", "Client.slua.logic.wardrobe.logic_wardrobe_avatar" })
    if AvatarLogic and AvatarLogic.InitCurrentWearPreviewMap then
        _G.LSI_AvatarLogic = AvatarLogic
        local original = AvatarLogic.InitCurrentWearPreviewMap
        AvatarLogic.InitCurrentWearPreviewMap = function(self, force)
            original(self, force)
            for resId, _ in pairs(LSI.customWorn) do
                if isCustomItem(resId) and lobbyCatAllowed(resId) then
                    local fakeData = buildFakeItemData(resId)
                    if fakeData and fakeData.itemSubType and AvatarLogic.AddToWearInfo then
                        AvatarLogic:AddToWearInfo(fakeData.itemSubType, tostring(fakeInstanceId(resId)), resId, fakeData.colorID or 0, fakeData.patternID or 0)
                    end
                end
            end
        end
    end

    LSI.customSet = {}
    for _, id in ipairs(CUSTOM_ITEM_IDS) do
        if type(id) == "number" and id ~= 0 then
            LSI.customSet[id] = true
        end
    end

    mergeCustomWornToRolewear()

    local fashionbagData = safeRequire({ "client.slua.logic.wardrobe.fashionbag.fashionbag_data", "Client.slua.logic.wardrobe.fashionbag.fashionbag_data" })
    if fashionbagData and fashionbagData.OnSelectFashionBag then
        local original = fashionbagData.OnSelectFashionBag
        fashionbagData.OnSelectFashionBag = function(self, index)
            if type(original) == "function" then original(self, index) end
            pcall(mergeCustomWornToRolewear)
        end
    end

    local AvatarDataUtil = safeRequire({ "GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil", "client.logic.avatar.AvatarDataUtil" })
    if AvatarDataUtil and AvatarDataUtil.GetAvatarStandaloneData then
        local original = AvatarDataUtil.GetAvatarStandaloneData
        if type(original) == "function" then
            AvatarDataUtil.GetAvatarStandaloneData = function()
                local info, hasData = original()
                if type(info) == "table" and type(info.wear_ext) == "table" then
                    for resId, _ in pairs(LSI.customWorn) do
                        if isCustomItem(resId) and lobbyCatAllowed(resId) then
                            local fakeData = buildFakeItemData(resId)
                            if fakeData and (fakeData.resID or fakeData.res_id) then
                                local rid = fakeData.resID or fakeData.res_id
                                table.insert(info.wear_ext, { rid, fakeData.colorID or 0, fakeData.patternID or 0 })
                                hasData = true
                            end
                        end
                    end
                end
                return info, hasData
            end
        end
    end

    LSI.applied = true
    return true
end

_G.Mytimer_ticker = TXtime_ticker

pcall(function()
    _G.InjectLobbySkins()

    if _G.Mytimer_ticker then
        if _G.__loopGuard19170 and _G.Mytimer_ticker.IsRunning and _G.Mytimer_ticker.IsRunning(_G.__loopGuard19170) then _G.Mytimer_ticker.RemoveTimer(_G.__loopGuard19170) end
        _G.__loopGuard19170 =         _G.Mytimer_ticker.AddTimerLoop(2, function()

            local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
            if okF and inFight then return end
            pcall(function()
                if _G.LobbySkinInjector and _G.LobbySkinInjector.customWorn and next(_G.LobbySkinInjector.customWorn) ~= nil then
                    if DataMgr and type(DataMgr.rolewear) == "table" then

                        local wornSet = {}
                        for _, v in pairs(DataMgr.rolewear) do
                            wornSet[tostring(v)] = true
                        end
                        for resId, _ in pairs(_G.LobbySkinInjector.customWorn) do
                            local catOk = (not _G.LobbyCatAllowed) or _G.LobbyCatAllowed(resId)
                            local fakeId = tostring(900000000 + tonumber(resId))
                            if catOk and not wornSet[fakeId] then
                                table.insert(DataMgr.rolewear, fakeId)
                                wornSet[fakeId] = true
                            end
                        end
                    end
                end
            end)
        end, -1, 1)
    end
end)

end

do

do
    local function postWardrobeRefresh()
        pcall(function()
            if not EventSystem or not EVENTTYPE_WARDROBE then return end
            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
            end
        end)
        pcall(function()
            if EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_HALL_DEPOT_DATA then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_DATA)
            end
        end)
    end
    if _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimer then
        for _, delay in ipairs({ 2, 5, 10, 18, 30 }) do
            _G.Mytimer_ticker.AddTimer(delay, postWardrobeRefresh)
        end
    end
end

do
    local function collectPreloadIds()
        local ids, seen = {}, {}
        local function add(id)
            id = tonumber(id)
            if id and id > 0 and not seen[id] then
                seen[id] = true
                ids[#ids + 1] = id
            end
        end
        local keys = { "HairSkin", "SuitSkin", "HatSkin", "FaceSkin", "MaskSkin", "GlovesSkin",
            "PantSkin", "ShoeSkin", "ParachuteSkin", "GliderSkin",
            "Backpack1Skin", "Backpack2Skin", "Backpack3Skin", "Backpack4Skin", "Backpack5Skin", "Backpack6Skin",
            "Helmet1Skin", "Helmet2Skin", "Helmet3Skin", "Helmet4Skin", "Helmet5Skin", "Helmet6Skin",
            "Armor1Skin", "Armor2Skin", "Armor3Skin", "Armor4Skin", "Armor5Skin", "Armor6Skin" }
        for _, k in ipairs(keys) do add(_G[k]) end
        if type(_G.WeaponSkinID) == "table" then
            for _, v in pairs(_G.WeaponSkinID) do add(v) end
        end

        if type(_G.WeaponSkinPack) == "table" then
            for _, packs in pairs(_G.WeaponSkinPack) do
                if type(packs) == "table" then
                    for _, pack in pairs(packs) do
                        if type(pack) == "table" then
                            add(pack.main)
                            if type(pack.attachments) == "table" then
                                for _, skinPartId in pairs(pack.attachments) do add(skinPartId) end
                            end
                        end
                    end
                end
            end
        end
        if type(_G.DeadBoxSkins) == "table" then
            for _, v in pairs(_G.DeadBoxSkins) do add(v) end
        end
        if type(_G.CustomVehicleSkinID) == "table" then
            for _, v in pairs(_G.CustomVehicleSkinID) do add(v) end
        end
        return ids
    end

    if _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimer then
        _G.Mytimer_ticker.AddTimer(8, function()
            local ids = collectPreloadIds()
            if #ids == 0 then return end
            local idx = 0

            if _G.__loopGuard19275 and _G.Mytimer_ticker.IsRunning and _G.Mytimer_ticker.IsRunning(_G.__loopGuard19275) then _G.Mytimer_ticker.RemoveTimer(_G.__loopGuard19275) end
            _G.__loopGuard19275 =             _G.Mytimer_ticker.AddTimerLoop(0.3, function()
                idx = idx + 1
                if idx > #ids then return end
                pcall(_G.download_item, ids[idx])
            end, #ids, 0.3)
        end)
    end
end

if _G.__MOD_SYSTEM_LOADED__ then
    return
end
_G.__MOD_SYSTEM_LOADED__ = true

PufferManager = require("client.slua.logic.download.puffer.puffer_manager")
PufferConst = require("client.slua.logic.download.puffer_const")
SKillInfo = require("GameLua.Mod.BaseMod.Client.KillInfoTips.KillInfo")
ECharacterHealthStatus = import("ECharacterHealthStatus")
UEnums = _ENV.UEnums

_G.__ModTeamKillSkinID = _G.__ModTeamKillSkinID or 0
TEAM_KILL_SUB_EFFECT = 22

function pufferDownload(id)
    if not id or id == 0 then return end
    local state = PufferManager.GetState(PufferConst.ENUM_DownloadType.ODPAK, {id})
    if state ~= PufferConst.ENUM_DownloadState.Done then
        PufferManager.Download(PufferConst.ENUM_DownloadType.ODPAK, {id})
    end
end

_dlElimTs = {}
function downloadEliminationAssets(skinID)

    local nowT = (os and os.clock and os.clock()) or 0
    local lastT = _dlElimTs[skinID]
    if lastT and nowT - lastT < 10 then return end
    _dlElimTs[skinID] = nowT
    pufferDownload(skinID)
    local cfg = CDataTable.GetTableData("WeaponAvatarBattleEffect", skinID)
    if cfg then
        if cfg.EffectPath and cfg.EffectPath ~= "" then pufferDownload(cfg.EffectPath) end
        if cfg.BgPath and cfg.BgPath ~= "" then pufferDownload(cfg.BgPath) end
    end
end

function downloadTeamAssets(skinID)
    pufferDownload(skinID)
    local cfg = CDataTable.GetTableData("TeamKillBroadcast", skinID)
    if cfg then
        if cfg.EffectPath and cfg.EffectPath ~= "" then pufferDownload(cfg.EffectPath) end
        if cfg.BgPath and cfg.BgPath ~= "" then pufferDownload(cfg.BgPath) end
    end
end

_G.download_item = downloadEliminationAssets

end

do

FakeFriendState = { installed = false, profiles = {} }

function FF_ConfigEnabled()
  local ok, v = pcall(function() return tonumber(_G.PGHACKS1_Config.Get("CI_FAKEFRIEND_EN", 0)) end)
  return ok and v == 1
end

function FF_GetIDs()
  local list, seen = {}, {}
  for i = 1, 5 do
    local ok, id = pcall(function() return tonumber(_G.PGHACKS1_Config.Get("CI_FAKEFRIEND_ID" .. i, 0)) end)
    if ok and id and id > 0 and not seen[id] then
      seen[id] = true
      table.insert(list, id)
    end
  end
  return list
end

function FF_IsFake(uid)
  uid = tostring(uid or "")
  if uid == "" then return false end
  for _, id in ipairs(FF_GetIDs()) do
    if uid == tostring(id) then return true end
  end
  return false
end

function FF_CreateProfile(uid)
  local uidStr = tostring(uid)
  local p = FakeFriendState.profiles[uidStr]
  if p then return p end
  p = {
    uid = uid, _uid = uid,
    nickName = uidStr, gameName = uidStr, platName = uidStr,
    picUrl = "", headIconUrl = "",
    sex = 0, level = 1, cur_avatar_box_id = 0,
    lastOnlineTime = 0, isInit = true, isFakeFriend = true,
  }
  FakeFriendState.profiles[uidStr] = p
  return p
end

function FF_FullInfo(uid)
  local p = FF_CreateProfile(uid)
  return {
    uid = p.uid, UID = p.uid,
    name = p.nickName, nickName = p.nickName,
    picUrl = "", headIconUrl = "",
    sex = 0, level = 1, cur_avatar_box_id = 0,
    intimacy = 0, online = 1, is_online = 1,
    teamState = 0, lastOnlineTime = 0, from = 0,
    isFakeFriend = true,
  }
end

function FF_InjectList(friendList)
  if not FF_ConfigEnabled() then return friendList end
  if type(friendList) ~= "table" then friendList = {} end
  local seen = {}
  for _, f in ipairs(friendList) do
    if type(f) == "table" then seen[tostring(f.uid or f.UID)] = true end
  end
  for _, id in ipairs(FF_GetIDs()) do
    if not seen[tostring(id)] then
      table.insert(friendList, FF_FullInfo(id))
      seen[tostring(id)] = true
    end
  end
  return friendList
end

function InstallFakeFriendHook()
  if FakeFriendState.installed then return true end
  local friendLogic
  pcall(function() friendLogic = require("FriendLogic") end)

  if not (friendLogic and (type(friendLogic.GetFriendList) == "function" or type(friendLogic.GetAllFriendList) == "function" or type(friendLogic.GetFriendData) == "function")) then
    friendLogic = nil
    pcall(function()
      local ModuleManager = require("client.module_framework.ModuleManager")
      local m = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.logic_friend)
      if m and (type(m.GetFriendList) == "function" or type(m.GetAllFriendList) == "function" or type(m.GetFriendData) == "function") then
        friendLogic = m
      end
    end)
  end
  if not friendLogic then return false end
  local function hook(name, wrapper)
    if type(friendLogic[name]) == "function" and not friendLogic["__FFOrig_" .. name] then
      friendLogic["__FFOrig_" .. name] = friendLogic[name]
      friendLogic[name] = wrapper
    end
  end
  hook("GetFriendList", function(...)
    local orig = friendLogic.__FFOrig_GetFriendList
    return FF_InjectList(orig and orig(...) or {})
  end)
  hook("GetAllFriendList", function(...)
    local orig = friendLogic.__FFOrig_GetAllFriendList
    return FF_InjectList(orig and orig(...) or {})
  end)
  hook("GetFriendData", function(uid, ...)
    local orig = friendLogic.__FFOrig_GetFriendData
    local data = orig and orig(uid, ...)
    if data then return data end
    if FF_ConfigEnabled() and FF_IsFake(uid) then return FF_CreateProfile(uid) end
    return nil
  end)
  hook("GetAllFriendData", function(...)
    local orig = friendLogic.__FFOrig_GetAllFriendData
    local data = orig and orig(...) or {}
    if FF_ConfigEnabled() then
      for _, id in ipairs(FF_GetIDs()) do
        if not data[id] then data[id] = FF_CreateProfile(id) end
      end
    end
    return data
  end)
  hook("IsMyFriend", function(uid, ...)
    if FF_ConfigEnabled() and FF_IsFake(uid) then return true end
    local orig = friendLogic.__FFOrig_IsMyFriend
    return orig and orig(uid, ...) or false
  end)
  hook("IsInnerFriend", function(uid, ...)
    if FF_ConfigEnabled() and FF_IsFake(uid) then return true end
    local orig = friendLogic.__FFOrig_IsInnerFriend
    return orig and orig(uid, ...) or false
  end)
  FakeFriendState.installed = true
  return true
end
_G.InstallFakeFriendHook = InstallFakeFriendHook

    if not InstallFakeFriendHook() then
        local ffTicker = _G.Mytimer_ticker or _G.time_ticker
        if ffTicker and ffTicker.AddTimer then
            for _, sec in ipairs({ 2, 5, 10, 20, 40 }) do
                ffTicker.AddTimer(sec, function() pcall(InstallFakeFriendHook) end)
            end
        end
    end

end


function ensureBagInject()

    M.getEntity = function()
        local ok, dc = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_data_center")
        if not ok or not dc then return nil end
        local ok2, e = pcall(dc.GetWardrobeData)
        return (ok2 and e) or nil
    end

    M.firstIns = M.firstIns or function(entity, resID)
        local arr = entity and entity.ResIDToIndexArrayMap and entity.ResIDToIndexArrayMap[resID]
        if not arr then return nil end
        for _, idx in pairs(arr) do
            local d = entity._data and entity._data[idx]
            if d and d.count and d.count > 0 then return d.insID end
        end
        return nil
    end

    M.allocIns = M.allocIns or function(entity, resID, preferred)
        preferred = tonumber(preferred)
        if R.resToIns[resID] then return R.resToIns[resID] end
        local owned = M.firstIns(entity, resID)
        if owned then return owned end
        if preferred and preferred > 0 and entity.InsIDToIndexMap and not entity.InsIDToIndexMap[preferred] then
            return preferred
        end
        for off = 1, 8000 do
            local id = INS_BASE + off
            if not entity.InsIDToIndexMap or not entity.InsIDToIndexMap[id] then return id end
        end
        return INS_BASE + (os.time() % 100000)
    end

    M.clearItemExpire = M.clearItemExpire or function(itemData, insID, resID, heavy)
        insID = tonumber(insID or (itemData and (itemData.ins_id or itemData.insID or itemData.instid)))
        resID = tonumber(resID or (itemData and (itemData.res_id or itemData.resID or itemData.resId)))
        if itemData then
            itemData.expireTS = 0
            itemData.expire_ts = 0
            itemData.validHours = 999999
            itemData.valid_hours = 999999
            itemData.obtain_time = os.time()
            itemData.obtainTime = os.time()
            if itemData.hasLimitTime ~= nil then itemData.hasLimitTime = false end
            if itemData.LimitTimeEnd ~= nil then itemData.LimitTimeEnd = 0 end
        end
        local entity = M.getEntity and M.getEntity()
        local d = entity and insID and entity.GetDataByInsID and entity:GetDataByInsID(insID)
        if d then
            d.expireTS = 0
            d.validHours = 999999
            d.expire_ts = 0
            d.valid_hours = 999999
            d.obtain_time = os.time()
            d.obtainTime = os.time()
            if (tonumber(d.count) or 0) < 1 then d.count = 1 end
            if heavy and resID then
                pcall(function() entity:LoadConfigForData(d, CDataTable.GetTableData) end)
                d.expireTS = 0
                d.validHours = 999999
                d.valid_hours = 999999
                d.obtain_time = os.time()
            end
        end
    end

    M.unexpireAllDepot = M.unexpireAllDepot or function()
        local entity = M.getEntity and M.getEntity()
        if not entity or not entity._data then return end
        for i = 1, entity._DataCount or 0 do
            local d = entity._data[i]
            if d and (d.count or 0) > 0 then
                d.expireTS = 0
                d.validHours = 999999
                d.expire_ts = 0
                d.valid_hours = 999999
                d.obtain_time = os.time()
                d.obtainTime = os.time()
            end
        end
    end

    M.ensureItem = M.ensureItem or function(entity, insID, resID)
        insID, resID = tonumber(insID), tonumber(resID)
        if not entity or not insID then return end
        local d = entity.GetDataByInsID and entity:GetDataByInsID(insID)
        if not d then return end
        d.count = math.max(tonumber(d.count) or 0, 1)
        pcall(function()
            entity:LoadConfigForData(d, CDataTable.GetTableData)
        end)

        d.expireTS = 0
        d.validHours = 999999
        d.expire_ts = 0
        d.valid_hours = 999999
        d.obtain_time = os.time()
        d.obtainTime = os.time()
        if d.hasLimitTime ~= nil then d.hasLimitTime = false end
    end

    M.isAvatarFrame = M.isAvatarFrame or function(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        local ok = false
        pcall(function()
            if CDataTable.GetTableData("AvatarFrame", resID) then ok = true end
        end)
        if ok then return true end
        pcall(function()
            local cfg = CDataTable.GetTableData("Item", resID)
            if cfg and tonumber(cfg.ItemSubType) == 2002 then ok = true end
        end)
        return ok
    end

    M.injectAvatarFrame = M.injectAvatarFrame or function(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        pcall(function()
            local RoleInfoAvatarFrameSystem = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
            RoleInfoAvatarFrameSystem.AvatarFrameList = RoleInfoAvatarFrameSystem.AvatarFrameList or {}
            RoleInfoAvatarFrameSystem.AvatarFrameList[resID] = RoleInfoAvatarFrameSystem.AvatarFrameList[resID] or {}
            RoleInfoAvatarFrameSystem.AvatarFrameList[resID].expire_time = 1
            pcall(function() RoleInfoAvatarFrameSystem.OnHeadFrameNotify(resID, 1) end)
        end)
        CFG.avatarFrames = CFG.avatarFrames or {}
        local found = false
        for _, id in ipairs(CFG.avatarFrames) do
            if tonumber(id) == resID then found = true break end
        end
        if not found then table.insert(CFG.avatarFrames, resID) end
        return true
    end

    M.notifyDepotNew = M.notifyDepotNew or function(insID, resID, count)
        insID, resID = tonumber(insID), tonumber(resID)
        if not insID or not resID then return end
        count = math.max(1, tonumber(count) or 1)
        pcall(function()
            local changeList = {
                [insID] = {
                    instid = insID, res_id = resID, count = count, isnew = 1,
                    lock_cnt = 0, valid_hours = 0, expire_ts = 0,
                }
            }
            if EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_HALL_DEPOT_ADD then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_ADD, changeList)
            elseif EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_HALL_DEPOT_DATA then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_DATA, changeList)
            end
        end)
    end

    M.weaponIdFromSkin = M.weaponIdFromSkin or function(resID)
        local wid
        pcall(function()
            local cfg = CDataTable.GetTableData("WeaponSkin", resID)
                or CDataTable.GetTableData("WeaponAvatar", resID)
            if cfg then
                wid = tonumber(cfg.WeaponID or cfg.weapon_id or cfg.WeaponId)
            end
        end)
        return wid
    end

    M.injectArmory = M.injectArmory or function(resID, insID)
        resID, insID = tonumber(resID), tonumber(insID)
        if not resID or not insID then return end
        local wid = M.weaponIdFromSkin(resID)
        if not wid then return end
        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            Arm.rsp_list = Arm.rsp_list or {}
            Arm.rsp_list.skin_list = Arm.rsp_list.skin_list or {}
            Arm.rsp_list.skin_list[wid] = Arm.rsp_list.skin_list[wid] or {}
            Arm.rsp_list.skin_list[wid][resID] = insID
            if Arm.ContructResIdToWardrobeInsID then Arm.ContructResIdToWardrobeInsID() end
        end)
    end

    M.refreshWardrobe = M.refreshWardrobe or function(force)
        pcall(function()
            if not EventSystem or not EVENTTYPE_WARDROBE then return end
            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
            end
        end)
    end

    M.loadConfig = M.loadConfig or function() end
    M.saveConfigNow = M.saveConfigNow or function()

        pcall(function()
            CFG.extraItems = CFG.extraItems or {}
            CFG.itemCounts = CFG.itemCounts or {}
            _G.pghacksConfig = _G.pghacksConfig or {}
            local bag = { extraItems = {}, itemCounts = {} }
            for i, id in ipairs(CFG.extraItems) do
                bag.extraItems[i] = tonumber(id) or 0
            end
            for k, v in pairs(CFG.itemCounts) do
                bag.itemCounts[tostring(k)] = tonumber(v) or 1
            end
            _G.pghacksConfig.LizardVipCrateBag = bag
            if _G.SaveModSettings then _G.SaveModSettings() end
        end)
    end
    M.persistMarkDirty = M.persistMarkDirty or function()
        if M.later then
            M.later(0.4, function() pcall(M.saveConfigNow) end)
        else
            pcall(M.saveConfigNow)
        end
    end

    M.rememberBagItem = M.rememberBagItem or function(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return end
        CFG.extraItems = CFG.extraItems or {}
        CFG.itemCounts = CFG.itemCounts or {}
        local found = false
        for _, id in ipairs(CFG.extraItems) do
            if tonumber(id) == resID then found = true break end
        end
        if not found then
            table.insert(CFG.extraItems, resID)
        end
        if (tonumber(CFG.itemCounts[resID]) or 0) < 1 then
            CFG.itemCounts[resID] = 1
        end
        M.persistMarkDirty()
    end

    if type(M.injectOne) ~= "function" then
        M.injectOne = function(entity, resID, insID, opts)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return false end
            opts = type(opts) == "table" and opts or {}
            local markNew = opts.markNew == true
            local addCount = tonumber(opts.addCount) or 1
            if addCount < 1 then addCount = 1 end
            local forceCount = tonumber(opts.forceCount)

            if M.isAvatarFrame(resID) then
                M.injectAvatarFrame(resID)
            end
            if not entity then
                return M.isAvatarFrame(resID)
            end

            CFG.itemCounts = CFG.itemCounts or {}
            CFG.newItems = CFG.newItems or {}

            insID = M.allocIns(entity, resID, insID)
            local owned = M.firstIns(entity, resID)
            if owned then
                R.resToIns[resID], R.insToRes[owned] = owned, resID
                local d = entity.GetDataByInsID and entity:GetDataByInsID(owned)
                if d then
                    local cur = tonumber(d.count) or 0
                    local newCount = forceCount or (cur + addCount)
                    d.count = newCount
                    d.expireTS = 0
                    d.validHours = 999999
                    d.valid_hours = 999999
                    d.expire_ts = 0
                    d.obtain_time = os.time()
                    d.obtainTime = os.time()
                    CFG.itemCounts[resID] = newCount
                    if markNew then
                        d.isNew = true
                        CFG.newItems[resID] = true
                        M.notifyDepotNew(owned, resID, newCount)
                    end
                end
                M.ensureItem(entity, owned, resID)
                M.clearItemExpire(nil, owned, resID, false)
                if M.weaponIdFromSkin(resID) then M.injectArmory(resID, owned) end
                M.persistMarkDirty()
                return true
            end

            if entity.InsIDToIndexMap and entity.InsIDToIndexMap[insID] then
                insID = M.allocIns(entity, resID, nil)
            end
            entity:AddData({
                instid = insID, res_id = resID, count = addCount, lock_cnt = 0,
                isnew = markNew and 1 or 0, valid_hours = 999999, expire_ts = 0,
                obtain_time = os.time(),
            })
            M.ensureItem(entity, insID, resID)
            M.clearItemExpire(nil, insID, resID, false)
            local d2 = entity.GetDataByInsID and entity:GetDataByInsID(insID)
            if d2 then
                d2.count = addCount
                d2.isNew = markNew
                d2.expireTS = 0
                d2.validHours = 999999
                d2.expire_ts = 0
                d2.valid_hours = 999999
                d2.obtain_time = os.time()
                d2.obtainTime = os.time()
            end
            CFG.itemCounts[resID] = addCount
            R.resToIns[resID], R.insToRes[insID] = insID, resID
            if M.weaponIdFromSkin(resID) then M.injectArmory(resID, insID) end
            if markNew then
                CFG.newItems[resID] = true
                M.notifyDepotNew(insID, resID, addCount)
            end
            M.persistMarkDirty()
            return true
        end
    end

    M.syncCollectFromMemory = M.syncCollectFromMemory or function() end
    M.reapplyAvatarFrames = M.reapplyAvatarFrames or function() end
    M.buildSavePayload = M.buildSavePayload or function()
        return {
            extraItems = CFG.extraItems,
            itemCounts = CFG.itemCounts,
            luckyTotalDraw = CFG.luckyTotalDraw,
            luckyClaimed = CFG.luckyClaimed,
            avatarFrames = CFG.avatarFrames,
        }
    end
    M.applyConfigTable = M.applyConfigTable or function(data)
        if type(data) ~= "table" then return end
        if type(data.extraItems) == "table" then CFG.extraItems = data.extraItems end
        if type(data.itemCounts) == "table" then CFG.itemCounts = data.itemCounts end
        if type(data.luckyTotalDraw) == "table" then CFG.luckyTotalDraw = data.luckyTotalDraw end
        if type(data.luckyClaimed) == "table" then CFG.luckyClaimed = data.luckyClaimed end
        if type(data.avatarFrames) == "table" then CFG.avatarFrames = data.avatarFrames end
    end
end

ensureBagInject()

NET_OK = NetErrorCode_NONE or "ok"

function installExpireAndWear()

    if not _G.__LocalCrateExpireHooked then
        _G.__LocalCrateExpireHooked = true
        pcall(function()
            if DataMgr then
                DataMgr.IsValidTime = function() return true end
            end
        end)
        pcall(function()
            local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
            wl.IsWearValid = function() return true end
            local oPage = wl.IsValidCurrentPageItem
            wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, serverTime)
                if v then
                    v.expireTS = 0; v.validHours = 999999
                    v.expire_ts = 0; v.valid_hours = 999999
                    v.obtain_time = os.time(); v.obtainTime = os.time()
                end
                if oPage then return oPage(self, mainTab, subTab, v, serverTime) end
                return true
            end
            local oGroup = wl.IsValidCurrentPageItemBySubTabGroup
            wl.IsValidCurrentPageItemBySubTabGroup = function(self, mainTab, subTabGroup, v, serverTime)
                if v then
                    v.expireTS = 0; v.validHours = 999999
                    v.expire_ts = 0; v.valid_hours = 999999
                    v.obtain_time = os.time(); v.obtainTime = os.time()
                end
                if oGroup then return oGroup(self, mainTab, subTabGroup, v, serverTime) end
                return true
            end
            if wl.IsItemExpire then wl.IsItemExpire = function() return false end end
            if wl.IsExpire then wl.IsExpire = function() return false end end
            if wl.CheckItemExpire then wl.CheckItemExpire = function() return false end end
        end)
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local oGet = wd.GetHallDepotItemDataByInsID
            if type(oGet) == "function" then
                wd.GetValidHallDepotItemDataByInsID = function(self, insID)
                    local d = oGet(self, insID)
                    if not d then return d end
                    d.expireTS = 0
                    d.validHours = 999999
                    d.expire_ts = 0
                    d.valid_hours = 999999
                    d.obtain_time = os.time()
                    d.obtainTime = os.time()
                    return d
                end

                if not wd.__localExpireGetHooked then
                    wd.__localExpireGetHooked = true
                    wd.GetHallDepotItemDataByInsID = function(self, insID)
                        local d = oGet(self, insID)
                        if d then
                            d.expireTS = 0
                            d.validHours = 999999
                            d.expire_ts = 0
                            d.valid_hours = 999999
                            d.obtain_time = os.time()
                            d.obtainTime = os.time()
                        end
                        return d
                    end
                end
            end
        end)
    end

    if not _G.__LocalCrateWearHooked then
        _G.__LocalCrateWearHooked = true
        pcall(function()
            local WRH = require("client.network.Protocol.WardRobeHandler")
            if not WRH or WRH.__localCratePutOn then return end
            WRH.__localCratePutOn = true
            local oSend = WRH.send_depot_put_on_req
            WRH.send_depot_put_on_req = function(insID, extra)
                insID = tonumber(insID)
                if not insID then
                    return oSend(insID, extra)
                end
                local itemData
                pcall(function()
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    itemData = wd:GetHallDepotItemDataByInsID(insID)
                end)
                if not itemData and R and R.insToRes and R.insToRes[insID] then
                    itemData = { resID = R.insToRes[insID], res_id = R.insToRes[insID], count = 1 }
                end

                if not itemData and insID >= 900000000 then
                    local rid = insID - 900000000
                    local okRid = false
                    pcall(function() okRid = (M.weaponIdFromSkin and M.weaponIdFromSkin(rid)) ~= nil end)
                    if not okRid and CFG and CFG.itemCounts and CFG.itemCounts[rid] then okRid = true end
                    if okRid then
                        itemData = { resID = rid, res_id = rid, count = 1 }
                    end
                end
                if itemData then
                    M.clearItemExpire(itemData, insID, itemData.resID or itemData.res_id, true)
                    local resID = tonumber(itemData.resID or itemData.res_id) or 0
                    local ours = (insID >= INS_BASE)
                        or (R.insToRes and R.insToRes[insID] ~= nil)
                        or (resID > 0 and R.resToIns and R.resToIns[resID] ~= nil)
                        or (CFG.extraItems and (function()
                            for _, id in ipairs(CFG.extraItems) do
                                if tonumber(id) == resID then return true end
                            end
                            return false
                        end)())
                    if ours then
                        local item = { res_id = resID, count = itemData.count or 1 }
                        pcall(function()
                            WRH.on_depot_put_on_rsp(NET_OK, item, nil, 3, insID, 0, extra)
                        end)
                        return
                    end
                end
                return oSend(insID, extra)
            end

            local oPutDown = WRH.send_depot_put_down_req
            if type(oPutDown) == "function" then
                WRH.send_depot_put_down_req = function(insID)
                    insID = tonumber(insID)
                    if not insID then return oPutDown(insID) end
                    local itemData
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        itemData = wd:GetHallDepotItemDataByInsID(insID)
                    end)
                    if not itemData and insID >= 900000000 then
                        local rid = insID - 900000000
                        local okRid = false
                        pcall(function() okRid = (M.weaponIdFromSkin and M.weaponIdFromSkin(rid)) ~= nil end)
                        if not okRid and CFG and CFG.itemCounts and CFG.itemCounts[rid] then okRid = true end
                        if okRid then
                            itemData = { resID = rid, res_id = rid, count = 1 }
                        end
                    end
                    if itemData then
                        local resID = tonumber(itemData.resID or itemData.res_id) or 0
                        local ours = (insID >= INS_BASE)
                            or (R.insToRes and R.insToRes[insID] ~= nil)
                            or (resID > 0 and CFG.itemCounts and CFG.itemCounts[resID])
                        if ours then
                            local item = { res_id = resID, count = itemData.count or 1 }
                            pcall(function() WRH.on_depot_put_down_rsp(NET_OK, item, insID) end)
                            return
                        end
                    end
                    return oPutDown(insID)
                end
            end
        end)
    end

    pcall(function() M.unexpireAllDepot() end)
end

installExpireAndWear()
M.later(1.0, installExpireAndWear)
M.later(3.0, installExpireAndWear)

pcall(function()
    local avatarClass = require("client.slua.umg.Wardrobe.subtab_avatar")
    local gunClass = require("client.slua.umg.Wardrobe.subtab_gun")
    local function wrapClick(classMod, key)
        if not classMod or not classMod.__inner_impl or not classMod.__inner_impl[key] then return end
        local impl = classMod.__inner_impl
        if impl["_LocalWrap_" .. key] then return end
        impl["_LocalWrap_" .. key] = true
        local orig = impl[key]
        impl[key] = function(self, widget, index)
            local grid = self.LoopScrollGrid_Normal or self.LoopScrollGridSkins
            local itemData = grid and grid.GetItemData and grid:GetItemData(index)
            if itemData then
                pcall(M.clearItemExpire, itemData, itemData.ins_id or itemData.insID, itemData.res_id or itemData.resID, true)
            end
            return orig(self, widget, index)
        end
    end
    wrapClick(avatarClass, "OnClickItem")
    wrapClick(gunClass, "OnClickItem")
end)

pcall(function()
    local Arm = require("client.logic.armory.logic_armory")
    if Arm and not Arm.__localSkinChangeHooked then
        Arm.__localSkinChangeHooked = true
        local oInstall = Arm.install_weapon_skin
        if type(oInstall) == "function" then
            Arm.install_weapon_skin = function(client_data, weapon_id, instanceID)
                instanceID = tonumber(instanceID)
                pcall(M.clearItemExpire, nil, instanceID)
                pcall(function() Arm.HandleWeaponSkinChange(client_data, weapon_id, instanceID) end)
                return oInstall(client_data, weapon_id, instanceID)
            end
        end
        local oRsp = Arm.install_weapon_skin_rsp
        if type(oRsp) == "function" then
            Arm.install_weapon_skin_rsp = function(client_data, errorCode, weapon_id, instanceID)
                if errorCode ~= 0 and errorCode ~= NET_OK and errorCode ~= "ok" then
                    pcall(function() Arm.HandleWeaponSkinChange(client_data, weapon_id, tonumber(instanceID)) end)
                    return
                end
                return oRsp(client_data, errorCode, weapon_id, instanceID)
            end
        end
    end
end)

function _G.LobbyWearSuitLocal(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    local inLobby = false
    pcall(function()
        inLobby = GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity()
    end)
    if not inLobby then return false end
    local ok = false
    pcall(function()
        local AM = rawget(_G, "AddOutfit")
        if not AM or not AM.getEntity then return end
        local ent = AM.getEntity()
        if not ent then return end

        AM.injectOne(ent, resID, nil, { addCount = 1, markNew = false })
